  CollectionHall_100442_Title = {Text = "Pickman"},
  CollectionHall_100458_Desc = {
    Text = "Hãy tạm gác lại những lo âu, để sự mệt mỏi nhanh chóng rời xa. \n Hãy cùng nhau nghỉ ngơi một chút bên ánh lửa trại ấm áp nhé."
  },
  CollectionHall_100458_LockTip = {
