  },
  CollectionHall_100459_Desc = {
    Text = "Hãy cháy đi, hãy cháy đi, tất cả những gì thuộc về bạn, hãy cháy hết đi. \n Rồi trong ngọn lửa vô tận đó, hãy bắt đầu lễ tang của bạn và thế giới!"
  },
  CollectionHall_100459_LockTip = {
