  },
  CollectionHall_100460_Desc = {
    Text = "\"Tôi đã nói rồi, bằng bất kỳ cách nào, tôi cũng sẽ đưa mọi người trở về nhà.\"\n\"Tôi sẽ thiêu rụi tất cả những gì thuộc về tôi, rồi……\nBằng ngọn lửa nghiệp chướng đến từ các vì sao, tôi sẽ thiêu rụi thế giới giả dối, ô uế và hỗn loạn này!\"\n\"Tôi tuyên bố với danh nghĩa Katie Gula!\"\n\"Trời sẽ sáng tỏ!\""
  },
  CollectionHall_100460_LockTip = {
    Text = "Hoàn thành hành trình tâm trí\"Không Hồi Tục\""
  },
  CollectionHall_100460_Title = {
    Text = "Bình minh thiêu đốt mọi thứ"
  },
  CollectionHall_100461_Desc = {
    Text = "Tình trạng điên cuồng của cái chết xoay quanh như một cái kính vạn hoa, hương vị ngọt ngào từ bệnh tật và xác chết là hương thơm tốt nhất, các bạn nâng ly từ xa qua vô số người sắp chết - nếu cái chết đã được định sẵn, thì hãy để chúng ta vui vẻ tiến về buổi vũ hội này, cùng nhau rơi xuống cánh cửa địa ngục trong nhịp cuối cùng của điệu nhảy."
  },
  CollectionHall_100461_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Bữa tiệc bùng cháy\" khó khăn"
  },
  CollectionHall_100461_Title = {
    Text = "Rượu vang đỏ, hoa tươi và cái chết rực rỡ"
  },
  CollectionHall_100462_Desc = {
    Text = "Rất lâu rất lâu trước đây, cô ấy là hoàng đế độc tài trong vũ trụ, mọi thứ cô ấy thấy đều thuộc về quyền lực của cô. \n Rất lâu rất lâu sau đó, trong mắt cô chỉ còn thấy bụi bẩn vô tận, từ đó những gì cô nắm giữ chỉ còn lại sự hoang vu và cô đơn."
  },
  CollectionHall_100462_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Bữa tiệc bùng cháy\""
  },
  CollectionHall_100462_Title = {
    Text = "Nữ hoàng cai quản sự hoang vu"
  },
  CollectionHall_100463_Desc = {
    Text = "Cô ấy hoang dã, bạo ngược, vui buồn thất thường, nhưng đồng thời cô cũng nhân từ, uyên bác, tràn đầy trí tuệ. \n Cô là một bạo chúa phóng đãng, cũng là người bảo vệ của những con chiên, cô ban cho bạn tình yêu, cũng ban cho bạn cái chết. Tất cả sinh linh trên mảnh đất này phải quỳ dưới chân cô, kính trọng kêu gọi tên của cô. \n Hãy say mê trong điệu nhảy của nữ hoàng, rồi cùng cô, chìm vào ngọn lửa đen tối vĩnh hằng."
  },
  CollectionHall_100463_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Bữa tiệc bùng cháy\""
  },
  CollectionHall_100463_Title = {
    Text = "Yến tiệc đi đến cái chết"
  },
  CollectionHall_100464_Desc = {
    Text = "Nếu chỉ có thể làm một việc cuối cùng trước khi chết, thì hãy nhảy múa đi. \n Uống rượu ngon ngọt, nuốt miếng thịt nướng thơm ngon, thỏa thích xoay vòng trong giai điệu tưng bừng. \n Để hình ảnh cuối cùng của thế giới trong mắt vẫn lấp lánh ánh vàng say mê."
  },
  CollectionHall_100464_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Bữa tiệc bùng cháy\" khó khăn"
  },
  CollectionHall_100464_Title = {
    Text = "Mặt nạ dịch bệnh"
  },
  CollectionHall_100465_Desc = {
    Text = "Cô ấy luôn thấy những ngày vinh quang xưa cũ trong hồ. \n Những ký ức phong hóa như giấc mơ giả tạo, trong giấc mơ cô ngồi giữa những phế tích vô tận, chứng kiến mọi thứ thuộc về cô đều mờ nhạt và tan biến như ảo ảnh. \n Khi ngay cả giấc mơ đó cũng sẽ bị quên lãng, sứ giả thổi sáo xuyên qua sương mù mà đến, dẫn dắt cô trở về con đường của những người đã khuất."
  },
  CollectionHall_100465_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Bữa tiệc bùng cháy\""
  },
  CollectionHall_100465_Title = {
    Text = "Bóng phản chiếu trong hồ"
  },
  CollectionHall_100466_Desc = {
    Text = "Sự tồn tại không bao giờ tắt giữa các vì sao một lần nữa mở mắt, chiếu rọi sức mạnh bất diệt đến hành tinh mờ đục, bẩn thỉu nhưng vô cùng xanh biếc này, \n giống hệt như khi mặt trời che khuất bầu trời xuất hiện cách đây bốn tỷ năm."
