  CollectionHall_117963_Desc = {
    Text = "Anh đã quyết tâm bỏ lại bên này, sang bên kia. \nTạm biệt anh, nhưng đừng quên Ngài. \nNgài sẽ nhắc nhở bạn, Ngài sẽ theo dõi bạn, kẻ điên khùng, thiên tài họa sĩ, và vầng trăng cao trên bầu trời đêm."
