  CollectionHall_117967_Desc = {
    Text = "Thân thể của nữ hoàng bị tấn công bởi sự phân rã, dân tộc của Arlan phải lưu vong trong cát vàng.  \nThời gian được chứng kiến từ các kẽ hở, bởi những kẻ đã khuất, chứng kiến số phận không thể làm gì được với Arlan hàng trăm năm."
