  },
  CollectionHall_117977_Title = {
    Text = "Tro tàn của trang thơ"
  },
  CollectionHall_117978_Desc = {
    Text = "Không có nghèo khó, đói khát, bệnh tật, phản bội. Đó là Cité nơi chỉ có hoa và thơ ca, là nơi chỉ thuộc về họ."
