  CollectionHall_117978_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Nơi cư trú của hoa hồng\""
  },
  CollectionHall_117978_Title = {
    Text = "Mơ mộng thiên đường"
  },
  CollectionHall_117979_Desc = {
    Text = "Nếu một khẩu súng xuất hiện trong màn đầu tiên, thì nó sẽ nổ vào cuối cùng.\nBạn đã nghĩ đến câu chuyện mà mình sẽ kể cho cô ấy khi tái ngộ.\nĐó là một giấc mơ, khởi đầu của giấc mơ rơi xuống một mặt trời rực rỡ, kết thúc của giấc mơ rơi xuống một mặt trời đen tối."
  },
  CollectionHall_117979_LockTip = {
    Text = "Hoàn thành Thế giới mộng mơ \"Tạm biệt miền đất không bao giờ\" độ khó khó khăn"
  },
  CollectionHall_117979_Title = {
    Text = "Mặt trời rơi"
  },
  CollectionHall_117980_Desc = {
    Text = "Nước mật đã được rót đầy, khách quý đã đến, hãy mang đến Lemvachi những hạt giống mới, hãy tận hưởng niềm đam mê thấm đẫm khát vọng!"
  },
  CollectionHall_117980_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 7-19 mở khóa"
  },
  CollectionHall_117980_Title = {
    Text = "Thời khắc nồng nhiệt"
  },
  CollectionHall_117981_Desc = {
    Text = "Thời gian, sự sống, hư vô, định mệnh.\nTất cả những giấc mơ mơ hồ, thực tại mờ mịt, đều hòa vào dòng chảy, biến mất như chưa từng tồn tại, từng bước không dừng lại, hướng về biển cả."
  },
  CollectionHall_117981_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·độ khó 7-12 mở khóa"
  },
  CollectionHall_117981_Title = {
    Text = "Quay trở lại biển"
  },
  CollectionHall_117982_Desc = {
    Text = "Nàng bước qua những gợn sóng đen nơi cát, nàng dẫn dắt bạn, nắm chặt bạn, mang đến cho bạn mọi thứ từ sự hoang tàn.  \nÁnh trăng đêm nay che giấu một bí mật lấp lánh và phức tạp, nàng vừa giải đáp nghi vấn của bạn trong điệu múa, cũng để lại cho bạn nhiều câu đố hơn trong một điệu múa."
  },
  CollectionHall_117982_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 7-19 mở khóa"
  },
  CollectionHall_117982_Title = {
    Text = "Vũ điệu của biển cát bạc"
  },
  CollectionHall_117983_Desc = {
    Text = "Đối xử với kẻ nổi loạn với sự nuông chiều, món quà hy sinh sở thích xấu xa của Ngài, cũng chia sẻ thói quen xấu của Ngài."
  },
  CollectionHall_117983_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Săn bắn vui vẻ!\""
  },
  CollectionHall_117983_Title = {
    Text = "Sao chép thói quen xấu"
  },
  CollectionHall_117984_Desc = {
    Text = "Điềm xấu và âm thanh vui vẻ giao thoa hạ xuống, hắn vừa là kẻ thù vừa là bạn, hắn mơ hồ khó lường."
  },
  CollectionHall_117984_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 8-14 mở khóa"
  },
  CollectionHall_117984_Title = {
    Text = "Khúc dạo đầu của vận mệnh"
  },
  CollectionHall_117985_Desc = {
    Text = "Bắt lấy từng nốt nhạc, rơi vào đúng nhịp điệu.\nCẩn thận, chú ý, đối mặt với người chỉ huy khó tính, đi sai một bước có thể khiến bạn rơi vào cảnh không thể cứu rỗi."
  },
  CollectionHall_117985_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 8-14 mở khóa"
  },
  CollectionHall_117985_Title = {
    Text = "Nhảy theo nhịp"
  },
  CollectionHall_117986_Desc = {
    Text = "Dùng một bông hoa hồng để đổi lấy một bài thơ.\nTrong trái tim trống vắng của mọi người, hoa hồng đang nở rộ một cách rực rỡ."
  },
  CollectionHall_117986_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Nơi cư trú của hoa hồng\"ở độ khó khó khăn"
  },
  CollectionHall_117986_Title = {
    Text = "Hoa hồng, ôi hoa hồng"
  },
  CollectionHall_117987_Desc = {
    Text = "Chúng tôi đã chuẩn bị cho bạn một kỳ nghỉ hoàn hảo, bao gồm bãi biển, ánh nắng mặt trời, giải bóng chuyền, bạn cũ và bạn mới.\nHãy chắc chắn bôi kem chống nắng, nếu mặt trời rơi xuống từ bầu trời, đừng hoảng sợ, đó là hiện tượng bình thường."
  },
  CollectionHall_117987_LockTip = {
    Text = "Hoàn thành Thế giới mộng mơ \"Tạm biệt miền đất không bao giờ\""
  },
  CollectionHall_117987_Title = {
    Text = "Mùa hè Londinium"
  },
  CollectionHall_117988_Desc = {
    Text = "Ngài không giỏi về âm nhạc, cũng không thích giải đố.\nNhưng ngài bình tĩnh và thanh nhã dệt ngài vào trong bản giao hưởng, bí hiểm mà bất lịch sự ném ra câu đố của mình."
  },
  CollectionHall_117988_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 8-14 mở khóa"
  },
  CollectionHall_117988_Title = {
    Text = "Câu đố của người chỉ huy"
  },
  CollectionHall_117989_Desc = {
    Text = "Con sói đáng thương, kiêu ngạo, không biết đầu trên chân dưới.\nNó bị ném vào phòng nghỉ với các khách khác, trong một cuộc chơi may mắn ngắn ngủi.\nMất may mắn quen thuộc, nó đã thua hơn một vạn bạc nguyên thủy của Leo."
  },
  CollectionHall_117989_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Săn bắn vui vẻ!\""
  },
  CollectionHall_117989_Title = {
    Text = "Thẻ xấu"
  },
  CollectionHall_117990_Desc = {
    Text = "Chiếc mũ giống nhau, hoa hồng giống nhau, tiếng cười giống nhau.\nRèm đã được kéo lên, khán giả đã vào chỗ, hãy đến đi, hãy đến và tìm xem, kẻ giết người đã rơi từ trong màn sương đen ra là ai?"
  },
  CollectionHall_117990_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Săn bắn vui vẻ!\""
  },
  CollectionHall_117990_Title = {Text = "N nhỏ"},
  CollectionHall_117991_Desc = {
    Text = "Cuộc sống tốt đẹp luôn bắt đầu bằng những cơn ác mộng và kết thúc tại nghĩa trang.\nÔi, đó chính là cuộc sống, cuộc sống ngọt ngào."
  },
  CollectionHall_117991_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Săn bắn vui vẻ!\"ở độ khó cao"
  },
  CollectionHall_117991_Title = {
    Text = "Ôi, cuộc sống"
  },
  CollectionHall_117992_Desc = {
    Text = "Hãy nắm lấy tay tôi.\nKhi các ngón tay chạm nhau, tôi sẽ tặng bạn một mùa xuân."
  },
  CollectionHall_117992_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Nơi cư trú của hoa hồng\""
  },
  CollectionHall_117992_Title = {
    Text = "Hai người trong ngày xuân"
  },
  CollectionHall_117993_Desc = {
    Text = "Một cuộc viếng thăm bất ngờ, một cuộc viếng thăm chu đáo, một cuộc viếng thăm hạnh phúc.\nLà bạn bè tương tự, là bạn bè không tương tự.\nÔi, bạn ơi, mỗi người đều cần bạn bè. Tôi sẽ đãi bạn bằng gì, bạn của tôi?"
  },
  CollectionHall_117993_LockTip = {
    Text = "Hoàn thành ý thức du hành \"Hình vẽ kỳ quái\""
  },
  CollectionHall_117993_Title = {
    Text = "Bạn bè không tương tự"
  },
  CollectionHall_117994_Desc = {
    Text = "Roulette bò ra từ trong quan tài, những quá khứ không ngừng đeo bám trong đêm tuyết.\nChơi một ván, lại một ván, da sói và vận may sẽ mang đến một thứ hai ánh nắng rực rỡ."
  },
  CollectionHall_117994_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Săn bắn vui vẻ!\""
  },
  CollectionHall_117994_Title = {
    Text = "Thứ hai của sói"
  },
  CollectionHall_117995_Desc = {
    Text = "Dân tộc Aran đã đi qua những vùng sa mạc, họ sinh ra nơi đây, lớn lên nơi đây, họ định mệnh phải thịnh vượng ở đây, và cũng phải diệt vong ở đây."
  },
  CollectionHall_117995_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 7-19 mở khóa"
  },
  CollectionHall_117995_Title = {
    Text = "Con đường cuối cùng phong phú"
  },
  CollectionHall_117996_Desc = {
    Text = "Đứa trẻ ngoan, bảo bối của mẹ, Sông thiêng sẽ an ủi những tiếng khóc trẻ thơ của bạn, Sông thiêng sẽ đón nhận linh hồn đã trôi đi của bạn."
  },
  CollectionHall_117996_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 7-19 mở khóa"
  },
  CollectionHall_117996_Title = {
    Text = "Còn lại bên Sông thiêng"
  },
  CollectionHall_117997_Desc = {
    Text = "Phần còn lại của khu vườn và tro tàn của quá khứ rơi xuống mảnh đất nhỏ bé này. Chúng bay lượn trong kỷ niệm đau buồn, chúng tan biến trong tham vọng cuồng nhiệt."
  },
  CollectionHall_117997_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Nơi cư trú của hoa hồng\"ở độ khó khó khăn"
  },
  CollectionHall_117997_Title = {
    Text = "Khu vườn ký ức"
  },
  CollectionHall_117998_Desc = {
    Text = "Quái dị nuôi dưỡng cảm hứng của nghệ sĩ, lớn lên, lớn lên, họa sĩ dùng màu sắc để giải cấu trúc thực tế, sự điên cuồng và si mê đang lớn lên trong những đường nét lộn xộn."
  },
  CollectionHall_117998_LockTip = {
    Text = "Hoàn thành ý thức du hành \"Hình vẽ kỳ quái\""
  },
  CollectionHall_117998_Title = {
    Text = "Nghệ thuật tiên phong"
  },
  CollectionHall_117999_Desc = {
    Text = "Có một nơi chỉ có thể đến trong giấc mơ đêm giữa hè, đó là nơi chúng ta có thể đoàn tụ mãi mãi."
  },
  CollectionHall_117999_LockTip = {
    Text = "Hoàn thành Thế giới mộng mơ \"Tạm biệt miền đất không bao giờ\""
  },
  CollectionHall_117999_Title = {
    Text = "Mãi mãi không có kỳ nghỉ"
  },
  CollectionHall_118000_Desc = {
    Text = "Người họa sĩ đã tìm thấy nghệ thuật kinh khủng đó, ông kéo bạt vẽ lên, trước khi lao mình vào, mời bạn bè tham gia một chuyến phiêu lưu kỳ diệu đầy nổ màu sắc."
  },
  CollectionHall_118000_LockTip = {
    Text = "Hoàn thành ý thức du hành \"Hình vẽ kỳ quái\""
  },
  CollectionHall_118000_Title = {
    Text = "Chuyến phiêu lưu điên rồ"
  },
  CollectionHall_118001_Desc = {
    Text = "Họ ôm chầm lấy huyết mạch, anh em, người yêu, bạn bè, họ hiến dâng bản thân, hòa tan trong một cuộc sống lại ngọt ngào đen tối.\nXương cốt của họ quy về Cây mẹ, thịt của họ chảy vào Sông thiêng."
  },
  CollectionHall_118001_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·độ khó 7-12 mở khóa"
  },
  CollectionHall_118001_Title = {Text = "Mẹ"},
  CollectionHall_118002_Desc = {
    Text = "Mặt trời rực rỡ sắp chết, gió cuốn theo cát bụi sẽ dập tắt nó.\nMặt trời chìm xuống, rơi xuống giữa trời và cát."
  },
  CollectionHall_118002_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 7-19 mở khóa"
  },
  CollectionHall_118002_Title = {
    Text = "Rơi vào cát vàng"
  },
  CollectionHall_118003_Desc = {
    Text = "Tại sao một đám cháy lớn có thể thiêu rụi tất cả những lời thề? \nTại sao trong thế giới của thơ ca cũng tràn đầy khổ đau?"
  },
  CollectionHall_118003_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Nơi cư trú của hoa hồng\""
  },
  CollectionHall_118003_Title = {
    Text = "Cách diễn đạt đối lập"
  },
  CollectionHall_118004_Desc = {
    Text = "Con đường nguồn cội, xây dựng từ sinh mạng, gào thét với nó, chống lại sức mạnh không thể phản kháng. Trả lại dòng máu cho Alan, trả lại sự phong phú cho Alan!"
  },
  CollectionHall_118004_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 7-19 mở khóa"
  },
  CollectionHall_118004_Title = {
    Text = "Bức tường bão"
  },
  CollectionHall_118005_Desc = {
    Text = "Đây là thực tại, đây là điên cuồng, đây là mặt tối, đây là giấc mơ.\nKẻ điên và thiên tài thì thầm đan xen nhau, nhỏ hơn, nhỏ hơn nữa — đừng rời mắt khỏi chúng."
  },
  CollectionHall_118005_LockTip = {
    Text = "Hoàn thành ý thức du hành \"Hình vẽ kỳ quái\""
  },
  CollectionHall_118005_Title = {
    Text = "Bước vào sự rối loạn"
  },
  CollectionHall_118006_Desc = {
    Text = "Giá lạnh, mưu mẹo, tuyết lớn, tất cả đều không thể làm rối mùi giác quan của thú dữ."
  },
  CollectionHall_118006_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Săn bắn vui vẻ!\""
  },
  CollectionHall_118006_Title = {
    Text = "Khứu giác"
  },
  CollectionHall_118007_Desc = {
    Text = "Hãy cẩn trọng, không chỉ có bạn cũ mới dùng ủng đá mạnh mẽ đá bạn… bóng chuyền."
  },
  CollectionHall_118007_LockTip = {
    Text = "Hoàn thành Thế giới mộng mơ \"Tạm biệt miền đất không bao giờ\""
  },
  CollectionHall_118007_Title = {
    Text = "Người bạn mới"
  },
  CollectionHall_118008_Desc = {
    Text = "Không không không không không không, đánh bài không phải để thắng.\nĐiểm chính của việc đánh bài chính là đánh bài, đánh bài chỉ để đánh bài."
  },
  CollectionHall_118008_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Săn bắn vui vẻ!\"ở độ khó cao"
  },
  CollectionHall_118008_Title = {
    Text = "Ván bài của thám tử nổi tiếng"
  },
  CollectionHall_118009_Desc = {
    Text = "Gần kề, vị thần đã chết, hơi thở cuối cùng, quá khứ huyền thoại nhưng chưa được biết đến, một cuộc chia ly dừng lại và nhẹ nhàng."
  },
  CollectionHall_118009_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·độ khó 7-12 mở khóa"
  },
  CollectionHall_118009_Title = {
    Text = "Chuông tử vong của những người tiên phong"
  },
  CollectionHall_118010_Desc = {
    Text = "Từ miệng cô ấy xuống, là lời tiên tri hay chỉ là mệnh lệnh của vua, là ân huệ hay ham muốn cá nhân.  \nLinh hồn cây và búp bê cộng hưởng, hứa hẹn cho cô sự cô đơn vĩnh cửu."
  },
  CollectionHall_118010_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·độ khó 7-12 mở khóa"
  },
  CollectionHall_118010_Title = {
    Text = "Lời sấm không âm thanh"
  },
  CollectionHall_118011_Desc = {
    Text = "Tôi đã quên hình dáng của Ngài, tôi đã quên tên của Ngài.\nNhưng tôi sẽ từ bỏ tư lợi, tôi mong muốn trở thành một con kiến bạc, chờ đợi Ngài trở lại, chờ đợi Ngài trở về.\nChờ khi bà ôm tôi vào lòng, chờ khi bà phủ nhận tiếng thở dài ấy."
  },
  CollectionHall_118011_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·độ khó 7-12 mở khóa"
  },
  CollectionHall_118011_Title = {
    Text = "Dành cho người đã khuất"
  },
  CollectionHall_118012_Desc = {
    Text = "Trên thảm cỏ của khu vườn, họ ngước nhìn mây bay đổi thay theo gió.  \nKorete, bạn thấy không, hai đám mây đang đuổi nhau, đó là Bà Bướm và Ông Sâu đang khiêu vũ."
  },
  CollectionHall_118012_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Nơi cư trú của hoa hồng\""
  },
  CollectionHall_118012_Title = {
    Text = "Như những đám mây màu sắc đang đuổi bắt nhau"
  },
  CollectionHall_118013_Desc = {
    Text = "Không ai nhớ đến quá khứ của cô, không ai biết đến những lời thì thầm của cô.\nCô gần gũi với người định mệnh, hơi thở đan xen, hình bóng bên nhau.\nCúi đầu，ngẩng cổ."
  },
  CollectionHall_118013_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 7-19 mở khóa"
  },
  CollectionHall_118013_Title = {
    Text = "Nàng sẵn lòng nhẫn nhịn"
