  CollectionHall_121341_Desc = {
    Text = "<Title:Tổng quan>\nCô \"Công chúa\"đảm nhận nhiệm vụ mang thai \"Thánh Nhân\", hiện nay đã là \"Thần mẫu\" có vai trò quan trọng trong giáo hội Thủy thủ.\nCô cũng từng là một quý cô hướng tới tự do, bước vào hành trình trốn chạy trên con tàu Sona Nier giống như Murphy được ghi chép bởi Mythag.\nNhưng trong thế giới không có Người giữ gìn, số phận đã gãy gục cái cổ cao quý của thiên nga trẻ.\nMạch máu lỗ hổng bám chặt lấy cô, thúc ép không thể chống lại, ngay cả khi bỏ mặc cơ thể chết cũng không thể thoát khỏi. Cô miễn cưỡng nói ra một câu lại một câu \"Tôi là Thần mẫu quý giá\", cũng chỉ là tự nhắc nhở và thuyết phục chính mình.\nChỉ có thể phục tùng, chỉ có phục tùng. Phục tùng mệnh lệnh của sấm rền vô lý, phục tùng số phận phi lý, rồi từ nỗi đắng cay bất tận, miễn cưỡng nếm trải một chút ngọt ngào của cái hư ảo."
  },
  CollectionHall_121341_LockTip = {
    Text = "Hoán tỉnh \"Đản vọng·Murphy\"để mở khóa"
  },
  CollectionHall_121341_Title = {
    Text = "Đản Vọng·Muphí"
  },
  CollectionHall_121381_Desc = {
    Text = "Bạn đổi một ngàn quả sồi lấy một câu chuyện từ thế giới khác.  \nMột câu chuyện về anh hùng và ma thần, về sự quan sát và kiên trì.  \nMột câu chuyện về sự bất lực và nỗi nhớ, về bạn cũ và bạn mới.  \nMột câu chuyện từng tồn tại."
  },
  CollectionHall_121381_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Đảo ngược vòng\""
  },
  CollectionHall_121381_Title = {
    Text = "Vọng âm từ quán trọ vạn tượng"
  },
  CollectionHall_121382_Desc = {
    Text = "Rất lâu sau đó, anh ấy và anh ấy cuối cùng đã có một bài thơ được truyền tụng.\nVề sự cứu rỗi sau cái chết, về linh hồn sinh đôi hòa làm một."
  },
  CollectionHall_121382_LockTip = {
    Text = "Hoàn thành Thế giới mộng mơ \"Ngoài chân trời·Xuống\""
  },
  CollectionHall_121382_Title = {
    Text = "Bài thơ của con chim không cánh"
  },
  CollectionHall_121383_Desc = {
    Text = "Chàng trai vì mọi thứ thoáng qua, đã trả giá bằng cái giá bị đòi hỏi. \nBây giờ, chỉ còn lại quyền lực im lặng đồng hành cùng anh. \nNhà vua chuẩn bị ngủ, trong giấc mơ đón nhận tận cùng của thế giới."
  },
  CollectionHall_121383_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Ngày đăng quang\""
  },
  CollectionHall_121383_Title = {
    Text = "Vùng đất cô độc vô hạn"
  },
  CollectionHall_121384_Desc = {
    Text = "Họ quanh bạn, họ kính trọng bạn, họ đồng hành cùng bạn.\nHọ hướng đến Đấng sáng tạo."
  },
  CollectionHall_121384_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-11 mở khóa"
  },
  CollectionHall_121384_Title = {
    Text = "Lên thuyền về phía thần sáng tạo"
  },
  CollectionHall_121385_Desc = {
    Text = "Đó là đôi cánh tái sinh từ sự hủy diệt, đó là đôi cánh đổi lấy tự do bằng hy sinh.\nLời tiên tri của định mệnh đã ứng nghiệm, anh ta thề trong nỗi hối hận, món nợ máu phải trả bằng máu."
  },
  CollectionHall_121385_LockTip = {
    Text = "Hoàn thành Thế giới mộng mơ \"Ngoài chân trời·Xuống\""
  },
  CollectionHall_121385_Title = {
    Text = "Khi bão nổi lên"
  },
  CollectionHall_121386_Desc = {
    Text = "Trong giấc mơ absurde và hỗn mang, Ngài ấy đã định phải đối diện với số phận của mình ngay từ đầu.\nNhưng Ngài đã trải qua quá nhiều, và đã định nghĩa quá nhiều.\nNgài đã quyết định với lý trí lớn nhất mà con người có thể giữ, quan sát nguồn gốc của mình, Thần tối cao đó."
  },
  CollectionHall_121386_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-11 mở khóa"
  },
  CollectionHall_121386_Title = {
    Text = "Trận chiến số mệnh nguyên thủy"
  },
  CollectionHall_121387_Desc = {
    Text = "Nhận được, mất đi, chặt đứt, hy sinh.\nNgười anh hùng đã trả giá tất cả, quyền năng bảo vệ của báu vật chính là phần thưởng của ngài."
  },
  CollectionHall_121387_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121387_Title = {Text = "Mắt mù"},
  CollectionHall_121388_Desc = {
    Text = "Hắn đội vương miện lên bản thân, hắn xích chính mình lại.  \nĐó là hơi ấm ngắn ngủi ảo tưởng, đó là ánh sáng huy hoàng đã định sẵn sẽ tan biến."
  },
  CollectionHall_121388_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Ngày đăng quang\""
  },
  CollectionHall_121388_Title = {
    Text = "Con đường cô độc của vị vua trẻ"
  },
  CollectionHall_121389_Desc = {
    Text = "Mặc dù tình huống không thuận lợi cho bạn, nhưng khóe miệng bạn đã hơi nhếch lên. \n\"Đến lượt tôi, rút thẻ!\"\nDù là ở Khách sạn Vạn tượng hay ở Mythag, \nChỉ cần xem thường khả năng gây sát thương của trợ giúp cũng sẽ phải chịu thiệt lớn đấy! Ignatius!"
  },
  CollectionHall_121389_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Đảo ngược vòng\""
  },
  CollectionHall_121389_Title = {
    Text = "Khoảnh khắc đảo ngược thuộc về tôi!"
  },
  CollectionHall_121390_Desc = {
    Text = "Một huyền thoại hoàn chỉnh không thể thiếu việc biến kẻ thù thành bạn."
  },
  CollectionHall_121390_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·Khó khăn 9-10 mở khóa"
  },
  CollectionHall_121390_Title = {
    Text = "Kẻ thù, bạn bè"
  },
  CollectionHall_121391_Desc = {
    Text = "Từ nay trở đi, bạn sẽ mang danh hiệu Người Giữ Gìn, cùng với vạn nghìn học sinh và giáo viên của Misaque."
  },
  CollectionHall_121391_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·Khó khăn 9-11 mở khóa"
  },
  CollectionHall_121392_Desc = {
    Text = "Có thể chúng ta chỉ là những khoảnh khắc nhỏ bé trong vĩnh cửu, những viên cát trong dòng chảy mạnh mẽ.\nNhưng vĩnh cửu chính là giá trị quý báu của chúng ta, vì bất kể thế giới điên cuồng và hỗn loạn ra sao —\nnhân phẩm của con người sẽ được xây dựng trên ánh sáng của lý trí."
  },
  CollectionHall_121392_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-11 mở khóa"
  },
  CollectionHall_121392_Title = {
    Text = "Ca ngợi vĩnh cửu"
  },
  CollectionHall_121393_Desc = {
    Text = "Những anh hùng lao vào câu chuyện cổ tích, mỗi câu chuyện cổ tích đều như nhau, động vật, quỷ, nàng tiên và những điều chưa biết ở phía bên kia.\nVượt qua tự do thoáng qua và ước muốn giả dối, cuối cùng của câu chuyện cổ tích, giấu một trái tim giả mạo bị áp đặt lên hắn."
  },
  CollectionHall_121393_LockTip = {
    Text = "Hoàn thành Thế giới mộng mơ \"Ngoài chân trời·Xuống\""
  },
  CollectionHall_121393_Title = {
    Text = "Bay vào thiên hà"
  },
  CollectionHall_121394_Desc = {
    Text = "Đây là nơi trọ \"Vạn tượng\" nằm trong vết rạn không gian ở thế giới khác.\nKết nối với những vũ trụ khác nhau bằng cánh cổng truyền tống, lấp lánh ánh sao rộng lớn, chào đón sự đến của bạn.\nĐợi đã... đây là dành cho người giữ gìn chúng ta làm gì?"
  },
  CollectionHall_121394_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Đảo ngược vòng\""
  },
  CollectionHall_121394_Title = {
    Text = "Chào mừng đến với khách sạn Vạn Tượng!"
  },
  CollectionHall_121395_Desc = {
    Text = "Lưỡi dao của Myrthag sẽ giúp bạn giành chiến thắng trong cuộc đối đầu này.\nSự gắn bó giữa bạn và đồng đội không thể bị phá vỡ.\nDù một ngày nào đó các bạn ở trong những vũ trụ khác nhau, điều đó cũng không thể thay đổi."
  },
  CollectionHall_121395_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Đảo ngược vòng\""
  },
  CollectionHall_121395_Title = {
    Text = "Myrthag lưỡi dao!"
  },
  CollectionHall_121396_Desc = {
    Text = "“Chưa thực hiện nhiệm vụ hàng ngày sao? Hay là trước tiên hãy chơi một ván 「Thẻ Bài Vạn Tượng」!”\n“Chưa đánh vào vùng cấm hòa tan sao? Hay là trước tiên hãy chơi một ván 「Thẻ Bài Vạn Tượng」!”\n“Đây là bẫy không phải thẻ bài vạn tượng! Tôi sẽ thu thập cho bạn xem một nghìn hạt sồi!”"
  },
  CollectionHall_121396_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Đảo ngược vòng\""
  },
  CollectionHall_121396_Title = {
    Text = "Cùng nhau chơi thẻ vạn tượng nào!"
  },
  CollectionHall_121397_Desc = {
    Text = "Gọi tên của tôi, trước khi bình minh bị lãng quên."
  },
  CollectionHall_121397_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·Khó khăn 9-11 mở khóa"
  },
  CollectionHall_121397_Title = {
    Text = "Từ sự quên @2"
  },
  CollectionHall_121398_Desc = {
    Text = "\"Hãy đến và ký kết hợp đồng với tôi, trở thành bậc thầy thẻ bài!\"\nCô gái rồng xinh đẹp đến từ thế giới khác gửi đến bạn một lời mời nhiệt tình và kỳ lạ.\nĐể biến sự cố nhỏ trong không gian này trở về bình thường nhanh chóng, bạn không còn sự lựa chọn nào khác."
  },
  CollectionHall_121398_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Đảo ngược vòng\""
  },
  CollectionHall_121398_Title = {
    Text = "Cô chủ quán, Ignatius!"
  },
  CollectionHall_121399_Desc = {
    Text = "Người đến sau sẽ tìm thấy một dòng chú thích dưới gánh nặng nặng nề như vậy.\nNgười duy nhất tránh né trở thành anh hùng đã trở thành anh hùng, đứa trẻ quý trọng bạn bè chỉ còn lại một người bạn duy nhất."
  },
  CollectionHall_121399_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Ngày đăng quang\""
  },
  CollectionHall_121399_Title = {
    Text = "Dư sẽ độc hành"
  },
  CollectionHall_121400_Desc = {
    Text = "Rời bỏ chủ, đối mặt với chủ, phản bội chủ.\nCâu chuyện của bạn không ai biết, ký ức của bạn mãi mãi tồn tại trong thế giới."
  },
  CollectionHall_121400_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121400_Title = {
    Text = "Chúa tể ngu ngốc của sự sáng tạo"
  },
  CollectionHall_121401_Desc = {
    Text = "Mọi thứ không còn có ý nghĩa nữa, vì vậy bạn có thể đứng ở đây.\nMọi ký ức trong quá khứ, chính là toàn bộ ý nghĩa mà bạn đã định nghĩa, vì vậy bạn đứng ở đây."
  },
  CollectionHall_121401_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121401_Title = {
    Text = "Hiện sinh"
  },
  CollectionHall_121402_Desc = {
    Text = "Con đường dẫn đến họ, con đường xa rời họ.\nMọi thứ sắp tách biệt, mọi thứ sắp kết thúc, mọi thứ sắp bắt đầu.\nHình bóng trước cánh cửa bắt đầu một cuộc chờ đợi dài dằng dặc, chờ đợi chìa khóa bạc chỉ dẫn về nhà bạn."
  },
  CollectionHall_121402_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121402_Title = {
    Text = "Con đường dẫn đến họ"
  },
  CollectionHall_121403_Desc = {
    Text = "Các khả năng của họ, phân ly, thu gọn, tan rã.\nCho đến khi đón nhận vị cứu tinh duy nhất, cho đến khi cuối cùng bước vào cái kết duy nhất."
  },
  CollectionHall_121403_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·Khó khăn 9-10 mở khóa"
  },
  CollectionHall_121403_Title = {
    Text = "Kết thúc duy nhất"
  },
  CollectionHall_121404_Desc = {
    Text = "Nhà vua trẻ đã chấp nhận giao ước này.\nÔng nói, đất nước của tôi sẽ được an toàn."
  },
  CollectionHall_121404_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Ngày đăng quang\""
  },
  CollectionHall_121404_Title = {
    Text = "Đăng quang"
  },
  CollectionHall_121405_Desc = {
    Text = "Trong vết rạn thời gian vỡ nát này từng tọa lạc một nơi trọ huyền thoại mang tên \"Vạn tượng\".\nTừng kết nối với các vũ trụ khác nhau bằng cánh cổng truyền tống, từng lấp lánh ánh sao rộng lớn, từng chào đón mỗi bậc thầy thẻ bài đến. \nVà bạn, chính là chứng nhân của tất cả những điều đó đã tồn tại."
  },
  CollectionHall_121405_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Đảo ngược vòng\""
  },
  CollectionHall_121405_Title = {
    Text = "Chào tạm biệt, bậc thầy thẻ bài!"
  },
  CollectionHall_121406_Desc = {
    Text = "Chúa nhìn bạn, bạn đã đâm vào mắt Chúa."
  },
  CollectionHall_121406_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121406_Title = {
    Text = "Đích đến của sự kết thúc"
  },
  CollectionHall_121407_Desc = {
    Text = "Chiến binh, kẻ báo thù, nô lệ, chủ, thương nhân.\nCùng một vị trí? Khác vị trí? Cùng một vị trí."
  },
  CollectionHall_121407_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-11 mở khóa"
  },
  CollectionHall_121407_Title = {
    Text = "Khúc ca đa dạng tính"
  },
  CollectionHall_121408_Desc = {
    Text = "Bạn biết đấy, bạn không đang tranh đấu vì những điều vĩ đại.\nĐể trốn học, để làm bài tập, để ăn đồ ngọt, để gặp gỡ bạn bè, để bên lò sưởi, để lãng phí thời gian.\nBạn chỉ là một người bình thường, mà phải ra đi mỗi ngày."
  },
  CollectionHall_121408_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·Khó khăn 9-11 mở khóa"
  },
  CollectionHall_121408_Title = {
    Text = "Dành cho những người đi đến cái chết hàng ngày"
  },
  CollectionHall_121409_Desc = {
    Text = "Động vật, tất cả các động vật bậc cao, đều không thể tránh khỏi bị điều khiển bởi hành vi xã hội.\nTuy nhiên, cô ấy đã tự mình đối mặt với cái chết, như mong muốn cấu trúc lại sự thật.\nMột thiên tài điên cuồng, không giống ai, cô ấy thà để sự hủy diệt đến với chính mình, cô ban phước cho mọi sinh linh được thoát khỏi mang tên hy vọng."
  },
  CollectionHall_121409_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121409_Title = {
    Text = "Giải cấu trúc hành vi cộng đồng"
  },
  CollectionHall_121410_Desc = {
    Text = "Ngài ấy từ thiên đàng gửi đến dòng nước khổ ải không ngừng chảy, tụ hội, tụ hội.\nCuối cùng trở thành dòng sông mà trước khi máu thịt hòa quyện, phải hồi tố."
  },
  CollectionHall_121410_LockTip = {
    Text = "Hoàn thành Thế giới mộng mơ \"Ngoài chân trời·Xuống\""
  },
  CollectionHall_121410_Title = {
    Text = "Dòng sông khổ"
  },
  CollectionHall_121411_Desc = {
    Text = "Ngài ấy tạm biệt với mong đợi tái ngộ.\nBởi vì đây là một người quý giá, vì đây là cái chết của một người quý giá không được định sẵn."
  },
  CollectionHall_121411_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-11 mở khóa"
  },
  CollectionHall_121411_Title = {
    Text = "Cái chết của một kẻ quý giá"
  },
  CollectionHall_121412_Desc = {
    Text = "Nghỉ một chút, thở phào đi.  \nNgay cả khi chủ đề phải đối mặt là ngày tận thế, không phải ai cũng có cơ hội cùng lúc đối mặt với ba vị thầy nặng ký như vậy."
  },
  CollectionHall_121412_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121412_Title = {
    Text = "Giữa màn kịch"
  },
  CollectionHall_121413_Desc = {
    Text = "Câu chuyện về một ngàn hạt sồi, tất cả phải bắt đầu từ hạt đầu tiên.\nTrong Bẫy, mỗi khi bạn chơi một thẻ,\n một làn sóng hồi ức màu vàng lướt qua trong đôi mắt của Ignatius."
  },
  CollectionHall_121413_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Đảo ngược vòng\""
  },
  CollectionHall_121413_Title = {
    Text = "Tiếp tục rót không giới hạn!"
  },
  CollectionHall_121414_Desc = {
    Text = "Điên loạn, khúc dạo đầu của hủy diệt, đây là logic nền tảng của thế giới có trật tự.\nNgài có hủy diệt không, thế giới có hủy diệt không?\nKhông ai biết.\nNhưng trước mặt Thượng Đế sáng tạo, điên loạn đang nuôi dưỡng sự tái sinh mới của Ngài và thế giới."
  },
  CollectionHall_121414_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-11 mở khóa"
  },
  CollectionHall_121414_Title = {
    Text = "Điên loạn fugue"
  },
  CollectionHall_121415_Desc = {
    Text = "Điều không hợp lý nhất trên thế giới là gì?  \nNó không có mục đích, không quan hệ đến ân oán, không phân biệt thiện ác.  \nNó chỉ muốn biến mọi thứ sinh ra trong giấc mơ thành tro bụi khi tỉnh dậy."
  },
  CollectionHall_121415_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121415_Title = {Text = "Bột"},
  CollectionHall_121416_Desc = {
    Text = "Như một mảnh ghép độc nhất, trở thành thần rất đơn giản.  \nVậy thì, cái giá phải trả là gì?"
  },
  CollectionHall_121416_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121416_Title = {
    Text = "Trở thành thần"
  },
  CollectionHall_121417_Desc = {
    Text = "Trong nền văn minh nhân loại dài lâu, chúng ta đã xây dựng nhiều thứ.\nVề vật chất, về tinh thần, về sự sống, yêu thương, khói lửa và cuộc xung đột.\nNhưng đó chỉ là tiếng ồn không đáng kể trong giấc mơ của Đấng tạo hóa, và là tác phẩm hư cấu mà người ta chưa khám phá."
  },
  CollectionHall_121417_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 9-13 mở khóa"
  },
  CollectionHall_121417_Title = {
    Text = "Tập hợp tưởng tượng"
  },
  CollectionHall_121418_Desc = {
    Text = "Myrthag, nhân vật giữ gìn nhát gan nhất trong lịch sử, đã chết trong niềm hạnh phúc khổng lồ."
  },
