  },
  CollectionHall_124124_Desc = {
    Text = "Bạn có khả năng gặp gỡ mặt thứ hai của nhiều tồn tại, dù đó có thể là một đứa trẻ không nên tồn tại, hoặc được sinh ra từ một vị thần sai lầm."
