  CollectionHall_124124_Title = {
    Text = "Mặt thứ hai"
  },
  CollectionHall_124125_Desc = {
    Text = "Ôi... hóa ra còn một kết cục tệ hơn."
  },
  CollectionHall_124125_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124125_Title = {
    Text = "Cô ấy, anh ấy và cái chết của Ngài"
  },
  CollectionHall_124126_Desc = {
    Text = "Bạn sẽ mô tả như thế nào về một người đồng hành ra đi khi quá chói lọi? \n Đừng mô tả sự chói lọi của anh ấy, hãy mô tả cánh tay của anh ấy, mô tả mùi hương gỗ tuyết tùng mà bạn ngửi thấy trên người anh ấy."
