  },
  CollectionHall_124126_Title = {
    Text = "Gỗ tuyết tùng"
  },
  CollectionHall_124127_Desc = {
    Text = "Ở cuối hành trình, bạn biết có ai đang đợi bạn. \n Nhưng bạn vẫn chưa thể trốn thoát, bạn lại rơi xuống từ độ cao."
