  CollectionHall_124127_Title = {
    Text = "Rơi xuống"
  },
  CollectionHall_124128_Desc = {
    Text = "Đứa trẻ không thuộc về người mẹ, nó đã quyết định, mọi người đều phải ở lại đây. \nỞ lại thiên đường ngọt ngào vĩnh cửu của nó."
