  CollectionHall_124128_LockTip = {
    Text = "Hoàn thành hoạt động điều tra · Khó khăn Chương Sao 4-10 mở khóa"
  },
  CollectionHall_124128_Title = {
    Text = "Khu vui chơi ngọt ngào"
  },
  CollectionHall_124129_Desc = {
    Text = "Bạn không kịp cứu cô ấy, cô ấy đã không thoát ra được. \n Cô ấy đã bị chia chác, cô ấy cô đơn không ai giúp đỡ, cô ấy đã buộc một sợi dây rốn giả."
  },
  CollectionHall_124129_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124129_Title = {
    Text = "Cuống rốn giả"
  },
  CollectionHall_124130_Desc = {
    Text = "3.14159@2,3.141592@3,3.14159265@4……\nHình tròn không bao giờ kết thúc trong tuyết, số pi tàn nhẫn, sẽ không bao giờ kết thúc."
  },
  CollectionHall_124130_LockTip = {
    Text = "Hoàn thành hoạt động điều tra · Khó khăn Chương Sao 4-10 mở khóa"
  },
  CollectionHall_124130_Title = {
    Text = "\"3.14159@4\""
  },
  CollectionHall_124131_Desc = {
    Text = "Bạn lại đến muộn một chút, đừng dừng lại, nhanh lên, nhanh hơn nữa. \n Nhanh chóng đến với kết cục tiếp theo."
  },
  CollectionHall_124131_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124131_Title = {
    Text = "Một cái kết"
  },
  CollectionHall_124132_Desc = {
    Text = "Ôm tôi đi, em yêu của tôi, cha của tôi, số phận của tôi."
  },
  CollectionHall_124132_LockTip = {
    Text = "Hoàn thành hoạt động điều tra · Khó khăn Chương Sao 4-10 mở khóa"
  },
  CollectionHall_124132_Title = {
    Text = "Trong tử cung hắc ám của con gái anh ấy"
  },
  CollectionHall_124133_Desc = {
    Text = "Bầu trời sắp sáng, hãy để chúng ta nói lời tạm biệt với ngày hôm qua. \n Tạm biệt những nỗi đau, sự vô nghĩa, và sự lúng túng của ngày hôm qua, \n chào đón một ngày mai tươi sáng hơn, ở hai phương trời khác nhau."
  },
  CollectionHall_124133_LockTip = {
    Text = "Hoàn thành hoạt động điều tra · Khó khăn Chương Sao 4-10 mở khóa"
  },
  CollectionHall_124133_Title = {
    Text = "Tạm biệt vào lúc bình minh"
  },
  CollectionHall_124134_Desc = {
    Text = "Cô ấy đã dựng lên một chiếc lá chắn nhỏ giữa thực tại và ảo tưởng. \n Chiếc lá chắn được làm từ bột mì, trứng, chanh, mật ong, đường, bột nở và bơ."
  },
  CollectionHall_124134_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124134_Title = {
    Text = "Khiên Bột"
  },
  CollectionHall_124135_Desc = {
    Text = "Thế giới này vẫn như mọi khi, đứa trẻ phụ thuộc vào mẹ, đứa trẻ cũng nói dối mẹ."
  },
  CollectionHall_124135_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124135_Title = {
    Text = "Giọng nói của kẻ nói dối"
  },
  CollectionHall_124136_Desc = {
    Text = "Ngày thứ 7 của sự ra đời của thần. \n Ôi, thần ơi, thần ơi…… \n Chỉ là những sai lầm vô lý và những lời nói dối giả tạo."
  },
  CollectionHall_124136_LockTip = {
    Text = "Hoàn thành hoạt động điều tra · Khó khăn Chương Sao 4-10 mở khóa"
  },
  CollectionHall_124136_Title = {
    Text = "Thần thối rữa"
  },
  CollectionHall_124137_Desc = {
    Text = "Hãy ngủ đi, hãy ngủ đi, đứa trẻ của biển cả, để ánh trăng đen tối chiếu xuống chiếc khăn ẵm tăm tối của con, để giấc mơ ngàn năm vĩnh cửu này chìm vào hư vô vĩnh hằng."
  },
  CollectionHall_124137_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124137_Title = {
    Text = "Ánh sáng đen của mặt trăng"
  },
  CollectionHall_124138_Desc = {
    Text = "Trốn chạy đi, hai con cá nhảy lên mặt nước. \n Chúng tạm thời bỏ lại mọi thứ, cố gắng lén lút sống cùng nhau trong cuộc sống lưu vong."
  },
  CollectionHall_124138_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124138_Title = {
    Text = "Lưu vong bí mật"
  },
  CollectionHall_124139_Desc = {
    Text = "Cha sinh ra con gái, con gái mang thai cha. \n Hư vọng, đảo lộn, số phận chu kỳ mà cô rơi vào."
  },
  CollectionHall_124139_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124139_Title = {
    Text = "Thai nghén của sự hư vọng đảo lộn"
  },
  CollectionHall_124140_Desc = {
    Text = "Có điều gì đáng sợ hơn cái chết và nỗi đau không?\nĐối với bạn, đây không phải là một câu hỏi khó để giải đáp."
  },
  CollectionHall_124140_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124140_Title = {
    Text = "Quay lại điểm xuất phát"
  },
  CollectionHall_124141_Desc = {
    Text = "Cô ấy và cô ấy có tín tâm của họ, anh ấy và anh ấy có sự phản bội và trung thành của họ. \n Cô ấy dệt nên một lời nói dối khổng lồ, anh ấy và anh ấy và cô ấy và cô ấy cùng cô ấy diễn kịch. \n Gia đình, mọi người tạo nên một mái ấm ngọt ngào và không thể tách rời."
  },
  CollectionHall_124141_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124141_Title = {Text = "Nhà"},
  CollectionHall_124142_Desc = {
    Text = "Hãy gọi tên của thần quốc nổi lên từ biển - Lemuria, Lemuria."
  },
  CollectionHall_124142_LockTip = {
    Text = "Hoàn thành hoạt động điều tra, mở khóa Chương sao 4-16"
  },
  CollectionHall_124142_Title = {
    Text = "Quốc hải"
  },
  CollectionHall_124224_LockTip = {
    Text = "Hoàn thành bất kỳ cấp độ nào của \"Bạc và Máu\"để mở khóa"
  },
  CollectionHall_124224_Title = {
    Text = "Bản ghi điều tra thế giới khác của Mộc Hạ"
  },
  CollectionHall_124395_Desc = {
    Text = "Vào ngày đau khổ và thỏa mãn nhất trong cuộc đời Lạc Đan, lưỡi kiếm trong tay nàng như cơn bão lao vào vị thần trước mắt. Thanh đại kiếm cùng thân xác hùng vĩ như hành tinh của Leviathan, cùng nhau vỡ vụn từng mảnh trong cơn bão ấy.\nSau khi trao vương miện đẫm máu cho tên nô lệ của kỵ sĩ đoàn, đổi lại, Lạc Đan chỉ đưa ra một yêu cầu duy nhất: nàng cần một vũ khí mới.\nMang trong lòng sự kính sợ và tôn kính đối với Lạc Đan, vị tân vương ra lệnh lấy xương của Leviathan, đúc cho nàng một đôi đại kiếm vô song. Trong những ngày đêm rèn giũa không ngừng nghỉ của những thợ rèn tài giỏi nhất sáu quốc gia, xương cốt của một vị thần đã chết, được tái sinh trong tay kẻ giết thần.\nMột đối thủ xứng đáng được ghi nhớ đã từng chứng kiến đôi lưỡi kiếm bất diệt này. Chiếc búa lớn của hắn đập vỡ áo giáp và đại kiếm của Lạc Đan, vết nứt lan ra như mạng nhện trên thân kiếm, những mảnh vỡ trắng sữa bắn tung trong không khí màu máu, như ngày nàng đâm vào Leviathan. Hắn tưởng mình đã tìm ra điểm yếu. Rồi, hắn thấy Lạc Đan đứng dậy trước mặt mình, thanh đại kiếm lẽ ra đã vỡ vụn đâm xuyên ngực hắn, hút lấy máu thịt hắn. Những xương mới trào ra từ chỗ vỡ, sắc bén hơn, dày đặc hơn trước. Mặt gãy mọc ra từng đốt, như bụi gai mọc hoang trong đồng nội. Hắn cảm nhận rõ ràng, sinh mệnh của mình đang bị lưỡi kiếm đúc từ xương trắng kia nhai nuốt.\nHóa ra, con quái thú từng nuốt chửng bầu trời sao chưa bao giờ chết. Từ khoảnh khắc khế ước được ký kết, Ngài đã hòa làm một với nàng. Mỗi khi Lạc Đan vung đại kiếm, những gai xương trên thân kiếm bắt đầu nở rộ, dùng những mũi nhọn sắc bén của mình gửi đến đối thủ lời chào tàn nhẫn.\nNó là vũ khí của nàng. Nàng là đôi chân của nó. Nàng và nó, từ đầu đến cuối đều chìm đắm trong cùng một khao khát. Họ bất tử bất diệt, mãi mãi không thỏa mãn.\nChiến trường không bao giờ ngừng nghỉ, là nơi quy về duy nhất của họ."
  },
  CollectionHall_124395_Title = {
    Text = "Kiếm Xương Bất Diệt"
  },
  CollectionHall_124397_Desc = {
    Text = "Nhiều năm sau, đối diện với thủy thủ đang cầu nguyện nằm dưới đất, Murphy tưởng tượng sẽ nhớ lại buổi chiều xa xăm khi \"mẹ\" kể cho cô nghe về câu chuyện con bạch tuộc vòng xanh.\nDi vật trong cái bình vừa mềm mại lại rực rỡ, màu xanh kỳ lạ nổi trong nước, dụ dỗ cô bé gần sát hơn không tự chủ.\nNhưng Miryam lại vuốt đầu cô, với lực đạo không thể từ chối khiến cô nhìn vào góc mờ mịt của khoang tàu — Một xác thủy thủ gục xuống đất, trông như bị độc tố hút cạn, trở nên hư vô nhợt nhạt.\n\"Hãy nhớ, biển yên tĩnh nhất cũng chết chóc nhất, thường là loại đẹp nhất.\"\nÁnh sáng lạnh từ cái chai thủy tinh sáng lên bóng dáng nhân từ của cô, Murphy chỉ cảm thấy một sự sợ hãi được bao bọc bởi cái đẹp.\n\nNăm tháng lặng lẽ trôi theo nhịp điệu của các ngôi sao, Murphy như thường ngày kiêu ngạo, nhưng lại học được cách im lặng và quan sát.\n\"Lemuria, Lemuria...\"\nCho tới khi trên bàn thờ, khuôn mặt luôn bình tĩnh và dịu dàng đó dần bị điên loạn thấm đẫm, cô mới ngỡ ngàng nhận ra, hóa ra mình chưa bao giờ thực sự hiểu Miryam. Đôi tay dịu dàng của \"mẹ\" từng vuốt lên đầu cô, cũng có thể dành cho kẻ thù của vùng đất thần thánh sự trừng phạt nghiêm khắc nhất.\nLúc đó, nỗi sợ được lưu giữ trong ký ức sâu thẳm đột ngột hồi sinh, cuối cùng kết tinh thành nhận thức lạnh giá — Sự nhân từ của cô chỉ là miếng vải chân tay giả, còn vòng xanh đẹp đẽ bên ngoài chỉ là độc tố chết người khép kín.\n\nTới ngày hôm nay, thần hư vô cuối cùng đã trao vương miện cho Murphy. Cô cúi xuống nhìn các thủy thủ nằm bò, đối diện với ánh mắt của Miryam, ánh nhìn không bao giờ bị dập tắt, gần như là sự kỳ vọng mỉa mai, như thể cô lại thấy bản thân nhỏ bé của mình đứng trước cái bình thủy tinh, nhìn sinh vật đẹp và run rẩy."
  },
  CollectionHall_124397_Title = {
    Text = "Độc tố vòng xanh"
  },
  CollectionHall_124400_Desc = {
    Text = "Dịch bệnh vô danh nuốt chửng thị trấn và làng mạc, những kẻ hiếu chiến thỏa sức tàn sát trong cơn hỗn loạn, bản giao hưởng của sắt và máu sôi sục điên cuồng.\nVì sợ hãi, hay lợi dụng sợ hãi.\nSợ hãi là kẻ thù vô hình, kẻ thù cổ xưa, kẻ thù chết người.\nChàng là một hiệp sĩ không xứng danh, chàng đã thua trước nỗi sợ hãi.\nThế nhưng lời thề từng long trọng tuyên thệ vẫn vang vọng bên tai, năm này qua ngày khác, xuyên qua cố hương đã từ lâu trở thành hư vô.\n\"Ta sẽ đối xử nhân từ với kẻ yếu, ta sẽ dũng cảm đối mặt với kẻ thù mạnh.\"\nBóng đêm che giấu dấu chân của kẻ hành hung, dòng thác tiếng la hét và khóc lóc nhấn chìm phố phường, đám đông như bầy cừu hoảng loạn.\n\"Ta sẽ không ngần ngại chống lại kẻ ác, ta sẽ chiến đấu vì những người không thể chiến đấu.\"\nĐầu giáo nhuốm máu, khiên bạc han gỉ, bóng tối mỉm cười thỏa mãn, đàn quạ lượn vòng trên đỉnh đầu, trong đồng tử lóe lên ánh sáng của ác quỷ.\n\"Ta sẽ giúp đỡ những người cần ta giúp đỡ.\"\n\"Là hắn, hắn đến rồi.\" Người ta thì thầm lầm bầm, nỗi sợ hãi bóp méo khuôn mặt họ, \"Quái vật rỗng ruột, bóng ma báo thù, từ vực thẳm của cái chết trở về, để kéo kẻ thù của hắn xuống đầm lầy đen tối của oán hận.\"\nLà chàng. Chàng chưa quên, chàng chưa bao giờ quên.\nTại sao phải kiên trì? Nếu như vạn vật rốt cuộc đều sẽ tiêu vong, dù là vinh quang hay tín ngưỡng.\nTại sao phải rút lui? Đã biết rằng dù số phận có chế giễu thế nào, con người cũng chỉ có thể quỳ gối thuận theo.\nChẳng lẽ chỉ để trung thành với lòng trung thành, dâng hiến cho sự dâng hiến?\nVị hiệp sĩ cuối cùng của công quốc hỏi một cách vô vọng, linh hồn cũng hoang tàn như thân xác tàn tạ, cặn bã của nỗi sợ hãi tự do chảy tràn, hội tụ thành đại dương của sự hủy diệt.\nNhưng lồng ngực trống rỗng vẫn im lặng không lên tiếng, câu trả lời đã mất vẫn chưa biết nơi đâu."
  },
  CollectionHall_124400_Title = {
    Text = "Quá Khứ Như Bóng Theo Hình"
  },
  CollectionHall_124404_Desc = {
    Text = "Đó là năm thứ hai tôi và cha chuyển đến thành phố biển, những lời khóc lóc trong thư của Evelyn khiến tôi bối rối, tôi đã quyết tâm chia tay cô ấy. Đây là vùng đất giàu có được trang trí bằng lụa và gỗ mun, tất cả những kẻ ăn xác thối đều ngửi thấy sự hỗn loạn khi nó đang ngủ, giá trị của tiền giấy có thể đổi lấy vàng nặng bằng nó, nắm giữ những tuyến đường đó, có thể khuấy động hàng triệu lần tài sản với chi phí rất nhỏ. \n Tuy nhiên, Evelyn, có lẽ do nguồn gốc kỳ lạ khó nắm bắt dẫn đến tính khí thần kinh, người phụ nữ này tin tưởng vào thông điệp từ tổ tiên, ở phương Đông có những nhánh phụ của họ thờ phụng những vị thần quái dị, như một loại cá nào đó ở biển sâu, sẽ treo những mồi ngon để dẫn dụ con mồi vào một cuộc ăn uống chậm rãi khó phát hiện. \n Cô ấy đã sai, thành phố biển không có chút mặn nào từ biển cả. \n Chỉ có những bông hoa ngọc lan chồng chất, nồng nàn đến mức khiến người ta say mê, nhưng cũng đầy sợ hãi. \n Những bông hoa ngọc lan đã khiến tôi và cha cùng sa vào. \n Khi tôi nhìn thấy cô ấy, hình bóng người phụ nữ tên là \"Xu\" xuất hiện trong tầm mắt tôi ngay giây đầu tiên, tôi đã không còn khả năng thoát khỏi vùng đất cổ xưa này nữa. \n Cô ấy khiến người ta muốn lại gần, cô ấy khiến người ta muốn chiếm hữu, cô ấy khiến người ta muốn @3 \n Cô ấy khiến người ta muốn muốn muốn muốn muốn \n cắt nhỏ, chẻ ra, đập vỡ mãi mãi mãi mãi mãi mãi... @2@3@2!! \n Ôi, tại sao tôi lại đến đây? Tôi muốn mang đi điều gì? Tôi là... ai? \n Không còn quan trọng nữa, cô ấy đã mời tôi, tôi ngồi trước bàn ăn trong ngôi nhà lớn đó. \n Cha tôi, người đã điên cuồng như tôi, trên mặt mang nụ cười ngoan ngoãn, những món ăn phong phú đã được bày trên bàn ăn, khiến đĩa ăn kim loại có nắp trở nên lạc lõng. \n Xu ngồi ngược ánh sáng trong ánh hoàng hôn, hào quang bao quanh cô ấy bằng một lớp viền vàng nhung, từ từ, chiếc quạt đen đó đã hạ xuống. \n Giống như Evelyn, giống như bạn bè thời thơ ấu của tôi, giống như một cuộc tình thoáng qua mờ ảo... giống như mẹ tôi. \n Đó là một gương mặt đẹp đẽ như tượng thần được dát vàng trong đền thờ. \n Tôi không nghe thấy tiếng hút, cũng không ngửi thấy mùi tanh từ cha, chỉ chăm chú nhìn gương mặt đó, và chủ nhân của gương mặt đó đưa ra một bàn tay trắng muốt, mở nắp đĩa, nhặt lấy miếng thịt phù hợp, cô ấy dùng hai que gỗ mảnh để gắp nó lên, nâng cao. \n Cô ấy gọi tôi, mỡ động vật đã được nướng rơi xuống khóe miệng tôi. \n \"Tiểu tiên sinh, cậu nên ăn một chút.\"\n\n Tôi ngoan ngoãn và ngớ ngẩn mở miệng. \n Hoa ngọc lan đã nở, nó đang lủng lẳng hướng về phía tôi. \n —— \"Nhật ký của người vô danh\"\n"
  },
  CollectionHall_124404_Title = {
    Text = "Mồi hoa ngọc lan"
  },
  CollectionHall_124405_Desc = {
    Text = "\"Lấy lý trí làm ngọn đèn sáng, sẽ xua tan được sương mù cuộc đời.\"\nĐã từ lâu, Mộc Hạ từng nghe câu nói như vậy.\nCó lẽ là lần nào đó kỹ thuật viên của công ty Thoreau buột miệng cảm thán khi đang hiệu chỉnh đèn xua sương? Hay có lẽ là lời đùa cợt của một người qua đường nào đó trong lần cô ghé nhà hàng Fillingen?\nMộc Hạ đã quên mất rồi, điều cô có thể nhớ rõ ràng, chính là nụ cười xã giao quen thuộc trên gương mặt mình khi nghe câu nói ấy, và sự giễu cợt ẩn sau nụ cười đó.\n\"Ngọn đèn sáng ư? Ha, đồ cổ lỗ sĩ quá đi, bây giờ người ta dùng đèn pin rồi.\"\nCô không phải không biết đó chỉ là một phép ẩn dụ, cô chỉ là không thèm hiểu.\nBởi vì rồi sẽ có một ngày, cô sẽ chết. Và sau khi chết, lý trí gì, sương mù gì, đều không còn tồn tại nữa — cô sẽ hoàn toàn giải thoát khỏi thế giới này.\nĐây là suy luận hợp lý và tất yếu. Điều cô cần làm, chỉ là tận hưởng quá trình trước khi cái \"tất yếu\" ấy đến.\nNhưng chưa từng có ai nói cho cô biết, \"tất yếu\" cũng có thể gặp phải \"bất ngờ\".\nSương mù tương tự, khốn cảnh tương tự, nhưng ở đây không có đèn xua sương, không có đoàn điều tra, không có bất cứ thứ gì quen thuộc với cô. Chiếc rìu của cô có thể chém đứt quái vật trên đời, nhưng không thể chém đứt màn sương mù hóa thành từ sự cô đơn và hoang mang của chính mình.\nCô có thể quay về không? Cô sẽ quay về chứ? Rốt cuộc khi nào mới có thể quay về…\nTừng câu hỏi nổi lên từ nội tâm cô, như dòng nước sâu vô hình, từ từ nuốt chửng tâm hồn cô. Lúc này đây, suy nghĩ duy nhất, toàn bộ suy nghĩ trong lòng cô, chính là —\nGiữ lấy lý trí.\nĐừng phát điên! Đừng phát điên! Đừng phát điên!\nDù là đối mặt với sương mù của thế giới kia, sương mù của thế giới này, hay sương mù trong chính nội tâm mình.\nĐể, một lần nữa quay về."
  },
  CollectionHall_124405_Title = {
    Text = "Ngọn đèn lý trí"
  },
  CollectionHall_124407_Desc = {
    Text = "Vào ngày sinh nhật bảy tuổi, cha đặt lên đầu gối cô một chiếc xa quay sợi mang tên \"Moirai\". Cái tên ấy thuộc về ba vị nữ thần số mệnh đã lâu không còn ai thờ phụng, nhưng bản thân chiếc xa quay lại nhẵn bóng và mới tinh, trục đồng lấp lánh ánh kim loại, lạnh lẽo và nặng nề.\nTừ đó, Arachne cầm lấy bánh xe số mệnh, không phải vì lựa chọn, mà bởi những lời vô tình thốt ra luôn ứng nghiệm về sau, cô không thể phớt lờ trách nhiệm đã được định sẵn này.\nTừ đó, cô cứ mãi dệt, ngày qua ngày, nhìn sợi chỉ số mệnh lặng lẽ quay trên chiếc xa quay tinh xảo, dệt nên cho thế nhân sự run rẩy của nụ hôn đầu, tiếng hí của chiến mã, tiếng khóc chào đời của hài nhi, và những nét khắc thô ráp trên bia mộ.\nTừ đó, cô chọn lọc trong muôn vàn sợi chỉ đan xen những hướng đi \"tốt đẹp hơn\", để đại dịch đen tối sớm rút lui, để lịch sử tránh khỏi lửa chiến tranh, để văn minh tái thiết từ đống hoang tàn… Đồng thời, cô cũng dệt nên những sợi chỉ dẫn đến điên cuồng, phản bội hay đêm đen vĩnh cửu, chỉ để duy trì tấm lưới số mệnh trải rộng xuyên không gian và thời gian.\n\"Thế nào mới là tốt đẹp hơn?\"\nChiếc xa quay im lặng không đáp, chỉ tiếp tục quay. Tốt lành, tồi tệ, tân sinh hay cáo phó, đều luân phiên hiện lên trên cùng một sợi chỉ. Khi ấy cô còn trẻ, chưa biết vận mệnh của mình là gì, nhưng đã nhìn thấy kết cục của thế giới ở cuối vô số đầu sợi chỉ.\n\"Nếu thế giới không thể tránh khỏi định mệnh hủy diệt…\"\n\"Không, ta yêu thế giới này.\"\nArachne chăm chú nhìn chiếc xa quay, từ bỏ ý nghĩ chưa kịp nói ra.\n\"Vậy thì… vận mệnh của ta thì sao?\"\nCô thì thầm tự hỏi, chỉ có tiếng vọng trống rỗng lang thang giữa bốn bức tường.\n…\nKhông đếm xuể bao nhiêu nền văn minh đã trỗi dậy rồi sụp đổ trên tấm lưới số mệnh, kim tự tháp ngủ yên trong cát, phi thuyền lướt qua biển sao, ngôn ngữ thay đổi như mùa luân chuyển, tên của thần minh được viết vào những cuốn từ điển phủ bụi… Còn cô vẫn luôn ngồi đó, quay chiếc xa quay trong tay, nhìn nhân loại lặp đi lặp lại vòng tuần hoàn của hy vọng và hủy diệt.\nCho đến một ngày, một tiếng gọi nhẹ nhàng vượt qua ngục tù vĩnh hằng và sự tĩnh lặng vạn cổ.\n\"Chị ơi…\"\nCuối cùng cô thu lại ánh mắt đang hướng về ngày tận thế, nhắm mắt nhìn về phía Nephreia, một bản ngã khác trong cơ thể cô — đôi mắt thuần khiết như trẻ sơ sinh ấy không có phán xét, không có sợ hãi, chỉ có sự tin tưởng tuyệt đối, như một tờ giấy trắng chưa hề chạm bút.\nKhoảnh khắc ấy, Arachne cuối cùng cũng hiểu ra, yêu thương và trách nhiệm, hận thù và hủy diệt, tất cả trước số mệnh đều không có gì khác biệt. Thế là, cô đem những ký ức bị chính tay mình cắt đứt, từ bỏ, những đau thương, tiếc nuối và mất mát lẽ ra đã xảy ra nhưng chưa từng đến, dệt thành một sợi chỉ, như món quà nặng nề nhất cũng dịu dàng nhất, buộc lên cổ tay Nephreia.\n\"Hãy rời khỏi nơi này đi, Nephreia.\" Arachne mỉm cười, \"Em tự do rồi.\"\nArachne không cần nhìn rõ vận mệnh của mình nữa. Bởi vì ngay khoảnh khắc cầm lấy chiếc xa quay năm bảy tuổi, cô đã chọn hướng đi cho tương lai. Và chiếc xa quay số mệnh, sẽ lặng lẽ quay, chứng kiến cuộc chiến không bao giờ hạ màn mà cô sắp dấn thân vào."
  },
  CollectionHall_124407_Title = {
    Text = "Vòng quay định mệnh"
  },
  CollectionHall_124410_Desc = {
    Text = "Ăn đi ăn đi ăn đi ăn đi...\nHuyễn hoặc của ác mộng.\nNghiền nát nghiền nát nghiền nát nghiền nát...\nLời thì thầm của đại dương.\nHủy diệt! Hủy diệt!! Hủy diệt!!! Hủy diệt！！！！\nCơn điên không thể kiềm chế.\n \"Mosk đói quá.\"\nCô gái nuốt những miếng thịt nhỏ giọt máu tươi, nhưng dù ăn bao nhiêu cũng không thể làm dịu đi sự trống rỗng trong dạ dày.\n \"Mosk khát quá.\"\nCô gái nuốt nước biển có mùi tanh hôi, nhưng dù uống bao nhiêu cũng không thể xóa tan đi sự khô khốc trong cổ họng.\n \"Mosk buồn ngủ quá.\"\nCô gái đánh vào bản thân tỉnh táo, nhưng dù ngủ bao lâu cũng không thể kiềm chế sự mệt mỏi trong tư duy.\nBởi vì chỉ có sự hủy diệt thuần túy mới có thể thỏa mãn Thần bên trong cô.\n \"Nhưng, Mosk, đừng!\"\nNhưng cô gái đã từ chối tiếng gọi của số mệnh, thép đặc chế trở thành chiếc lồng mà cô không thể gỡ bỏ.\nCô đã tự tạo cho mình một nhà tù vững như bàn thạch, dùng sự ràng buộc mang tên chính mình, giam cầm cơn điên từ sâu thẳm đại dương.\n \"Mosk, đã bị nhốt lại, kẻ xấu!\"\nĐến đây, từ khi AF 1■■ xuất hiện, nuốt chửng vô số sinh linh, cơn lốc lớn Musk đã hoàn toàn trở về im lặng vào AF 31■.\n\n\n\n\n"
  },
  CollectionHall_124410_Title = {
    Text = "Điên rồ bị giam cầm"
  },
  CollectionHall_124413_Desc = {
    Text = "Trên giá sách, ngoài những tài liệu nghiên cứu khô khan, còn có vài cuốn sách thiếu nhi trông rất thú vị.\n《Cô bé Lọ Lem》, 《Bạch Tuyết》, 《Nàng Tiên Cá》, 《Công chúa tóc dài》…… Chủ nhân của chúng vì sao lại cất những cuốn sách này trên giá — giờ đây đã không thể biết được.\nNhững câu chuyện ấy dệt nên những tình tiết hoàn toàn khác biệt với hiện thực. \"Hoàng tử\", \"Công chúa\", \"Tình yêu\"…… Những từ ngữ ấy khiến trái tim thiếu nữ rung động xao xuyến.\nVô số ánh sáng lấp lánh trên bầu trời đêm đổ xuống mặt đất, tựa như sắp hội tụ thành một dòng sông ánh sáng tuôn chảy.\nTrong ánh trăng tỏa rạng, thiếu nữ lặng lẽ kiễng chân, giả vờ đang mang một đôi giày thủy tinh trong suốt. Dường như luôn mong chờ — đêm dài tĩnh mịch, cô đơn này rồi sẽ bừng sáng……"
  },
  CollectionHall_124413_Title = {
    Text = "Cổ tích trong bùn lầy"
  },
  CollectionHall_124414_Desc = {
    Text = "Người phù thủy già lang thang giữa các thương thuyền, luôn giấu bóng mình trong bóng tối của chiếc áo vải cũ rách nói rằng, la bàn sẽ dẫn dắt mọi người đến nơi Người đó cần đến, các Thủy thủ vừa đùa giỡn vừa chế nhạo những lời vô nghĩa mang mùi thảo dược của bà, ném xuống năm đồng Léofang, đổi lấy vật trang trí bằng đồng thau tinh xảo này.\nRồi họ cập bến ở cảng thị trấn sau này mất đi tên gọi, Pontos thích câu chuyện này, chủ nhân của la bàn thích Pontos.\nTất nhiên, không ai không thích Pontos — hài hước, vui vẻ, đến đi phóng khoáng như một làn gió.\nLẽ ra nó phải là một kỷ niệm tốt đẹp, là chiếc chìa khóa mà Pontos tặng lại cho người cháu trai thân yêu của mình để mở ra những tưởng tượng về phương xa — nhưng nó khiến Pontos không tìm được anh ta, Pontos không cho phép, và tuyệt đối sẽ không để cuộc sống của anh ta có một khả năng nào khác.\nKhi nhiều năm trôi qua, Pontos băng qua vô số đêm tối dưới ánh trăng, tìm kiếm bóng hình lẽ ra phải trở về Epoyanth, anh đã nghĩ như vậy.\nÔi, phép thuật bảo vệ vô ích kia đã rời khỏi anh ta rồi, Pontos bây giờ có thể đưa anh ta trở về.\nChỉ là Pontos chưa biết, \"la bàn sẽ dẫn dắt mọi người đến nơi Người đó cần đến\", như mỗi con tàu đều có hành trình riêng của mình, những người khác nhau luôn sẽ chọn những hướng đi khác nhau."
  },
  CollectionHall_124414_Title = {
    Text = "La bàn chỉ đường lạc lối"
  },
  CollectionHall_124415_Desc = {
    Text = "\"Bạn có muốn mua một que diêm không?\" Đêm đông, cô bé tay chân đỏ cóng thì thầm, \"Một que, chỉ một que diêm thôi.\"\n\"Xin lỗi nhé, tôi sẽ không mua diêm của bạn,\" bóng trắng tinh khẽ cúi người, che khuất vầng trăng mùa đông, \"Ngược lại, tôi còn muốn bán cho bạn một thứ gì đó.\"\n\"Nhưng, tôi không có tiền…\"\n\"Không sao. Hãy tin vào ân sủng của tiên nữ đi, bạn sẽ sớm bán được diêm thôi.\"\nCô tiên áo trắng nhét một viên kẹo vào tay cô bé, rồi ghé sát tai cô bé.\n\"Thấy người phụ nữ trung niên mặc áo choàng lông thú bên kia đường không? Hãy túm lấy vạt áo bà ấy, khóc thật to, nói rằng thưa bà tốt bụng, trời lạnh quá, bà nội con bị bệnh nặng, nếu không được ăn một bữa no, bà sắp chết vì bệnh rồi, xin bà hãy cho con ít tiền.\"\n\"Nhưng mà, bà nội đã rời xa con từ lâu rồi…\"\n\"Vậy càng tốt! Hãy thử bắt chước cảm giác lúc đó, khóc cho thật thật vào…\"\n\"Nếu bà ấy vẫn keo kiệt không chịu móc tiền ra, tôi cũng có cách khác. Người còn lang thang ngoài trời vào đêm giao thừa như thế này, gia đình chắc chắn không hạnh phúc. Thì bạn hãy thêm vào, bà nội là người thân duy nhất của con, hôm nay là đêm giao thừa, ai cũng không muốn cô đơn một mình, xin bà, thưa bà xinh đẹp, chỉ cần ba xu thôi, để con sớm bán hết diêm, về đoàn tụ với bà nội.\"\n\"Diêm một xu…\"\n\"Hai xu còn lại, một xu là phần trăm của tôi, còn một xu phải cúng cho nó.\" Caraboo lắc lắc cây gậy phép trong tay, con sâu trắng đang ngủ chảy ra như sóng nước.\n\"Đừng nghĩ nhiều, cứ tin vào ân sủng của tiên nữ là được, chiêu này chắc chắn trăm trận trăm thắng. Nhớ nhé, trước khi bà ấy móc tiền ra, tuyệt đối đừng buông tay. Nếu thất bại, chúng ta lại đi tìm bà quý tộc cô đơn tiếp theo thôi. Yên tâm đi, ở cái thế đạo này, phụ nữ có tiền dư đủ để nuôi cả hai chúng ta.\"\nTại sao phương pháp trăm trận trăm thắng lại có thể thất bại, chẳng ai còn muốn truy cứu nữa. Tóm lại, sau khi cập nhật một trăm tám mươi hai bộ lời thoại, những que diêm của cô bé đã bán hết sạch.\nTrong câu chuyện mà \"bà tiên đỡ đầu\" thực sự không xuất hiện, cô tiên giả mạo cũng đã cứu được cô bé nghèo khổ đáng thương đang trên bờ vực chết cóng.\nĐáng mừng thay, đáng mừng thay."
  },
  CollectionHall_124415_Title = {
    Text = "Chân Lý Thanh Yên"
  },
  CollectionHall_124844_Desc = {
    Text = "<Title:Tóm tắt>\nCô gái bí ẩn đến từ Thái Mô Lân. Theo mô tả của cô, nguyên bản là sinh viên chuẩn tại một trường đại học địa phương, vì một \"cuộc gặp gỡ lãng mạn như số phận\" mà trở thành tiền phong của Đoàn điều tra sương mù.\nTrong sự kiện \"Thảm họa sương mù\" của Hội Phồn Tinh Lê Minh, Mouchette vô tình được gọi đến thế giới này, sau đó trong nghi thức giữa bạc và máu, cô đã trải qua lễ rửa tội, từ con người biến thành Thể thức tỉnh, và kết thúc \"Thảm họa sương mù\".\nỞ trong thế giới không thuộc về mình, cô vẫn tìm kiếm cách trở về, nhưng đồng thời, cô cũng đầy hứng thú với tương lai của thế giới này, khao khát chứng kiến \"kết thúc của thế giới\"."
  },
  CollectionHall_124844_LockTip = {
    Text = "Mở khoá sau khi đánh thức \"Mộc Hạ\""
  },
  CollectionHall_124844_Title = {Text = "Mouchette"},
  CollectionHall_125443_LockTip = {
    Text = "Cần hoàn thành bất kỳ màn chơi nào trong sự kiện giới hạn thời gian \"Hải Thành Cổ Văn: Huyễn Nữ Vô Hình\""
