  },
  CollectionHall_126315_LockTip = {
    Text = "Cần hoàn thành bất kỳ màn chơi nào trong sự kiện giới hạn thời gian \"Kẻ Dệt Tự Trói: Sân Khấu Của Rối\""
  },
  CollectionHall_126315_Title = {
    Text = "Kẻ dệt tự trói: Sân khấu con rối"
  },
  CollectionHall_126425_LockTip = {
    Text = "Có thể mở khóa tại Điều tra Hành động Thiên Thể thiên 4-1"
  },
  CollectionHall_126425_Title = {
    Text = "Hình bóng Muphí"
  },
  CollectionHall_126471_Desc = {
    Text = "Mouchette đã quen với sự tồn tại của sương mù từ lâu. \n Dù là sương mù khó chịu đến đâu, sương mù nguy hiểm đến đâu, cô ấy luôn có thể bình an bước ra từ đó. \n Lần này cũng vậy. \n Cuối cùng cô ấy sẽ bước ra khỏi sương mù của thế giới mới, trở về chiều không gian thuộc về mình. \n Dù phải trả giá như thế nào."
  },
  CollectionHall_126471_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Lễ rửa bạc và máu\""
  },
  CollectionHall_126471_Title = {
    Text = "Khám phá sương mù của thế giới mới"
  },
  CollectionHall_126472_Desc = {
    Text = "Sương mù cuối cùng cũng sẽ tan biến. \n Lúc đó, những tiếng thét vang vọng trong sương mù sẽ lắng lại, những vết máu chảy trên bàn thờ sẽ được lau sạch. \n Linh hồn lạc lối sẽ được giải thoát, tìm thấy con đường đúng đắn - \n đến với những vì sao lấp lánh, hoặc lưu lại trên mảnh đất thật."
  },
  CollectionHall_126472_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Lễ rửa bạc và máu\""
  },
  CollectionHall_126472_Title = {
    Text = "Thời điểm sương mù tan biến"
  },
  CollectionHall_126473_Desc = {
    Text = "Vũ trụ mang thai thế giới, thế giới mang thai sự sống. Và sự sống của các thế giới khác nhau lại mang thai ra những quy tắc và lý tưởng khác nhau. \n Khi họ giao tranh, cuộc chiến không chỉ là giữa hai cơ thể, hai ý chí, hai sự sống. \n Đó là sự va chạm của hai vũ trụ, song song vĩnh cửu nhưng lại đột ngột giao nhau."
  },
  CollectionHall_126473_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Lễ rửa bạc và máu\""
  },
  CollectionHall_126473_Title = {
    Text = "Cuộc chiến của niềm tin"
  },
  CollectionHall_126474_Desc = {
    Text = "Sau khi kết thúc nhiệm vụ, tôi sẽ tạm biệt phiên bản quá khứ của mình. \n Tạm biệt những quá khứ quen thuộc mà không thể trở lại, tạm biệt Taimulan và phiên bản mình thời còn là con người. \n Tôi sẽ nhớ thế giới đầy sương mù đó. \n Từ giờ trở đi, tôi sẽ sống với một danh tính mới, tồn tại trong thế giới này khi sương mù tan biến, thế giới đầy thú vị và kinh dị này."
  },
  CollectionHall_126474_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Lễ rửa bạc và máu\"độ khó cao"
  },
  CollectionHall_126474_Title = {
    Text = "Sinh mới của Người nói sương"
  },
  CollectionHall_126475_Desc = {
    Text = "Dưới thế giới tàn khốc, linh hồn của một người có thể dễ dàng bị thiêu rụi. \n Vì vậy, chúng ta tìm kiếm từ người khác và thế giới, tình cảm gia đình, tình yêu, tình bạn, nỗi nhớ quê hương… \n Những cảm xúc không thể chạm tới ấy, từ đây trở thành sức mạnh vô hình, sự sống tiếp diễn, giúp mọi người cháy lâu hơn trong thế giới này, lâu hơn một chút…"
  },
  CollectionHall_126475_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Lễ rửa bạc và máu\""
  },
  CollectionHall_126475_Title = {
    Text = "Trí tuệ sinh tồn tàn khốc"
  },
  CollectionHall_126476_Desc = {
    Text = "Những vì sao từ cổ chí kim đã chứng kiến sự ra đời, trưởng thành và thịnh vượng của thế giới, chúng cũng sẽ chứng kiến sự kết thúc của thế giới. \nÔi những người khao khát sự sống, cách duy nhất để tồn tại không nằm dưới chân chúng ta, không nằm trên mảnh đất đã phản bội chúng ta, mà ở trên đầu chúng ta, nơi những vì sao vĩnh cửu tỏa sáng."
  },
  CollectionHall_126476_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Lễ rửa bạc và máu\""
  },
  CollectionHall_126476_Title = {
    Text = "Nơi tinh tú lấp lánh"
  },
  CollectionHall_126477_Desc = {
    Text = "Cứu thế giới không phải là phong cách của cô ấy, và nơi đây, cũng không phải là thế giới của cô ấy. \n Nhưng cô ấy đã nghe thấy giọng nói của Người Giữ Gìn, đã thấy Người Giữ Gìn hy sinh to lớn để cứu thế giới. \n Thế giới được người khác liều mạng bảo vệ, không nên bị hủy diệt. \n Ít nhất trong khoảnh khắc này, không nên do chính cô hủy diệt."
  },
  CollectionHall_126477_LockTip = {
    Text = "Hoàn thành kết nối đa chiều \"Lễ rửa bạc và máu\"độ khó cao"
  },
  CollectionHall_126477_Title = {
    Text = "Lựa chọn không thể hiểu"
  },
  CollectionHall_126906_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Đàm thoại dưới quạt\" mở khóa bất kỳ cấp độ nào"
  },
  CollectionHall_126906_Title = {
    Text = "Tập thơ khóc đêm"
  },
  CollectionHall_126989_Desc = {
    Text = "<Title:Tóm tắt>\nNguồn gốc thực sự của cô ấy thì đã không thể xác minh, tài liệu ghi chép sớm nhất về vị \"thần thánh\" cổ xưa này dường như có thể truy nguyên từ hàng ngàn năm trước.\nMỗi người nhìn về phía cô ấy đều sẽ thấy những diện mạo khác nhau, thực tế có khả năng không biết mà ô nhiễm trí nhớ của người khác, có thể một cách tiềm thức hòa nhập hình ảnh của mình vào trí nhớ của đối phương, cuối cùng khiến đối phương nhận thức mình là người quan trọng duy nhất.\nKhác với hầu hết các thể thức tỉnh khác, cô ấy gần như không có cảm xúc và góc nhìn thuộc về con người.\nCô ấy là một ý niệm, một cơn cuồng tưởng, một làn sương - cô ấy được cảm nhận là Tuần, được cảm nhận là Lưu, Lý, Tiền, Trương, cô ấy sinh ra trong hạnh phúc, cũng theo đuổi niềm vui đến từ sự hỗn loạn không ngừng.\nNhưng cô ấy không hoàn toàn không thể hiểu, sự tồn tại khó có thể định nghĩa, những cá nhân mà cô ấy chọn, những cá nhân mang lại cho cô sự vui vẻ tột độ, sẽ có cơ hội dòm trộm vào cái tên thực sự có thể định nghĩa họ, không biến đổi vô thường như các danh xưng khác.\n \"Ngàn Quạt Huyền Nữ\"."
  },
  CollectionHall_126989_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"Tuần\""
  },
  CollectionHall_126989_Title = {Text = "Xu"},
  CollectionHall_127110_Desc = {
    Text = "Đao hai tay dài và nặng, với đủ lực có thể chém người thành hai đoạn. \n\n Dao găm nhẹ nhàng linh hoạt, dễ dàng ẩn giấu, rất phù hợp cho những cuộc tấn công bất ngờ. \n\n Dao cong có đường cong đẹp mắt, lưỡi dao sắc bén, khi chém có thể dễ dàng đâm vào da thịt, tạo ra một vết thương sâu. \n\n Súng nhanh và mạnh mẽ, tên nỏ im lặng và nhanh chóng, các bộ phận kim loại khác nhau lấp lánh dưới ánh đèn. Ramona mười tuổi đứng trước bức tường đầy vũ khí, khuôn mặt mang vẻ trưởng thành và cẩn trọng không phù hợp với tuổi của cô. \n\n \"Con muốn chọn cái nào?\" Giọng của cha nuôi — không, là người đã nuôi dưỡng cô lớn lên — vang lên từ phía sau, \"Chọn xong rồi, tôi sẽ đi tìm thầy giáo cho con.\"\n\n Cái nào nhỉ? Đao hai tay nặng nề vừa là ưu điểm vừa là nhược điểm; dao găm khó đối phó với vũ khí dài; dao cong tuy dài nhưng việc cắt luôn gây ra nhiều thương không cần thiết; súng ồn ào quá, tên nỏ dễ hết đạn. \n\n Sau nhiều ngày quan sát tại sân tập Misaque, cô biết mình có thể nhìn ra điểm yếu của cả hai bên chiến đấu và lập kế hoạch tấn công gần như trực giác. Những điều cần nhiều kinh nghiệm để biết, ở cô chỉ mất một giây để suy luận. Không, cô không cần những thứ đó. Cô cần một vũ khí chính xác hơn, có thể gây ra nhiều nhất thương với ít lực nhất. \n\n Cô bé suy nghĩ một lúc, kéo một chiếc ghế từ bên cạnh, đứng lên và với tay lấy thanh kiếm mảnh treo cao. \n\n Thanh kiếm mảnh mai thanh lịch, linh hoạt nhẹ nhàng, có thể gây ra thương chính xác — đúng rồi, chính là nó, nó đáp ứng mọi yêu cầu của cô."
  },
  CollectionHall_127110_Title = {
    Text = "Đảo ngược thời gian"
  },
  CollectionHall_127111_Desc = {
    Text = "\"Khi một thế giới đang tiến đến ngày tận thế, sẽ xảy ra những niềm vui gì?\"\nMộc Hạ không biết, nhưng cô ấy đang mong đợi. \nCảm giác mong đợi này khác với trước đây, lần này không phải là những niềm vui nhỏ bé từ việc đánh bại vài cổ vật, mà là một nghiên cứu và khảo sát với quy mô của cả một thế giới. Và trong nghiên cứu và khảo sát này, điều quan trọng và cốt lõi nhất chính là một người——\nNgười Giữ Gìn của Misaque. \n \"Tôi sẽ cứu lấy thế giới này...\"\n \"Thế giới này, nhất định sẽ không đi đến số phận sụp đổ...\"\nNgười mang trong mình lý tưởng, gánh vác sự sống chết của cả một thế giới đã hứa như vậy. Để đáp lại, Mộc Hạ biết mình nên thể hiện vẻ mặt cảm động, đó là quy tắc xã giao đã được xã hội nhân loại quy ước. \nNhưng cô không muốn giả vờ nữa, hoặc nói đúng hơn, sau khi chứng kiến Người Giữ Gìn đối mặt với @4, hy sinh bản thân để cứu lấy một thế giới, cô cảm thấy không cần thiết phải giả vờ trước người đã trải qua nỗi kinh hoàng của vũ trụ. \n \"Giả vờ\" là quy tắc trò chơi của xã hội nhân loại, trang nhã nhưng nhàm chán, còn vũ trụ... vũ trụ thì chân thực và rõ ràng——\nhoặc là sinh tồn, hoặc là hủy diệt. \nVì vậy, câu trả lời của cô đối với Người Giữ Gìn cũng chân thực và rõ ràng. \n \"Tôi không quan tâm thế giới này có được cứu rỗi hay không, hoặc sẽ bị hủy diệt... So với những điều đó, tôi tò mò về bạn hơn.\"\nTôi tò mò liệu bạn có thể thực hiện lý tưởng của mình hay sẽ gục ngã trên con đường theo đuổi lý tưởng. \nCũng tò mò liệu thế giới này có đáp lại mong muốn của bạn hay không, hay sẽ không thể tránh khỏi việc đi đến hủy diệt. \nDù là loại nào, cũng sẽ là một niềm vui lớn lao và hiếm có. \nTôi sẽ luôn mong chờ ngày đó... \nbằng đôi mắt của tôi, bằng chiếc rìu của tôi, chờ đợi."
  },
  CollectionHall_127111_Title = {
    Text = "Cuồng sát đến tận cùng thế giới"
  },
  CollectionHall_127112_Desc = {
    Text = "\"Ký ức là gì?\"\n \"Là thứ bạn đã quên.\"\n\nLily có một người mẹ hay quên. \nCô ấy sẽ quên gọi Lily cùng ăn cơm, quên cho Lily uống thuốc, thậm chí còn quên cả tên của Lily. \n \"Phải làm sao đây?\"\nLily ngồi trên giường bệnh, thở dài một cách nghiêm túc. \nMột người mẹ như vậy thật phiền phức. \n\nSau đó, Lily viết tên mình lên một tấm bảng gỗ, mỗi ngày đeo trước ngực. \nNhư vậy chắc sẽ nhớ cô ấy rồi chứ? \nBan đầu, mẹ vẫn còn cười nói rằng cô ấy đang làm việc thừa thãi, chỉ là biến chứng do làm việc quá nhiều. \n\nDần dần, bà bắt đầu bối rối, không kiên nhẫn: \n \"Lily... Lily là ai?\"\nĐôi mắt màu hổ phách nhìn chằm chằm vào Lily, mang theo một chút dè chừng. \nThì ra, khi ý nghĩa của chữ viết cũng bị quên, mối quan hệ tạm thời được duy trì bằng ngôn ngữ cuối cùng cũng sẽ tan vỡ. \n\nLily ôm lấy mẹ. \nTrái tim của hai mẹ con chỉ cách nhau vài inch, nhưng cô cảm thấy cô đơn vô cùng. \n\nTừ ngày đó, Lily cất đi tấm bảng, không còn nũng nịu mẹ, cũng không còn nhắc nhở rằng cô đã đói nhiều ngày. \nCô là bệnh nhân sắp chết, chờ đợi sự phán quyết của thần chết một cách tê dại. \nCô là khán giả đứng bên lề, nhìn từ xa mình bị tiêm, bị mê man, bị biến thành bất cứ hình dạng nào mà mẹ hy vọng. \nNhững lời nói vui vẻ, những cái ôm mềm mại giữa mẹ và con... \nNhững kỷ niệm vui vẻ lấp lánh như bong bóng ảo mộng, Lily cẩn thận khóa chúng trong lòng. \nChỉ vào những đêm mệt mỏi, cô mới sẵn sàng lấy chúng ra, nhẹ nhàng liếm láp."
  },
  CollectionHall_127112_Title = {
    Text = "Vượt qua nỗi đau"
  },
  CollectionHall_127113_Desc = {
    Text = "Tháp cao sừng sững đổ sụp ầm ầm, những cuốn sách do các học giả từ các thời không và chủng tộc khác nhau viết bị rơi rớt khắp nơi, chỉ trong một khoảnh khắc, những tam giác đen lớn nhỏ đã bao phủ lên từng quyển sách, từng viên gạch, và nhanh chóng kết nối thành một mảng lan rộng ra xung quanh. \n Chất lỏng màu đen như dung nham chảy trên những con đường ngăn nắp, người dân hét lên, khóc lóc, cố gắng chạy trốn khỏi thảm họa khủng khiếp này. Nhiều người cố gắng sử dụng phương tiện để thoát thân nhưng trong cơn hoảng loạn đã đâm vào các tòa nhà hoặc tàu vũ trụ và xe cộ gặp tai nạn; nhiều người khác không kịp phản ứng, chỉ có thể chạy bộ theo hướng xa rời chất lỏng, nhưng bị những người cũng đang kinh hoàng đẩy ngã xuống đất, cuối cùng bị chất lỏng đồng hóa. Trẻ em đứng bên đường khóc lớn, vài người trẻ tuổi ẩn nấp trong những tòa nhà còn sót lại, mơ hồ nghĩ rằng như vậy có thể tránh được cái chết. \n \"Rõ ràng không có điềm báo, tại sao, tại sao!\"\n \"Tại sao không ai cảnh báo chúng ta!\"\n \"@1, là rỗng rỗng! Cứu tôi với!\"\n \"Hãy tiến hành di chuyển ý thức! Chỉ có như vậy mới— a!\"\n \"@2, mau dùng thiết bị!\" một giọng nói vang lên, \"Chúng tôi sẽ giúp cô kéo dài thời gian!\"\n \"Không! Tôi—\"\n \"Chúng tôi đã bị @1 rồi, còn cô, cô vẫn còn hy vọng.\" một giọng nói nhẹ nhàng đáp lại, \"Sống sót, @2, sống sót. Và rồi—\"\n\n Wenkel đột nhiên mở to mắt, bên cạnh cô là những chồng sách cao ngất, mấy chiếc cốc đầy vết cà phê. Ở phía xa, trên bảng đen dán đầy những mẩu giấy nhớ và ghi chú lớn nhỏ, kèm theo đó là một công thức tính toán dang dở. Trong căn phòng lộn xộn, ở góc, ở giữa, và gần chiếc máy lớn mà cô đang ngồi đều có đèn chiếu sáng, khiến cả văn phòng trở nên vô cùng sáng rõ. \n Cô im lặng một lúc, thu mình hơn vào thiết bị định vị, tiếp tục thực hiện phép tính bị gián đoạn."
  },
  CollectionHall_127113_Title = {
    Text = "Nhân tố không xác định"
  },
  CollectionHall_127114_Desc = {
    Text = "Đau đớn, cơn đau dữ dội tràn ngập tất cả các giác quan của cô ấy. \n\n Bộ đồ lặn bằng kim loại dưới áp lực nước trở nên vô nghĩa, vỏ bọc bị lõm vào trong, ốc vít bị nứt, có cái gì đó đè lên khoang bụng của cô, có cái gì đó xuyên qua cánh tay của cô. Nước biển lạnh lẽo chảy vào từ chỗ hỏng của bộ đồ lặn, chỉ có chiếc mũ bảo hiểm bằng kim loại dày là còn giữ được hình dạng, bảo lưu cho cô một chút oxy mong manh. \n\n Qua cửa sổ quan sát duy nhất của chiếc mũ bảo hiểm, cô thấy nước biển bên ngoài từ xanh lam chuyển sang xanh đen, rồi từ xanh đen trở thành đen tối. Hơi nước từ việc hô hấp ngưng tụ trên kính, tiếng ầm ầm của cơn xoáy dần dần xa xôi, trở thành ảo ảnh còn sót lại trong tai. Cô dần dần không cảm nhận được các chi của mình, việc hô hấp cũng trở nên nặng nề hơn. \n\n Cô đoán rằng mình có lẽ đã ngất đi, lạnh, mất máu, thiếu oxy, mỗi điều đều đủ khiến ý thức của cô mờ mịt. Đồng thời cô không thể xác định, vì dù cô có nháy mắt thế nào, trước mặt vẫn chỉ là một màu đen tối giống nhau. \n\n Đây là nơi ánh sáng không thể đến, là lĩnh vực sâu thẳm của đại dương chưa ai khám phá. \n\n Một cảm giác hưng phấn chậm chạp cuối cùng khuấy động dòng máu trong cô — lĩnh vực chưa biết, cuộc phiêu lưu cuối cùng. Cô có thể coi đây là hoàn thành ước mơ của mình không? Dù bây giờ cô không nhìn thấy gì cả. \n\n Một cảm giác kỳ lạ từ mắt cá chân truyền đến, cô vô thức cúi đầu nhìn xuống, phát hiện trong bóng tối, dường như có cái gì đó đang leo lên dọc theo bắp chân của cô. Có phải là sinh vật biển kỳ lạ không, sao mà lạnh hơn cả nước biển? Sao…… Trong bóng tối như thế này, cô dường như có thể thấy được hình dáng của nó? \n\n Đen tối, đang di chuyển, như bùn lầy…… \n Đây là cái gì? Cô đang ở đâu? Cô…… là ai?"
  },
  CollectionHall_127114_Title = {
    Text = "Vòng xoáy ký ức"
  },
  CollectionHall_127115_Desc = {
    Text = "(Dưới đây là một đoạn trích từ cuốn hướng dẫn chẩn đoán của Clementine, chỉ để tham khảo)\n\n1. Kẻ khắc sét. \n2. 16, 17...? Trời mới biết. \nSau khi người ta chết rồi thì còn quan tâm những thứ vô dụng này làm gì? \n3. Một ngôi làng chài rách nát, bạn không thể tìm thấy tên nó trên bất kỳ bản đồ nào. \n4. Tôi không muốn nói. \n5. Quái thai. Xấu xí. Ngu như heo. Ngốc@1... những cái này khá phổ biến. \n6. Khuôn mặt cá trê vàng lấp lánh, gọi tắt là mặt cá trê. \n7. Trời mưa. \n8. Tôi không biết. Khi trời mưa, tôi sẽ đi qua lại trên bãi biển... \nĐã vài năm rồi, chỉ nhìn về phía xa, không làm gì khác. \n9. Tôi đã bảo là tôi#¥%không biết@1cút!! \n------- \n14. Hmm... có lẽ chú Owen từng nói với tôi rằng ông ấy sẽ lái một con thuyền buồm lớn đến đón tôi \"về nhà\" khi trời mưa... \n15. Đúng vậy, ông ấy đã giữ lời hứa... \nTôi đã trôi nổi dưới đáy biển mấy ngày, vừa khát vừa đói, đau khắp người... \nRồi tôi nhìn thấy chú Owen và con thuyền buồm trắng của ông ấy. \nToàn bộ cơ thể ông ấy, à không, chính xác hơn là bộ xương của ông ấy treo trên cột buồm——ông ấy cũng đã thất bại trong việc chuyển hóa. \nRồi tôi dùng hết sức lực cuối cùng trôi tới đó, ngồi trên cột buồm để bầu bạn cùng ông ấy. \n16. Chúng tôi đã hẹn sẽ cùng nhau về nhà."
  },
  CollectionHall_127115_Title = {
    Text = "Vảy cả đau nhói"
  },
  CollectionHall_127116_Desc = {
    Text = "\"Người ta sinh ra khi thủy triều dâng lên, chết đi khi thủy triều rút xuống.\"\nĐây là truyền thuyết vẫn luôn được lưu truyền ở quê hương của Ninh Phi Nga. \n\nNgười dân Sevada không sợ hãi cái chết, trong mắt họ, sự nảy mầm và héo úa của sức sống giống như thủy triều lên xuống, đều là một phần của tự nhiên. \nHọ yêu thích bầu trời xanh, biển cả, đàn hải âu bay lượn, và hoa loa kèn nở rộ dưới ánh mặt trời. \nHọ căm ghét hơi nước, đường sắt, và mọi thứ có dấu hiệu can thiệp nhân tạo quá nặng nề —— bao gồm cả can thiệp vào sức sống. \nViệc cắt đứt sức sống một cách nhân tạo, đối với người Sevada, là điều không thể chấp nhận được. \n\nNinh Phi Nga không phải là một người Sevada điển hình. \nVí dụ, cô luôn bị thu hút bởi bầu không khí của những con tàu đắm. \nMột con tàu đắm chết là ngôi nhà của vô số sinh mạng: cá, cỏ biển, các loại sò... \nỞ đây, sự sống và cái chết đan xen với nhau theo cách bí ẩn, thanh tao. \nNinh Phi Nga tiếp cận con tàu đắm với lòng bình yên, như bước vào một nhà thờ lớn trang nghiêm. \n\nTrong những năm tháng cha đưa cô đi du lịch để giải sầu, Ninh Phi Nga đã xem một vở kịch năm màn. \nVề nội dung của vở kịch đó, Ninh Phi Nga đã mờ nhạt, dường như kể về cuộc đời của một vị hoàng đế cổ đại. \nÔng ta sống cuộc đời chinh chiến khắp nơi, nhưng lại chết vì một âm mưu nhục nhã. \nCô nhớ một câu thoại trong đó: \n<Italic:Những kẻ hèn nhát đã chết nhiều lần trước khi thực sự chết; còn người anh hùng chỉ chết một lần trong đời.>\n\nNhiều năm sau, khi Ninh Phi Nga bước vào dòng nước lạnh lẽo, nhưng lại đau khổ vì sự gắn bó với sức sống, câu nói đó lại hiện lên trong đầu cô: \n \"Người anh hùng chỉ chết một lần trong đời...\"\nVì vậy, cô lau khô nước mắt, lần cuối cùng chào tạm biệt cha mẹ, rồi tiếp tục tiến về con tàu đắm trong lòng mình. \nCô sẽ trở thành người anh hùng của chính mình."
  },
  CollectionHall_127116_Title = {
    Text = "Món quà suy tàn"
  },
  CollectionHall_127117_Desc = {
    Text = "@1 năm 6 tháng 5\nAlbino đã mang về một số bạc tâm hiếm từ rã nứt. Thật có hắn.\nCải tiến lại phương pháp tinh chế.\nLần này đã cung cấp đủ khí carbon dioxide và clorua, bốc hơi ở nhiệt độ thấp, kết tinh...\nMột số bước cơ học, không có gì đáng ghi chép.\n\n@1 năm 6 tháng 6\nCắt bỏ nội tạng và chi của mẫu thử 024.\nĐây là chất liệu mà Albino mang về từ phòng khám, đã hình thành 13 lỗ rỗng rỗng, đường kính lớn nhất 8mm.\nCắt bỏ các khối u của quái vật rỗng rỗng OS-106.\nTheo so sánh dữ liệu thử nghiệm, sự cảm ứng giữa nó và 024 là cao nhất.\nVấn đề duy nhất... những râu chạm quá \"hoạt bát\".\nTôi nghĩ trong một thời gian dài tôi sẽ không muốn ăn bạch tuộc nữa.\nHy vọng kết quả cuối cùng không làm tôi thất vọng.\n\n@1 năm 6 tháng 6\nThí nghiệm ghép nối thành công, các dấu hiệu sức sống của mẫu thử biến mất.\nĐây là tình trạng thường gặp, chỉ cần đảm bảo rằng khu vực ghép nối không bị lây nhiễm lan rộng.\nGửi vào phòng quan sát trong một tuần, tiếp theo không phải là công việc của tôi nữa.\nHôm nay đọc được hai bài viết chỉ trích thí nghiệm thân thể được đánh thức trên \"tạp chí nội bộ\".\nKhông cần nói, tên ký tên rõ ràng là những người bạn cũ của tôi ở Misaque.\nThật buồn cười, nếu những kẻ cổ hủ này chịu di chuyển cái mông béo của họ, đi dạo qua phòng thí nghiệm, họ sẽ biết kết luận của tôi là không thể lay chuyển.\nThí nghiệm 024 sẽ trở thành một cuộc phản công tuyệt vời.\n\n@1 năm 6 tháng 22\nHai tuần đã trôi qua, các dấu hiệu sức sống của 024 vẫn không ổn định — hoặc nói cách khác, nhân cách bên trong cô ấy đang tăng sinh điên rồ với tốc độ phân chia tế bào.\nThí nghiệm đã thất bại theo cách không thể tin nổi.\nGửi 024 đến bình tượng nến đi, tôi không cần nó đứng canh tôi mỗi ngày, để nhắc nhở tôi về sự ngu ngốc và liều lĩnh của mình."
  },
  CollectionHall_127117_Title = {
    Text = "Sự phản đòn của cơ thể biến dạng"
  },
  CollectionHall_127118_Desc = {
    Text = "Đó là một trái tim bạc trắng, trong suốt, không tì vết. \n Nó được làm từ bạc nguyên chất, nhịp đập có trật tự trong trái tim của cơ cấu cơ khí. \n Nó cũng từng bị thịt máu xói mòn, cũng từng bị bùn lầy làm ô uế. \n Nhưng khi bóng ma của cái chết bao trùm, nó cuối cùng đã trở về hình dạng nguyên thủy của mình."
  },
  CollectionHall_127118_Title = {
    Text = "Trái tim bạc"
  },
  CollectionHall_127119_Desc = {
    Text = "Thời gian trôi qua, lơ-tan đã không còn nhớ rõ lắm về ký ức của thời điểm hành tinh mới sinh. \nCô chỉ nhớ rằng, mình là một sinh linh được chọn. \n\nĐó là câu chuyện xảy ra trước khi mọi khái niệm ra đời. \n「Sức sống」chưa kịp bén rễ, 「thần minh」cũng xa xôi ngoài trời cao. \nTrong đám mây sao hỗn loạn, hỗn độn va chạm với nhau, vật chất dần thành hình trong sự va đập và khuấy đảo. \nHành tinh nhỏ thu thập bụi sao, đá núi nhô lên thành hình, khí quyển lắng xuống thành những vùng nước lớn. \nRồi, nơi đây được tuyên bố trở thành một 「hành tinh」. \n\nLinh hồn hỗn loạn bị giam cầm trong nhà tù của thời gian, va đập vào đất mới sinh. \nKhông thể kiểm soát bản tính tàn bạo, bị dục vọng phá hủy điều khiển, Người ấy đã làm sụp đổ vô số dãy núi, lấp đầy vô số dòng sông. \nRồi——「thần minh」đã vượt qua các vì sao xa xôi, giáng xuống hành tinh hoang vu. \n\n「thần minh」đem đến hạt giống của văn minh, cũng giam giữ linh hồn hỗn loạn trong thân thể của 「trật tự」. \n「Hãy……kết một giao ước với tôi.」 \nĐối mặt với linh hồn hỗn loạn đang gầm thét, thần minh bọc trong vải trắng thì thầm. \n「Một nền văn minh vĩ đại sẽ ra đời ở đây.」 \n「Bạn sẽ gặp những trí giả vô vi, sẽ đối đầu với những lưỡi kiếm do dự……trong tương lai, bạn sẽ không còn bị kiểm soát bởi sự phá hủy và hủy diệt.」 \n「Trước khi ngày đó đến……trước khi chúng ta tái ngộ, hãy thay tôi bảo vệ nơi này.」"
  },
  CollectionHall_127119_Title = {
    Text = "Thần thú nơi thiên đường"
  },
  CollectionHall_127120_Desc = {
    Text = "Anh ta được Đại công chỉ định làm hiệp sĩ khi mới chỉ chứng kiến bảy mùa trên thế giới. \n\nLời đùa của Đại công với đứa trẻ đã bị mọi người coi là thật. \nCác hiệp sĩ huấn luyện anh ta về cưỡi ngựa và võ nghệ, các nữ quan dạy anh ta về lễ nghi, và công chúa cũng tin tưởng và dựa vào hiệp sĩ nhỏ bé này. \n\nDạo bước trên đồng cỏ cao nguyên của Aquitaine và thung lũng, hiệp sĩ trẻ tuổi dắt ngựa của công chúa. Công chúa nằm bất lực trên lưng ngựa, bóng tối vô hình đang tiêu thụ thân thể cô. \n\n \"Công chúa, chúng ta không thể đi tiếp nữa.\"\nQua thung lủng này, qua dòng sông kia, sẽ rời xa đất đai nuôi dưỡng họ. \nChiến tranh lan rộng bên ngoài, kẻ thù dòm ngó mảnh đất màu mỡ từ bên kia bờ. \nVới rào cản tự nhiên, mảnh đất nhỏ bé có thể sống sót, duy trì danh dự của một \"quốc gia\". \nTại đầu thung lủng, họ chứng kiến sự sụp đổ và nỗi đau bên kia bờ. \nLời cầu nguyện và nỗi buồn của những người vô tội rơi xuống dòng sông, trở thành một phần của bài thơ chiến thắng. \n\nDù là quốc gia vĩ đại đến đâu, cũng không thể cản được bị cuốn vào dòng lịch sử. \n\nKẻ thù chặt đứt đôi tay non nớt, anh ta không còn có thể cầm giáo và khiên. \nKẻ thù dẫm nát đôi chân yếu đuối, khiến anh ta chỉ có thể nhìn trân trối khi kỵ binh địch đập mở cửa cung điện. \nHiệp sĩ cố gắng cắn vào chân ngựa của quân địch, nhưng không thể ngăn chặn hành động tàn bạo của kẻ thù. \n\nRồi, anh ta lần đầu tiên thấy \"dịch hạch đen\" mà công chúa nói. \n\nDòng lũ đen ào ạt ra khỏi cửa cung điện, lấp kín giáp chân của kỵ binh, nhưng không ai dừng lại vì điều đó. \nDòng \"dịch hạch đen\" cuồn cuộn tràn vào miệng mũi, xâm nhập vào phổi, nhưng anh ta vẫn không muốn gục ngã tại đây. \nSau đó, giọng nói quen thuộc nhất trực tiếp vang lên trong đầu anh. \n \"Anh đã làm đủ rồi... hiệp sĩ trung thành nhất của tôi.\"\n\nCuối cùng, trước mắt chỉ còn trống rỗng."
  },
  CollectionHall_127120_Title = {
    Text = "Trái tim hiệp sĩ"
  },
  CollectionHall_127121_Desc = {
    Text = "Họ được sinh ra từ trí tưởng tượng của con người đối với sự bí ẩn, nhưng không điên cuồng và dữ dội như trong tưởng tượng. \n\n Họ là lý trí, họ là bình tĩnh. \n\n Họ đến vì tương lai, vì sự tồn tại. \n\n Họ là phép màu kỳ lạ nhất, khó tin nhất. \n\n Ban đầu, giọng nói của họ giống như tiếng côn trùng kêu. Nhưng sau khi hoàn toàn hiểu được suy nghĩ của họ, giọng nói đó đã im bặt. \n\n Sau đó, những chủ nhân của giọng nói cố gắng chi phối mọi quyết định của cô. \n\n Trong năm đầu tiên thức tỉnh với thân thể được đánh thức, cô đã học cách sống chung với giọng nói trong đầu. \n\n Cô lặn sâu vào ý thức, trở thành một phần của Gestalt, thu thập thông tin và kiến thức cần thiết, sau đó an toàn rút lui, trở lại thực tế. \n\n Khi \"dịch hắc tử\" tìm đến thân thể này, cô cũng làm như vậy. \n\n Cô muốn tách rời thân thể khỏi kiến thức, ký ức, linh hồn, để não trở thành một cá thể bất tử. \n\n Sau cuộc phẫu thuật, cô suýt rơi vào giấc ngủ sống động và kỳ diệu — nhưng chỉ mất vài giây, suy nghĩ của cô đã bắt đầu vận hành trở lại. \n\n Cô biết rõ rằng, mình đang tiến gần đến sự hủy diệt tuyệt đối trong hỗn loạn vượt quá hình thức, lực lượng và tính đối xứng."
  },
  CollectionHall_127121_Title = {
    Text = "Vượt qua cái chết"
  },
  CollectionHall_127122_Desc = {
    Text = "Mọi người luôn thích dùng thước đo của bản thân để quy định ranh giới, xác định ký hiệu. \nThế giới bị giới hạn trong thân xác con người, thật là chật hẹp, ngu ngốc và đáng thương biết bao. \nCô ấy sớm từ bỏ thân xác, nhưng vẫn không thể chạm tới ranh giới thực sự. \nDòng sông kiến thức hỗn loạn vô tận, và hư vô màu đen lại một lần nữa đuổi kịp cô. \nCô ấy lặng lẽ nhìn thẳng vào nó, nếu bất kỳ hình thức nào cũng không thể nhìn thấy toàn cảnh thế giới, thì liệu phía sau hư vô mới chính là câu trả lời thực sự? \nCô ấy đã đặt cược cuộc sống của mình vào một canh bạc điên rồ nhất đời. \nCuối cùng cô cũng nhìn thấy sự kết thúc. \nCánh cửa của sự thật mở ra, hình dáng của thế giới chợt lật ngược. \nHóa ra là vậy, hóa ra là vậy. \nCô ấy khao khát muốn mọi người đều thấy được sự thật của hư vô, để giải thoát khỏi những cuộc vật lộn vô ích. \nTrước đây, cô đứng trên đỉnh sóng, dẫn dắt thế giới tiến về phía trước. \nGiờ đây, cô vẫn vung roi chăn cừu, bước đi nhẹ nhàng đưa thế giới vào vực thẳm. \nMọi người hoảng sợ đuổi cô đi, coi cô là một kẻ điên cuồng xấu xa. \nThật kỳ lạ, cô nghĩ. \nNhưng các bạn trong mắt tôi cũng như vậy. \n"
  },
  CollectionHall_127122_Title = {
    Text = "Ma-nơ-canh của miền quên lãng"
  },
  CollectionHall_127123_Desc = {
    Text = "Đừng sợ cái chết. Đó chỉ là quá trình mà thể xác trả linh hồn về với bóng tối, như thủy triều rút đi, trở về với sự yên tĩnh sâu thẳm. Hoàn toàn tan biến trong sự phân rã, trở thành một tồn tại vô nghĩa, không ai biết đến mới thực sự là điều đáng sợ.\nCô ấy chết không được an bình.\nThân thể khô héo đã lạnh, máu và chất phân rã hòa trộn thành một chất lỏng màu đỏ đậm. Nhưng linh hồn trẻ trung của cô vẫn run rẩy trong cổ họng, một chút ý thức chưa tắt, giống như khói lưu lại giữa xương. Như một con bướm đẹp mong manh, gãy cánh.\nDulcein lặng lẽ bước vào căn phòng, bước chân không tạo ra bụi. Anh quỳ xuống bên cô, ánh mắt nhẹ nhàng lướt qua đôi mắt nhắm chặt, các khớp ngón tay chưa duỗi ra và linh hồn chưa yên tĩnh.\n\"Liệu tôi còn sống không?\"\n\"Ngọn tối sẽ nuốt chửng tôi sao?\"\nAnh không nói, chỉ giơ tay ra, từ từ mở từng ngón tay cô ra, như đang làm phẳng những nếp nhăn cho một cánh hoa rung rinh. Không có lòng thương hại, cũng không có trách móc, chỉ có sự bình yên và kiên nhẫn, như một thần linh công bằng và trang nghiêm nhất trên thế giới, ban cho cô quyền được yên tĩnh. Trong khoảnh khắc đó, cô như đã đến được sự bình yên vĩnh hằng.\nVà hương thơm tinh khiết tỏa ra từ bàn tay họ nắm chặt, anh cúi xuống, thỏa mãn và trang nghiêm, để lại một nụ hôn trên mu bàn tay cô. Khi nụ hôn rơi xuống, âm thanh cuối cùng của cái chết dần dần kéo dài ra, cho đến khi hòa vào một cơn gió nhẹ giữa không trung, như một cái hồ yên tĩnh sau bão bùng. Không còn nghi ngờ, không còn oán hận, không còn sợ hãi. Cuối cùng, cô đã thuộc về cái chết.\n\"Tôi sẽ nhớ bạn.\" \nAnh thẳng người lên, nhìn cô ở trạng thái yên tĩnh hoàn toàn bây giờ. Trong thoáng chốc, răng sắc nhọn đã đâm vào da, anh nghe thấy giọng nói của Selene.\n\"Tôi tin bạn, anh trai.\" \nCô đã gặp may, trong ký ức của Dulcein, cô sẽ có được sự an nghỉ vĩnh cửu."
  },
  CollectionHall_127123_Title = {
    Text = "Nụ hôn yên nghĩ"
  },
  CollectionHall_127124_Desc = {
    Text = "Bạn lần đầu tiên gặp một golem sống là tại nhà của nữ học giả. \n「Cho đến tận bây giờ, cô ấy vẫn làm tôi ngạc nhiên. Đối với tôi, cô ấy chính là vũ trụ.」\nGolem mỉm cười cơ khí với bạn, miệng lảm nhảm những lời mơ hồ. \nBạn nhìn vào đôi mắt xám của cô ấy, cảm thấy như đang đứng giữa một biển xám cuồn cuộn, ánh sáng lấp lánh đang bò từ một đường chân trời sang đường chân trời khác. \n\nTrước khi rời đi, nữ học giả đưa cho bạn một cuốn sổ cũ nát, ghi chép cách chế tạo golem. \nĐêm hôm đó, bạn trải ra nó và nghiên cứu những công thức và chú ngữ viết vội, nhưng trong đầu bạn đầy rẫy nụ cười khó nắm bắt của golem. \nBạn không thể quên cô ấy. \n\nMấy ngày sau, bạn tìm một lý do để ghé thăm lại. \nBạn bước qua đống sách, dụng cụ, xương cốt chất cao như núi, tách ra lớp màn dày và mạng nhện bị cuốn vào, cuối cùng ngồi xổm trước golem. \nNữ học giả co ro ở góc phòng. Chỉ vài ngày, cô ấy đã tiều tụy, ánh mắt đã mất hết ánh sáng. \n「Bạn vẫn đến... giống như họ.」\nNữ học giả ho yếu đuối. \n「Đúng vậy... tôi đến rồi.」\nBạn nhặt lấy tay golem và hôn liên tục. \nNgón tay lạnh nhẹ vuốt cổ bạn, kèm theo chút đau đớn nhỏ, bạn nhắm mắt. \n\nKhi tỉnh dậy, bạn đang tắm trong ánh nắng trắng ấm áp, thân thể di chuyển theo nhịp sóng biển dịu dàng. \nBạn cảm thấy nhẹ nhàng chưa từng có, như linh hồn đã rời khỏi thân thể. \nBạn quay đầu, nhìn thấy những đầu lâu màu xám đen. \nHọ hét lên, vặn vẹo, như những bông hoa đen hoang dã, rải rác trên biển nguyên chất xám. \n「Không——」\nHọng ói ra chất lỏng đen, bạn không thể cử động. \nThì ra bạn cũng đã trở thành một phần của những đầu lâu đó. \n\n「@2 năm 6 tháng, nhà luyện kim nổi tiếng Romanin Ludwig được phát hiện chết một cách kỳ lạ trong thư phòng nhà mình, đầu lâu biến mất, cùng với cuốn sách luyện kim bí ẩn...」\n\n(Nội dung trên được ghi chép trong Tập II của 「Những Điều Thú Vị về Luyện Kim」 tại Thư viện Misaque)"
  },
  CollectionHall_127124_Title = {
    Text = "Bộ sưu tập quý giá nhất"
  },
  CollectionHall_127125_Desc = {
    Text = "Đến bây giờ, Castor cũng không thể nói ra ý nghĩa thực sự của tự do.\nAnh thường cảm thấy mình là người ngu ngốc hơn trong hai anh em, từ khi còn trẻ đã lặng lẽ đi theo Pollux, lắng nghe em trai nói về những ý tưởng xa vời kỳ quặc.\nTrong cuộc sống tu luyện khô khan và tê liệt, anh nghĩ rằng có được một chút ánh sáng thoải mái đã là điều hạnh phúc nhất, cho đến khi Juliette ra lệnh thực hiện nghi lễ cải tạo định kỳ cho Pollux.\nNỗi đau vô tận đổ dồn lên đầu Pollux một mình, Castor mơ màng bất lực đứng bên cạnh em trai, nhìn nụ cười trên gương mặt tươi trẻ ngày càng thưa thớt, trong khi mình không nghĩ ra được điều gì có thể làm được.\n\"Em có biết tự do có nghĩa là gì không?\" Giữa đêm khuya, Pollux cầm quyển sách đã bị cả hai lật đi lật lại, yên lặng hỏi Castor.\nCastor lắc đầu.\n\"Vậy, anh có muốn đi xem thế giới bên ngoài không? Anh trai.\" \nCastor chợt kinh ngạc, anh dường như hiểu được những điều mà Pollux muốn theo đuổi, những điều anh chưa bao giờ thấy, chỉ tồn tại trong những chữ viết khô cằn, nằm ngoài những gì anh tưởng tượng.\nAnh bị shock bởi ý tưởng táo bạo và lạ lùng đó, anh im lặng, có lẽ đã rất lâu trôi qua, có lẽ chỉ vài hơi thở, anh gật đầu không chút sợ hãi.\nDù điều đó phải chống lại toàn bộ giáo hội, dù điều đó phải hi sinh chính mạng sống của mình.\nVậy là, một đôi chim bay ra khỏi chiếc lồng chưa từng bước ra ngoài, thật tiếc là họ chưa từng nghĩ rằng, cái giá của tự do lại nặng như vậy.\nÂm thanh súng của thợ săn vang lên, và những con chim rơi từ trên không xuống.\nCastor vừa mới nếm trải hương vị của tự do, thì phải nhìn em trai của mình, đôi cánh bay về tự do bị giật phăng đi.\nĐối mặt với cơn thịnh nộ khủng khiếp của Juliette, gương mặt em trai nhợt nhạt và run rẩy, lại ngẩng mặt lên giữa đám đông, nở một nụ cười chưa từng khuất phục với mình.\n\"Kiên trì lên, vì tự do.\"\nCastor liên tục nhớ lại hình dáng không lời của những lời Pollux, cho đến khi trong sự dày vò u ám, anh nhai hai từ như tín ngưỡng thành dấu ấn, thì anh lại gặp Pollux lần nữa. Và lúc này anh chợt phát hiện, người đã luôn dẫn dắt mình phía trước, đã tàn nhẫn vứt bỏ hai từ đó."
  },
  CollectionHall_127125_Title = {
    Text = "Tự do không thể chịu đựng nổi"
  },
  CollectionHall_127126_Desc = {
    Text = "Vào một đêm mưa gió, con gái của thần ngồi cô đơn dưới cửa sổ. \n Ánh trăng lạnh lẽo chiếu xuống chiếc khăn, đứa trẻ thánh thần chảy chất dịch đen đang ngủ say bên trong. \n Con gái của thần bắt đầu hát một bài ru. \n \"Ngủ đi, ngủ đi, bé nhỏ của biển.\"\n \"Cái nôi của bạn là ánh trăng đen.\"\n \"Nuốt chửng các vì sao vào giấc mơ.\"\n Giọng hát cũng là lời cầu nguyện, những đàn cá sâu thẳm theo đó mà tụ tập. \n Toàn bộ con tàu giống như một bàn thờ khổng lồ, chính xác như ngày cô sinh ra đứa trẻ thánh thần. \n Rạch ngực mình, gỡ bỏ thịt xương chảy máu, để trả giá cho ân tình nuôi dưỡng và số phận của giống loài. \n Sự hy sinh của cô không mang lại tự do mà cô khao khát, cái chết không phải là giấc ngủ vĩnh hằng, chỉ là khởi đầu của bi kịch. \n Kể từ đó, sự bình yên của cô chỉ đến từ ban đêm. \n \"Ngủ đi, ngủ đi, bé nhỏ của biển.\"\n Khi bài ru này kết thúc, vương quốc vĩ đại của thần sẽ xuyên thủng mặt biển, nổi lên từ đại dương sóng gió. \n Ôm ấp những ảo tưởng như vậy, Muphí cũng nhẹ nhàng nhắm mắt lại."
  },
  CollectionHall_127126_Title = {
    Text = "Giấc ngủ trong bóng tối"
  },
  CollectionHall_127127_Desc = {
    Text = "Anh ta luôn tự trách mình, và cũng dùng sự trách móc đó đuổi hết tất cả bạn bè đi. Anh ta từng nghĩ rằng mình sẽ mãi mãi cô độc bước đi, theo đuổi sự hoàn mỹ của âm nhạc. \n Trên cao không chịu nổi cái lạnh, anh ta chấp nhận số phận đã định. \n Cho đến khi anh ta nghe thấy tiếng đàn của người đó. \n Tiếng đàn của người đó không liên quan gì đến sự hoàn hảo, âm nhạc quá tùy hứng giống như chính con người đó, thỉnh thoảng có những sai sót không đúng với bản nhạc, thậm chí còn đột nhiên quên một phần nào đó. Lúc ấy, đôi tay của anh ta luôn tự phát chơi ra những âm thanh khéo léo sinh động, khiến mọi người đều bất ngờ và khen ngợi. \n Anh ta nhìn người đó, như thể đang nhìn thấy tinh linh âm nhạc đang vui đùa giữa những nốt nhạc. \n Đây chính là điều được cha anh gọi là tài năng. Quả thực, anh ta cũng bị cuốn hút như mọi người, nhưng anh ta không thể thay đổi bước chân của mình. \n Anh ta là một người tầm thường ngu ngốc, chỉ có thể đi trên con đường khó khăn này. \n Mọi người đều đi theo người đó, trong khi anh ta thì ngày càng xa cách. \n Anh ta khao khát được gần gũi với người đó, nhưng ngoài việc chơi nhạc ra, anh ta không biết làm gì khác. \n Làm thế nào để nói chuyện với người đó, cần phải dùng bản nhạc nào mới có thể chiếm được sự yêu thích của người ấy. \n Anh ta biên soạn bản nhạc, như thể cân nhắc lời mở đầu. Cho đến khi anh ta không còn cơ hội để mở miệng nữa. \n Nỗi hối tiếc sâu nặng ngập tràn anh ta, mọi thứ bỗng chốc trở nên vô nghĩa. \n Trong mắt chỉ còn lại bức thư chưa hoàn thành, muốn gửi cho linh hồn đã rời xa. \n Anh ta đổ mồ hôi sôi nước mắt, cuối cùng ngã gục trước bản nhạc, trong giấc mơ vẫn không chạm tới ánh sáng ở cuối con đường. \n Nếu tôi đã định không thể đi đến cuối con đường đó, thì sự kiên trì suốt đời của tôi là vì điều gì? \n Có âm thanh của cây sáo xa xăm từ ánh sáng đó truyền đến, an ủi linh hồn đầy chất vấn của anh ta. \n Trong cơn mơ màng, anh ta nhặt cây sáo lên, biết được sứ mệnh thực sự của mình. \n Dùng tiếng đàn không bao giờ ngừng nghỉ của mình, mang đến sự bình yên vĩnh cửu. \n"
  },
  CollectionHall_127127_Title = {
    Text = "Khúc cầu hồn vĩnh cửu"
  },
  CollectionHall_127128_Desc = {
    Text = "Dù không có ký ức về đoạn đời trước, từ cơ bắp chưa phát triển của bạn có thể thấy bạn chắc hẳn không phải là người yêu thích thể thao hay bạo lực.\nBạn thực sự không hiểu tại sao tiêu chuẩn chiến đấu mà Misaque đặt ra cho điều tra viên lại cao đến vậy, toàn diện đến vậy.\nChẳng lẽ trọng tâm của điều tra viên không phải là hai chữ \"điều tra\", không phải là trí tuệ, logic chặt chẽ và một chút vận may vừa đủ sao?\nMỗi lần bị Ramona kéo dậy từ chăn ở ký túc xá, đứng trên sân tập trống rỗng đối mặt với những đợt tấn công liên tiếp, bạn lại đặc biệt nhớ đến những bài học logic châm biếm của giáo sư Đóa. Ngay cả những bài tập dồn dập và những bài kiểm tra khiến bạn đau đầu cũng nhẹ nhàng hơn nhiều so với nỗi đau bị đánh đập và ngã trong huấn luyện chiến đấu.\nLần thứ 19, bạn bị thanh kiếm chặn tất cả lối đi ép mất thăng bằng, ngã ngồi xuống đất, cảm giác như toàn thân sắp gãy vụn.\nThở hổn hển, bạn chán nản lau mồ hôi trên trán, nhất quyết không chịu đứng dậy nữa.\nRamona không có biểu hiện bất ngờ nào, cô ấy vung một đường kiếm đẹp mắt rồi thu kiếm lại, gót giày vang lên từng tiếng khi tiến về phía bạn. Bạn nhắm mắt lại, quyết tâm chịu đựng mọi lời chỉ trích và phê bình.\nĐáng ngạc nhiên là không có bất kỳ cú đánh hay lời mắng chửi nào đến, ba giây sau bạn mở mắt, chỉ thấy một gương mặt tươi cười nhẹ nhàng ở gần.\nRamona hơi cúi người, một bàn tay được bao bởi găng tay trắng chìa ra phía bạn.\n「Thực ra bạn đã rất cố gắng rồi, tôi biết. Nhưng những gì chúng ta phải đối mặt luôn là nỗi sợ hãi và nguy hiểm không thể biết trước, ngay cả tôi cũng sẽ có những khoảnh khắc bất ngờ không thể lường trước.」\n「Thì cứ coi như để tôi yên tâm một chút, làm lại lần nữa nhé, đồng đội.」"
  },
  CollectionHall_127128_Title = {
    Text = "Huấn luyện đồng đội"
  },
  CollectionHall_127129_Desc = {
    Text = "Con người là một sinh vật thích hát, điều này cũng đúng với người trên ngôi sao hoang. \n Giai điệu tự do tuôn trào từ cổ họng, không cần bất kỳ ý định hay mục đích nào. \n Chúng bị gió thổi thành những nốt nhạc rải rác, rồi cùng với cảm xúc mà tàn lụi. \n Người ta nói rằng, trong sa mạc, tất cả các bộ tộc lang thang đều có những bài hát riêng của mình. \n Nhưng người trên ngôi sao hoang lại đánh mất bài hát của chính mình. \n\n Cùng với bài hát, tên gọi cũng bị đánh mất. \n Không ai biết tên gọi ban đầu của ngôi sao hoang. \n Đây là một hành tinh bị nguyền rủa. Hạn hán, bão tố, nạn đói... \n Đủ loại thảm họa lần lượt xuất hiện, cuối cùng khiến ngôi sao hoang hoàn toàn sụp đổ. \n Những nhân vật lớn mặc trang phục lộng lẫy rời bỏ bằng con thuyền, ngôi sao hoang trở thành ngôi sao hoang thật sự, chỉ còn lại những người dưới đáy không được ban phước. \n Họ đều bị bỏ rơi. \n\n Kể từ đó, người trên ngôi sao hoang quyết định, họ không cần tiếng cười, không cần thơ, cũng không cần bài hát. \n Họ sẽ ghi nhớ nỗi khổ và nỗi đau bị bỏ rơi, mãi mãi bò lê trong sa mạc trắng cho đến khoảnh khắc hành tinh bị hủy diệt."
  },
  CollectionHall_127129_Title = {
    Text = "Bản ballad của sự trói buộc"
  },
  CollectionHall_127130_Desc = {
    Text = "Phần lớn thời gian, cái chết đến thật êm đềm, khi ý thức của con người còn chưa kịp phản ứng, thần chết đã lặng lẽ đến gần, lấy đi cuộc sống tươi tắn mong manh đó.\nTuy nhiên, có truyền thuyết rằng ở một nơi nào đó trong sa mạc không người biết đến, tồn tại một nữ thần chết màu hổ phách. Cô sẽ tuyên bố một cách dứt khoát và dùng lửa hổ phách, súng hổ phách, mang đến cái chết màu hổ phách.\nMột người đàn ông đứng trong biển cát dưới ánh trăng, tay cầm vũ khí run rẩy không ngừng. Ông ta không rời mắt khỏi hình dáng màu hổ phách của Caitigula, không dám lơi lỏng chút nào.\nMồ hôi lạnh nhỏ giọt từ trán ông, rơi vào lòng mỗi người đứng sau. Ông dẫn dắt rất nhiều người, nhưng vào lúc này lại rất ít có ích.\nÔng không hiểu, chỉ là theo hợp đồng để cướp một kho hàng đã không còn người, vậy mà lại đụng phải thần chết trong truyền thuyết.\n \"Bạn nói về thần chết sao? Chỉ là những tin đồn nhàm chán trước đây thôi.\"\nCaitigula bình thản nói.\n \"Tôi đã làm cho chúng trở thành màu hổ phách, có lẽ bạn vẫn có thể tìm thấy mấy lớp sơn chưa lột ra trên đó?\"\nCô hồn nhiên trình bày cho người đối diện xem súng đôi trong tay.\n \"Ngọn lửa màu hổ phách ở miệng súng đã rắc một loại vật chất đặc biệt.\"\nNgón tay cô chạm vào lòng súng, xoay một vòng rồi lấy ra một ít bột không rõ nguồn gốc.\n \"Cái gọi là thần chết, chỉ là hình ảnh mà tôi từng tạo ra.\"\n \"Cái hình ảnh đó mạnh mẽ, bí ẩn, không gì có thể cản trở.\"\n \"Nó có thể giúp tôi gây áp lực lên những kẻ ti tiện vô năng.\"\nCô nói với vẻ kiêu ngạo, chẳng hề bận tâm đến ánh mắt ngày càng hung tợn của người đối diện.\nCô nói mà như không có ai bên cạnh, hoàn toàn không nhận thức được nguy hiểm đã đến gần.\nKhi những viên đạn trút xuống cô, ánh mắt cô bộc lộ sự sốc và bàng hoàng.\nChỉ để che giấu sự phấn khích và điên cuồng trong tiềm thức.\n.........\nÂm thanh súng ngừng lại, tất cả như cô mong đợi.\nCô đứng giữa chiến trường, mọi thứ xung quanh đều nhuốm màu cháy.\nCaitigula chỉ làm hai động tác - nâng súng, bắn.\nKhi cô giơ cao khẩu súng, thần chết sẽ nhảy múa phía sau mọi thứ, đồng đều mang đến điềm báo cái chết.\nKhi cô bóp cò, ngọn lửa sẽ cuốn đi tất cả, dâng tặng thế giới một biển hoa hổ phách. \n \"Chúng đã đồng hành cùng tôi qua nhiều năm tháng, chứng kiến vô số máu và cái chết.\"\n \"Chúng đã bị buộc phải mặc chiếc áo lie của sự dối trá, để che giấu sự yếu đuối của tôi.\"\n \"Giờ đây, chúng không còn là tin đồn nữa.\""
  },
  CollectionHall_127130_Title = {
    Text = "Cái chết màu hổ phách"
  },
  CollectionHall_127131_Desc = {
    Text = "\"Bạn có hối hận không?\"\n Từ chiếc đèn thủy tinh lấp lánh, vị thần cổ xưa sống lại ngửi thấy cô, mờ ảo quấn quýt bên vai cô, đẩy cửa sổ ra, mang đến làn gió đêm nhẹ nhàng kèm theo hương thơm thoang thoảng. \n \"Khi tôi nhíu mày, khói lửa sẽ bùng lên trên những bức tường thành. Khi tôi nở nụ cười, dòng nước bốn phía sẽ mang đến bảo vật kỳ lạ và thú lạ, rượu mật và món ngon. Tôi là báu vật quý giá nhất của cả triều đại, tại sao tôi phải hối hận?\"\n Cô vì hơi say mà mặt mày đỏ ửng, cười khúc khích, nằm trong chiếc giường cao mềm mại chất đầy lụa và da thú, dần dần buồn ngủ. \n...\n \"Bạn có hối hận không?\"\n Vị thần cổ xưa sống trên một làn khói hương nói chuyện với anh, làn khói mờ ảo chảy xuống từ lầu các, phác họa ra những nụ hoa đã nở. \n \"Họ đánh nhau đến mức đầu rối như tơ, tôi chỉ cần ngồi hưởng lợi, leo cao thì ngã càng mạnh. Không giống như tôi, có đủ mọi thứ, ai hối hận cũng không đến lượt tôi.\"\n Anh cười cợt nhả lại rót đầy một bình rượu, tùy tiện lấy một nhánh mềm, trêu chọc những con côn trùng đang kêu vang trong lồng. \n...\n \"Bạn có hối hận không?\"\n Vị thần cổ xưa từ giếng đi ra cười thầm bên tai cô, làn sương quấn quanh tóc cô, làm một bông hoa ngọc lan trắng đầy đặn rơi từ cành xuống. \n \"Tôi có tình yêu, có ràng buộc, có cháo nóng khi về nhà lúc hoàng hôn, cũng có rượu ngon khi sum họp ăn mừng, tôi làm sao có thể hối hận, tôi chắc chắn không hối hận.\"\n Cô nhặt hoa đặt bên mái tóc, ánh nến vàng ấm áp lung lay theo tà váy của cô, ánh mắt cô tha thiết dán vào bên cửa sổ, nhìn về người mà cô đang đợi. \n...\n \"Bạn có hối hận không?\"\n Chiếc trâm váy chạy trốn lấm bẩn những dấu vết bùn bẩn trước cổng cung điện, vệ sĩ hôm qua ân cần dâng quà dường như không nghe thấy tiếng khóc cầu cứu của cô, hai thanh kiếm lạnh lẽo giao nhau rơi xuống, chặn lại con đường sống sót duy nhất của cô. \n Làn sương thở dài một cách uể oải, sau đó một bông hoa mai đỏ nở ra giữa tuyết, lại bị một trận tuyết tiếp theo hoàn toàn chôn vùi. \n...\n \"Bạn có hối hận không?\"\n Những viên ngọc quý từ chiếc hộp gỗ đàn hương đổ xuống vỡ tan trên gạch xanh, tiếng vỡ của những thứ lấp lánh rơi xuống lại còn dễ nghe hơn cả tiếng nhạc ống ngày xưa. \n Những bức tranh chữ mà anh yêu quý nhất, ngày nào cũng treo trước bàn để thưởng thức, lăn ra trước sân, những dấu mực của bức tranh tuyệt diệu bị đầu dao xé rách, đúng như cuộc chiến mà anh không nhìn thấy đang tàn phá đất nước. \n Làn sương quấn quanh một cách chế nhạo, sau đó một ngọn lửa bùng lên, những câu trúc và bức họa đều bị tiêu diệt thành tàn tro của triều đại trước. \n...\n \"Bạn có hối hận không?\"\n Chủ nhân của cái tên cô nhớ trên đầu lưỡi không bao giờ trở lại, xương khô bên bờ sông xa xôi, người đẹp trên gối. \n Anh đã trở thành phò mã của công chúa, con rể của hoàng đế? Anh đã lãng phí mười năm trong hoa cỏ không trở lại? Anh đã chôn thân trong bụng dân lưu vong trở thành lương thực sau thiên tai? \n Làn sương ngân nga một cách mờ ám, nhưng không hề cho cô câu trả lời mà cô khổ sở truy hỏi. \n\n Báu vật quý giá nhất khi triều đại thịnh vượng, sẽ trở thành đồ chôn cất quý giá nhất khi triều đại sụp đổ. \n Đứa con cưng nhàn rỗi nhất khi gia đình thịnh vượng, sẽ trở thành quân cờ lý tưởng nhất khi gia đình suy tàn. \n Và câu chuyện cuối cùng, trên đời thực sự có quá nhiều quá nhiều."
  },
  CollectionHall_127131_Title = {
    Text = "Nhíu mày uổng phí"
  },
  CollectionHall_127132_Desc = {
    Text = "Những đám mây u ám bao phủ bầu trời Lentiennam, che khuất ánh trăng. Tiếng chuông giữa đêm đã vang lên, những ống khói cao vút vẫn phun ra khói đen nóng hổi và hơi nước. Những bông tuyết dính bụi trong gió, chưa kịp rơi xuống đất đã bị nhuốm màu xám nhạt, chúng lắc lư rơi trên đèn đường, gần như ngay lập tức bị nhiệt độ của đèn làm tan chảy, nhỏ xuống người cô gái đi qua. \nCô gái mặc váy nâu, ống tay áo rộng lớn được vội vàng cuộn lên, lộ ra hai cánh tay gầy guộc. Cô chạy vất vả, thỉnh thoảng kéo lên ống tay áo, cố gắng đuổi theo người phụ nữ phía trước. \nNgười phụ nữ liếc nhìn cô gái, lẩm bẩm: \"Nhanh lên, đừng nghĩ rằng đi chậm là không cần đi.\" \n\"Dạ, mẹ,\" cô gái vội vàng chạy đến bên cạnh người phụ nữ, thở hổn hển, \"Xin lỗi, mẹ.\" \n\"Đừng gọi tôi là mẹ!\" Người phụ nữ nắm lấy cánh tay cô gái, kéo cô đi nhanh hơn, \"Kẻ hút máu vô dụng, nếu không phải vì mày, tôi đâu có phải sống ở cái nơi tồi tệ này.\" \n\"Xin lỗi...\" \n\"Câm miệng, đồ vô dụng.\" Móng tay của người phụ nữ cắm vào cánh tay cô gái, để lại những vết hằn sâu, \"Tôi nói cho mày biết, từ nay xưởng phường mới là nhà của mày, cũng đừng nghĩ gì về việc tìm tôi, tôi thà chết còn không muốn thấy mặt mày, nghe rõ chưa?\" \n\"Tôi... tôi biết rồi.\" Cô gái cúi đầu, những giọt nước mắt rơi xuống bị giày dẫm, hòa cùng tuyết bẩn mất hút trên con đường bảng đá. Tiếng còi công nhân tan ca từ xa vọng lại, một con mèo hoang chạy qua con hẻm, tiếng động nhỏ bé bị chìm trong bước chân của họ. Họ rẽ qua góc phố, đi qua sân sau treo quần áo, tỏa ra mùi ẩm ướt, cuối cùng dừng lại trước một tòa nhà có cửa sắt. \n\"Mày chờ ở đây đi,\" giọng người phụ nữ rất bình thản, thậm chí mang theo chút vô cảm, \"Khi trời sáng, người trong đó sẽ ra, họ sẽ nhận mày. \nĐừng theo tôi, nếu không xem tôi có đánh chết mày không.\" \nNgười phụ nữ quay lưng rời đi, bóng dáng gầy guộc và cong queo nhanh chóng biến mất trong bóng tối. Cô gái vô lực nắm chặt tay mình, vừa nhìn theo nơi người phụ nữ rời đi, vừa dùng ống tay áo lau nước mắt trên khuôn mặt. \nÁnh đèn vàng nhạt từ phía sau cô xuất hiện, kéo dài bóng dáng của cánh cửa sắt và cô. Một bàn tay đặt lên vai cô, làm cô giật mình. \n\"Em bé đáng thương, sao lại một mình ở đây?\" Người đến là một người phụ nữ trẻ, mặc bộ đồ giống như tu sĩ, \"Đến, chị Sara sẽ đưa em vào. Sẽ không lạnh nữa đâu.\""
  },
  CollectionHall_127132_Title = {
    Text = "Hồi ức đêm đông"
  },
  CollectionHall_127133_Desc = {
    Text = "\"Bộ tác phẩm làm nên tên tuổi của tôi à? Ừm —— tò mò thế nhỉ, được được, dù sao cũng là yêu cầu của VVIP. Nhưng kể về chuyện bình thường thì quá tầm thường với danh hiệu Đại Sư Phép Thuật của tôi, hãy để tôi biểu diễn một màn hoành tráng để giới thiệu cho bạn nhé! \nĐến đây, mời quý khách ngồi vào hàng ghế VIP, buổi biểu diễn phép thuật hồi ức đầy kịch tính và vui vẻ về tiền bạc và bội phản sắp bắt đầu!\"\n-------\nMột tiếng vỗ tay, ánh đèn sáng lên, chiếc mũ phép thuật của Kassia lơ lửng giữa không trung, miệng màu vàng mở ra đóng lại, hóa ra phát ra giọng nói của Kassia. \n \"Không phải từ rất lâu trước đây, ở một nơi không quá xa xôi, có một rạp xiếc, trong rạp xiếc có thỏ, có hề, có sư tử, có voi ——\"\nKhi chiếc mũ rung động, từ bên trong rơi ra một con thỏ, một chú hề, một con sư tử, một con voi. Tiếng trống dồn dập hơn, cùng với tiếng pháo nổ rầm rầm, Kassia mặc bộ đồ biểu diễn lộng lẫy chui ra khỏi mũ và đeo mũ lên đầu mình. \n \"Quan trọng nhất là, có một học trò phép thuật tài năng xuất chúng, tài hoa phi thường!\"\n-------\nSự trưởng thành của học trò đi kèm với những tràng pháo tay, thậm chí còn thu hút được một nhà đầu tư mặc đồ lộng lẫy. Điều kỳ lạ là, kể từ khi nhà đầu tư cùng họ đi du lịch, thỏ, hề, sư tử, voi... nhiều người và động vật đã biến mất một cách liên tiếp. Sân khấu trở nên trống trải, nhưng học trò dường như không nhận ra điều đó, cô ấy tiếp tục cuộc sống như cũ, cho đến khi nhà đầu tư đưa cho cô ấy một cốc rượu. \nHọc trò uống rượu, ngất đi, sân khấu tối sầm, tiếng thở dài yếu ớt vang lên từ bóng tối. \n \"Đó là lần đầu tiên tôi hiểu được sự hối tiếc.\"\n-------\n \"Nhưng, sự hối tiếc sao đủ? Tôi còn muốn biết cảm giác của ông nhà đầu tư khi khóc, cảm giác của khán giả khi cười, tôi muốn biết thêm, thêm nữa. Lúc này —— \nTôi mở mắt ra.\"\nPhân mảnh giấy nổ tung trong không trung, những mảnh vụn bay phất phơ, Kassia đột nhiên xuất hiện ở trung tâm sân khấu, cô ấy gõ nhẹ vành mũ, chiếc mũ mở miệng, phun ra một luồng ánh sáng rực rỡ. \n \"Tôi mở mắt ra, rồi phát hiện, tất cả cảm xúc đều là ánh sáng, đều có thể chứa đựng trong chiếc mũ phép thuật của tôi. \nBây giờ, hãy thư giãn, quý khách thân yêu của tôi, phần tiếp theo sẽ không đau chút nào, chỉ khiến bạn cảm thấy hơi tê dại, cuộc sống có chút nhàm chán...\""
  },
  CollectionHall_127133_Title = {
    Text = "Buổi diễn ảo thuật vui vẻ"
  },
  CollectionHall_127134_Desc = {
    Text = "Clementine không phải là một đứa trẻ mạnh mẽ, vì vậy khi mắc bệnh quái ác, bị đau đớn và cái chết dần đến hành hạ, cô luôn tỉnh dậy giữa đêm, khóc không tiếng.\nVà mỗi lần khóc xong vào sáng hôm sau, bên đầu giường của cô sẽ xuất hiện một \"món quà.\" \nMột ít kẹo được bọc đẹp, phụ kiện thời thượng, gấu bông đáng yêu......\nNhưng điều gây ấn tượng nhất với cô là một mẫu vật nhộng côn trùng.\nLúc đó, cô đã bị bệnh rất nặng, không thể dậy được, chỉ có thể cố gắng nâng mẫu vật đó lên, mở to mắt nhìn vào sự sống trong nhộng xuyên sáng.\nSự sống đó đã yên nghỉ, nhưng sự sống đó cũng đạt được sự sống vĩnh cữu.\nCòn cô, đang gần kề cái chết chân thật.\nNghĩ đến đây, nước mắt cô im lặng rơi xuống. Nhưng một đôi tay đã lau khô nước mắt cho cô.\n\"Đừng khóc, Clementine. Một ngày nào đó, bạn cũng sẽ giống như những nhộng này, có được sự sống mới.\" \n\"Tôi sẽ giúp bạn đạt được sự sống mới.\" \nCha cô sẽ không bao giờ nói dối, ít nhất là không nói dối với cô, vì vậy Clementine tin tưởng tuyệt đối vào câu nói này.\nCô tin tưởng cha mình, vì vậy khi vào ngọn núi ô uế đó, cô không chút do dự, khi chịu đựng cơn đau phẫu nát, cô không than vãn.\nBởi vì cô tin rằng mọi thứ đều là giá trị và quá trình cần thiết để có được sự sống mới.\nKhi tất cả nỗi đau và tuyệt vọng qua đi, cô sẽ hồi phục và trở về nơi được gọi là \"nhà,\" đoàn tụ với người thân duy nhất của mình."
  },
  CollectionHall_127134_Title = {
    Text = "Nỗi đau ẩn dấu"
  },
  CollectionHall_127135_Desc = {
    Text = "Cô ấy không bao giờ mơ. \n\n Học trò điêu khắc trẻ tuổi tin tưởng vào lý trí và trật tự tuyệt đối, giống như những tác phẩm lạnh lẽo của cô. \n Ngay từ lần đầu tiên nhìn thấy nó, cô đã bị mê hoặc. \n Mềm mại, tinh khiết — đó là nguyên liệu màu sắc hoàn hảo. \n Cô bận rộn dưới ánh trăng, mang chất nhầy đen từ nghĩa địa về xưởng. \n\n Một tuần sau, bức điêu khắc mang tên 《@2》 được trưng bày tại triển lãm. \n Đêm hôm đó, cô nghe thấy tiếng sóng biển từ xa. \n Đó là lần đầu tiên cô mơ. \n Dưới ánh sáng buổi sáng yên tĩnh, cung điện dưới đáy biển phủ đầy bụi đang say giấc. \n Cô đi qua những rạn san hô trắng, hít thở trong không khí tràn ngập sự cô đơn và lãng quên. \n\n Khi tỉnh dậy, ngón tay cô đang co quắp, chuyển sang màu đen, cuối cùng đã mọc ra san hô trắng. \n Cô ngửi đi ngửi lại, cảm nhận những tiếng thì thầm từ cổ xưa, của vô số sinh vật. \n Đó là hóa thạch thật sự mềm mại. \n Cô cười một cách thần kinh — thì ra đây là mơ. \n Cô tự nhốt mình trong xưởng, bắt đầu sáng tạo quên mình. \n Đúc khuôn, nặn đất, tô màu… \n Hỗn loạn, có trật tự. Vô cơ, hữu cơ. \n\n Cô sẽ mãi mãi mơ."
  },
  CollectionHall_127135_Title = {
    Text = "Cái chết của thiếu nữ san hô"
  },
  CollectionHall_127136_Desc = {
    Text = "Mẹ. mẹ. \nMuphí đã mất hầu hết ký ức liên quan đến người đó từ lâu. \nCó người nói rằng, người mẹ sắp chết đã bảo vệ cô, máu làm nghẹt cổ họng cô. \nSau đó mọi người xông lên, thô lỗ tách họ ra. \nChính vào khoảnh khắc đó, Muphí nhìn thấy khuôn mặt của mẹ. Đó là một khuôn mặt điên rồ nhưng rất đẹp. \nKể từ khi có thể nhớ, cô đã có một \"mẹ\" mới. \nÔn hòa, cẩn trọng, bà ấy sẽ đáp ứng mọi yêu cầu vô lý của Muphí, nhưng vẫn giữ khoảng cách vừa đủ. \nKhi Muphí nghĩ rằng mối quan hệ của họ sẽ tiếp tục như vậy, giống như biểu cảm của Miriam không bao giờ thay đổi, cô bị nâng lên ngai vàng đen tối, trong giấc mơ thấy quả \"trứng\" phát sáng. \nNó lấp lánh trong đêm tối, giống như đôi mắt, lại giống như ngôi sao. Tiếng hát hư ảo vang vọng xung quanh đền thánh: \n<Italic:từ @1 của con gái mình, thần minh của @1 đến @1...> \nCô được giao một sứ mệnh vĩ đại có liên quan và không liên quan đến cô: trở thành người mẹ giúp thần minh tái sinh. \nThật kỳ lạ. Cô vẫn chưa hiểu rõ thế nào là mẹ, thế nào là con gái, nhưng lại phải bắt đầu học cách làm một \"mẹ\". \nMuphí nhớ lại khuôn mặt đẹp đẽ nhưng điên rồ kia, nhớ lại vị ngọt đắng trên đầu lưỡi. \nNgười phụ nữ đẹp đẽ đó, chắc chắn không muốn tôi rơi xuống mộ phần như thế này, phải không?"
  },
  CollectionHall_127136_Title = {
    Text = "Chào đời bí mật"
  },
  CollectionHall_127137_Desc = {
    Text = "Về nguồn gốc chính xác của Vanda, người dân làng Cambrian có nhiều lời đồn thổi. \n\nCó người nói rằng, họ đã tận mắt nhìn thấy Vanda ngồi trên một tảng đá khổng lồ rơi xuống bờ hồ. \nCó người nói rằng, cô ấy là nữ Pharaoh đến từ Lemvah, ông ta từng thấy những gai nhọn y hệt trên xác ướp. \nCòn có người nói rằng, cô ấy là nữ công tước đến từ vùng Flan, sau khi liên tục khiến bốn người chồng qua đời, cô đã kế thừa một khối tài sản khổng lồ. \n...\n\nNhững lời đồn thổi như gió bay đi, người dân làng tiếp tục cày cấy, dệt vải, xay bột. \nTrong những năm tháng khó khăn, thuế nặng nề như lưỡi dao treo trên đầu, chặt đứt mọi nhánh cây và ước mơ. \nChỉ là... mỗi khi đi ngang qua khu vực hồ nơi nữ hoàng nghỉ ngơi, âm nhạc từ trong rừng rậm dễ dàng cuốn hút trái tim mọi người. \nĐó là giai điệu không nên xuất hiện ở đây. \nNó quá vui vẻ, quá lười biếng, đến mức trở nên tà ác, giống như tiếng thì thầm của quỷ dữ. \n\n \"Hãy đến đây, hãy buông bỏ tất cả.\"\n \"Vị vua từ bi ngồi giữa hồ, Người đang chờ đợi sự phục vụ của những kẻ mù mắt...\"\n\nVì vậy, vào một đêm không gió, người dân mệt mỏi đặt xuống dụng cụ nông nghiệp, quyết định thỏa mãn sự tò mò trốn chạy. \nÔng ta vòng qua rừng cây, qua cây cầu nhỏ, hai bên đường hoa nở rộ, ông ta thậm chí không liếc nhìn. \nÔng ta nhìn thấy hồ nước màu xanh. \nNó nối liền với bầu trời sao thấp, bên bờ là một tòa lâu đài cổ kính. \n\nNữ hoàng đội mão gai ngồi giữa hồ, kiên nhẫn chờ đợi những tín đồ đến hành hương. \nCô ấy giơ tay ra, tận hưởng những nụ hôn và sự tôn sùng từ loài người. \nMây đen tan đi, trăng sáng lên. \nNữ hoàng đâm gai nhọn vào lưng ông ta. \nChất chích điện lan dọc theo mạch máu, ông ta quỳ gối, bị chặt bỏ tứ chi, bị moi mắt. \n\nTừ đó, trọng lực nặng nề từ mặt đất không thể giữ ông ta lại nữa, tất cả thơ ca và ước mơ của ông ta chỉ còn gắn bó với nữ hoàng. \nÔng ta cuối cùng đã đón nhận số phận của mình."
  },
  CollectionHall_127137_Title = {
    Text = "Sắc lệch nữ hoàng"
  },
  CollectionHall_127138_Desc = {
    Text = "\"Người khổ hạnh suốt ngày, cầu nguyện rằng món quà này có thể làm ấm lòng linh hồn bạn, mong rằng tình yêu thương của Đức Cha sẽ xoa dịu nỗi đau trong lòng bạn, mang đến những giấc mơ ngọt ngào.\"\nĐêm bạc tuyết sắp kết thúc, ngọn nến leo lắt. Sau một thời gian dài đặt xuống tảng đá nặng nề, Salvador cởi bỏ bộ áo dài trang trọng, thay vào đó là bộ trang phục đỏ ấm áp. Để chuẩn bị cho lễ hội mùa đông ngày mai, anh đã đặc biệt đến cửa hàng nhỏ của Dafidel để chuẩn bị một bất ngờ cho các học sinh của missa. \n \"Đây là món quà cuối cùng...\"\nSalvador ngồi tĩnh lặng trên chiếc ghế cũ ở góc trường, vô thức lún sâu vào giấc mơ vì mệt mỏi. \nĐó là một giấc mơ ngọt ngào. Hộp quà dưới chân không biết vì lý do gì mà mở ra một cách lặng lẽ - bốn con người gừng đột nhiên nhảy ra, đôi mắt sáng lấp lánh được điểm bằng đường, hương quế và đinh hương xoay tròn trong không khí lạnh lẽo. \nHương thơm đánh thức ký ức bị chôn vùi, anh cảm thấy như trở về hành lang nhà thờ thời thơ ấu, những viên đường caramel tan chảy truyền tải tín hiệu ngọt ngào trên đầu lưỡi. Những phước lành bị nhiễm đớn đau và dịch bệnh, đang dần hồi phục cùng với điệu valse ngọt ngào này. \n...\nCùng lúc đó, bốn bóng hình lén lút từ từ tiến gần đến Salvador đang say giấc. \n \"Chủ nhân... chủ nhân có coi chúng ta là những đứa trẻ hư không...\"\n \"Hú hú - Orietta quá tò mò! Mở ra đi nào ~ một, hai... wow, nhiều người gừng quá!\"\n \"Cậu, cậu... đã nói tên rồi, lỡ như... họ sẽ ghét chúng ta...!\"\n \"Hì hì, chúng tôi không có ý định đánh cắp đâu! Đều là do Brown làm hết!\"\nSalvador nghe thấy những con người gừng nhỏ nói chuyện rôm rả, cảm nhận một con người gừng nhảy lên đầu gối, hơi thở quế thoảng qua mu bàn tay đầy nếp nhăn của mình. \nKhông, không phải những con người gừng trong giấc mơ, mà là những đứa trẻ nghịch ngợm trong thực tế. Salvador có thể tưởng tượng được nụ cười hạnh phúc trên khuôn mặt của bọn trẻ khi mở hộp quà một cách lén lút. Để có được khoảnh khắc đẹp đẽ, hạnh phúc và bình yên này, anh sẵn sàng chịu đựng mọi nỗi đau. \n \"Ôi... bộ râu của tôi, có phải đang bị rối với tóc không?\"\nSalvador giả vờ vẫn ngủ say, để bọn trẻ tiếp tục \"hành động bí mật\" vui vẻ này."
  },
  CollectionHall_127138_Title = {
    Text = "Sự thú vị trong hộp"
  },
  CollectionHall_127139_Desc = {
    Text = "Bạn và Ramona chưa từng hẹn ước sẽ gặp lại nhau.\nVào khoảnh khắc cánh cửa từ từ khép lại trước mắt, giới hạn của cuộc chia ly mà hai người tự vạch ra trong lòng, đã là vĩnh hằng định sẵn.\n\nVậy mà, khi cô ấy trong kẽ hở của thời gian, trong cuộc gặp gỡ thoáng qua chớp nhoáng ấy nhẹ nhàng móc lấy ngón út của bạn…\nĐây đã là lần gặp lại ngoài mong đợi, đủ để gọi là may mắn.\n\"Bạn chẳng thay đổi chút nào cả.\" Cô ấy nói.\n\nVì câu nói ấy, vì hơi ấm yếu ớt nơi đầu ngón tay… dù cách xa hai thế giới, bạn vẫn nguyện dốc hết tất cả, vượt qua dải ngân hà để gặp cô ấy.\nNăm sau ngày này, móc tay thề nguyện."
  },
  CollectionHall_127139_Title = {
    Text = "Chúng ta cuối cùng sẽ gặp lại nhau"
  },
  CollectionHall_127140_Desc = {
    Text = "\"Rút lui, rút lui!\"\n \"Đi về @3! Nhanh lên!\"\n \"Cứu tôi, cứu tôi! Đừng bỏ rơi tôi!\"\n \"Bỏ mặc hắn đi, nhanh rút lui — Elva!\"\nNgười lính cầm súng lưỡi lê lao ra ngoài trong một bước nhảy, tiếng pháo nổ vang bên cạnh cô, tiếng giao tranh, kêu la và tiếng còi chiến tranh gấp gáp hòa quyện thành một. Máu nhuộm đen đất, tỏa ra mùi tanh nồng mà ngay cả khói thuốc súng cũng không thể che giấu, những người lính ngã xuống với ánh mắt trống rỗng, dù là màu quân phục nào cũng trở nên chói chang trong khoảnh khắc này.\nElva nghiến răng, đối mặt với từng người tấn công cô. Cô có thể nhìn thấy, người trẻ tuổi đang cầu cứu, anh ta bị ấn xuống đất, dùng cả hai tay cố gắng chặn lưỡi dao của một kẻ địch cao lớn.\nTiếng súng nổ vang và cơn đau dữ dội cùng lúc ập đến, kẻ địch ở xa từ từ ngã xuống, Elva lập tức quay người vung kiếm, chịu đựng cơn đau ở chân và lao về phía trước, tận dụng khoảnh khắc kẻ địch mất thăng bằng để đâm xuyên qua ngực đối phương, đồng thời bóp cò.\nĐạn bắn vào thân thể bắn tung thịt máu, cô lau mặt một cách tùy tiện, quay đầu muốn xác nhận sự an toàn của người trẻ tuổi, nhưng phát hiện anh ta đã không biết khi nào rời đi.\nCô cúi xuống, một con dao xuyên qua đùi trái của cô từ trên đầu gối, máu ấm áp chảy róc rách.\nCô xé một miếng vải từ áo choàng và buộc vào đùi để hạn chế chảy máu, dùng súng lưỡi lê làm gậy chống tạm thời, lê bước theo đội quân."
  },
  CollectionHall_127140_Title = {
    Text = "Ý chí bất khuất"
  },
  CollectionHall_127141_Desc = {
    Text = "Lịch sử luôn là lời nói một chiều của người chiến thắng, cây mẹ tiêu vong, quốc gia sụp đổ, mọi thứ về quá khứ đều đang thay đổi âm thầm. \nNhà thơ ca ngợi câu chuyện về người đẹp Niniveh, khách du lịch ngồi quanh đống lửa trại lắng tai nghe. \n\n \"Đi xuyên qua sa mạc bạc, người đẹp ngoại quốc xâm nhập Niniveh. \nNước sông Ngân Hà trượt từ vai cô ấy, ngọc Sinai rơi từ mắt cô ấy. \nTrong đôi mắt vàng óng, nhìn thấy quá khứ của đất nước khác biệt. \nTrên làn da màu mật, viết nên tương lai của Niniveh.\"\n\nSau đó thì sao? Người đẹp ấy có trở thành hoàng hậu không? \nNhà thơ già gảy đàn bảy dây, thở dài một hơi dài. \n\n \"Cô ấy là thuốc mê, muôn loài say đắm. \nCô ấy là độc dược, thấm sâu vào phổi các quan lại. \nCô ấy là lũ lụt, sinh linh không thể thoát khỏi. \nCô ấy là sứ giả của dịch hạch đen, mang đến bệnh tật, ác mộng, cái chết và ngày tận thế của Niniveh.\"\n\nĐàn chưa buông xuống, bên bàn rượu đứng dậy một người, khiến tất cả khách uống rượu chú ý. \nNgười đó giữa những ngón tay thon thả để rơi vài đồng tiền rượu, vàng bạc lăn xuống, kêu leng keng. \nNơi cô ấy đi qua, ánh mắt theo dõi, ánh đèn lấp lánh. \n\n \"Thời gian trôi qua... nhưng không sao, Ngài sẽ không đáp lại những lời nói vẩn vơ này. \nMột ngày nào đó, các ngươi sẽ hiểu lòng từ bi và độ lượng của Ngài... giống như tôi đã hiểu...\"\nCô ấy đẩy cánh cửa nhỏ cũ kỹ của quán rượu, giống như đẩy ra một hộp châu báu, ánh trăng rơi trên vai trần, phản chiếu ánh sáng lấp lánh. \nNgười đẹp được ánh trăng yêu thương, quả thật có làn da như mật."
  },
  CollectionHall_127141_Title = {
    Text = "Từ bi dưỡng dục"
  },
  CollectionHall_127142_Desc = {
    Text = "Khi cô mở mắt trong nhà hoa, ngọn lửa đã bao trùm cả khu vườn, tiến đến trước mặt cô. \nCánh cửa nhà hoa bị khóa từ bên ngoài, không khí ngập tràn mùi rượu và dầu. Cô gọi tên Collette lớn tiếng, cho đến khi giọng nói bị khói làm khản đặc, đáp lại cô chỉ có tiếng gió của ngọn lửa. \nCô cảm thấy may mắn. May thay Collette ra ngoài, nếu không với ngọn lửa lớn như vậy, cô ấy cũng sẽ gặp nguy hiểm. \nCô cảm thấy buồn. Trong khoảnh khắc cuối cùng của cuộc đời, cô không thể gặp người bạn thân yêu lần cuối. Khi Collette trở về, nhìn thấy khu vườn bị thiêu rụi và bản thân cô, chắc chắn cô ấy sẽ rất buồn? \nCô cảm thấy tiếc nuối. Cuộc sống của họ đang trở nên tốt đẹp hơn, nhưng ngọn lửa này sẽ kết thúc mọi thứ. \nCháy. Ngôi nhà đang cháy. Bầu trời đang cháy. Lá cây đang cháy. Hoa đang cháy. Những cảnh tượng từng diễn ra trong khu vườn hiện lên trước mắt cô: cô đưa cô ấy đến khu vườn, cô đưa cho cô ấy một bông hồng, cô làm việc suốt cả ngày để mang đến cho cô ấy những chiếc bánh mì mềm mại. Họ chơi đùa, đuổi bắt, nằm dưới ánh nắng bình yên, mơ ước về ngày họ sẽ sống trong phòng của quý bà. \nCháy. Quá khứ đang cháy. Tương lai đang cháy. Khu vườn mang theo tất cả câu chuyện và tình cảm, đang cháy điên rồ. \nNước mắt chảy xuống khuôn mặt cô, dưới sức nóng của ngọn lửa, nhanh chóng biến mất. \nCô cảm thấy đẹp. Trong thơ ca, nỗi đau và sự tiếc nuối là đẹp. Cô tìm kiếm khắp nơi, tìm thấy giấy và bút đã bị ngọn lửa xâm chiếm gần hết. \nLòng biết ơn, tình yêu, sự lưu luyến, lời chúc phúc, vẻ đẹp. Cô muốn để lại tất cả những điều tốt đẹp nhất này cho Collette. \n \"... gửi Collette. Ôrla, trong ngọn lửa.\"\nTại cuối trang thơ, cô để lại dấu ký cuối cùng. \nỞ cách đó trăm mét, trên con đường đối diện khu vườn, Collette dường như cảm nhận được điều gì đó. Cô ngẩng đầu lên, ánh sáng của ngọn lửa chiếu rọi lên khuôn mặt cô. \nNước mắt chảy xuống khuôn mặt cô, dưới sức nóng của ngọn lửa, nhanh chóng biến mất."
  },
  CollectionHall_127142_Title = {
    Text = "Hồi kết của bài thơ"
  },
  CollectionHall_127143_Desc = {
    Text = "Họ chèo thuyền trong dòng sông tối tăm, nhợt nhạt, im lặng, mệt mỏi. \n Sương mù mờ ảo duỗi dài cánh tay, kéo họ vào bóng tối, lang thang trong đêm trường không có hồi kết. \n\n Sau đó, họ nhìn thấy một tia sáng. \n Đó là ánh sáng từ bờ bên kia xa xôi, nó chớp nhoáng nhưng đủ để chiếu sáng linh hồn u ám. \n Vì vậy, họ theo ánh sáng, vụng về chèo ra khỏi bóng tối, đến trước bình minh của ánh sáng. \n Cũng đến trước mặt các bạn. \n\n Có lẽ đây chỉ là một cuộc gặp gỡ ngắn ngủi, nhưng họ dồn sức vẫy tay, gào thét. \n Mọi người đều tắm trong ánh sáng thiêng liêng, mọi người đều cười. \n Họ nói — \n Nguyện mỗi khoảnh khắc gặp gỡ đều quý giá như ngày lễ. \n Nguyện trái tim chân thành không bao giờ ngừng đập. \n Nguyện chìa khóa bạc dẫn đường cho các bạn."
  },
  CollectionHall_127143_Title = {
    Text = "Hoàng hôn và Bình minh"
  },
  CollectionHall_127144_Desc = {
    Text = "Gió từ bốn phương ùa đến, bạn cầm nến đứng ở cửa vào mê cung. \nBạn có chút bối rối. \nDường như vừa rồi, bạn còn đang ở căng tin của Misaque, nghe Charlotte kể về những truyền thuyết liên quan đến mê cung dưới thư viện. \nVà bây giờ, bạn mặc áo ngủ, mắt còn ngái ngủ đi qua đi lại trong những hành lang nối tiếp nhau. \n \"Charlotte, Charlotte...\"\nKèm theo tiếng xào xạc, những con nhện trắng ùa vào như thủy triều. \nChúng tụ lại thành một cô gái trắng bệch. Cô ấy ngồi trên chiếc xích đu được điêu khắc bằng thịt, lắc lư qua lại. \n\n \"Bạn đã đến.\" cô ấy nói. \n \"Tôi tìm Charlotte, người bạn của tôi. Cô ấy bị lạc, tôi phải tìm thấy cô ấy...\"\nBạn gần như muốn khóc lên. \nCô gái cười khanh khách. Cô ấy nhảy xuống xích đu, đi đến trước mặt bạn. \n \"Bạn quên rồi sao, giao dịch của chúng ta...\"\nCô gái đưa tay vuốt ve bụng bạn, bỗng nhiên hiểu ra. \n \"Đúng rồi. Bạn đã trở thành con cái của tôi, nên không nhớ gì cả.\"\n \"Con cái...?\"\nBạn cúi đầu cảm nhận nơi da thịt tiếp xúc. \nCảm giác ấm áp như mạng nhện thâm nhập vào da, sau đó lan tỏa đến tận sâu nhất trong mạch máu. \nCô gái nháy mắt bí ẩn, ghé sát tai bạn thì thầm: \n \"Charlotte, đang ở trong bụng bạn đấy.\""
  },
  CollectionHall_127144_Title = {
    Text = "Hậu duệ người da trắng"
  },
  CollectionHall_127145_Desc = {
    Text = "Trên sân khấu khổng lồ, một cô gái đang múa. \n Tóc cô được chải gọn gàng thành một búi tóc, trên đầu điểm xuyết những chiếc lông trắng tinh và chiếc vương miện nhỏ xinh, chiếc váy trắng tinh khôi theo từng động tác của cô mà xoay tròn, trong tiếng violon buồn bã. \n Cánh tay duỗi ra, mũi chân chạm đất, thiên nga trắng cúi đầu dài, kể cho hoàng tử nỗi buồn và nỗi đau của mình. \n Liz nhỏ tuổi há miệng nhìn cô gái nhẹ nhàng và duyên dáng trên sân khấu, đó là chị họ của cô, người đã đến nhà cô trước khi cô ra đời, được đào tạo nghiêm ngặt dưới sự hướng dẫn của bà cô. Chị họ thường ngày luôn giản dị và trầm lặng, hôm nay lại sống động hơn bao giờ hết, cô giống như một con thiên nga sắp vỗ cánh bay đi, và họ, tất cả mọi người trong nhà hát, đều bị cuốn hút dưới cái bóng của cô. \n Nhịp tim của cô càng lúc càng nhanh, càng lúc càng nhanh — thật đáng ghen tị! Cô cũng muốn trở thành con thiên nga ấy, để lại bóng hình của riêng mình trên sân khấu vĩnh cửu. Cô biết mình có thể làm được, chẳng phải bà đã từng khen chân cô dài và thẳng khi cô không để ý sao? Chẳng phải chị họ đã làm nghệ sĩ chính nhiều năm nói rằng cô có tài năng múa rất xuất sắc sao? Đúng vậy, chỉ cần cô bắt đầu, chỉ cần cô mang giày mũi nhọn, mọi người chắc chắn sẽ từ những thành phố xa xôi đến xem buổi biểu diễn, cô sẽ là vũ công vĩ đại nhất thế kỷ này, ngôi sao rực rỡ của nghệ thuật ballet! \n Thời điểm đó, cô vẫn chưa biết rằng chờ đợi cô chỉ có ngọn lửa mãnh liệt."
  },
  CollectionHall_127145_Title = {Text = "Fouetté"},
  CollectionHall_127146_Desc = {
    Text = "Đây là một năm sau khi bạn đến Mythag. Bạn vẫn nhớ ngày mình tỉnh lại sau vụ nổ lớn và lần đầu tiên bước vào ngôi trường này chứ? Bạn đã được phát bộ đồng phục vừa vặn và gọn gàng, có ký túc xá thuộc về riêng mình, lần đầu tiên tham quan nhà ăn và ăn sạch hai chồng dĩa. Mọi khoảnh khắc thư giãn trong ngày hôm đó đã dừng lại đột ngột, chớp mắt bạn đã bị buộc phải học chương trình dự bị kéo dài một năm vì kiến thức quá nghèo nàn và não bộ như trẻ sơ sinh. Học ngôn ngữ, huấn luyện thể chất, kiểm tra khả năng Bạc, bổ sung kiến thức sinh học đặc biệt... Sau nhiều lần khổ sở, kết quả của bạn là không tốt có tốt. Điểm tiếng phổ thông Leo của bạn không đạt và thành tích liên kết ba người đánh thức một lần đã khiến bạn nổi danh trong khuôn viên trường. May mắn thay, nhờ khả năng đặc biệt và tài năng xuất chúng của bạn, bạn đã nhanh chóng đạt tiêu chuẩn khả năng của một điều tra viên, không cần phải thêm thời gian cho chương trình dự bị nữa. Còn về những điểm yếu không đồng đều của bạn, thì để những người bạn ngày càng ăn ý giúp bạn ôn tập và hỗ trợ. Ah, nơi này mặc dù có nhiều ác quỷ, nhưng cũng là một lũ ác quỷ đáng tin cậy và nhẹ nhàng. Nơi đây thường xuyên mây mù, mưa rơi, ít có ngày nắng, vô số người bị lãng quên hoặc sẽ bị lãng quên vẫn kiên trì, hy sinh và tiến lên không ngừng. Trong một ngày bình thường như vậy, Mythag lại đón chào một năm học mới. Bạn đứng trước gương chỉnh sửa cổ áo đồng phục, làm phẳng từng nếp gấp, rồi mở cửa ký túc xá. \"Hơi ngáp, cuối cùng cũng đến, tôi đã gần như ngủ gật.\"\"Bạn đang học trong ký túc xá à? Tân sinh viên.\" Bạn cười ngượng ngùng với Lotan, rụt cổ lại trước hình ảnh màu hồng đủ khiến bạn rùng mình, trốn sau Ramona và Ogier đang mỉm cười, năm bóng đen lay động và kéo dài trong khuôn viên buổi sáng. \"Đi thôi, bạn đồng hành.\"\"Từ hôm nay, bạn chính thức trở thành một thành viên của Mythag.\""
  },
  CollectionHall_127146_Title = {
    Text = "Ngày khai giảng"
  },
  CollectionHall_127147_Desc = {
    Text = "Dọc theo sông Tem, rẽ phải vào đường Beckman, tiếp tục đi khoảng một trăm feet, bạn sẽ thấy \"Văn phòng Thám tử Lắc\"ở góc khuất đó. \n\nLà văn phòng thám tử có tỷ lệ phá án cao nhất ở Lentiennam, nơi đây không có những giá sách lớn đầy sách chuyên ngành, không có bức tường dán đầy bài báo cắt ra, cũng không có bữa trà chiều tinh tế. \nBạn có thể chỉ gặp phải biển hiệu \"Ra ngoài có việc\" treo trước cửa và con chó già mệt mỏi nằm bên cạnh. \n\nNếu may mắn hơn một chút, vào một buổi sáng Chủ nhật nắng đẹp, bạn có thể đợi được thám tử nổi tiếng trở về sau cơn say. \nLúc này, anh ta vừa kết thúc ván cược trước đó, túi tiền không còn bao nhiêu, bạn có thể thoải mái đề nghị anh ta những nhiệm vụ vô lý của bạn: tìm mèo, giải cứu mẹ bị lừa vào tà giáo, thu thập bằng chứng ngoại tình của chồng... \nMiễn là bạn có, anh ta sẽ nhận. \n\n \"Tôi thích khoảnh khắc trước khi chết, vì vậy tôi chắc chắn sẽ trở thành một con bạc.\"\n \"Vậy còn việc trở thành thám tử? Xin lỗi, tôi không thấy mối liên hệ giữa việc tìm mèo và cận kề cái chết.\"\n \"Không, bạn không hiểu... Quá trình tìm kiếm sự thật tự bản thân nó đã đủ hấp dẫn, bất kể lớn hay nhỏ. Giống như...\"\n \"Giống như tham gia một cuộc hẹn với cái chết.\""
  },
  CollectionHall_127147_Title = {
    Text = "Thời khắc may mắn"
  },
  CollectionHall_127148_Desc = {
    Text = "Polyxenus đã có một giấc mơ.\nAnh ta mơ thấy mình khoác trên mình bộ giáp bạc, nhận từ tay một vị vua trang nghiêm một thanh kiếm dài sáng bóng như ánh trăng.\nRồi anh ta cưỡi trên một con ngựa trắng lớn, hướng về một hang động, khi anh ta vào sâu trong lòng đất, những cây ở miệng hang đều thì thầm mơ màng.\nTrong sâu thẳm của hang động ẩn chứa một bóng tối màu xanh đậm, đó là một con quái vật cao lớn như núi thịt, hai mắt kỳ dị tỏa ra ánh sáng màu xanh lá.\n \"Quái vật gây hại cho quốc gia, ta không thể để ngươi đe dọa vương quốc thiêng liêng này nữa, hôm nay, ta sẽ dùng thanh kiếm chính nghĩa này diệt ngươi!\"\nCon quái vật đó rung rinh, có vẻ như đang đáp lại, phát ra tiếng gầm ghê rợn.\nPolyxenus không hiểu ngôn ngữ của nó, cũng không muốn hiểu những lời nó nói, anh giơ thanh kiếm lên, bắt đầu chiến đấu với con quái vật tỏa ra khí tức tà ác. Những xúc tu của quái vật lan ra rìa tối tăm của hang động, va chạm vào thanh kiếm chiếu sáng.\nGiống như mỗi câu chuyện anh hùng khác, hiệp sĩ dũng cảm đã nhảy lên lưng con quái vật, trong một tiếng hét, đâm mũi kiếm vào ngực nó.\nQuái vật lăn ra, Polyxenus trong hơi thở nhẹ nhõm, ngẩn ngơ nhìn dấu vết đang từ từ lan rộng dưới kiếm——Làm sao mà từ cơ thể xấu xí và ác độc đó lại chảy ra dòng máu ấm áp và đỏ tươi như vậy?\nAnh bừng tỉnh khỏi giấc mơ, cảm giác dính dính của máu trên tay dường như không thể xóa nhòa, ánh mắt anh bỗng nhiên nhìn thấy quyển sách cũ do Castor gìn giữ, được cất giấu cẩn thận trong khe giữa giường.\nAnh đã lật qua quyển sách một cách tùy tiện, vừa lúc là bài kể lại câu chuyện của hiệp sĩ mà Castor thường đọc, giữa trang sách, anh thấy một lời tiên tri như sau:\n \"Khi con quái vật ác độc bị chiến binh đánh bại, mọi người sẽ thấy những hiện tượng lạ trên bầu trời, mặt trời sẽ biến thành bóng tối, và mặt trăng sẽ trở thành máu.\"\nPolyxenus nhíu mày, khinh thường ném quyển sách cũ về vị trí ban đầu, dưới ánh trăng anh thì thầm cầu nguyện.\n \"Đầy tớ của Chúa được phái đến đây để ban phước cho các ngươi, khiến các ngươi rũ bỏ tội lỗi, từ bóng tối trở về ánh sáng, cùng với tất cả những người công chính thuần khiết tiến vào miền đất thanh tẩy...\"\nNgười cầm đèn không chiếu rọi cho người đầy tớ thành kính của Ngài, cơn ác mộng vẫn lăn tăn trong trái tim, đó là linh hồn đang chìm sâu của anh lặng lẽ khóc trong giấc mơ."
  },
  CollectionHall_127148_Title = {
    Text = "Bốt Lợi Khắc Tư"
  },
  CollectionHall_127149_Desc = {
    Text = "<Bold:24 tháng 1>\nTrên người có mùi hôi hám.\nHôm nay khi trở về nhà cùng đầy tớ Teresa, chúng tôi đi qua khu Nam An Phú.\nĐây không phải là một trải nghiệm dễ chịu.\nĐó là một nơi nguy hiểm@2 có một số gã trên người mọc những vết thương kỳ lạ, giống như những lỗ hình tam giác.\nĐầy tớ Teresa nói đây là hình phạt của Chúa dành cho những kẻ ngoại giáo.\n\n<Bold:22 tháng 2>\nSốt đã một tháng.\nHôm nay cuối cùng cũng ăn được chút gì đó. Là thịt bò tươi, mềm và nhiều nước…\nĐúng, nhiều nước.\nMùi vị ngọt ngào@2 màu đỏ@2\nTất cả gương trong nhà đều bị cất đi, ngay cả Bobby cũng không dám nhìn tôi.\nHe he. Họ không biết, vào ban đêm, tôi có thể thấy hình dạng của mình từ cái bóng trên cửa sổ.\nTrên mặt, cổ, và ngực tôi… từ trên xuống dưới, đầy rẫy,\nmọc đầy những hình tam giác@2 màu đen\n\n<Bold:17 tháng 3>\nMàng mắt tôi như bị phủ một lớp voan đỏ.\nThế giới trở thành màu máu@3\nCha tôi đứng trong sương máu gọi tôi, đây là lần đầu tiên ông nói với tôi bằng giọng lớn như vậy.\nÔng ở rất gần tôi, nhưng giọng nói lại xa vời. Tôi ngửi thấy sự tuyệt vọng, sự ghê tởm và máu.\nĐừng@2 đưa tôi đi, đừng……"
  },
  CollectionHall_127149_Title = {
    Text = "Ngụ ngôn của kẻ tham ăn"
  },
  CollectionHall_127150_Desc = {
    Text = "Người dân Erivan sống trong thành phố đá màu xám, bên cạnh hồ lớn màu xanh. \n\n Hồ lớn không có tên, từ khi người Erivan có ký ức, nó đã tồn tại ở đó. \n Theo truyền thuyết, một nữ yêu quái xấu xa bị phong ấn dưới đáy hồ. \n Cô ta cùng tuổi với hồ lớn, là một sự tồn tại kinh khủng được tạo ra thô lỗ vào lúc vũ trụ mới mở ra. \n Người dân Erivan ngây thơ và nhút nhát sợ hãi nữ yêu quái, họ cố gắng làm hài lòng nữ yêu quái, để đảm bảo cô ta sẽ luôn yên lặng ở đáy hồ. \n\n \"Nên làm gì đây?\"\n \"Đúng vậy, nên làm gì đây?\"\n \"Hãy nhảy múa đi! Dù sao, nhảy múa cũng tốt.\"\n\n Vì vậy, mỗi khi trăng lồi, người dân Erivan tụ tập bên bờ hồ, nhảy múa uyển chuyển trước tượng thần làm bằng giấy cỏ. \n Khi đó, trăng sáng và sao thưa thớt, mọi thứ đều bình yên. \n\n Hàng trăm năm sau, người dân Erivan quên đi lịch sử, quên đi những câu chuyện đạo lý, và quên cả tượng thần. \n Trong lễ kỷ niệm nghìn năm xây dựng thành phố đá, họ cười đùa tự do, uống rượu ngon say sưa. \n Tiếng ồn ào rơi xuống hồ, giống như những viên đá rơi vào nước, tạo ra những vòng tròn vô tận từ trung tâm hồ, cuối cùng chạm đến sự tồn tại ở sâu dưới đáy. \n Vì vậy, đúng vào lúc trăng lồi, người dân Erivan nghe thấy tiếng động ngoài phạm vi âm thanh, nhìn thấy mặt trăng và lửa ngoài phạm vi thị giác. \n Cuối cùng, họ cũng trở thành một phần của sự im lặng. \n\n Sự im lặng vĩnh cửu trong không gian vô hạn khiến người dân Erivan đầy sợ hãi. \n Họ bị buộc phải ngồi bất động như những nhà huyền bí, chứng kiến những nhóm người mới trước mặt họ cười đùa tự do, uống rượu ngon say sưa, đi lại liên tục, lặp đi lặp lại. \n Vì vậy, vũ trụ sẽ tiếp tục nở rộng mãi mãi, các thiên hà sẽ ngày càng xa nhau, tất cả mọi thứ sẽ tiêu vong. \n Đó là cách mọi việc diễn ra. \n Điều đó có quan trọng hay không nếu người dân Erivan cảm thấy cô đơn."
  },
  CollectionHall_127150_Title = {
    Text = "Yến tiệc lặng yên"
  },
  CollectionHall_127151_Desc = {
    Text = "Cô gái mở mắt và phát hiện mình đang ở trong một khoảng không tối tăm. \n \"Này!\" cô hét to, \"Có ai đó không?\"\nTiếng vang trôi nổi trong không gian không nhìn thấy ranh giới, dần dần tan biến, cô gái hít sâu một hơi, lại hét to: \"Chị gái, Brun, người Tây Khu!\"\n \"Có ai đó không——\"\nCâu hỏi với âm lượng lớn hơn trước đó bay xa, rồi từ từ trở lại. Một vài sợi ánh sáng xanh nhạt như bị tiếng vang dẫn dắt, từ xa đến gần, chúng được cấu thành bởi vô số hạt lơ lửng, múa bay, nhỏ như bụi, uốn lượn trong không khí như rắn, và gợn sóng như biển. Dải ánh sáng nối tiếp nhau không ngừng lướt qua cô gái đứng tại chỗ, nhanh chóng biến cả bầu trời thành một biển sao, những hạt nhỏ xuyên qua ngón tay và mái tóc của cô, không để lại dấu vết nào. \n \"Đây là... cái gì vậy?\"\nBụi phát sáng xung quanh cô nhẹ nhàng gợn sóng, không có câu trả lời. \n \"Tôi nhớ bảo tàng sáp, nhớ chị gái, tôi... hình như đã chết, đây có phải là thiên đường không?\" cô nhìn quanh, \"Sao không có thiên thần nào cả, liệu có phải địa ngục không!\"\nTiếng của cô rơi vào tai mình, lần này, thậm chí tiếng vang cũng không xuất hiện. \nMột cảm giác cô đơn khó tả nảy sinh từ đáy lòng cô, trong cơn hoảng hốt, cô như quay lại thời điểm trước khi gặp chị gái, gặp Brun. Mùi hôi thối của cống nước u ám bao trùm, cô vừa lạnh vừa đói, nhưng không thể rời đi, vì có người đã đẩy cô xuống và đặt một cái thùng lớn trên miệng cống. \nCô vỗ vỗ mặt mình, bước chân về phía trước. \nBụi phân ra trước mặt cô, lại tụ lại sau lưng cô. Nhấc chân, đặt chân, nhấc chân, đặt chân. Cô cứ thế đi mãi, đi mãi, không biết mình đã đi bao lâu, cũng không biết mình đã đi bao xa. Trước mặt cô là nhiều bụi và bóng tối hơn, còn phía sau, dù là hướng đến hay con đường đã đi qua, đều không còn dấu vết, cho đến khi—— \n \"Thức tỉnh thành công, Jenkin, Jenkin, bạn có nghe thấy không?\""
  },
  CollectionHall_127151_Title = {
    Text = "Con đường lạc lối"
  },
  CollectionHall_127152_Desc = {
    Text = "Cha Thượng Đế từ bầu trời đến. \n Khi đó, đất là vùng đất đỏ lửa, lửa bừng bừng. Chân của Cha Thượng Đế đạp lên lửa. \n Cha Thượng Đế nói, lửa cuối cùng sẽ tắt, và lửa đã làm như vậy. \n Đất chảy thành đất, Cha Thượng Đế viết lên đó lời Chúa: \n Đất sẽ làm nền tảng cho sinh linh. \n Thung lũng trở thành thung lũng, đồng bằng trở thành đồng bằng. \n Lời Chúa vững chắc, đây là tấm bảng đá đầu tiên. \n\n Cha Thượng Đế nhìn mây nặng trĩu, nói, mây cuối cùng sẽ rơi mưa, và mây đã làm như vậy. \n Mưa tụ lại thành dòng nước, Cha Thượng Đế viết lên đó lời Chúa: \n Nước sẽ làm nôi ấm. \n Nước trở thành hồ, thành biển, biển đã nhấn chìm đất. \n Lời Chúa vững chắc, đây là tấm bảng đá thứ hai. \n\n Cha Thượng Đế nhìn nước u ám, nói, ánh sáng sẽ hạ xuống, ánh sáng đã làm như vậy. \n Ánh sáng rơi xuống nước, Cha Thượng Đế viết lên ánh sáng lời Chúa: \n Ánh sáng sẽ nuôi dưỡng. \n Ánh sáng mang lại sự ấm áp. \n Lời Chúa vững chắc, đây là tấm bảng đá thứ ba. \n\n Cha Thượng Đế thấy đất, nước, ánh sáng đều đã có, nói, sự sống sẽ đến. \n Ngài để máu của mình chảy xuống, viết lên đó lời Chúa: \n Máu sẽ mang thai sinh mới. \n Máu của Cha Thượng Đế lan tỏa, trở thành vật có sự sống, sinh sản trong biển. \n Lời Chúa vững chắc, đây là tấm bảng đá thứ tư. \n\n Cha Thượng Đế thấy sự sống đã có, nói, sinh vật sẽ thay đổi vĩnh viễn. Sinh vật đã làm như vậy. \n Những vật vô hình bò lên đất khi nước rút. \n Cha viết lên những vật đang thay đổi lời Chúa: \n Sự thay đổi không thể dừng lại. \n Những vật bò lên đất mọc ra rễ, mọc ra chân tay, mọc ra đủ hình dạng. \n Lời Chúa vững chắc, đây là tấm bảng đá thứ năm. \n\n Cha Thượng Đế thấy sự sống đã có, sự thay đổi cũng đã có, nói, cái chết cũng sẽ đến. Cái chết đã đến. \n Cái chết của người già, cái chết của người yếu ớt. Cha Thượng Đế viết lên cái chết lời Chúa: \n Những cái chết sẽ trở về với nguyên thủy. \n Thân thể của người chết từ từ biến mất, trở về lòng Cha Thượng Đế. \n Lời Chúa vững chắc, đây là tấm bảng đá thứ sáu. \n\n Cha Thượng Đế thấy sự sống, cái chết, sự thay đổi đều đã có, nói, đây đều là di vật của ta, ta sẽ để lại phúc lành. \n Cha Thượng Đế lấy xương của mình ra, viết lên đó lời Chúa: \n Ở cuối con đường của vạn vật, có thể dùng xương của ta, thay quyền của ta. \n Đưa sự sống bằng giá của thịt máu. \n Lời Chúa vững chắc, đây là tấm bảng đá thứ bảy. \n\n Cha Thượng Đế nhìn mọi thứ đều đã có, ngừng lại nghỉ ngơi. \n Nước bao bọc Cha Thượng Đế, ánh sáng cung cấp sự ấm áp cho Cha, đất che phủ Cha. \n Sau đó, Cha Thượng Đế ngủ say, mọi vật đều sống theo lời của Cha, đó chính là thế giới hiện tại."
  },
  CollectionHall_127152_Title = {
    Text = "Bảng đá Thánh ngôn"
  },
  CollectionHall_127153_Desc = {
    Text = "Người chính là vị vua thông hiểu mọi điều, là tối cao của Lemuria. \n Lapis lazuli là ngai vàng của Ngài, vàng là vương miện của Ngài. Linh hồn là quyền lực của Ngài, Ngài an ngủ ở nơi cao nhất. \n Các linh mục phục vụ thần cũng phục vụ Ngài, quỳ gối trước Ngài, \n họ là những thần dân trung thành của Ngài, là những tín đồ tín tâm của Ngài. \n\n Các thần vào ban đêm phái đi ánh trăng, đưa Ngài đến cung điện vĩnh hằng để làm khách, \n nơi đó, họ chia sẻ thức ăn của linh hồn với Ngài, trao cho Ngài trí tuệ của thần. \n Họ ban cho Ngài những giấc mơ vô tận, để Ngài có thể thấy được khởi đầu của vạn vật, thấy được tận cùng của thời gian. \n Ngài vì thế mà biết rằng: khởi đầu của vạn vật đều là hỗn mang, các thần trong đó tỉnh giấc, xây dựng cung điện treo lơ lửng trong bóng tối. \n Ngài vì thế mà biết rằng: tận cùng của thời gian là một mảnh tối tăm, mọi thứ trở về hỗn mang. \n\n Ôi, vua của các vua, con cưng của thần, \n ai có thể sánh với Ngài? \n Ai có thể như Ngài thống trị từ giấc mơ, ai có thể như Ngài oai nghi? \n Ôi, thần vương cao quý, chủ tịch trẻ tuổi, \n xin Ngài hãy an ngủ thật say. \n Những thần dân và tín đồ của Ngài sẽ kiên nhẫn chờ đợi, Ngài mang về lời tiên tri của thần. \n Kính thưa chủ tịch Schraubverschwinden, lệnh cho chủ của vực thẳm, \n xin Ngài cho phép chúng tôi gọi tên Ngài, ban cho chúng tôi sự che chở, \n tulô, tulô."
  },
  CollectionHall_127153_Title = {
    Text = "Ngợi ca Thần Vương"
  },
  CollectionHall_127154_Desc = {
    Text = "Nhiều năm qua, tôi luôn nghĩ về Yu U Hahi. \nNhưng chỉ trong đống đổ nát của những ngôi đền này, tôi mới thực sự nhìn rõ anh ta. \nTôi thấy anh ta bị cuốn vào xiềng xích nặng nề, buộc phải nằm trên mặt đất, vươn cổ ra, cố gắng với tới bữa ăn đã biến chất. \nNhư một con chó. \n\nSau khi Caligula chết, với tư cách là đồng lõa của tên bạo chúa, anh ta bị khóa trong đống đổ nát của ngôi đền cho đến nay. \nTôi kéo xích tay, dẫn một nô lệ của Torre đến. \nAnh ta lập tức đứng thẳng thân thể, đồng tử mở to, họng phát ra tiếng nuốt nước bọt gấp gáp. \n\n \"Chờ đã.\"\nTôi kéo xích, kéo nô lệ đến khoảng cách vừa đủ để anh ta không thể với tới. \n \"Giúp tôi giết một người.\"\nAnh ta cười toe toét, lộ ra hàm răng sắc nhọn như thú vật. \n \"Bạn là người thứ 19 nói điều này với tôi, và tôi buộc phải từ chối bạn.\"\nTôi cố gắng giữ vẻ mặt nghiêm túc, không để anh ta nhìn thấu sự thất vọng của tôi: \n \"Tại sao?\"\n \"Nếu bạn muốn tôi giết một nghìn người, tôi rất vui lòng. Giết một người? Cược của bạn còn xa mới đủ.\"\n \"Nếu người đó là hoàng đế hiện tại thì sao?\"\nTôi hít sâu một hơi. \n \"Cược này đủ chưa?\"\nYu U Hahi cười ha hả: \n \"Đây là vấn đề toán học, bạn già à. Một là một, một nghìn là một nghìn.\"\n\n \"Bốc cháy rồi, Cung điện Vàng bốc cháy rồi!\"\nXa xa, ngọn lửa bùng lên dữ dội. \nBạo chúa, bạo chúa... \nTôi đã khóc trong vô vọng, vì Seneca, cũng vì cung điện hoa mỹ sắp trở thành đống đổ nát. \n \"Buồn vậy sao?\"\nYu U Hahi lại gần. \nAnh ta đã thưởng thức xong nô lệ của Torre, đang thỏa mãn mà mấp máy môi. \nVâng, tôi hứa với anh ta rằng, nếu có thể giết được bạo chúa, ngoài tự do, anh ta còn có thể tiếp tục hưởng dụng một nghìn sức sống vô tội. \nAnh ta có hiểu được ý nghĩa của ngọn lửa này không? \nAnh ta có hiểu được việc phục vụ một tên bạo chúa không thể cứu chữa có ý nghĩa gì không? \nE rằng không. \nAnh ta chỉ là một con thú mà thôi. \n\n \"Roma giống như một đống đổ nát.\" Con thú nói. \n \"Hoặc nói đúng hơn, đất nước của các người, thế giới... \nTrong mắt tôi, nó là một đống đổ nát vô nghĩa và vô tận. \nCác người rơi lệ vì nó, tàn sát lẫn nhau, làm tất cả những việc vô ích và vô nghĩa... \nThành thật mà nói, tôi không hiểu.\"\n\nTôi nhìn vào thân thể đầy vết thương của anh ta. \nĐây là một tượng ma golem được tạo nên từ hàng triệu thịt máu, trải qua hàng trăm năm, liên tục bị nghiền nát và tái cấu trúc, giống như Roma vậy. \n \"Còn cậu? Cậu cũng là một đống đổ nát sao?\"\n \"Có lẽ vậy.\"\nAnh ta duỗi người, đôi mắt dài hẹp ánh lên ánh lửa vàng từ xa. \n \"Nhưng tôi không quan tâm.\""
  },
  CollectionHall_127154_Title = {
    Text = "Yến tiệc đẫm máu"
  },
  CollectionHall_127155_Desc = {
    Text = "Đấng Chủ Tể của Lo Duyên, xin hãy lắng nghe lời cầu nguyện của tôi. \n Xin hãy ban xuống lời tiên tri của Ngài, cho tôi sự khải thị, \n để tôi có thể phục hồi vương quốc của Ngài. \n Trên mảnh đất vô tín ngưỡng này, trên vùng băng giá bao quanh bởi biển, \n xin hãy dựng lên cột đá của Ngài, xây dựng đền thờ của Ngài. \n\n Đấng Chủ Tể của vực sâu, những gì trên bàn thờ này là lễ vật dành cho Ngài. \n Thịt máu tinh khiết đến từ con cừu trăng tròn, trái tim mạnh mẽ đến từ con bò trưởng thành, \n đôi mắt sắc bén đến từ đại bàng bay lượn, xương cứng đến từ cá voi du hành. \n Lapis lazuli là ngai vàng của Ngài, vàng là vương miện của Ngài, \n xin hãy ban cho tôi giấc mơ của Ngài, cho tôi lời Chúa, \n để tôi có thể phục hồi thân thể của Ngài. \n Trong vực sâu dưới băng, trong lĩnh vực dưới biển, \n xin hãy hiến dâng thân thể sẽ hạ sinh vào thời khắc đúng đắn. \n\n Đấng Vua của Lemuria, Đấng am hiểu mọi sự, xin hãy đáp lại lời cầu nguyện của tôi. \n Kể từ khi Ngài an nghỉ trong lòng biển, đã trôi qua hàng trăm năm, \n tôi nhân danh Ngài, thực hiện việc của Ngài, tuyên dương danh tiếng đẹp đẽ của Ngài, chưa bao giờ lơi lỏng. \n Kiên định là đức tin của tôi, tín tâm là trái tim của tôi. \n Ngài là vị thần vương duy nhất, là hiện thân của bất tử, \n nguyện Ngài chấm dứt sự chờ đợi của tôi, trở lại thế gian, để tôi được nghe lời khôn ngoan của Ngài."
  },
  CollectionHall_127155_Title = {
    Text = "sức mạnh thành tâm"
  },
  CollectionHall_127156_Desc = {
    Text = "Ô Ryta sinh ra khi ảnh hưởng của trận đại hồng thủy đối với thành phố đã hoàn toàn tan biến, nhưng ở những thị trấn hẻo lánh, người dân vẫn đang phải đấu tranh để sống sót. \n\n Hồng thủy khiến mọi người bắt đầu sợ hãi biển cả và sông ngòi, những ai có thể rời đi thì đã sớm rời đi, hiện tại còn ở lại ngôi làng chài nhỏ này chỉ là những phụ nữ và trẻ em khó tìm được chỗ đứng bên ngoài. \n Ở nơi u ám và lạnh lẽo này, Ô Ryta là đứa trẻ duy nhất. \n\n Cô bé kiên trì tin vào những câu chuyện cổ tích mà bà kể — cha mẹ cô đã trở về với biển cả, họ đang chờ Ô Ryta lớn lên. Khi cô lớn lên, mọi người sẽ đoàn tụ, trở thành một gia đình hạnh phúc một lần nữa. \n\n Khi cô còn chưa biết nói, dường như cô đã từng ngủ trong vòng tay ấm áp, nhưng những kỷ niệm khác về cha mẹ, Ô Ryta đã không còn nhớ rõ. \n Nhưng là một đứa trẻ sinh ra và lớn lên ở nơi yên tĩnh, Ô Ryta không hiểu ý nghĩa của \"cô đơn\" hay \"lẻ loi\", cô có riêng một nhóm bạn. \n\n Khác với những người lớn vẫn còn ám ảnh bởi trận lụt, Ô Ryta luôn không sợ hãi biển cả. \n Dân cư của Vua Biển cả, đương nhiên phải làm bạn với biển cả. \n Ô Ryta học cách chơi cùng \"đồng hương\" của mình. \n Cô bắt chước cách di chuyển của con sò múa lượn, học theo cách bơi lội của cá hề trong đám rong biển. \n Cô nằm trên lưng rùa da. Dòng sóng đưa cô trôi đến nơi xa xôi. \n Cô chơi đùa với đàn sứa dưới ánh trăng đầy rẫy trên mặt biển. \n\n Cô là niềm vui, cô là trí tưởng tượng, cô là tiên nữ. \n\n Cô là giấc mơ. \n"
  },
  CollectionHall_127156_Title = {
    Text = "Giấc mơ biển cả"
  },
  CollectionHall_127157_Desc = {
    Text = "Mắt thấy một cô gái quê mặc váy lễ lộng lẫy, trang sức vàng bạc, quạt lông chim, lẻn vào thế giới của giới thượng lưu tinh hoa... \n Không gì bất lịch sự hơn. Dưới phạm thượng, quả thật là dưới phạm thượng...! \n Theo tôi, nên bắt buộc những người thuộc tầng lớp thấp hơn đeo biểu tượng và huy hiệu phù hợp, để tránh bị nhầm lẫn với chúng ta. \n — Công tước Philip Harold \n\n Nếu bạn sống ở Lentiennam, chắc chắn đã nghe nói về cái gọi là \"Hiệu ứng Sorrel\". \n Vẫn đang lo lắng vì quần áo nhà mình không bán được? Vậy thì bạn nên cầu nguyện có chút mối quan hệ, để nhận được sự ưu ái của bà Sorrel — đúng vậy, dù chỉ là một chiếc mũ hình đuôi heo ngốc nghếch, miễn là nó được bà Sorrel đội trên đầu, nó sẽ trở thành món đồ hot. \n Bà ấy chính là thần tượng đại chúng của thời đại mới. \n — \"Bài kiểm tra danh tiếng của bà Sorrel\", Tạp chí Quý cô \n\n Đó là một đêm hè trời quang đãng. \n Chúng tôi cùng ngồi trên sân thượng lát đá cẩm thạch, uống rượu quý hiếm được chế biến qua nhiều năm, bàn luận về thơ ca và hòa bình thế giới. \n Rồi chuyện xảy ra @4 \n Nói trọng điểm? Khụ khụ, xin lỗi... \n Tóm lại, người phụ nữ này đã lừa tôi ba nghìn lôi ô phường, hai phần bất động sản ở Suliran, và một trái tim chân thành! \n — Một vị tử tước lòng tan vỡ không muốn tiết lộ tên"
  },
  CollectionHall_127157_Title = {
    Text = "Nhân danh đóa hồng"
  },
  CollectionHall_127158_Desc = {
    Text = "Phân ly. trải nghiệm. đổ xô đến. xâm lược. \n\nĐối với từ gốc Semitic \"p-l-sh\" của người Phi-li-tin, các học giả Kinh Thánh luôn có những ý kiến khác nhau về ý nghĩa thực sự của nó. \nLần đầu tiên trong đời, Goliath cảm thấy những học giả già nua này cũng có chút tài năng thực sự, vì bốn từ ngắn gọn này gần như tóm tắt cuộc đời của anh ta làm người Phi-li-tin. \n\nNgười Phi-li-tin thực sự là dân tộc trên biển. \nHọ giống như những con cá mập đuôi dài tụ tập lại, lần theo mùi máu tìm đến các hòn đảo để trú ẩn, rồi tiêu diệt tất cả cư dân bản địa tại đó. \n\nNgười Phi-li-tin không biết mệt mỏi. \nHọ không bao giờ dừng chân, khi mọi thứ đã lắng xuống, gen bất an lại thúc đẩy họ rời đi, tìm kiếm con mồi mới. \n\nNgười Phi-li-tin không quan tâm đến ngày mai. \nHọ luôn tiêu xài phung phí tài sản cướp được với tốc độ kinh hoàng, uống cạn giọt rượu cuối cùng, rồi sinh sôi, đấu tranh, bội phản... \n\nKhi tàu ra khơi, Goliath nhìn lại đường di chuyển của tàu trên mặt biển. \nMáu của người Phi-li-tin, máu của cư dân bản địa, máu của kẻ thù, máu của chim biển... \nChúng hòa quyện vào nhau, giống như mực đỏ thẫm đổ vào màu xanh vô tận. \n\nNgày hôm sau, mặt trời mọc như thường lệ, nước biển lấp lánh như muôn vạn mảnh vàng, mọi dấu vết đều biến mất. \nDù đang giữa biển khơi, đại dương dường như đã lãng quên họ."
  },
  CollectionHall_127158_Title = {
    Text = "Lưỡi kiếm khổng lồ"
  },
  CollectionHall_127159_Desc = {
    Text = "Trong dân gian Casshuliya lưu truyền một truyền thuyết về nền văn minh đã chìm. \n\n Theo truyền thuyết, trước khi có các ghi chép lịch sử, sự dịch chuyển bất thường của các vì sao đã khiến một nền văn minh tiền sử chìm xuống đáy biển, và người Casshuliya chính là hậu duệ của nền văn minh đó. \n Ngoài việc buôn bán và đánh bắt cá, một trong những mục đích lớn của người Casshuliya khi ra khơi là tìm kiếm nền văn minh tổ tiên đã mất. \n Họ tin rằng, những cô gái sinh ra dưới các vị sao nhất định sẽ có sự giao cảm với nền văn minh tổ tiên, họ có thể chỉ dẫn vị trí của nền văn minh đã chìm, đồng thời cũng có thể bảo vệ đoàn thuyền khỏi sóng gió. \n\n Hilaster chính là người được chọn như vậy. \n Cô bị trói trên cột buồm cao với cánh buồm trắng căng phồng, nhìn xuống những con người đang bận rộn bên dưới. \n Cô không quan tâm, cũng không hiếu kỳ. \n\n Hilaster có thể cảm nhận thời tiết trên biển từ hướng gió và sự di chuyển của các loài chim biển, thỉnh thoảng cô cũng có thể cảm nhận được hơi thở từ vùng đất xa xôi đang ngủ yên. \n Cô sinh ra dường như thuộc về biển cả, thuộc về những con thuyền — Hilaster thường nghĩ như vậy, sự thật bị giam cầm dường như không gây ra bất kỳ gợn sóng nào trong lòng cô. \n Đôi khi cô sẽ rời khỏi cột buồm, đuổi theo những con chim trắng bay lượn trên không, lúc đó con thuyền sẽ theo sát cô không rời. \n Mọi người tin rằng những cô gái là biểu tượng của một chuyến đi suôn sẻ, những con thuyền được ban phúc sẽ có thể trở về an toàn, mang theo khối tài sản khổng lồ và nền văn minh tiên tiến. \n Còn cô thì không hề hay biết về điều đó."
  },
  CollectionHall_127159_Title = {
    Text = "Cánh buồm bảo hộ"
  },
  CollectionHall_127160_Desc = {
    Text = "Đùng, đùng, đùng. \n Tiếng bước chân từ xa đến gần, một quý ông đội mũ lễ nghi đi qua đống đổ nát, đứng trước người canh gác đang hấp hối. \n Quý ông: Bạn đang làm gì ở đây? \n\n (Quý ông bị mắc chứng nói lắp nghiêm trọng, còn người canh gác thích vòng vo. Để tiện cho bạn đọc, tác giả chỉ trích dẫn những điểm chính trong cuộc trò chuyện.) \n\n Người canh gác: Tôi đang canh giữ nhà tù. \n Quý ông liếc nhìn xung quanh vùng đất trống không người, cùng với đống đổ nát đang từ từ sụp đổ do bị nhiễm rỗng rỗng. \n Quý ông: Nhưng ở đây không có nhà tù, cũng không có tù nhân. Vương quốc của bạn đã không còn tồn tại từ lâu rồi. \n Người canh gác: Tôi đang canh giữ nhà tù. \n Quý ông: Tại sao? \n Người canh gác ngẩng đầu lên, trên khuôn mặt còn non nớt mang theo sự mơ hồ và kiên định. \n Người canh gác: Tôi không biết… Tôi muốn về nhà. \n Người canh gác: Tôi canh giữ nhà tù cho vị đại nhân đó. Nếu đại nhân vui, tôi có thể về nhà. \n Còn vị đại nhân đó là ai, tại sao lại phải canh giữ cho ông ta, cô ấy cũng không rõ. \n Quý ông không truy hỏi, như thể đó là chuyện hết sức tự nhiên. \n Quý ông: Quê hương của bạn, nó trông như thế nào? \n Người canh gác: Ở đó chỉ có mùa đông và đêm tối, còn có rừng rậm và biển cả mênh mông. \n Quý ông: Nghe có vẻ không thích hợp để sống. \n Người canh gác: Tôi ghét ban ngày. Thấy không, tôi được làm bằng sáp, nếu tiếp xúc với mặt trời, tôi sẽ biến mất. \n Người canh gác: Vì vậy tôi chỉ có thể trốn ở đây, không thể tự mình về nhà. \n Quý ông gật đầu như có điều gì đó suy nghĩ. Bỗng nhiên ông ta trở nên hưng phấn. \n Quý ông: Thật trùng hợp, bạn được làm bằng sáp, và tôi vừa đúng là một nghệ nhân làm tượng sáp. \n Quý ông: Chúng ta hãy làm một thỏa thuận — tôi có thể cho bạn đi dưới ánh nắng mặt trời, tôi còn có thể giúp bạn tìm đường về nhà. Đổi lại, bạn phải trở thành trợ lý của tôi. \n Người canh gác: Trợ lý, đó là làm gì? \n Quý ông: Bạn có thể thay tôi canh giữ bảo tàng sáp. Nó khác với nhà tù này, nó là nghệ thuật, nghệ thuật sẽ không sụp đổ. \n Người canh gác: Nghệ thuật mạnh mẽ đến vậy sao? \n Quý ông vui vẻ cười lên. \n Quý ông: Đúng vậy, mạnh mẽ như vậy. \n\n Ở cuối câu chuyện, người canh gác mơ hồ đi theo quý ông, giống như cô ấy mơ hồ đến đây trong nhà tù này vậy. \n Cô ấy luôn là một người dễ dàng thích nghi với hoàn cảnh."
  },
  CollectionHall_127160_Title = {
    Text = "Trôi dạt trong khát vọng"
  },
  CollectionHall_127161_Desc = {
    Text = "Bạn bước chân lên một vùng hoang vu không bóng người. \n Dấu vết hoạt động của nhân loại đã biến mất từ lâu, những sinh linh khô héo trong linh hồn khó khăn lết qua bụi than và sương mù. \n Sự tồn tại ở đây không đáng để ngưỡng mộ, không ai biết điểm dừng của hành trình, chỉ quanh quẩn trong cảnh vật vô tận, quanh quẩn, quanh quẩn. \n Cho đến khi bước chân của họ trở nên nặng nề, ngã mạnh xuống đất, ngước nhìn bầu trời và giơ tay gọi—— \n\n Mong rằng sau khi cuộc hành trình của tôi kết thúc, \n với xương cốt làm đất màu mỡ, làm dinh dưỡng, làm nguồn sống, mầm non yếu ớt sẽ lại phá đất."
  },
  CollectionHall_127161_Title = {
    Text = "Sinh lại trên đất diệt vong"
  },
  CollectionHall_127162_Desc = {
    Text = "Cô ấy đã hỏi một vạn lần trong đêm khuya, tại sao cô phải chịu đựng nỗi đau vô tận này?\n Không ai trả lời. \n Những lời thì thầm xuyên qua cổ họng khản đặc trở thành những mảnh vụn, không truyền đến tai bất kỳ vị thần nào. \n Nỗi đau của cô lâu dài khó tiêu tan, dần dần lên men thành mủ, biến thành một sự thù hận ngày càng sâu sắc. \n Bỗng một ngày, cô phát hiện ra những người xung quanh bắt đầu rỉ ra chất lỏng màu đen, giống hệt như máu chảy ra từ cơ thể mình. \n Họ nhanh chóng trở nên điên cuồng, giống như chính cô. \n Có thể đó là nỗi đau của họ, cô lạnh lùng quan sát, lại cảm thấy một chút khoái cảm. \n Nhưng nếu đó là nỗi đau, chẳng phải cô đã bị màu đen đó ngập tràn từ lâu rồi sao. \n Cô tiến gần đến những mảng màu đen còn sót lại, nhưng lại bất ngờ nhận được tự do. \n Tự do không mang lại cho cô sự giải thoát, cô giống như một ác quỷ bị lưu đày ở địa ngục ngàn năm, những mong ước trong lòng đã bị thù hận ăn mòn hoàn toàn. \n Cơ thể cô bị giam giữ trong xiềng xích, tâm hồn cô trĩu nặng như những khối chì. \n Chỉ có những tiếng hét thê thảm mới có thể rửa sạch linh hồn nặng nề của cô, để cô có thể thở một cách thoải mái. \n Hãy đến đây, nếm trải những gì tôi đã nếm, để bạn trở thành tôi. \n Cô nhận ra màu đỏ thật sự là một màu sắc tuyệt diệu. \n Cuối cùng cô cũng hiểu rằng, nỗi đau không có lý do. \n Hoặc là tự mình uống cạn, hoặc là mời người cùng nếm. \n Tối nay cô rót đầy rượu đắng, mời gọi toàn bộ thị trấn. \n"
  },
  CollectionHall_127162_Title = {
    Text = "Chìm trong màu đỏ thẫm"
  },
  CollectionHall_127163_Desc = {
    Text = "Con tàu của tôi bị cái gì đó vướng víu chặt chẽ, cánh quạt đang phải vật lộn, âm thanh thật đáng sợ. \n Những đám mây mưa tụ tập trên đầu chúng tôi, trong lớp mây đen tối, sấm sét cuộn lên. \n Khi sấm sét đánh vào cột buồm, cánh quạt đã thoát khỏi sự trói buộc và lại quay trở lại. \n Tôi thở phào nhẹ nhõm, nhưng trưởng máy đã bắt đầu la hét. \n\n Nước biển hòa lẫn với một loại chất lỏng sền sệt, trong cơn bão ngoài khơi, mùi hương bị gió thổi đi xa, mũi tôi chỉ ngửi thấy cái chết. \n Nhưng tôi nhận ra, chất lỏng phát sáng đó là một loại máu. \n Người bạn thân yêu nhất của tôi, con tàu mà tôi tin tưởng nhất, đã cống hiến hết sức lực trước khi chìm xuống — những lưỡi cắt đáng lẽ phải xé toạc nước biển, đã mạnh mẽ cắt đứt xúc tu của quái vật. \n\n Đây là điềm lành! Chúng tôi sẽ sớm rời khỏi cơn bão! \n Tôi đang định an ủi các thủy thủ của mình, nhưng ngay khi tôi ngẩng đầu lên, một ánh sáng xuất hiện giữa biển tối. \n Đó có phải là ngọn hải đăng không? Làm sao có thể chứ? Không, không thể nào. \n Đây là giữa đại dương, đất liền gần nhất cách hàng trăm hải lý, làm sao có người, và làm sao có thể xây dựng hải đăng ở đây? \n\n Các thủy thủ của tôi bắt đầu khóc, bắt đầu cầu nguyện, bắt đầu hát lên những bài ca quê hương. \n Sau đó, ngọn hải đăng đột ngột tắt. \n Tất cả ánh sáng biến mất, cơn bão gầm thét cũng chuyển thành những cơn mưa nhỏ rơi xuống boong tàu. \n Các thủy thủ ca ngợi Chúa nhân từ, đắm chìm trong niềm vui sống sót sau thảm họa. \n Nhưng tôi đã nhìn thấy rõ ràng. \n\n Điều đã biến mất trong ánh sáng, thực sự là một người phụ nữ với dáng vẻ quyến rũ."
  },
  CollectionHall_127163_Title = {
    Text = "Giữa tâm bão"
  },
  CollectionHall_127164_Desc = {
    Text = "Khi anh hùng cuối cùng kết thúc cuộc hành trình vĩ đại của mình, mọi người khép lại trang cuối của cuốn sách tranh và chìm vào giấc ngủ say nồng. \n\nĐêm dài sắp đến, câu chuyện của Hiro mới chỉ bắt đầu. \n\nCô ấy dọc theo bờ biển dài đi về phía bắc, vượt qua suối, leo qua núi cao, cho đến tận cùng của vùng đất băng giá. \nĐã nhiều năm trôi qua kể từ cuộc kháng chiến gây chấn động thế giới đó, nơi Hiro đi qua, gió hòa mưa thuận, mọi việc đều suôn sẻ, giữa nô lệ và chủ nhân duy trì một sự cân bằng tinh tế, sự nổi loạn dữ dội trở nên vụng về và buồn cười. \nCô ấy bị nghi ngờ, bị chế nhạo, và cuối cùng bị lãng quên. \nNhưng cô ấy không bao giờ biện minh. \n\nChiến binh Hiro đến và đi không dấu vết, cô chôn sâu hạt giống tự do trong lòng đất giữa biển. Năm năm, mười năm, một trăm năm… \nSẽ có một ngày, chúng sẽ phá vỡ mặt đất và phát triển mạnh mẽ. \n\nKhông ai biết nơi chôn cất cuối cùng của sát thủ Sparta này, người ta nói rằng bạn thân cũ của cô, Ibanimonda, đã thu thập thi thể của cô. \nNhiều năm sau, khi bạn đi qua một sườn đồi cỏ nở đầy hoa nhài, có thể bạn sẽ thấy một ngôi mộ nhỏ, trên đó viết rằng: \n\nDưới lớp cỏ này chôn một chiến binh, hoặc nói rằng \ncô ấy từng là một chiến binh \ncô là con gái của Pericles già, cũng là niềm tự hào của đảo Tilos \nNhà thơ Flacus ca ngợi cô vì sự dũng cảm trong chiến đấu \nNgười Sparta tóc đen biết rõ thành tích của cô"
  },
  CollectionHall_127164_Title = {
    Text = "Phá gỡ xiềng xích"
  },
  CollectionHall_127165_Desc = {
    Text = "A.F.@1 năm @1 tháng @1 ngày\n\n08:00\n\nTiến hành lắp ráp các bộ phận mã số từ 107 đến 133.\n\nBộ phận loại C chỉ còn thiếu chút nữa thôi, sau khi hoàn thành sẽ được đưa vào sử dụng làm lõi năng lượng cho búp bê tự động \"Người Tích Tắc\".\n\nTôi định tự mình lắp ráp, nhưng @2 nói, người phụ trách phải học cách tin tưởng đồng nghiệp của mình.\n\nCũng dám nói, rõ ràng cô ấy mới là người kiểm tra bộ phận đến tận nửa đêm.\n\n-------\n\nA.F.@1 năm @1 tháng @1 ngày\n\n00:21\n\nĐộng cơ điện MF311000 đã lắp ráp xong, bánh răng ăn khớp, đường ống thông suốt, hiện các chức năng hoạt động bình thường. Sắp tiến hành hiệu chỉnh lần cuối.\n\n13:07\n\nKết nối năng lượng đặc biệt S, động cơ điện MF311000 vận hành tốt, tương thích tốt với thân thể nhân tạo số EA307850, thân thể nhân tạo vận hành bình thường.\n\n@2 rất lạc quan, cô ấy cho rằng lần này chúng tôi có thể tiến xa hơn trước. Tôi nhắc cô ấy đừng quên những gì đã xảy ra trong lần đánh thức thứ năm, cô ấy liền bịt tai nói không nghe thấy. Lần đó nếu không phải tôi phản ứng nhanh, ngọn lửa tự cháy từ lõi năng lượng đã thiêu sạch tóc cô ấy rồi.\n\nThật nên để cô ấy nếm thử cảm giác trọc đầu, biết đâu như vậy cô ấy còn học được cách cẩn thận.\n\n-------\n\nA.F.@1 năm @1 tháng @1 ngày\n\n14:55\n\nChuẩn bị cuối cùng hoàn tất, năng lượng sẵn sàng, thiết bị trói buộc đã kích hoạt, trạng thái trói buộc: Tốt. Thân mình sẽ được lắp đặt sau khi hoàn thành đánh thức.\n\n15:00\n\nBắt đầu lần khởi động thứ 13 của \"Người Tích Tắc\".\n\n15:05\n\nThân mình EA307853 vận hành bình thường, động cơ điện MF311000 vận hành bình thường. Khớp cổ của \"Người Tích Tắc\" hoạt động bình thường, bộ phận đầu của \"Người Tích Tắc\" vận hành bình thường.\n\n15:15\n\n\"Người Tích Tắc\" thực hiện thành công lệnh chớp mắt, theo dõi ánh mắt, mở miệng. Động cơ điện có hiện tượng phát nhiệt, nhưng vẫn trong phạm vi chấp nhận được.\n\nSắp tiến hành lắp đặt bộ phận tứ chi, cầu trời lần này chúng tôi thuận lợi.\n\n18:07\n\nKhi thực hiện lệnh đi bộ, lõi động cơ nóng chảy, mạch điện cháy rụi. Năng lượng đặc biệt S vẫn nguyên vẹn.\n\n@2 rất bảo vệ nguồn năng lượng đặc biệt này, ngay cả tôi cũng bị cấm chạm vào. Tôi nghĩ tôi có thể hiểu được, đó thực sự là một vật thể bí ẩn, trông giống như kim loại bạc bình thường, cũng không có vẻ gì là có khả năng tích trữ năng lượng, nhưng thực sự có thể cung cấp năng lượng cho búp bê tự động, hơn nữa nhiệt độ cao như vậy cũng không gây ra hư hại gì cho nó, thật không thể tin được.\n\nNếu thứ này có thể sản xuất hàng loạt, hoặc khai thác với số lượng lớn…\n\nCó lẽ tôi nên tìm một ngày hỏi lại cô ấy, cũng không biết cô ấy còn phải dành bao nhiêu thời gian cho con búp bê này nữa. Ngày nào đó chính cô ấy biến thành một con búp bê, tôi cũng chẳng lấy làm ngạc nhiên.\n"
  },
  CollectionHall_127165_Title = {
    Text = "Lõi tan vỡ"
  },
  CollectionHall_127166_Desc = {
    Text = "「Chúng ta dùng đồng và sắt phàm tục, đo lường quỹ đạo của những vì sao, nhưng vực thẳm vô tận có thuật toán riêng của mình, không thể định liệu trước.」\nTrên con tàu đang từ từ chìm, Copperchant đọc bài thơ \"Khúc Hải Dẫn Tưởng nhớ Thủy Thủ」.\nCô đã biết vận mệnh của mình, cũng đã chọn vận mệnh của mình, vậy nên đối diện cái chết, cô không sợ hãi, chỉ có sự bình yên—bình yên mà cháy, bình yên mà hoàn thành lần cuối dẫn đường.\nNhưng ánh sáng từ đám cháy quá rực rỡ, cô không thể thấy đường phía trước, không thể phát ra âm thanh hay vẫy cờ. Dưới sự dẫn đường không đầy đủ như vậy, liệu tàu có thể đi đúng hướng?\nCô không biết và vì vậy sinh ra nỗi sợ hãi và lo âu.\nLúc này,\" Khúc Hải Dẫn Tưởng nhớ Thủy Thủ\" đã đưa ra hướng dẫn:「Người điều hướng trẻ tuổi ơi, ngươi cuối cùng sẽ bị ôm trong lòng nước mặn, biến thành ngọn lửa lân tinh dẫn đường.」\nNgọn lửa lân tinh dẫn đường? Copperchant im lặng. Quả thực cô đã nghe kể về câu chuyện lửa Thánh Elmo lan truyền giữa các thủy thủ, nhưng cơ thể phàm tục làm sao có thể biến thành ngọn lửa thánh chiếu sáng thế gian?\nNhưng dù hy vọng mỏng manh, Copperchant vẫn không ngừng cầu nguyện trong lòng: cầu nguyện mình có thể thực hiện nhiệm vụ, hoàn thành công việc hướng dẫn cuối cùng.\nNgoại trừ Copperchant tự mình, không ai có thể nghe thấy lời cầu nguyện này, nhưng như vậy đã đủ rồi—\nTrong bóng tối, chính lõi bạc đã dùng chất nhầy phân rã là dưỡng liệu, bùng phát ánh sáng mạnh mẽ, thực hiện lòng ước nguyện cuối cùng của cô.\n「Sổ Đen Triều Thần sẽ ghi lại tên ngươi, khiến sóng giận dữ gào thét cho ngươi vang lên khúc nhạc an hòa vĩnh cửu.」\nCuối cùng, như bài thơ\" Khúc Hải Dẫn Tưởng nhớ Thủy Thủ\" đã nói, cô chết trên biển.\nNhưng cô đã vượt qua bài thơ\" Khúc Hải Dẫn Tưởng nhớ Thủy Thủ」.\nĐó là sự ngạo mạn và khuyên bảo của người điều hướng nhân loại khi đối diện với biển cả, mà giờ đây, cô đã trở thành lửa Thánh Elmo, dẫn đường con tàu vĩnh viễn."
  },
  CollectionHall_127166_Title = {
    Text = "Thánh hỏa dẫn lối"
  },
  CollectionHall_127167_Desc = {
    Text = "Cô ấy được gọi là đứa con bị nguyền rủa, sinh ra cùng với cái chết, là người con không được chúc phúc. \n \"Chiếc nôi\" thuộc về cô ấy và em gái vừa vỡ, ánh sáng rực rỡ đã chảy ra từ khe hở, bám rễ trên mặt đất. Trong khoảnh khắc, cỏ xanh héo úa, hoa tươi trở nên xám xịt, thậm chí cả những cây lớn ở xa, cá trong hồ cũng bị cô ấy hút hết sinh lực, trở thành những xác không hồn. \nDân tộc của cô ấy kinh hoàng, vội vàng chuyển tất cả các chiếc nôi khác đi. Cô ấy cố gắng phá vỡ chiếc nôi, như một con chim non đập tan vỏ trứng, tay cô ấy duỗi ra nhưng bị tránh né với sự ghê tởm, những gì cô ấy nhìn thấy chỉ là những khuôn mặt đầy chán ghét. \nChỉ có em gái cô ấy, người sinh sau cô ấy vào đêm đó, lại trưởng thành sớm hơn cô ấy, luôn ôm lấy cô ấy. Dùng giọng hát giống như một con chim linh thiêng, cô ấy hát bài hát ru một bài lại một bài. \nNgủ đi, ngủ đi, chị yêu dấu của tôi; \nNgủ đi, ngủ đi, giấc mơ tốt đẹp sẽ đến. \n\nCô ấy không nên tồn tại, nếu cô ấy không tồn tại, em gái xinh đẹp của cô ấy sẽ không bị dính bóng tối tội lỗi. \nEm gái đáng thương của tôi, cô ấy luôn nghĩ, bạn đã gánh chịu giá cả của sự tồn tại mà không nên gánh chịu. \nEm gái đáng thương của tôi, cô ấy luôn nghĩ, miễn là chị có thể làm được, nhất định sẽ tận lực vì bạn. \nNgủ đi, ngủ đi, em yêu dấu của tôi; \nNgủ đi, ngủ đi, tôi vẫn yêu bạn trong giấc mơ."
  },
  CollectionHall_127167_Title = {
    Text = "Khúc ru thôn phệ"
  },
  CollectionHall_127168_Desc = {
    Text = "Anh ta nhìn thấy ngọn tháp nhà thờ tan chảy như một cây nến, nhỏ giọt xuống đôi cánh trắng của vị linh mục. Những thánh tích trên kính màu thối rữa với tốc độ cực nhanh thành bộ xương, rồi ngay lập tức lùi lại trở thành trẻ sơ sinh. Những hình dạng hình học nhọn và tròn mềm được đọc ra từ miệng tín đồ, chất đầy cả hội trường.\nAnh ta nhìn thấy không gian nhà ga lặp đi lặp lại gập lại thành không gian phi Euclid, sân ga ở xa gần như trong tầm tay, cửa soát vé ở gần lại trở nên xa vời. Đồng hồ trong sảnh quay ngược chiều kim đồng hồ, đám đông như xương khô bị những đường dây vô hình kéo lùi lại, khói tím dày đặc như hoa violet bay từ đám mây vào ống khói của chiếc tàu.\nAnh ta nhìn thấy \"Không\" trong rừng trở thành thực thể, cây cối, đá, dây leo chỉ là những đường viền trong suốt do \"Không\" vẽ ra. Lông thiên nga là những mảnh màu mosaic liên tục thay đổi, nơi chúng bơi qua, mặt hồ đông cứng thành kính màu trong suốt. Dưới ghế dài của cặp tình nhân, bóng râm màu cam rực rỡ đang cố gắng gặm nhấm mắt cá chân của chủ nhân.\nAnh ta nhìn thấy những nốt nhạc của nhà hát opera như những giọt mưa rơi xuống khán giả, anh ta nhìn thấy nghĩa trang nhẹ nhàng gợn sóng, giống như một cái bìu của quái vật khổng lồ đang thở... \nAnh ta thấy nhiều, rất nhiều. Anh ta đã kể lại những gì anh ta nhìn thấy cho mẹ, thầy, bạn bè của mình, anh ta đã vẽ những gì anh ta nhìn thấy lên bức tranh. Anh ta muốn mang thế giới mà mình thấy đến trước mặt mọi người, nhưng những người xung quanh anh ấy ngày càng ít lại, một thế giới ngày càng xa rời anh ta.\nNhưng tại sao lại như vậy? Anh ta chỉ ghi lại những điều mà mình đã thấy. Pikman không thể hiểu nổi điều đó.\nPikman buồn khổ đứng trước gương. Anh ta thấy một con xác sống gặm nhấm cái miệng đầy răng nhọn vào anh ta.\n \"Không có gì quan trọng hơn việc nhìn thấy sự thật. Điên loạn, hỗn loạn, tham lam... có muốn xem không, Pikman?\"\nPikman nhận ra cười với anh ta, bước vào tấm gương đó.\nAnh ta chỉ muốn tận mắt chứng kiến điều thực sự điên cuồng nhất, và trung thành vẽ nó lên vải của mình.\nAnh ta không phải là con người, cũng không phải là xác sống.\nAnh ta chỉ là họa sĩ hiện thực Pikman."
  },
  CollectionHall_127168_Title = {
    Text = "Bất thường của Chủ nghĩa Hiện thực"
  },
  CollectionHall_127169_Desc = {
    Text = "Khi một người có thể biết hết tất cả quá khứ và tương lai, điều đang chờ đợi anh ta không phải là niềm vui của sự toàn tri, mà là sự thương cảm và tuyệt vọng vô tận. \n Đôi mắt của cô ấy có thể nhìn thấy những sợi chỉ ẩn sau mọi sự vật, một đầu của sợi chỉ kết nối với quá khứ, đầu kia kết nối với tương lai. \n Sợi chỉ đó được mọi người gọi là số phận. \n Cô ấy nhìn nhận những người đi theo bên cạnh mình như thế nào? \n Con người tốt bụng và nhân ái, con người kiêu ngạo và đa nghi. \n Nhưng số phận của những người đó và số phận của nhân loại đã được định sẵn từ khi bắt đầu mỗi lần gặp gỡ. \n Chắc chắn cô ấy yêu mến họ, nếu không tại sao lại nhiều lần đưa tay ra, cho họ lửa? \n Chắc chắn cô ấy kỳ vọng vào họ, nếu không tại sao lại kiên định bước vào bóng tối của vòng luân hồi trong sự hủy diệt? \n Vì yêu mến, cô ấy luôn mang nỗi buồn. \n Vì kỳ vọng, cô ấy nhiều lần thất vọng. \n Cô ấy sâu lún trong đầm lầy đen tối, liên tục gỡ rối giữa vô số sợi chỉ đen, không biết mệt mỏi. \n Bánh xe số phận xoay chuyển liên tục. \n Cô ấy thấy ngọn lửa tham lam cuốn lấy bầu trời. \n Cô ấy thấy sự cố chấp mù quáng dẫn đến tự sát. \n Cô ấy thấy những ý niệm điên cuồng gia tăng sự hủy diệt. \n Sự hỗn mang vô trật tự luôn đến chậm rãi. \n Hy vọng và tuyệt vọng luẩn quẩn một cách vô ích, không bao giờ có điểm dừng. \n Cho đến khi cô ấy nhìn thấy một ánh sáng sao trong bóng tối. \n Ánh sáng ấy yếu ớt, nhưng cô ấy đã ở trong bóng tối quá lâu. \n Vào khoảnh khắc đối diện, cô ấy đã rơi nước mắt. \n"
  },
  CollectionHall_127169_Title = {
    Text = "Vòng quay vô định"
  },
  CollectionHall_127170_Desc = {
    Text = "Năm mới, bạn quyết định tổ chức một buổi lễ chưa từng có, để đón chào sự chuyển giao của thời gian một cách trang trọng nhất. \n Vì vậy, bạn đã chuẩn bị rất lâu. Thắp nến, để ánh sáng ấm áp chiếu sáng khuôn viên trường vào đêm đông; dựng một bục cao giữa sân tập, trải thảm nhung đỏ thẫm đầy hoa văn. Bạn thậm chí tự tay cắt ra vô số dải ruy băng được quấn bằng vàng và bạc, chỉ mong khoảnh khắc đếm ngược này vượt qua nỗi buồn chia ly, trở thành dấu ấn vĩnh cửu khi năm cũ và năm mới ôm nhau. \n Nhưng... vẫn thiếu điều gì đó. \n Bạn bước vào sâu trong kho cũ, phủi đi lớp bụi dày, cuối cùng tìm thấy chiếc đồng hồ cổ. Vỏ của nó đã phai màu, kim đồng hồ đã gãy, rơi ra do sự xâm thực của thời gian, rõ ràng là không thể sử dụng được. \n Khi đang cảm thấy bế tắc, Thái Di Sơ xuất hiện, sau lưng là một chiếc đồng hồ mới tinh. \n Chiếc đồng hồ đó thật quen thuộc. Cô vẫn cười nhí nhảnh, nhưng trong ánh mắt lại ẩn chứa một sự ấm áp kiên định. \n \"Thế nào, chiếc đồng hồ này, kết hợp với điệu nhảy của tôi, chắc chắn sẽ là buổi lễ hoành tráng nhất.\"\n \"Cái này... không phải là đồng hồ của Tà Vy chứ?\"\n \"Ôi, bạn cũng biết cô ấy cô đơn ngồi trong nước, thật buồn tẻ.\"\n \"Nếu để cô ấy tham gia vào buổi lễ của chúng ta, cảm nhận được tình yêu của tôi, có lẽ sẽ khiến cô ấy có chút hứng thú nhỉ～\"\n Đêm khuya dần buông xuống, Thái Di Sơ đứng trước chiếc đồng hồ khổng lồ, như một món quà được thời gian tự tay gói lại. \n Những dải ruy băng như những bông pháo chưa nở quấn quanh thân thể cô, dưới ánh đèn lấp lánh tạo thành sóng vàng đỏ và bạc xanh. Chiếc nơ đầy đặn ở eo chính là nút thắt cuối cùng do năm mới tự tay buộc lại—cô chính là món quà lớn nhất của năm cũ, được bọc trong lụa vui tươi, chờ đợi thời gian mở ra. \n Cánh tay cô từ từ nâng lên, đầu ngón tay dạo chơi theo ánh sáng, cuối cùng chỉ vào chiếc đồng hồ treo lơ lửng phía sau. Mười hai con số trên mặt đồng hồ kết thành ánh sáng, nhảy múa trên đầu ngón tay cô. \n Đám đông ngước nhìn điệu nhảy say mê của Thái Di Sơ, như bị không khí vui tươi lây lan, bắt đầu rung động theo nhịp điệu của cô. \n Và khi tiếng chuông vang lên, đầu ngón tay cô nhẹ nhàng chạm vào khởi đầu vĩnh cửu. Món quà bị trói buộc mở rộng vòng tay, biến tất cả sự ăn mừng được lưu trữ trong năm cũ thành những phước lành bay bổng, rải xuống trần gian."
  },
  CollectionHall_127170_Title = {
    Text = "Thời khắc đếm ngược"
  },
  CollectionHall_127237_Title = {
    Text = "Tin cũ của thành phố biển"
  },
  CollectionHall_127239_Title = {
    Text = "Quốc gia Bàn Long"
  },
  CollectionHall_129601_Desc = {
    Text = "<Title:Tóm tắt>\nCô gái sống trên một hòn đảo biệt lập, vui vẻ và tràn đầy sức sống. \nDo tính cách hoạt bát và sức mạnh bẩm sinh, nhiều người khó có thể thích nghi với sự gần gũi quá nhiệt tình của cô khi lần đầu gặp mặt. Nhưng chỉ cần ở bên nhau một thời gian, mọi người sẽ nhận ra rằng cô chỉ muốn giúp đỡ bạn bè hết mức có thể. \nMặc dù đôi khi cách giúp đỡ của cô khác thường, nhưng nhìn chung, hầu hết thời gian, cô vẫn giúp đỡ người được giúp giải quyết rắc rối, có lẽ? \nTrong trạng thái không kiểm soát được khả năng của mình do sự ức chế bị gỡ bỏ, phòng thí nghiệm thường xuyên nổ tung. \nDo thiếu giáo dục cần thiết, đôi khi Mosk cần phải diễn đạt bằng tay chân một lúc lâu mới có thể khiến người đối thoại hiểu ý mình. Tất nhiên, Mosk không cần người khác làm như vậy, trực giác tuyệt vời của cô có thể giải quyết vấn đề này rất tốt. \nCô rất thân thiết với Nốtira và Người Giữ Gìn. Theo lời cô, ba người đã có một lời hứa về việc cùng nhau phiêu lưu, nhưng Nốtira thì hoàn toàn không nhớ, còn Người Giữ Gìn thì không nói về trải nghiệm đó. \nThỉnh thoảng, bên cạnh Mosk có thể thấy một con hải mã đội mũ Misaque, Mosk gọi nó là\"Viên than nhỏ thế hệ hai\". Mỗi khi như vậy, một số công việc đáng lẽ phải hoàn thành sẽ tự dưng biến mất."
  },
  CollectionHall_129601_LockTip = {
    Text = "Giải khóa sau khi hoán tỉnh \"Mosk\""
  },
  CollectionHall_129601_Title = {Text = "Vortice"},
  CollectionHall_129803_LockTip = {
    Text = "Cần hoàn thành bất kỳ màn chơi nào trong sự kiện giới hạn thời gian \"Tàu hỏa hạnh phúc lao nhanh: Khởi hành\""
