  CollectionHall_133769_Title = {
    Text = "Chìm đắm"
  },
  CollectionHall_133770_Desc = {
    Text = "Kính thưa quý hành khách, xin chào mọi người!\nLễ hội Kỳ Tuế sắp đến, trong khoảnh khắc tươi đẹp sum họp gia đình, từ biệt năm cũ đón năm mới này, toàn thể nhân viên phục vụ của chuyến tàu, xin gửi đến quý vị — những người trở về quê hương từ muôn nơi, vượt qua hành trình vất vả — những Lời chúc chân thành nhất —\nChúc quý vị Kỳ Tuế vui vẻ, Hạnh phúc bên gia đình, phi tốc trên đường, vạn sự như ý! <(￣︶￣)↗[GO!]"
  },
  CollectionHall_133770_LockTip = {
    Text = "Hoàn thành Bản ghi đặc nhiệm \"Tàu chạy về lễ hội cầu năm\""
  },
  CollectionHall_133770_Title = {
    Text = "Phi Tốc: Chuyến Tàu Hạnh Phúc"
  },
  CollectionHall_133771_Desc = {
    Text = "Kính thưa quý hành khách, chúng tôi rất tiếc phải thông báo rằng, do tâm trạng cá nhân của trưởng tàu, chuyến tàu Hạnh Phúc lần này sẽ tạm thời dừng tại đây. Thời gian khởi hành cụ thể sẽ được phát thanh thông báo ngay sau khi cuộc tàn sát lẫn nhau kết thúc.\nTrong thời gian dừng tàu, hệ thống điều hòa, chiếu sáng và nhà vệ sinh vẫn hoạt động bình thường, quý khách vui lòng sử dụng tùy theo nhu cầu giết chóc, để tránh không xảy ra nguy hiểm.\nDù sao, nghĩa vụ của chuyến tàu Hạnh Phúc chính là mang lại tiếng cười cho tất cả hành khách～(￣▽￣～)(～￣▽￣)～"
  },
  CollectionHall_133771_LockTip = {
    Text = "Hoàn thành Bản ghi đặc nhiệm \"Tàu chạy về lễ hội cầu năm\""
  },
  CollectionHall_133771_Title = {
    Text = "Dừng Gấp!"
  },
  CollectionHall_133772_Desc = {
    Text = "Xin lưu ý: Ga tiếp theo phía trước là Quốc gia Bàn Long. Quý hành khách xuống tàu tại Quốc gia Bàn Long vui lòng học trước kỹ thuật hát bài \"Bông Hoa Nhài Tươi Đẹp\".\nBởi vì, các bạn đã không còn cơ hội xuống tàu nữa rồi φ(≧ω≦*)♪"
  },
  CollectionHall_133772_LockTip = {
