  },
  CollectionHall_133773_Title = {
    Text = "Xanh và xanh thẳm hơn"
  },
  CollectionHall_134293_Desc = {
    Text = "<Title:Giới thiệu>\nChủ nhân của Nhà hát Định Mệnh, biên kịch, diễn viên, người dệt vĩnh hằng và tù nhân vĩnh cửu của số mệnh…\nNgay từ khi sinh ra, Arachne đã sở hữu khả năng nhìn thấy những sợi tơ định mệnh. Sử dụng chiếc xa quay mang tên \"Moirai\", nàng không ngừng nghỉ dệt nên số phận cho thế giới, duy trì sự cân bằng mong manh của định mệnh. Vì điều đó, nàng đã trục xuất mọi điều tốt đẹp và yếu đuối khỏi bản thân mình, đưa ra những quyết định đúng đắn nhất cho mọi số mệnh, một mình gánh chịu tội lỗi của tất thảy vận mệnh.\nNàng đã sớm biết rằng, ở tận cùng của lưới định mệnh, sự hủy diệt rốt cuộc không thể tránh khỏi. Thế nhưng nàng vẫn không ngừng dệt từ thuở hồng hoang, nhìn tất cả những gì mình yêu thương từ từ rơi vào điểm kết cục hư vô ấy.\nNàng dệt, chờ đợi, chờ đợi sợi tơ mà nàng chưa từng thấy trước — sợi tơ sẽ cứu vớt lưới định mệnh khỏi vực thẳm."
  },
  CollectionHall_134293_LockTip = {
    Text = "Mở khóa sau khi đánh thức \"Arachne\""
  },
  CollectionHall_134293_Title = {Text = "Arachne"},
