  CollectionHall_139856_Title = {
    Text = "Người đưa tin"
  },
  CollectionHall_140337_Desc = {
    Text = "Bạn dạo bước giữa các tinh vân, chứng kiến từng ngôi sao băng lần lượt rơi rụng.\nCó những ngôi nóng bỏng, có những ngôi rực rỡ, có những ngôi lạnh giá, có những ngôi u ám — chưa kịp nói lời từ biệt, chúng đã kéo theo vệt đuôi dài, lần lượt mờ nhạt trên bầu trời.\nBạn bụm lấy tro tàn, muốn khắc ghi dấu vết tồn tại vào tim.\nNhưng những hình ảnh ấy rốt cuộc vẫn trôi qua kẽ tay, xuyên qua ký ức ngày càng phai nhạt, tan biến trong thời không vô tận.\nHóa ra bạn cũng chỉ là một ngôi sao trong muôn ngàn cơn mưa sao.\nNhưng bạn sẽ không dừng lại. Bạn phải bước tiếp, xuyên qua sự tịch diệt dài đằng đẵng, cho đến kỷ nguyên tiếp theo.\nCho đến khi sao lấp đầy bầu trời."
  },
  CollectionHall_140337_Title = {
    Text = "Gửi Muôn Vì Sao"
  },
  CollectionHall_140428_LockTip = {
