  CollectionHall_141832_Title = {
    Text = "Trăng Non và Tuyết Sâu: Bảo Vật của Umapati"
  },
  CollectionHall_142131_Title = {
    Text = "Hạt Giống Tình Yêu Bị Lãng Quên"
  },
  CollectionHall_142154_Title = {
    Text = "Thị trấn"
  },
  CollectionHall_142155_Desc = {
    Text = "Khi bị những sinh vật dị dạng không thể hiểu, không thể nhận ra, gây buồn nôn áp sát, việc phát động Tấn Công phòng thủ là bản năng của sinh vật.\nVì vậy, điều này không thể coi là tội lỗi."
  },
  CollectionHall_142155_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\" ở độ khó Khó"
  },
  CollectionHall_142155_Title = {
    Text = "Bạo Lực Vô Tội"
  },
  CollectionHall_142156_Desc = {
    Text = "\"Ngươi có nghe thấy giọng ta không? Dù bóng hình đã Tan chảy trong gió.\"\nTừ trong gió vọng lại tiếng Gọi từ xa xôi, đó là tiếng tìm kiếm vượt qua khoảng thời gian xa thẳm, từ đêm đông rộng lớn và lạnh giá, truyền đến từ bờ kia của sự Quên lãng."
  },
  CollectionHall_142156_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\""
  },
  CollectionHall_142156_Title = {
    Text = "忘却の彼方"
  },
  CollectionHall_142157_Desc = {
    Text = "Ký ức nháy mắt chồng chất, kết cục thật giả không rõ ràng.\nNhưng điều đó có thực sự quan trọng không?\nDù sao, không phải mọi câu chuyện đều bắt đầu bằng tình yêu, nhưng tất cả đều sẽ kết thúc bằng cái chết."
  },
  CollectionHall_142157_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\""
  },
  CollectionHall_142157_Title = {
    Text = "Bốn Lớp Ký Ức"
  },
  CollectionHall_142158_Desc = {
    Text = "Nếu một ngày nào đó, bạn cũng giống như tôi, rơi vào cảnh Huyết Nhục nát bấy, thối rữa tan hoang.\nThì chắc chắn bạn cũng sẽ hiểu được—\nKhoảnh khắc chạm vào đầu ngón tay nhỏ nhắn của cô ấy, là điều kỳ tích hiếm có trên cõi đời này."
  },
  CollectionHall_142158_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\""
  },
  CollectionHall_142158_Title = {Text = "Kỳ Tích"},
  CollectionHall_142159_Desc = {
    Text = "Bạn có chán ngán cuộc sống bình thường, lặp đi lặp lại, tẻ nhạt, ngày qua ngày không?\nHãy thử điều gì đó mới mẻ đi, một thế giới khác đang mở rộng miệng đón chào, gửi đến bạn lời mời nồng nhiệt."
  },
  CollectionHall_142159_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\""
  },
  CollectionHall_142159_Title = {Text = "Vùng Máu"},
  CollectionHall_142160_Desc = {
    Text = "Tình yêu là cao thượng, tình yêu là Tham lam; tình yêu là phúc lành, tình yêu là lời nguyền.\nTình yêu sinh ra từ nước, cũng sẽ tan biến theo nước.\nMà mùa mưa sẽ không còn trở lại."
  },
  CollectionHall_142160_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\" ở độ khó Khó"
  },
  CollectionHall_142160_Title = {Text = "Mùa Mưa"},
  CollectionHall_142161_Desc = {
    Text = "Mọi Sinh lực đều sinh ra trong vô tri, hấp thụ dưỡng chất từ vạn vật, cải tạo môi trường, Ngấu Nghiến tài nguyên, Lễ vật cho bản thân.\nĐây là tội nguyên thủy không thể thoát khỏi."
  },
  CollectionHall_142161_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\""
  },
  CollectionHall_142161_Title = {
    Text = "Tội lỗi nguyên thủy"
  },
  CollectionHall_142162_Desc = {
    Text = "Có một loài thực vật gọi là bồ công anh, để hạt giống của mình trôi theo gió.\nNhững hạt giống bông mềm lang thang theo gió, rời xa quê hương thật xa, thật xa.\nCô đơn một mình, khi nào nó mới quyết định được nơi mình thuộc về?\nĐó là, khi trong sa mạc có duy nhất một người yêu cây bồ công anh ấy."
  },
  CollectionHall_142162_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\""
  },
  CollectionHall_142162_Title = {
    Text = "Bồ Công Anh Đi Về Đâu"
  },
  CollectionHall_142163_Desc = {
    Text = "Trời đất bao la, biển cát mênh mông.\nĐó là vùng đất không người chỉ có bạn và tôi.\nĐó là cuộc lãng du tình yêu tự do vĩnh cửu."
  },
  CollectionHall_142163_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\""
  },
  CollectionHall_142163_Title = {
    Text = "Lãng Du Biển Cát"
  },
  CollectionHall_142164_Desc = {
    Text = "Ta có thể Gọi tên ngươi không? Dù cho thế giới có tan biến.\"\nNếu tất cả ký ức đều sẽ bị Sự diệt vong xóa nhòa, bóng tối của sự Quên lãng sẽ Nuốt chửng mọi quá khứ chưa kịp tưởng nhớ.\nVậy thì hãy nắm tay nhau, để ánh sáng bạc Liên Kết bạn và tôi.\nTrong giấc mộng mới mẻ, trong tiết xuân sớm khi những hạt giống non mềm vừa nảy mầm."
  },
  CollectionHall_142164_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\""
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento"
  },
  CollectionHall_142165_Desc = {
    Text = "Hãy cất cao tiếng hát, những sinh lực rực rỡ đang ca ngợi tự do, gieo trồng Vũ Chủng của hy vọng đến khắp mọi nơi."
  },
  CollectionHall_142165_LockTip = {
    Text = "Hoàn thành Kết Nối Đa Chiều \"Hạt Giống Tình Yêu Bị Lãng Quên\" ở độ khó Khó"
  },
  CollectionHall_142165_Title = {
    Text = "Bài Ca Mở Màn"
  },
  CollectionHall_142868_Desc = {
    Text = "<Title:Giới thiệu>\nPontos luôn nhớ tâm trạng của mình vào ngày biết được lịch sử gia tộc. Trước đó, anh chưa bao giờ chuẩn bị sẵn sàng để gánh vác bất kỳ trách nhiệm nào, mọi người đều yêu quý anh, anh điển trai, thú vị và vô tư.\n@1Những con tàu qua lại quanh năm ở Vương Cảng khiến anh không phải đối mặt với những ngày tháng tẻ nhạt lặp đi lặp lại, anh đã nghe quá nhiều câu chuyện, nhiều người nói anh hiểu biết rộng, đến mức anh không muốn thừa nhận rằng mình có thể trở nên tầm thường như mọi người.\nVì vậy, anh bị nhấn chìm trong niềm hân hoan khổng lồ vừa bất ngờ vừa thuận lẽ tự nhiên. Hơn nữa, sự tồn tại vĩ đại và khó lường hơn ẩn sau bóng ma đã thúc đẩy gia tộc qua bao thế hệ đã công nhận anh — anh sinh ra đã khác biệt.\nThế nhưng một trò đùa của \"N\"đã khiến những kẻ cuồng tín tàn phá cả ngôi làng trong một cuộc tấn công ven biển không phân biệt đối tượng.\nKhông thể đối mặt với thảm họa ập đến bất ngờ, để có được Sức mạnh từ vực thẳm, Pontos đã chọn cách hiến tế thân xác của mình cho @3, cùng với đó là tất cả mọi khả năng của bản thân.\nNhưng điều đó có quan trọng gì đâu, sẽ không còn bất cứ thứ gì vượt khỏi tầm kiểm soát của anh nữa.\nAnh sẽ không bao giờ mất đi bất cứ thứ gì nữa."
  },
  CollectionHall_142868_LockTip = {
    Text = "Mở khóa sau khi Hoán tỉnh \"Pontos\""
  },
  CollectionHall_142868_Title = {Text = "Pontus"},
  CollectionHall_142901_Title = {
    Text = "Epojans Vĩnh Cửu"
  },
  CollectionHall_143468_Desc = {
    Text = "Hồi chuông báo tử đã vang lên, kẻ phản bội dâng lên màn trình diễn điên rồ nhất.\nVô số sợi chỉ, sẽ dệt nên kết cục như thế nào—\ndo bạn quyết định."
  },
  CollectionHall_143468_LockTip = {
