  },
  CollectionHall_143468_Title = {
    Text = "Cùng dệt nên hồi kết"
  },
  CollectionHall_143469_Desc = {
    Text = "Mau lại đây nào, mau lại đây nào, mọi người đều đang chờ bạn.\nBước qua hành lang dài dằng dặc, bước lên sân khấu vĩnh cửu.\nBạn chính là toàn bộ vở kịch, nhân vật chính duy nhất đấy."
  },
  CollectionHall_143469_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143469_Title = {
    Text = "Xoắn ốc vô tận"
  },
  CollectionHall_143470_Desc = {
    Text = "Họ cùng nhau ca hát, họ mỗi người một nhiệm vụ.\nNhưng tất cả đều là cô ấy.\nĐây là vở độc diễn không bao giờ kết thúc buổi diễn thuộc về cô ấy."
  },
  CollectionHall_143470_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143470_Title = {
    Text = "Chương trình độc diễn"
  },
  CollectionHall_143471_Desc = {
    Text = "Act I: Kéo sợi\nAct II: Cân đo\nAct III: Phán quyết\nCứ thế lặp đi lặp lại, cứ thế lặp đi lặp lại......"
  },
  CollectionHall_143471_LockTip = {
    Text = "Hoàn thành điều tra hành động·khó khăn Bài sao 5-11 để mở khóa"
  },
  CollectionHall_143471_Title = {
    Text = "Ba màn kịch"
  },
  CollectionHall_143472_Desc = {
    Text = "Chẳng qua là một chàng thanh niên Cuồng nhiệt, đã nổ súng tại một góc phố bình thường.\nÍt nhất là vào lúc đó, Mọi người đều nghĩ vậy."
  },
  CollectionHall_143472_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143472_Title = {
    Text = "Tự của lửa chiến"
  },
  CollectionHall_143473_Desc = {
    Text = "Kẽo kẹt, kẽo kẹt.\nSố phận ơi, bánh xe của ngươi quay mãi không ngừng.\nNghèo khó lẫn quyền lực đều bị ngươi Tan chảy như băng.\nNgươi che giấu bản thân, lại ẩn giấu diện mạo,\nnhưng cũng chiếu sáng về phía ta......"
  },
  CollectionHall_143473_LockTip = {
    Text = "Hoàn thành điều tra hành động·khó khăn Bài sao 5-11 để mở khóa"
  },
  CollectionHall_143473_Title = {
    Text = "Số phận ơi, ngươi thật tàn nhẫn"
  },
  CollectionHall_143474_Desc = {
    Text = "Tạm biệt nhé, trong giai điệu cuối cùng.\nTạm biệt nhé, dưới ánh mắt dõi theo của số phận.\nNhân vật chính của câu chuyện, sẽ bước lên hành trình mới."
  },
  CollectionHall_143474_LockTip = {
    Text = "Hoàn thành điều tra hành động·khó khăn Bài sao 5-11 để mở khóa"
  },
  CollectionHall_143474_Title = {
    Text = "Và tôi vẫn đang hát"
  },
  CollectionHall_143475_Desc = {
    Text = "Người thân yêu ơi, hãy để chúng ta mượn hơi men, cùng nhau khiêu vũ thêm một điệu nữa nào."
  },
  CollectionHall_143475_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143475_Title = {
    Text = "Dạ hội mê say nhẹ"
  },
  CollectionHall_143476_Desc = {
    Text = "Khán giả rơi lệ vì chia ly, cũng rơi lệ vì Gặp lại.\nCòn những tội nhân ở trung tâm sân khấu, cũng nên dành cho nhau những tràng pháo tay."
  },
  CollectionHall_143476_LockTip = {
    Text = "Hoàn thành điều tra hành động·khó khăn Bài sao 5-11 để mở khóa"
  },
  CollectionHall_143476_Title = {
    Text = "Tù nhân đang cúi chào"
  },
  CollectionHall_143477_Desc = {
    Text = "Người đời thích quy kết một cuộc chiến tranh vào Một tiếng súng.\nNhưng số phận sẽ chế nhạo, đó là sự tự lừa dối của toàn nhân loại."
  },
  CollectionHall_143477_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143477_Title = {
    Text = "Khi bướm Vỗ cánh"
  },
  CollectionHall_143478_Desc = {
    Text = "Một vở diễn không có hậu truyện là chưa hoàn chỉnh.\nThay đổi đôi chút lời thoại, điều chỉnh phông cảnh, luân phiên diễn viên — mỗi lần trở lại, đều là một màn hoàn toàn mới."
  },
  CollectionHall_143478_LockTip = {
    Text = "Hoàn thành điều tra hành động·khó khăn Bài sao 5-11 để mở khóa"
  },
  CollectionHall_143478_Title = {
    Text = "Biến tấu trở lại"
  },
  CollectionHall_143479_Desc = {
    Text = "Ngòi bút phi trên trang giấy trắng, đuổi theo từng con chữ, mà những con chữ ấy dẫn đến kết cục đã được định sẵn từ trước.\nTất cả, đều xảy ra trước khi bạn lật mở từng trang sách."
  },
  CollectionHall_143479_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143479_Title = {
    Text = "Điều sẽ định, điều đã định"
  },
  CollectionHall_143480_Desc = {
    Text = "Một chút bitters đắng, 20ml vermouth ngọt, một ít rượu sherry, thêm đầy đá rồi khuấy đều — đây là một ly khai vị thượng hạng, cũng là một vở kịch đã diễn năm trăm lần."
  },
  CollectionHall_143480_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143480_Title = {Text = "Adonis"},
  CollectionHall_143481_Desc = {
    Text = "Bạn coi số phận như một tên hề, thì sẽ không bị số phận nô dịch.\nHãy đón chào Ngài bằng tiếng cười không ngừng nghỉ, hãy cùng nhau gọi tên Ngài —\nHạnh phúc."
  },
  CollectionHall_143481_LockTip = {
    Text = "Hoàn thành điều tra hành động·khó khăn Bài sao 5-11 để mở khóa"
  },
  CollectionHall_143481_Title = {
    Text = "Kẻ hề giá lâm"
  },
  CollectionHall_143482_Desc = {
    Text = "\"Tôi ghét bạn, ghét bạn tự làm kén nhốt mình, ghét bạn bất lực, ghét bạn từ bỏ chính mình.\"\n\"......Nhưng mối hận này cũng đang thiêu đốt chính tôi, vì, tôi cũng yêu bạn.\""
  },
  CollectionHall_143482_LockTip = {
    Text = "Hoàn thành điều tra hành động·khó khăn Bài sao 5-11 để mở khóa"
  },
  CollectionHall_143482_Title = {
    Text = "Bi ca của hồn ma báo thù"
  },
  CollectionHall_143483_Desc = {
    Text = "Thế giới ban cho bạn vô số ngã rẽ để lựa chọn, nhưng tất cả đều hội tụ tại một điểm — mang tên hủy diệt, mang tên tận cùng."
  },
  CollectionHall_143483_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143483_Title = {
    Text = "Bản sao của thế giới"
  },
  CollectionHall_143484_Desc = {
    Text = "Màn lên màn xuống, vở diễn thay đổi, cô ấy vẫn ở trong nhà hát — cô ấy là tác giả, khán giả, cũng là diễn viên.\nHỡi người chủ nhân của số phận, bạn thật tàn nhẫn, mãi mãi im lặng, vậy mà sao lại rơi lệ?"
  },
  CollectionHall_143484_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143484_Title = {
    Text = "Vở kịch dệt nên bởi số phận"
  },
  CollectionHall_143485_Desc = {
    Text = "Nếu như hủy diệt rốt cuộc không thể tránh khỏi, liệu xé toạc tấm lưới số phận có thể mang đến sự cứu chuộc thực sự?\nKhông ai có thể trả lời, không vị thần nào có thể trả lời.\nNhưng ít nhất, những khổ đau vô tận cũng sẽ cùng nhau tiêu tan."
  },
  CollectionHall_143485_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143485_Title = {
    Text = "Màn trình diễn phạm thượng"
  },
  CollectionHall_143486_Desc = {
    Text = "Những gương mặt bước đi giữa thế gian, vô cùng thật, tưởng chừng tự do, chẳng qua là những vật cố định trên sân khấu.\nMọi cử chỉ hành động, đều bị sợi chỉ của số phận dẫn dắt."
  },
  CollectionHall_143486_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143486_Title = {
    Text = "Sợi chỉ của chúng sinh"
  },
  CollectionHall_143487_Desc = {
    Text = "Sau khi tỉnh giấc, tất cả sẽ biến mất, bị quên lãng hoàn toàn — điền trang, vườn hoa, bài ca, tranh vẽ......\nĐó là một mùa xuân không tồn tại."
  },
  CollectionHall_143487_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143487_Title = {
    Text = "Ảo mộng dệt mùa xuân"
  },
  CollectionHall_143488_Desc = {
    Text = "Tiếng dây đàn Tuần khởi, Maid cất tiếng ngân.\nNgười đứng sau màn bước ra sân khấu, cô ấy cúi chào bạn, mời bạn chứng kiến quỹ đạo số phận đã định."
  },
  CollectionHall_143488_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143488_Title = {
    Text = "Vén véu của cô ấy"
  },
  CollectionHall_143489_Desc = {
    Text = "Đây là điệu múa ứng tấu chỉ có thể biểu diễn một lần trong đời.\nNhưng không sao, nó sẽ may mắn được trở thành bản mẫu, đóng khung mãi mãi."
  },
  CollectionHall_143489_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143489_Title = {
    Text = "Vũ kịch: \"Cái chết của Thiên Nga\""
  },
  CollectionHall_143490_Desc = {
    Text = "Màn nhung kéo lên, những nhân vật kỳ quặc lần lượt xuất hiện.\nHọ cất tiếng hát, các cô ấy múa, trước khi số phận ập đến, kiên trì đưa vở diễn lên sân khấu, dù kết cục đã được viết sẵn từ lâu."
  },
  CollectionHall_143490_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143490_Title = {
    Text = "Song ca khi màn mở"
  },
  CollectionHall_143491_Desc = {
    Text = "Để mọi thứ đi đúng quỹ đạo, luôn có những thứ phải bị loại bỏ, bị ruồng bỏ.\nNhững tồn tại không được chọn, tất cả rơi xuống vực thẳm tối tăm, tiếng than khóc và Chửi rủa của chúng, cuối cùng chẳng ai nghe thấy."
  },
  CollectionHall_143491_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143491_Title = {
    Text = "\"Tôi\" bị bỏ rơi"
  },
  CollectionHall_143492_Desc = {
    Text = "Chết đi như thế này, thật đẹp. Cô ấy nghĩ."
  },
  CollectionHall_143492_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao 5-16 để mở khóa"
  },
  CollectionHall_143492_Title = {
    Text = "Sự bù đắp tuyệt mỹ"
  },
  CollectionHall_143592_LockTip = {
    Text = "Hoàn thành bất kỳ màn chơi nào trong duy thức tiềm hành \"Epojans Vĩnh Cửu\" để mở khóa"
  },
  CollectionHall_143592_Title = {Text = "Nghiện"},
  CollectionHall_144377_Desc = {
    Text = "Trong suốt những tháng ngày canh gác dài đằng đẵng, Tà Vy cũng từng đặt chân lên một vùng đất.\nCô ấy tỉ mỉ quan sát Hành động của từng sinh vật, lặng lẽ đi lại ở rìa thế giới loài người.\n\nMột ngày bình thường, khi màn đêm buông xuống, ánh đèn dày đặc ở ngoại ô thành phố thu hút Ánh Mắt của cô ấy.\nPhông cảnh, ca múa, những gánh hàng rong bán bánh kẹo, lũ trẻ nô đùa cười giỡn, những kẻ nhàn rỗi nâng chén uống thỏa thuê. Đó là hơi thở của Sinh lực, là khoảnh khắc nghỉ ngơi thoáng qua.\nCảnh tượng quá đỗi hấp dẫn, cô ấy không nhịn được mà hiện ra hình dạng.\n\n\"Xin chào, cho tôi một chiếc kẹo đường vẽ.\"\n\"Được thôi, quý khách chờ một chút. Muốn vẽ gì nào?\"\nTà Vy khẽ nghiêng đầu. Cô ấy chỉ nhớ cần đưa ra những đồng tiền vô chủ mà mình tình cờ nhặt được, nhưng lại hoàn toàn quên mất rằng mình có thể bày tỏ mong muốn.\n\"Nếu quý khách chưa nghĩ ra, để tôi vẽ theo hình dáng của quý khách thì sao? Trông quý khách đẹp như tiên nữ vậy.\"\nTà Vy mỉm cười gật đầu, người bán hàng hô to một tiếng, giơ muỗng đường lên, bắt đầu vẽ.\n\nTích tắc. Tích tắc.\nThứ rơi xuống bảng đá, lại không phải là mật đường màu vàng óng.\nMà là mưa, mưa đen.\nChất lỏng đen nhớt nhỏ xuống từ bầu trời cao đến mức mắt thường không thể nhìn thấy, làm tan chảy bầu trời thành một vết nứt kinh hoàng.\n\n\nRồi, Tà Vy bắt đầu Rơi Lên Trên.\nĐó là thế giới đang chìm xuống. Nụ cười của người bán hàng đóng băng thành một khung hình tĩnh trong ký ức của Tà Vy, rồi cùng vạn vật chìm vào biển đen mênh mông, hóa thành một hạt bụi vô nghĩa trong vô số ngôi sao đã tắt, hóa thành quá khứ xa vời không thể chạm tới đối với cô ấy.\nĐây là cơn chấn động do cô ấy gây ra, cũng là Kỷ luật mà cô ấy phải gánh chịu.\nCô ấy nhìn từ xa, lặng im không nói. Cô ấy Chỉ là Rơi Lên Trên.\nĐây mới là vị trí cô ấy phải giữ, cánh cửa bạc \"Vượt qua thời không\" đó.\nCô ấy sẽ đứng đây mà nhìn xuống mãi mãi."
  },
  CollectionHall_144377_Title = {
    Text = "Rơi Lên Trên"
  },
  CollectionHall_144448_Desc = {
