  CollectionHall_144454_Desc = {
    Text = "Những kẻ ngu ngốc, nông cạn, tự cao tự đại, bề ngoài mạnh mẽ bên trong rỗng tuếch đã xây dựng vương quốc của riêng mình.\nNhững Vỏ rỗng không bao giờ thay đổi sẽ không thốt ra lời thật, bởi vì không có gì có thể ghép lại từ trong vực thẳm trái tim quá sợ hãi sự thay đổi đến mức đã vỡ vụn quá sớm."
