  CollectionHall_145434_Title = {
    Text = "Trò Chơi Của Leviathan: Cuộc Tranh Đoạt Tàn Sát"
  },
  CollectionHall_145460_Desc = {
    Text = "Từ ngày ra đời, Ngài đã chìm vào cơn đói vĩnh cửu.\nXương tàn của các ngôi sao vỡ vụn giữa kẽ răng Ngài, tàn tích của các nền văn minh thối rữa trong bụng Ngài. Cơn đói của Ngài là một lời nguyền cổ xưa hơn cả thời gian. Ngài lần lượt nuốt chửng sức mạnh, sai khiến nô lệ diễn trò chơi quyền lực và dục vọng, thế nhưng Ngài chưa bao giờ hiểu rõ ý nghĩa tồn tại của mình là gì.\nCho đến khi người chiến binh mang tên Rotan xuất hiện trước mặt Ngài.\n「Leviathan.」\nNgài không còn nhớ lần cuối cùng nghe thấy tên mình là khi nào. Những vị vua quỳ phục không dám thốt ra nó, những tế sư điên loạn chỉ có thể thay thế bằng những bài thánh ca.\nVậy mà nàng dễ dàng gọi tên Ngài, như thể gọi tên một đối thủ đã chờ đợi từ lâu.\n「Đã đến lúc ngươi ra tay rồi!」\nNgài đã tồn tại mười hai nghìn năm, trong suốt khoảng vĩnh hằng dài đằng đẵng ấy, các hành tinh chỉ là thức ăn, chúng sinh chỉ là kiến cỏ, vô số kẻ mạnh chẳng qua chỉ là trò tiêu khiển nhất thời. Không có gì khiến Ngài cảm thấy no đủ, cũng không có gì khiến Ngài cảm thấy sợ hãi, cho đến ngày hôm nay.\nNgười phàm này, chiến binh này, giơ cao thanh kiếm khổng lồ, lao về phía Ngài như một cơn bão.\nKiếm khổng lồ xé toạc vảy giáp. Bên tai Ngài, vang lên tiếng gầm rú của chính mình khi sinh ra giữa hỗn mang. Lửa giận của Ngài phá hủy các thiên thể, cơn đói của Ngài nuốt chửng tinh vân.\nKiếm khổng lồ chặt đứt vuốt sắc. Ngài hồi tưởng lại, vị「thần minh」mặc bạch sa kia đã đến trước mặt Ngài, tách rời sức mạnh và ý chí của Ngài.\nKhoảnh khắc kiếm khổng lồ đâm xuyên trái tim, Leviathan bật cười.\nMười hai nghìn năm, ý chí đã mất kia, cuối cùng đã trở lại trước mặt Ngài, chặt Ngài ra từng mảnh, chinh phục Ngài, nuốt chửng Ngài. Nàng sẽ dẫn dắt Ngài, bước qua từng vùng lãnh thổ, tiến về biển sao xa hơn, chinh phục từng sự tồn tại hùng mạnh.\nVào ngày đó, con thú hỗn mang cổ xưa được tái sinh. Khoảnh khắc trở về bên nàng, Ngài hoàn toàn hiểu rõ, Ngài và nàng, được sinh ra từ sức mạnh thuần túy, triệt để.\nSức mạnh bản thân, chính là toàn bộ ý nghĩa."
  },
  CollectionHall_145460_Title = {
    Text = "Hoàng Hôn Của Ngư Thần"
  },
  CollectionHall_146400_Desc = {
    Text = "<Title:Giới thiệu>\nCác vị Thần Minh cổ xưa không thể dập tắt ngọn lửa thịnh nộ vĩnh cửu của Cá Voi Tinh Thiên, chỉ có thể tách linh hồn và thể xác của Ngài ra. Ý chí của Ngài rơi xuống vùng hoang thổ, hóa thành chiến binh mang tên Lotan: Ngư Thần.\nCô ấy thiên tính hiếu chiến, xem việc theo đuổi Sức mạnh tột đỉnh là bản năng và vinh quang duy nhất. Vì điều đó, cô ấy bước vào cuộc tuyển chọn của Cá Voi Tinh Thiên, ký kết Khế Ước với Ngài, rồi khi Sức mạnh đạt đến đỉnh điểm, dùng đại kiếm chém giết Chủ trị của mình, thu nạp quyền năng của con thú nuốt sao vào bản thân.\nXương voi nhọn sắc xuyên thủng Huyết Nhục, giáp xương u tối phủ lên thân xác, đôi mắt chứa đựng bầu trời sao chỉ còn lại ánh nhìn lạnh lùng dành cho kẻ thù.\nCô ấy không tìm thấy niềm vui trong hủy diệt, cũng không thèm đoái hoài đến những cuộc tàn sát vô nghĩa. Điều cô ấy khao khát, chỉ là những kẻ thù Hưng phấn hơn, chỉ là Sức mạnh mạnh mẽ hơn.\nVị chiến binh thuần túy nhất ấy, truy đuổi bóng dáng của những kẻ mạnh, đặt chân đến từng góc khuất của biển sao, cho đến khi tất cả những kẻ mạnh đều ngã xuống dưới lưỡi kiếm, cho đến khi tất cả mọi con đường đều đi đến tận cùng."
  },
