  },
  CollectionHall_147986_Title = {
    Text = "Khúc Ca Kình Ngư Hấp Hối"
  },
  CollectionHall_147987_Desc = {
    Text = "Trên một vùng hoang vu, những con thú trợn mắt nhìn nhau lảng vảng, chúng đều đang tìm kiếm thời cơ — một thời cơ để cắm nanh nhọn xuyên qua cổ họng, xé tan đối phương hoàn toàn."
  },
  CollectionHall_147987_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Cho Đến Khi Kình Thiên Vẫn Lạc\""
  },
  CollectionHall_147987_Title = {
    Text = "Nanh Vuốt Đối Mặt"
  },
  CollectionHall_147988_Desc = {
    Text = "Hãy cất cái vương miện nhàm chán của ngươi đi, ta chưa bao giờ thèm để mắt đến nó. Hãy rút kiếm ra, thế giới đang điên cuồng vì máu!\nNhư vậy, chỉ vì như vậy —\nHãy giết chóc! Hãy gặm nhấm! Hãy diệt vong!"
  },
  CollectionHall_147988_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Cho Đến Khi Kình Thiên Vẫn Lạc\""
  },
  CollectionHall_147988_Title = {
    Text = "Vũ Điệu Cuồng Loạn Giết Trời"
  },
  CollectionHall_147989_Desc = {
    Text = "Thuở ấy ta vẫn còn là đứa hầu thấp hèn nhất, đã tận mắt chứng kiến một cuộc chinh phạt xứng danh tàn khốc.\nVị chủ nhân huyền thoại ấy, sức mạnh đúc nên xương máu của bà, máu nóng sôi thành ngọn lửa bất diệt, ánh lửa lại thắp sáng đôi mắt bà —\nHãy thay ta tiếp tục khắc ghi ký ức này, đứa con của ta. …Cuối cùng bà đã chiến thắng, và chinh phục bầu trời đầy sao."
  },
  CollectionHall_147989_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Cho Đến Khi Kình Thiên Vẫn Lạc\""
  },
  CollectionHall_147989_Title = {
    Text = "Chinh Phạt Chẳng Bao Giờ Ngừng"
  },
  CollectionHall_147990_Desc = {
    Text = "Bánh mì và xiếc, thế nhân chỉ hân hoan vì hai thứ đó mà thôi.\nNgài thưởng thức, Ngài chẳng quan tâm.\nCô trải nghiệm, cô chẳng quan tâm."
  },
  CollectionHall_147990_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Cho Đến Khi Kình Thiên Vẫn Lạc\""
  },
  CollectionHall_147990_Title = {
    Text = "Bất Tử Được nuôi dưỡng Bởi Tham Vọng Quyền Lực"
  },
  CollectionHall_147991_Desc = {
    Text = "Kẻ chết ngã xuống sau người sắp chết, kẻ mạnh quỳ phục trước người mạnh hơn.\nTrên lưỡi dao lạnh lẽo sắc bén, chỉ hiện lên bóng dáng của kẻ đang đứng vững."
