  CollectionHall_148015_Title = {
    Text = "Nguyên Tắc"
  },
  CollectionHall_148138_Desc = {
    Text = "Trong phòng thí nghiệm rộng lớn, các loại thiết bị tinh vi đều được sắp xếp ngăn nắp, chỉ có vô số ống dẫn đan xen nhau, tựa như những con rắn uốn lượn quấn quýt, nằm phục dưới sàn, treo lơ lửng trên không.\nTín hiệu tư duy như một dòng sông mà không ai có thể nhìn thấy, nhưng thiên tài đã quen với việc giao tiếp cùng nó từ lâu. Não bộ là nguồn cội của chúng, rồi chảy qua những ống dẫn cơ học, cuối cùng hội tụ trong cái vỏ xác mới tạo ra này.\nKhi ý thức được truyền đi, nhiều ký ức bị phong kín lâu ngày cũng được lật ra sau bao năm xa cách — gia đình, Misaque, thí nghiệm còn dang dở… Trong khoảnh khắc mơ hồ, thiên tài nhớ lại nhiều năm trước, khi bà chưa thoát khỏi sự trói buộc của thân xác ban đầu, có một học sinh nhàm chán, thích thú xoay quanh bà, ánh mắt lấp lánh ánh sáng mang tên tò mò.\n\"Theo bà, một cơ thể nhân tạo có thể chứa đựng linh hồn thực sự không?\"\nPhàm nhân luôn thích tưởng tượng những thứ vượt xa tầm nhìn của họ, đây là một câu hỏi tầm thường. Nhưng với tư cách là giáo viên, bà vẫn đưa ra vài câu trả lời, dù không thèm ngước mắt lên.\n\"Cơ thể của ngươi cũng chẳng khác gì vật nhân tạo, tim, tứ chi, ngũ quan — sự vận hành của những cơ quan này khác gì máy móc?\"\n\"Thôi được rồi, thay vì mơ mộng viển vông những thứ đó, chi bằng dành thời gian rèn luyện cái bộ não han gỉ của ngươi đi, nếu không, cái thân xác chảy máu của ngươi sẽ càng thêm vô dụng.\"\nGiờ đây, người đặt câu hỏi năm xưa đã bị cát bụi của thời gian vùi lấp, không còn tồn tại nữa. Chỉ có chiếc bình chứa trí tuệ vẫn đang suy nghĩ, và sẽ mãi mãi suy nghĩ.\nCái gọi là linh hồn mà thế nhân hay nhắc đến chẳng qua là hoạt động điện hóa học được tạo thành từ 86 tỷ tế bào thần kinh đan xen nhau, dù là thịt xương hay máy móc, sự khác biệt về nguyên liệu không thay đổi bản chất rằng chúng chỉ là vật mang.\nĐúng vậy, phàm nhân bất lực, nhưng bà — một thiên tài — có thể làm được, và đã làm được — chỉ có như vậy mới có thể giải mã chân lý của thế giới, chạm đến đỉnh cao của tri thức.\nThị giác, chẳng qua là ánh sáng xuyên qua nhãn cầu, cuối cùng hội tụ thành hình ảnh trên võng mạc.\nKhứu giác, chẳng qua là phân tử mùi kết hợp với thụ thể, vạch qua con đường cảm nhận hóa học của dây thần kinh.\nThính giác, chẳng qua là sóng âm được ốc tai chuyển đổi, biến thành tín hiệu điện truyền lên vỏ não.\nNơi con búp bê đang ở quá tối tăm, ánh đèn yếu ớt lay động, đến bóng tối cũng không thể được chiếu ra. Bà khép nhẹ đôi mắt, vì biết rõ dù có mở chúng ra, thứ hiện vào tầm mắt cũng chỉ là khung cảnh không thay đổi.\nCăn phòng được dọn dẹp sạch bóng, dung dịch trong các lọ cũng được đậy kín. Cơ thể không cần hô hấp, càng không cần thiết phải hít vào thứ không khí vô vị này để kiểm tra giác quan.\nChỉ có một tiếng bíp cơ học lạnh lẽo, vang vọng trong phòng thí nghiệm rộng lớn:\n\"Đồng bộ ý thức hoàn tất, xác nhận khởi động cơ thể.\"\nĐủ rồi.\nDù là giọng vô cơ, nhưng nghe lại thấy thân quen, như thể neo chặt vào thực tại của thế giới vật chất, lại như thể chỉ đơn giản nhắc nhở bà rằng, kỳ nghỉ ngắn ngủi đã kết thúc, đã đến lúc dấn thân vào vòng nghiên cứu mới."
  },
  CollectionHall_148138_Title = {
    Text = "Đồng Bộ Linh Hồn"
  },
  CollectionHall_148140_Desc = {
    Text = "<Title:Giới thiệu>\nĐêm tuyết rét cắt xương, cô bé chân trần đã dâng linh hồn cho con sâu.\nNếu bán đi thứ rẻ mạt ấy có thể đổi lấy hạnh phúc mà bao người khao khát mà không được, thì cô chẳng có gì phải do dự hay tiếc nuối.\nTừ đó cô như một bóng trắng, lang thang trên cõi người hoang vắng, dùng lời dối trá dệt nên thánh điện, dùng kẹo ngọt giả tạo ân sủng, đổi lấy những lễ vật qua ngày.\nCô và con sâu, như đôi bạn đồng hành ăn ý nhất.\nCho đến khi từ đỉnh núi vang lên thông điệp mới, báo cho thế gian biết về thánh địa có thể thực hiện mọi ước nguyện.\nCây diêm ấy đã được quẹt sáng.\nCô sẽ dùng nó để làm tan chảy cả ngọn núi tuyết."
  },
  CollectionHall_148140_LockTip = {
    Text = "Hoàn thành điều tra hành động Bài sao chương 6 \"Đại Tiệc Trên Núi Tuyết\" để mở khóa"
