  CollectionHall_149045_Desc = {
    Text = "\"Hãy đội vòng hoa lên, đây là lễ trao huân chương của ngươi rồi, chàng hiệp sĩ nhỏ thân mến của ta.\"\nKhi hoa cúc trắng nở rộ khắp đồng nội, những người lính lười biếng thường mượn danh nghĩa hộ vệ để kéo chàng thiếu niên lang thang nơi đây.\nMón trang sức kết từ loài hoa phổ biến nhất ở Công quốc Aquitaine, được nhẹ nhàng đặt lên mái tóc vàng.\n\"Thưa ngài, có lẽ… chúng ta nên luyện tập rồi chứ?\"\nChàng thiếu niên nói vậy, nhưng vẫn ngoan ngoãn đội thẳng chiếc vòng hoa trắng tinh.\nLoài thực vật nhỏ bé này, luôn tắm mình trong ánh sáng, ở vương quốc của chàng thiếu niên, cũng là biểu tượng của hy vọng.\nKhi mở mắt ra lần nữa, những hình ảnh tươi sáng ấy đã không còn tồn tại.\nChiến mã đang hí vang, kẻ thù khinh thường ùa vào, giữa muôn vàn binh mã, chàng chỉ có một mình.\nRồi, tiếng ồn ào chói tai đột ngột im bặt——\nLàn sóng đen tràn vào linh hồn chàng.\nTiếp theo vang lên là tiếng xé toạc của giáo dài xuyên qua da thịt, tiếng máu chảy ào ạt, tiếng rên la của kẻ thù.\nSự khinh miệt trên những khuôn mặt ấy tan biến không còn, thay vào đó là nỗi sợ hãi và sự rút lui bao trùm tứ phía.\nCòn chàng thiếu niên chỉ máy móc giơ tay lên, đâm xuyên, rút ra, rồi lại giơ lên.\nCho đến khi người lính cuối cùng ngã xuống.\nKhói bụi che khuất vô số khuôn mặt, tàn tích của kẻ chinh phạt và người bị chinh phạt chồng chất trên mặt đất, không còn phân biệt được nữa.\nBóng tối quấn lấy lưng chàng, cười nhạo: \"Tiếp tục đi. Hạ giáo xuống, thêm một lần nữa.\"\n\"Giữa kẻ bảo vệ và kẻ hủy diệt, vốn chỉ cách nhau một ranh giới mong manh. Giờ đây, ngươi đã đưa ra lựa chọn của mình.\"\nBóng tối che phủ bầu trời, máu thấm đẫm đất đai.\nChàng nhìn về phía đồng nội xa xa — chỉ một đêm ngắn ngủi, nơi ấy đã mãi mãi mất đi màu sắc của ngày xưa.\nGió thổi tung vạt áo của chàng thiếu niên, cũng lướt qua mảnh đất cỏ may mắn còn sót lại.\nTrong đêm tối im lặng, ở góc khuất mà ngay cả ác quỷ cũng không hay biết, một vệt trắng tinh khôi khó nhận ra vẫn còn đọng lại trong đáy mắt chàng.\nĐó là bông hoa cúc trắng cuối cùng của vương quốc này, lặng lẽ sinh trưởng ở nơi không ai để ý.\nDù đã nhuốm màu đỏ thắm, thân hoa cong gãy, nhưng vẫn chưa ngã xuống."
  },
  CollectionHall_149045_Title = {
    Text = "Và Hoa Cúc Vẫn Nở Hoa"
  },
  CollectionHall_149759_Desc = {
    Text = "<Title:Giới thiệu>\nOrci rốt cuộc cũng thừa nhận rằng, với tuổi tác và sức mạnh của mình, chàng vẫn chưa đủ tư cách trở thành một kỵ sĩ hộ quốc.\nTrong thế giới này, chàng đã không nhận được lời ủng hộ then chốt ấy.\nVì vậy, dưới sự khuyên nhủ của công chúa, chàng trở về lãnh địa của cha, sống như một thiếu gia quý tộc bình thường.\n\nKhi lửa chiến tranh ập đến, Orci — người không thể từ bỏ danh phận kỵ sĩ — vội vã quay về hoàng cung, nhưng đã quá muộn.\nCông chúa đã tự hủy hoại bản thân theo cách tàn khốc nhất; những đồng liêu quen thuộc không ai sống sót — họ vẫn kiên thủ trận địa đến phút cuối cùng.\nKhi quân địch xông vào cung điện đã hoang tàn, định vơ vét sạch sẽ nơi này, chàng không thể kìm nén cơn thịnh nộ và nỗi bi thương, chọn cách phó thác thân xác cho thứ sức mạnh bóng tối đầy cám dỗ kia.\nKẻ thù chưa kịp chỉnh đốn đội hình, đã bị chàng tiêu diệt toàn bộ, nhưng sau khi trả thù xong, người thiếu niên chẳng cảm thấy chút giải thoát nào.\n\nBóng tối đen kịt chiếm lĩnh thân xác chàng, nhuộm đen linh hồn chàng, trong những ngày tháng mê muội ấy, chàng đã phạm phải vô số lỗi lầm.\n\n— Giết chóc, phá hoại, làm mọi điều trái với lời thề......cho đến khi một tia nắng đánh thức chàng khỏi vùng hư vô vô tận.\n\nCó lẽ, bắt đầu hối hận từ bây giờ vẫn chưa muộn.\nChàng vẫn còn cơ hội cầm lại giáo và khiên, chiến đấu để bảo vệ đức hạnh."
  },
