  CollectionHall_48611_Desc = {
    Text = "<Title:Chiều Vật Chất>\nChiều tồn tại của vật chất, thế giới thực mà con người sinh hoạt hàng ngày. \nTrong chiều vật chất, không gian được thể hiện bằng ba chiều, thời gian tuyến tính, vật chất có thể cảm nhận, cảm xúc và tinh thần trừu tượng không thể nhìn thấy. \nMọi thứ đều tự nhiên như vậy, dường như những điều không thể hiểu được chưa bao giờ tồn tại. \n\n<Title:Chiều Tinh Thần>\nChiều của tinh thần, còn được gọi là 「chiều ảo mộng」. \nTrong chiều tinh thần, cảm xúc, ký ức, chấp niệm, v.v., đều có thể hình thành các cá thể khác nhau. \nNgoài tinh thần của cá thể trong chiều vật chất, nơi đây còn cư trú các loài sinh vật của chiều tinh thần. Loại sinh vật này khó có thể quan sát bằng mắt thường, chỉ có thể cảm nhận thông qua các thiết bị đặc biệt hoặc thám thính trong các thâm cảnh."
  },
  CollectionHall_48611_Title = {
    Text = "Chiều không gian"
  },
  CollectionHall_48612_Desc = {
    Text = "<Title:Định nghĩa và đặc tính>\nHiện tượng ăn mòn đặc biệt của một chất.\nNgoại trừ một số cá nhân, hầu hết con người không thể quan sát hiện tượng này bằng mắt thường.\nKhi hiện tượng tiến triển, sự tồn tại của người bị ăn mòn sẽ bị xóa bỏ. Dấu vết sống, ghi chép viết, thậm chí cả ký ức liên quan đều biến mất.\nHọ sẽ bị cả thế giới lãng quên.\n\n<Title:Sự lây lan của hiện tượng ăn mòn>\nKhông có thông tin về đường lây truyền.\nHiện tượng ăn mòn xuất hiện và biến mất một cách ngẫu nhiên, không thể dự đoán hay tìm thấy dấu vết. Hiện nay, chỉ có thể đạt được hiệu quả lây lan thông qua các phương pháp cụ thể như nghi lễ đặc biệt, di vật, v.v.\n\n<Title:Các can thiệp vào hiện tượng ăn mòn>\nChỉ có thể can thiệp và chữa trị thông qua bạc tâm và sản phẩm lõi bạc.\nHầu hết các đối tượng dễ bị ăn mòn xâm nhập, có thể can thiệp bằng sản phẩm lõi bạc trước khi bị ăn mòn hoàn toàn.\nMột số ít cá nhân có khả năng kháng lại hiện tượng ăn mòn, nhưng tinh thần của họ sẽ bị tổn thương không thể phục hồi, không thể sửa chữa bằng sản phẩm lõi bạc, hiện chưa tìm thấy phương pháp can thiệp hiệu quả."
  },
  CollectionHall_48612_Title = {
    Text = "rỗng rỗng"
  },
  CollectionHall_48614_Title = {Text = "cửa"},
  CollectionHall_48616_Desc = {
    Text = "<Title:Ngày thành lập>\nA.F.187, tiền thân là Học viện Misage được thành lập vào năm A.F.90\n\n<Title:Người sáng lập>\nWard Phillips, Keralaksh, Tavi\n\n<Title:Tổng quan>\nMột trường đại học đặc biệt lấy việc chống lại Dung Thực làm sứ mệnh.\nLà bên thứ ba hoàn toàn độc lập với chính phủ các quốc gia, không tham gia bất kỳ cuộc đấu tranh chính trị nào, không thuộc về bất kỳ phe phái nào.\nToàn bộ giảng viên, sinh viên cùng nhân viên chỉ hơn một nghìn người. Ngoài các khóa học thông thường về kinh tế, nhân văn, khoa học, còn mở các khóa học đặc biệt dành cho Điều tra viên, Thủ Mật Nhân và Hoán Tỉnh Thể.\nKhu học chính tọa lạc tại Vương quốc Leo. Khi hiện tượng Dung Thực xuất hiện ở khắp nơi trên thế giới, trường sẽ cử đội điều tra cùng Điều tra viên, Thủ Mật Nhân đến giải quyết.\nLà một tổ chức đặc biệt coi trọng cả lý thuyết lẫn thực hành, hậu quả của việc trượt môn cũng rất nghiêm trọng."
  },
  CollectionHall_48616_LockTip = {
    Text = "Hoàn thành phần mở đầu để mở khóa"
  },
