  },
  CollectionHall_48618_Title = {
    Text = "Lời mở đầu"
  },
  CollectionHall_48619_Desc = {
    Text = "<Title:Ngày thành lập>\nA.F.186\n\n<Title:Người sáng lập>\nCác quốc gia ký kết Hiệp định Misidia\n\n<Title:Tổng quan>\nTổ chức toàn cầu do con người bình thường tạo nên.\nĐược thành lập với sự đóng góp tài chính chung từ các chính phủ quốc gia, tồn tại độc lập với chính phủ, là cơ quan quản lý chính thức và đơn vị phản ứng đầu tiên đối với hiện tượng rỗng rỗng.\nHầu hết thành viên đều là những người bình thường không có nền tảng huyền học hay năng lực siêu nhiên, với mục tiêu và nhiệm vụ duy nhất là chống lại hiện tượng rỗng rỗng.\nCó nhiều văn phòng ở các quốc gia trên thế giới, mỗi văn phòng phụ trách một khu vực khác nhau.\nNghiêm túc và cứng nhắc là ấn tượng đầu tiên của mọi người về tổ chức này, bộ đồng phục màu trắng đã giặt quá mức thẳng tắp như cột sống của họ."
  },
