  CollectionHall_48635_Desc = {
    Text = "<Title:Giới thiệu>\n Misaque - viện trưởng lâm thời.\n Sư phụ của cô là Crowley MacKinnon, là đàn em trực tiếp của Herbert.\n Là một trong những nhân chứng của sự kiện Herbert giết sư phụ, sau khi sư phụ qua đời vẫn luôn thay mặt xử lý các công việc liên quan đến học viện.\n Người theo chủ nghĩa hiệu quả tuyệt đối, không bao giờ trễ hẹn, cắt tóc ngắn vì có thể tiết kiệm thời gian chải đầu.\n Vì chiến loạn đã vượt biên từ quê hương Elke đến Leo.\n Ngón trỏ tay phải không thể uốn cong bình thường, được cho là bằng chứng bị đối xử tàn nhẫn trong trại tập trung."
  },
  CollectionHall_48635_LockTip = {
    Text = "Hoàn thành phần mở đầu để mở khóa"
  },
  CollectionHall_48635_Title = {Text = "Czort"},
  CollectionHall_48636_Desc = {
    Text = "<Title:Giới thiệu>\nMột trong ba người sáng lập, cùng với Walter Phillips và Ké Lác Khắc Xích, đã thành lập tiền thân của Đại học Misag —— Trường học Misag. \nLà \"thân thể được đánh thức\"đầu tiên, cũng là tồn tại cung cấp công nghệ thức tỉnh. \nLuôn trấn giữ hồ đen, số người từng thấy mặt cô đếm trên đầu ngón tay, là một trong những bí mật cao nhất của Đại học Misag. \n \"Xì... đừng dò xét @2 của bạn.\""
  },
