  },
  CollectionHall_49000_Desc = {
    Text = "Dâng hiến tình yêu và cái chết cho thế giới."
  },
  CollectionHall_49000_Title = {Text = "Ủng hộ"},
  CollectionHall_49001_Desc = {
    Text = "Tích lũy lâu nay, tại đây tuyên bố——"
  },
  CollectionHall_49001_Title = {
