  },
  CollectionHall_49003_Desc = {
    Text = "Trò chuyện với \"Ngài\"."
  },
  CollectionHall_49003_Title = {
    Text = "Thì thầm"
  },
  CollectionHall_49004_Desc = {
    Text = "Lời chúc phúc dành cho mầm non và bào thai."
  },
  CollectionHall_49004_Title = {Text = "Hy vọng"},
  CollectionHall_49015_Desc = {
    Text = "Sau khi thảm họa biến mất không dấu vết và khủng hoảng được tuyên bố tạm thời giải trừ, đội đặc nhiệm Misaque mang theo \"thu hoạch bất ngờ\" rời khỏi Akutê. \n Miss Dexter nhìn lại lần cuối vào hố nổ khổng lồ ở trung tâm, mầm non của một loại cây không rõ tên đã lặng lẽ phá đất mà không biết từ khi nào. \n Cô thở phào nhẹ nhõm, tâm trạng vui vẻ. \n Khu rừng Akutê sẽ đón chào mùa xuân của nó. \n Liễu sẽ đâm chồi khi mùa xuân tới, lan sẽ lặng lẽ nở hoa sau mùa mưa tiếp theo, tất cả sức sống đều sẽ đón nhận sự tái sinh. \n Và hành trình đối mặt với điều chưa biết của họ cũng sẽ bước lên một khởi đầu mới. \n"
  },
  CollectionHall_49015_Title = {
    Text = "Mùa xuân ở Acushnet"
  },
  CollectionHall_49018_Desc = {
    Text = "A. F. 314, một đêm đông sâu thẳm, tiếng nổ vang vọng khắp rừng Akutê. \nĐất rung chuyển, rừng sáng như ban ngày. Kèm theo tiếng thét của sức sống và tiếng khóc của tự nhiên, thị trấn bị san phẳng. \nTheo lời của học sinh dự bị hệ Thức Tỉnh Dexter, người tham gia cuộc điều tra \"Thảm họa Akutê\", trong ánh lửa bừng lên đêm đó, có những tia sáng đen và bạc lấp lánh."
  },
  CollectionHall_49018_Title = {
    Text = "Mặt trời lặn"
  },
  CollectionHall_49025_Desc = {
    Text = "Lời cầu nguyện màu sương trắng."
  },
  CollectionHall_49025_Title = {
