  },
  CollectionHall_49026_Title = {
    Text = "Song Sinh Xuyên Tạc·Trắng"
  },
  CollectionHall_49027_Desc = {
    Text = "Truyền nhân huyền thoại đầu tiên chế tạo ma tượng, nuôi dưỡng chúng bằng máu."
  },
  CollectionHall_49027_Title = {
    Text = "Tiệc xa xôi"
  },
  CollectionHall_49028_Desc = {
    Text = "Người tạo ra ma tượng đầu tiên trong truyền thuyết, đã dùng chính đôi tay để tiêu diệt ma tượng."
  },
  CollectionHall_49028_Title = {
    Text = "Đập Nhịp Đỏ Thẫm"
  },
  CollectionHall_49029_Desc = {
    Text = "Suỵt… bí mật ẩn trong đệm thịt mềm mại."
  },
  CollectionHall_49029_Title = {
    Text = "Sự xuống máy"
  },
  CollectionHall_49030_Desc = {
    Text = "Hãy sinh sôi! Hãy nảy nở. Hãy để những linh hồn mang hạt giống của Cây Mẹ lan tỏa khắp thế gian."
  },
  CollectionHall_49030_Title = {
    Text = "Tái diễn hóa"
  },
  CollectionHall_49031_Desc = {
    Text = "Trôi nổi trong khe hở của dòng thời gian tuần hoàn."
  },
  CollectionHall_49031_Title = {
    Text = "Lời mời đỏ thẳm"
  },
  CollectionHall_49033_Desc = {
    Text = "Sợi dây thời gian đứt gãy, những phím đàn đang chảy đều vỡ vụn. \n Họ đứng bên ngoài hiện thực, dùng hiện thực làm chất liệu vá lại những thiếu sót, để bản nhạc không bao giờ hạ màn lại vang lên trên cao. \n Còn những giọt nước mắt rơi xuống khi giấc mơ tỉnh lại thì chảy về đâu, không ai biết."
  },
