  CollectionHall_50271_Title = {Text = "Lai Yểu"},
  CollectionHall_51019_Desc = {
    Text = "<Title:Ngày thành lập>\nTrước Hồng tích\n\n<Title:Người sáng lập>\nKhông rõ\n\n<Title:Tổng quan>\nDân du mục tách ra từ Đế quốc Assyria. \nSống sâu trong những cơn bão dữ dội quanh năm ở sa mạc Lemvahi, cuộc sống rất nguyên thủy và ít liên lạc với người ngoài. Người Aran tin vào \"cây mẹ phong thịnh\", dựa vào khả năng sinh sôi bất thường của cây mẹ phong thịnh và nước sông thiêng để duy trì quy mô dân số. \nSau \"Hành động Lemvahi\", người Aran biến mất, không còn tin tức."
  },
