  CollectionHall_51373_Title = {
    Text = "Vật không thể đoán định"
  },
  CollectionHall_51374_Desc = {
    Text = "<Title:Giới thiệu>\nGiáo sư Đại học Misaque, nhà hoạt động xã hội, quý tộc.\nTừng là một chàng trai giàu có tiêu tiền như nước, phạm phải một số tội nhỏ không đáng kể và được biết đến trong cả giới chính đạo lẫn hắc đạo.\nSau đó, gia tộc bị giáo phái tà ác tàn sát, ông trở thành người sống sót duy nhất. Chỉ mình ông ấy mới hiểu rõ những gì đã xảy ra sau đó.\nDù là cha nuôi của Ramona nhưng lại luôn im lặng về nguồn gốc của cô.\nKhi còn trẻ, tất cả các môn học đều không đạt yêu cầu, thế mà sau này lại trở thành giáo sư tại Đại học Misaque.\nTính cách phóng khoáng nhưng không hề dính tin đồn tình ái.\nTóm lại, đây là một người đầy rẫy những mâu thuẫn."
  },
  CollectionHall_51374_LockTip = {
    Text = "Hoàn thành phần mở đầu để mở khóa"
  },
  CollectionHall_51374_Title = {Text = "Đắc-tơ"},
  CollectionHall_51375_Desc = {
    Text = "<Title:Giới thiệu>\nCon nuôi của Dexter, người bạn điều tra đáng tin cậy nhất của nhân vật chính.\nTừ nhỏ đã lui tới các lớp học của các khoa trong trường, có hiểu biết sâu sắc về hiện tượng rỗng rỗng và thân thể được đánh thức.\n\nKhi còn nhỏ, Ramona cũng từng ao ước có \"cha mẹ ruột\", nhưng dưới sự chăm sóc và yêu thương của Dexter và các thầy cô, cô đã coi trường học là ngôi nhà thực sự của mình.\n\nLạnh lùng, lý trí và lòng tốt vừa đủ khiến cô không có chút \"kỳ lạ\" nào – trong nhóm những người kỳ lạ như Misaque, sự \"bình thường\" của cô lại càng nổi bật hơn.\nDù luôn giữ vẻ mặt lạnh lùng, nhưng những người quen biết cô đều biết, đó chỉ là sự mệt mỏi của một \"thiên tài\"."
  },
