  },
  CollectionHall_57597_Desc = {
    Text = "<Title:Giới thiệu>\nGiám mục hiện tại của vùng Lentiennam, cũng là thân thể được đánh thức một cách bất ngờ bởi vị giám mục đời trước.\nLà tín đồ trung thành của Cha Sáng Tạo, ngài thực hành lời dạy của Cha bằng chính sinh mệnh của mình, đối xử với vạn vật bằng lòng nhân ái và sự khoan dung, được người dân vô cùng kính trọng, thậm chí một số tín đồ gọi ngài là \"Thánh nhân của Lentiennam\".\nTrớ trêu thay, chính lòng thương xót và từ bi đối với muôn loài đã cướp đi mạng sống của ngài khi còn là con người.\nKhi còn sống, ngài từng cố gắng chữa trị hiện tượng rỗng rỗng, không tiếc hiến dâng thịt máu của mình cho bảng đá sức sống để giảm bớt đau đớn và kéo dài sự sống cho những \"bệnh nhân\" trong giáo khu. Sau khi ngài mất, bảng đá biến mất——cho đến khi ngài tái sinh dưới dạng thân thể được đánh thức.\nĐôi mắt bị che phủ bởi băng vải và vải bó có thể nhìn thấy ánh sáng của linh hồn, vì vậy sau khi gặp Người Giữ Gìn, ngài đã xác định: Người giữ bí mật chính là sứ giả nhợt nhạt mà Cha Sáng Tạo đã tiên tri, người có thể cứu thế giới này khỏi bóng tối sắp tới."
  },
  CollectionHall_57597_LockTip = {
    Text = "Hoàn thành Báo cáo Đặc vụ\"Màu máu\"để mở khóa"
  },
  CollectionHall_57597_Title = {Text = "Salvador"},
  CollectionHall_57598_Desc = {
    Text = "<Title:Giới thiệu>\nVị vua trẻ nhất của nền văn minh Lemuria cổ đại.\nTừ nhỏ đã sở hữu tài năng đặc biệt, ngủ hơn hai mươi giờ mỗi ngày, và khi tỉnh dậy cũng luôn trong trạng thái uể oải.\nThỉnh thoảng có thể cảm nhận được cảm xúc của các vị thần, mơ thấy những mảnh ký ức từ các thời không khác nhau, do đó được người dân tôn kính, sùng bái và suy tôn làm vua.\nNhưng vị vua trẻ không mấy bận tâm. Ông chỉ cố gắng lẩn tránh những điềm báo và lời tiên tri từ thần linh.\n\nCuối cùng, ông nhìn thấy trước số phận diệt vong của Lemuria, nhưng không biết cách thay đổi, nên buộc phải giữ im lặng.\nCho đến ngày thảm họa giáng xuống, tất cả mọi người rơi vào tuyệt vọng. Để đáp lại lòng mong đợi của thần dân, ông đã tạo ra một lời tiên tri giả.\nVề vị vua bất tử, và lời tiên đoán về sự tái sinh của ông.\nCuối cùng, thế giới cũ chìm trong biển nước. Thời gian trôi qua, loài người mới dần sinh sôi trên mặt đất, còn những câu chuyện tiền sử thì không ai nhớ đến nữa.\nCó lẽ chính ông cũng không ngờ rằng, lời tiên tri vô tình của mình sẽ trở thành nguồn cảm hứng cho vô số huyền thoại sau này.\nÔng đã đánh giá thấp sức mạnh của niềm tin."
  },
  CollectionHall_57598_LockTip = {
    Text = "Sau khi thức tỉnh \"Tulô\" sẽ mở khóa"
  },
  CollectionHall_57598_Title = {Text = "Tulu"},
  CollectionHall_57599_Desc = {
    Text = "<Title:Giới thiệu>\nSứ giả từ dân tộc Á Lan, tự nhận rằng mình đi theo lời mách bảo từ giấc mơ để đến Lemvahi. \nDẫn đầu đội ngũ của dân tộc Á Lan, họ đã lang thang lâu dài bên ngoài Tường Bão. Mục tiêu chính là tìm cách phục hồi cây thánh của dân tộc Á Lan —— cây mẹ phong thịnh. \nThực chất thuộc về Hội Giáo đèn lồng. Chưa ai hiểu rõ động cơ thực sự ẩn sau nụ cười bi ai vĩnh cửu của cô ấy, có lẽ khi hành trình tiếp tục, sẽ có thể hé lộ đôi chút bí ẩn."
  },
  CollectionHall_57599_LockTip = {
    Text = "Hoàn thành điều tra hành động chương 7 \"Sông Dục Vọng\"để mở khóa"
  },
  CollectionHall_57599_Title = {Text = "Juliette"},
  CollectionHall_57600_Desc = {
    Text = "<Title:Giới thiệu>\nSống trong nền văn minh tiền sử Lemuria, cả gia đình đều là những người tu hành tâm linh sùng đạo kính thần.\nTừ nhỏ đã chăm chỉ tu luyện, lớn lên như nguyện bước vào thần điện ở thủ đô, trở thành một tế tư.\nNàng khao khát thần tích, khao khát trải nghiệm linh ảo huyền bí, nhưng chúng chưa từng giáng lâm.\n\nKhi Turu lên ngôi làm vương, nàng trở thành đại tế tư hầu cận bên cạnh.\nLần đầu tiên nhìn thấy tân vương, nàng cảm thấy vô cùng xuất thần và hoan hỷ, nàng lập tức hiểu ra đây chính là điều nàng khao khát — hiện thân của thần linh nơi nhân gian.\nĐúng vậy. Ý nghĩa tồn tại của nàng chính là phụng sự vị ấu vương này.\n\nCho đến khi hồng thủy nhấn chìm đại lục cùng nền văn minh Lemuria xuống đáy biển, nàng cũng chưa từng lay động tín niệm ấy."
  },
  CollectionHall_57600_LockTip = {
    Text = "Hoàn thành Thế giới Mộng Ảo \"Phỉ Báng\"để mở khóa"
  },
  CollectionHall_57600_Title = {Text = "Miryam"},
  CollectionHall_57601_Desc = {
    Text = "<Title:Giới thiệu>\nVì muốn gieo rải hạt giống vượt qua bức tường chiều không gian, nhưng lại vì \"tình yêu\" mà từ bỏ bản năng sinh sôi của chủng tộc.\nSaya vô tình lạc đến vũ trụ này, được Tincture — kẻ du hành giữa các vì sao — đánh thức từ Ngân Tâm. Nàng mơ hồ tìm kiếm phương hướng, lưu lại trên một hành tinh hoang vu, cho đến khi gặp được Người Giữ Bí Mật của Misagor.\nTrong quá trình tìm tòi, trong những cuộc trò chuyện sâu sắc, hai thực thể khác biệt đã đi đến một đáp án tương đồng về định nghĩa của \"tình yêu\".\nKý ức có thể mờ nhạt, nhưng sợi dây liên kết từng hình thành với người quan trọng sẽ một lần nữa dẫn lối cho nàng.\nTrong thế giới tràn ngập sự lãng quên này, nàng kiên định giữ lấy căn bệnh mang tên tình yêu của mình."
  },
  CollectionHall_57601_LockTip = {
    Text = "Mở khóa sau khi đánh thức \"Saya\""
  },
  CollectionHall_57601_Title = {Text = "Saya"},
  CollectionHall_57602_Desc = {
    Text = "<Title:Giới thiệu>\nTrong những truyền thuyết cổ xưa, thế giới tồn tại hai con quái thú khổng lồ, mỗi con chiếm giữ một nơi sâu thẳm dưới đáy nước và phía đông Vườn Địa Đàng. \nHai con quái thú này chỉ có thể gặp nhau khi thời gian đến tận cùng, họ sẽ được dâng làm lễ vật cho Mẹ Sinh Mệnh Tiamat, để đổi lấy sự luân hồi của sức sống. \n\nLơ-tan chính là con 「thú」ẩn sau truyền thuyết. \nCô ấy là sản phẩm tự nhiên của hành tinh, khác với truyền thuyết, cô ấy vừa là hố sâu dưới đáy nước, vừa là linh hồn của Vườn Địa Đàng. \nCô ấy là sức mạnh hỗn loạn thuần khiết, là linh hồn tự do không bị trói buộc, là trật tự chưa được định nghĩa. \nPhá hủy và quy tắc là quyền năng mà thế giới ban cho cô ấy, hai bản năng hoàn toàn đối lập va chạm trong cơ thể Lơ-tan, để cân bằng sức mạnh đủ để xé nát cô ấy, cô ấy cần dùng chiến đấu để giải phóng dục vọng phá hủy. \nLơ-tan được hành tinh giao phó trách nhiệm bảo vệ lịch sử. 「Công việc」của cô ấy là tuân theo ý chí của hành tinh, quét sạch, trừng phạt những người ảnh hưởng đến vận mệnh của hành tinh, nhưng những người như vậy chỉ xuất hiện sau hàng nghìn năm. \nTrong vô tận, chờ đợi sứ mệnh giáng xuống, Lơ-tan khao khát sự xuất hiện của một đối thủ. \n\nVì vậy, cô ấy từng hướng ánh mắt về vị vua trẻ tuổi kia, thậm chí còn triệu hồi tai ương từ trên trời rơi xuống. \nTuy nhiên, mọi thứ đều không làm tổn hại đến ý chí chiến đấu mãnh liệt của cô ấy, chúng chỉ càng trở nên mạnh mẽ hơn khi cô ấy thức tỉnh."
  },
  CollectionHall_57602_LockTip = {
    Text = "Được mở khóa sau khi thức tỉnh \"lơ-tan\""
  },
  CollectionHall_57602_Title = {Text = "Lotan"},
  CollectionHall_57603_Desc = {
    Text = "<Title:Giới thiệu>\nThái tử của Thành phố Chôn Vùi một thời, hiện nay là Đức Vua Thịt Đối của những thây ma được tôn thờ như một vị thần.\nDù anh là một thanh niên thông minh, công bằng, nhưng vì\"Gu\"ăn độc đáo của mình - ăn xác, anh đã bị Hoàng gia tránh né.\nCha anh đã bị ám sát bởi Dulles vào đêm trước khi thoái vị. Trong quá trình bị phân hủy và nuốt chửng, ý thức của anh đã hòa làm một với Ngài được tôn thờ trong đền thờ, từ đó anh đã nếm trải được hương vị cơ thể mình, vị ngọt đáng kinh ngạc đã khiến anh nhung nhớ.\nAnh coi việc ăn uống là một nghệ thuật lãng mạn, đó không chỉ là sự thỏa mãn của khẩu vị mà còn là một kỷ niệm bị lãng quên.\nPhân rã sẽ phá hủy mọi thứ, để quá khứ tan biến theo gió, nhưng Dulles sẽ chứng kiến tất cả những huyền thoại và sự bình dị của những người sống sót, để máu và thịt lưu lại trong ký ức của mình cho đến vĩnh cửu."
  },
  CollectionHall_57603_LockTip = {
    Text = "Thức tỉnh \"Dullesai\" sẽ mở khóa"
  },
  CollectionHall_57603_Title = {Text = "Doresain"},
  CollectionHall_57604_Desc = {
    Text = "<Title:Giới thiệu>\nTừng là lãnh chúa của một vùng điền trang rộng lớn.\nSau khi hành tinh mẹ bị hủy diệt bởi hiện tượng rỗng rỗng, đã rơi xuống thung lũng sông Cambrian trên một khối đá vụn khổng lồ.\nSở trường trong quản lý gia súc, sáp nhập đất đai và quản trị đầu tư rủi ro.\nMỗi lần xuất hành, phía sau luôn có đoàn tùy tùng bất tử hùng hậu.\n1 người làm bệ bước chân, 2 người nghệ sĩ hát rong giải trí, còn 4 người lái xe ngựa…\nNgay cả Giáo hoàng cũng sẽ cảm thấy đội hình của mình đơn sơ đến mức đáng xấu hổ."
  },
  CollectionHall_57604_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Buổi tiệc bùng cháy\"để mở khóa"
  },
  CollectionHall_57604_Title = {Text = "Wanda"},
  CollectionHall_57605_Desc = {
    Text = "<Title:Giới thiệu>\nChị gái sinh đôi yêu quý của Tinkert.\nNgay từ khi mới nở đã thể hiện \"thiên phú\" khác biệt, vì năng lực không thể kiểm soát, Pheinert chỉ có thể mãi cuộn mình trong \"tã lót\" mà không thể lớn lên.\nBị coi là cá thể sẽ mang đến bất hạnh cho tộc loài, vì vậy đã bị trục xuất khỏi không gian sinh sống ban đầu cùng với Tinkert.\n\nEm gái dựa vào sự bố thí của tầng lớp thượng lưu để đổi lấy dưỡng chất cần thiết cho cuộc sống, cô dành phần lớn vật tư để nuôi dưỡng Pheinert.\nSau một thảm họa nào đó, kiếm được duy nhất một tấm \"vé\", đã dỗ dành Pheinert lên chuyến hành trình rời khỏi hành tinh hoang vu.\nVào khoảnh khắc cất cánh, Pheinert đã thực hiện cuộc phản kháng đầu tiên, và cũng là lần cuối cùng:\nCô lấy việc rời khỏi tã lót, hấp thụ năng lượng sinh mệnh của tất cả mọi người làm điều kiện, ép buộc Tinkert phải rời đi…\nVì bản thân là \"có khiếm khuyết\", nên vô cùng tự ti.\n\nTừng một thời từ chối ăn uống, mong muốn bản thân sớm chết đói, để tránh trở thành gánh nặng cho Tinkert.\nLâu dần, hình thành thói quen xấu là kén ăn.\n\nThích những góc tối tăm. Thông thường phải đến những nơi như tầng hầm mới có thể tìm thấy Pheinert."
  },
  CollectionHall_57605_LockTip = {
    Text = "Sẽ được mở khóa sau khi thức tỉnh \"Phiệt\""
  },
  CollectionHall_57605_Title = {Text = "Faint"},
  CollectionHall_57606_Desc = {
    Text = "<Title:Giới thiệu>\nKatie Gura là một cô mồ côi được sinh ra ở vùng sa mạc, khi còn là một thiếu nữ, cô đã nhận nuôi nhiều trẻ em cùng hoàn cảnh đau thương như cô.\nĐể dẫn dắt những đứa trẻ này trong cuộc sống khó khăn trên thế giới, cô đã tạo dựng một lớp vỏ bề ngoài giả tạo để chống lại những tổn thương ác ý.\nNhiều người nhìn vào cô coi như một biểu tượng của sự tàn nhẫn và điên cuồng.\nDù ở bất kỳ cuộc xung đột nào, cô cũng sẽ với sự nhiệt huyết điên cuồng và những phương thức tàn nhẫn nhất để đáp lại những kẻ dám đứng trước họng súng của cô.\nTheo thời gian trôi qua, ngay cả những đứa trẻ còn đang bập bẹ cũng đã biết rằng, trên biển cát vô tận, có một tử thần màu hổ phách đang hiện hữu.\nTrong một cuộc đối đầu với N, cô không ngoài dự đoán đã thua trận đấu đó, và cũng mất đi tất cả.\nNhưng ngay cả N cũng không biết rằng, cô đã bị một vị nào đó trong các vì sao để ý.\nSau khi trải qua cái chết định mệnh, cô đã thừa kế sức mạnh của Ngài đó và sứ mệnh mà Ngài đã định ra cho mình.\nCơ thể của cô chứa đựng sự tồn tại trong các vì sao, cô đã có thể trở thành một phần trong số họ.\nNếu thời khắc cuối cùng không thể ngăn cản, Ngài sẽ ném bỏ tất cả, trở về cực thiên, trở thành bến cảng đầu tiên và cũng là cuối cùng."
  },
  CollectionHall_57606_LockTip = {
    Text = "Thực hiện vượt ải kẻ lang thang \"Ngày cực thịnh không tàn\" mở khóa sau"
  },
  CollectionHall_57606_Title = {Text = "Kathigu-ra"},
  CollectionHall_57607_Desc = {
    Text = "<Title:Giới thiệu>\nMeltdown·Đóa ban đầu là niềm tự hào của Misaque và khoa học nhân loại. Trong cuộc chiến kéo dài với hiện tượng rỗng rỗng, cô nhận ra rằng, hiện tượng này không chỉ làm tiêu tan thân thể mà còn mở ra con đường dẫn đến chân lý. \nSau khi tình cờ tiếp xúc với một bảng đá cổ khắc những lời răn bí ẩn, cô quyết định bước trên con đường tối tăm vô tận này, từ bỏ việc thay thế cơ thể búp bê để kéo dài sức sống, để mặc cho sự rỗng rỗng xâm nhập não bộ. \nCuối cùng, cô đạt được điều mong muốn, hiểu rõ bản chất của rỗng rỗng, nhưng cũng hoàn toàn đi vào hủy diệt và hư vô. \nKhi niềm tin và lý trí như ngọn đèn soi sáng cho mọi người biến mất, Meltdown·Đóa bắt đầu thực hiện những hành động hủy diệt ở nơi giáo viên và học sinh trong trường không thể nhìn thấy, \"giúp đỡ\" gây ra nhiều vụ tai nạn thương vong trước khi bị Misaque phát hiện và áp dụng mức giám sát và kiểm soát cao nhất. \nChỉ là, sau lưng cái búp bê sụp đổ, linh hồn thiên tài bất diệt dường như vẫn đang giao tiếp từ xa với nơi sâu thẳm và tối tăm hơn của thế giới."
  },
  CollectionHall_57607_LockTip = {
    Text = "Sau khi thức tỉnh \"Nóng chảy·đóa\", sẽ mở khóa"
  },
  CollectionHall_57607_Title = {
    Text = "Doll: Tận Thế"
  },
  CollectionHall_57608_Desc = {
    Text = "<Title:Giới thiệu>\nXuất thân thấp kém, nhưng nhờ vẻ đẹp mà cô được nhiều người yêu mến, miễn cưỡng sống trong tầng lớp thượng lưu với vai trò ca nữ.\n\nKhi tai họa xảy ra, dựa vào lòng thương xót và ân huệ, cô đã kiếm được chiếc \"vé máy bay\" duy nhất để thoát thân.\n\nMọi người đều mặc định rằng suất này thuộc về cô, nhưng cô đã quyết tâm trong bóng tối, muốn đưa chị gái Phiệt lên chuyến bay an toàn.\n\nTuy nhiên, vào phút chót, chị gái đã dùng lực lượng để ép buộc, trói cô vào ghế, đưa cô rời khỏi hành tinh hoang vu.\n\n\nSau khi bị đánh thức bất ngờ, Tinkerer luôn day dứt trong lòng, cô tin rằng chị gái chưa chết, hoặc đã hồi sinh dưới hình dạng nào đó giống như cô.\n\nTừ đó, cô đã nỗ lực hết mình để tìm kiếm tung tích của chị gái, không tiếc bất cứ giá nào."
  },
  CollectionHall_57608_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"tinkerer\""
  },
  CollectionHall_57608_Title = {Text = "Tinct"},
  CollectionHall_57609_Desc = {
    Text = "<Title:Giới thiệu>\nĐược gọi là \"Não của Misaque\", một trong những cố vấn ngoại vụ của Misaque. \nNhập học Misaque lúc 14 tuổi, từng chủ trì cải tiến thiết bị duy trì sự sống của Alistair. \nTrong một chuyến đi ra ngoài, bị nhiễm rỗng rỗng, sau khi viết tới tám mươi trang hướng dẫn Bước kích hoạt, cô đã bình tĩnh qua đời. \nSau khi chết, đồng đội theo hướng dẫn, đưa bạc tâm của cô vào thiết bị kích hoạt, tạo ra \"đóa thân thể được đánh thức\". \nSau khi được kích hoạt, cô bình tĩnh đứng dậy mặc quần áo, bình tĩnh bước vào phòng nghiên cứu, bình tĩnh tiếp tục nghiên cứu mà cô để lại trước khi chết. \nThiên tài quả thật như vậy, thế giới của họ khô khan và bình lặng!"
  },
  CollectionHall_57609_LockTip = {
    Text = "Sau khi thức tỉnh \"Đóa\" có thể mở khóa"
  },
  CollectionHall_57609_Title = {Text = "Doll"},
  CollectionHall_57610_Desc = {
    Text = "<Title:Giới thiệu>\nThể tinh thần của một chủng tộc ngoài hành tinh trốn thoát từ hành tinh bị rỗng nuốt chửng, chiếm lấy thân thể của một thiếu nữ vừa chết, tránh được số phận tử vong giống như cha mẹ. \nTuy nhiên, niềm vui ngắn chẳng tày gang. Khi thân thể con người này xuất hiện triệu chứng rỗng, thể tinh thần của cô cũng bị cố định trong cơ thể và không thể thoát ra thêm lần nào nữa. \nTrong nỗi sợ hãi bị rỗng xâm nhiễm, cô rơi vào sụp đổ tinh thần. Cô chủ động liên lạc với Misaque, yêu cầu biến mình thành thân thể được đánh thức và đồng ý dùng kiến thức kỹ thuật của chủng tộc mình làm phần thưởng đáp lại. \nSau khi trở thành thân thể được đánh thức, cô tiến hành nghiên cứu về cơ khí, điện học, và các vấn đề liên quan đến tinh thần tại học viện. Nhưng do sự sợ hãi đặc biệt đối với rỗng, cô không thể thực hiện nghiên cứu về nó. Thậm chí, vì bóng tối tâm lý mà cô sợ hãi bóng tối, không dám ngủ, mỗi ngày sống trong sự nhạy cảm và căng thẳng."
  },
  CollectionHall_57610_LockTip = {
    Text = "Giải khóa sau khi thức tỉnh \"Wenkel\""
  },
  CollectionHall_57610_Title = {Text = "Winkle"},
  CollectionHall_57611_Desc = {
    Text = "<Title:Giới thiệu>\nThể tinh thần được sinh ra trong bình diện tinh thần, ban đầu trôi nổi cô đơn trong đại dương xám rộng lớn và trống rỗng, theo các du khách tinh thần thỉnh thoảng đến mà đến Trái Đất, trải nghiệm những ước nguyện khác nhau và chặt đầu họ, thu thập đầu của họ trong đại dương, hấp thụ trí tuệ và cảm xúc của họ.\nĐã được đánh thức từ hơn một nghìn sáu trăm năm trước, và nhập vào người đánh thức mình để chặt đầu cô ta, do đặc tính hấp thụ sức mạnh tinh thần, vẫn duy trì sự tồn tại bằng cách thu thập đầu, và vì giải trí đã săn lùng và chặt đầu nhiều hơn số cần thiết. Cho đến khi gặp được chủ cửa hàng thực sự, bị chế ngự và đạt được đổi chỗ, làm trợ lý theo chủ cửa hàng cho đến khi sức sống cô kết thúc.\nQuái vật đã xây dựng tình bạn thật sự với chủ cửa hàng đã hiểu được khát vọng thực sự của mình, chặt đầu chủ cửa hàng và kế thừa ngoại hình và cửa hàng của cô. Từ đó không còn săn lùng đầu một cách tùy tiện, mà chuyển sang cách giải quyết các ủy thác huyền bí thông qua việc trao đổi cửa hàng để lấy đầu, và giảm bớt sự cô đơn sau khi mất chủ cửa hàng thông qua việc giao tiếp với khách hàng.\nƯớc nguyện hiện tại là bảo vệ cửa hàng và thành phố mà chủ cửa hàng yêu thích."
  },
  CollectionHall_57611_LockTip = {
    Text = "Hoàn thành ghi chép nhiệm vụ đặc biệt \"Bóng ma thị trấn mưa\"để mở khóa"
  },
  CollectionHall_57611_Title = {
    Text = "Hoa thuỷ tiên"
  },
  CollectionHall_57612_Desc = {
    Text = "<Title:Giới thiệu>\nTrước khi chết, cô từng là một nhà ảo thuật du lịch khắp thế giới.\nLớn lên trong một rạp xiếc, cuộc sống của cô đầy rẫy những \"kẻ khác biệt\", kẻ trộm, tội phạm bỏ trốn, trẻ mồ côi, người khuyết tật, người dị dạng...\nKassia cũng là một \"kẻ khác biệt\": cô không thể cảm nhận cảm xúc, cũng không thể tự phát sinh cảm xúc.\nLà một tài năng biểu diễn thực sự, cô luôn thu hút được sự cổ vũ của khán giả.\nDù sau đó gặp phải @2, trở thành linh hồn của nạn nhân dị giáo, cô vẫn tiếp tục biểu diễn ảo thuật như khi còn sống, mời khán giả vào \"thế giới thần kỳ như tiên cảnh\".\nLạ thay, mỗi khán giả sau khi xem màn ảo thuật đều cảm thấy \"thiếu điều gì đó\", cuộc sống trở nên ngày càng vô vị.\nHọ bối rối, tê dại, thậm chí tự tử.\nCòn cô tiểu ảo thuật gia của chúng ta? Cô ẩn mình sau bức màn, vui vẻ thưởng thức \"phần thưởng ngọt ngào\" mà mình thu hoạch được.\nBiểu diễn hoành tráng tốn kém, cô chỉ muốn phát triển bền vững."
  },
  CollectionHall_57612_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"Kasia\""
  },
  CollectionHall_57612_Title = {Text = "Casiah"},
  CollectionHall_57613_Desc = {
    Text = "<Title:Giới thiệu>\nThực thể bí ẩn tình cờ vượt qua hàng rào thế giới, cũng là một khả năng khác của Ramona.\nTrong \"sự kiện đó\", để bảo vệ sự an toàn của Người Giữ Gìn, không thể không buông thả sức mạnh của người đánh thức khống chế thân thể.\n\nSau khi sự kiện kết thúc, @2 đã để lại ảnh hưởng trên cơ thể của Ramona.\nÝ thức của @2 ở lại trong thân thể cô ấy, chèn ép không gian tồn tại của ý thức từng ngày.\nVì điều này, cô ấy rơi vào sự đấu tranh và đau khổ vô tận.\n\nBởi không muốn người khác lo lắng, cô thể hiện như mọi thứ đều ổn\n, chăm sóc tóc và cuộc sống của mình rất gọn gàng.\nThỉnh thoảng ý thức sẽ mất đi, thể hiện trạng thái trống rỗng\n, thậm chí nói chuyện bằng một giọng điệu khác.\nKhông cần lo lắng về điều này. Ngay cả khi xuất phát điểm khác nhau, tất cả hành động đều vì sự hòa bình của Người Giữ Gìn và thế giới này."
  },
  CollectionHall_57613_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Cách một bước\"để mở khóa"
  },
  CollectionHall_57613_Title = {
    Text = "Ramona: Thời Quy"
  },
  CollectionHall_57614_Desc = {
    Text = "<Title:Giới thiệu>\nCô sinh ra ở đất nước của thơ ca và hoa hồng, là hiện thân của thi ca. \nNàng tiên lang thang trong giấc mơ dệt bằng chữ, vui mừng với từng tia nắng hé lộ và rơi lệ khi từng bông hoa tàn phai. \nCô trầm ngâm, cô sầu não, khao khát sự đồng hành của một tâm hồn khác. \n\nRồi một ngày, trong khu vườn rực rỡ hoa, chàng thợ làm vườn trẻ đã đặt một bông hồng trước mặt cô. \nVà cô mỉm cười e thẹn, nhẹ nhàng nhận lấy bông hoa. \n \"Cuối cùng cũng không còn phải một mình nữa.\"\nĐó là điều cô tin tưởng vào thời điểm ấy."
  },
  CollectionHall_57614_LockTip = {
    Text = "Hoàn thành ghi chép Đặc vụ\"Nơi trú ngụ của Hoa Hồng\"để mở khóa"
  },
  CollectionHall_57614_Title = {Text = "Horla"},
  CollectionHall_57615_Desc = {
    Text = "<Title:Giới thiệu>\nNữ hoàng duy nhất của tộc Aran, từ thời cổ đại. \nKhi còn nhỏ, cô được tôn làm sứ giả của cây, truyền đạt chỉ dụ của vua. Sau cuộc nổi dậy đầu tiên, cô bị coi là tế phẩm và ném vào dòng sông thiêng liêng của tộc Aran, nhưng đã thức tỉnh ý chí của cây. \nThịt máu của cô hòa quyện với sữa của cây, rễ của cây chảy trong huyết mạch của cô. Cô chính là cây mẹ phong thịnh, cây mẹ phong thịnh chính là cô. \nTuy nhiên, sức mạnh rỗng rỗng đã làm ô nhiễm huyết mạch của tộc Aran, cô tự nguyện dùng thân thể mình thay cây mẹ chịu đựng sự ô nhiễm, để cầu một tia hy vọng cho tộc Aran. \nNgày nay, khi tộc Aran đã biến mất trong dòng chảy của lịch sử, chỉ có cây mẹ phong thịnh sừng sững rồi sụp đổ chứng kiến câu chuyện liên quan đến cô."
  },
  CollectionHall_57615_LockTip = {
    Text = "Sau khi \"Thái Di Sơ\"được thức tỉnh, tính năng sẽ được mở khóa"
  },
  CollectionHall_57615_Title = {Text = "Thais"},
  CollectionHall_57616_Title = {
    Text = "Giữa các vì sao"
  },
  CollectionHall_57617_Desc = {
    Text = "<Title:Giới thiệu>\nThầy tâm lý của Đại học Misaque, phụ trách việc hỗ trợ tâm lý cho các điều tra viên.\nÔn nhu và thiện lành, được giáo viên và sinh viên trong trường yêu mến, nhưng một số thành viên của Misaque lại rất sợ cô.\nBỏ qua những tách trà đỏ không rõ thành phần — chưa từng có ai thấy cô ấy ngừng cười, chỉ riêng điều này đã đủ khiến người ta lạnh sống lưng rồi."
  },
  CollectionHall_57617_LockTip = {
    Text = "Hoàn thành phần mở đầu để mở khóa"
  },
  CollectionHall_57617_Title = {Text = "Xy-lvia"},
  CollectionHall_57618_Title = {
    Text = "Kẻ ngu dốt"
  },
  CollectionHall_57619_Title = {
    Text = "Hỗn chủng"
  },
  CollectionHall_57620_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"Pikman\""
  },
  CollectionHall_57620_Title = {
    Text = "Người lạ"
  },
  CollectionHall_57621_Desc = {
    Text = "<Title:Giới thiệu>\nĐiều tra viên kỳ cựu của Misaque, được những Người Giữ Gìn tôn trọng gọi là 「đàn anh」.\nTừng sợ ra ngoài vì một số lý do không thể nói rõ, vừa học tại trường vừa kiêm nhiệm công việc tình báo.\nSau khi người bạn thân qua đời, đã thay đổi phong cách sống trước đây và chuyển sang tiền tuyến, để tưởng nhớ bạn, anh ấy quyết định tiếp tục công việc mà người bạn đã từng làm.\nLuôn mang theo bên mình một chiếc chìa khóa bạc bị vỡ, khó khăn duy trì những ký ức đang dần phai nhạt."
  },
  CollectionHall_57621_LockTip = {
    Text = "Hoàn thành phần mở đầu để mở khóa"
  },
  CollectionHall_57621_Title = {Text = "Vilịêm"},
  CollectionHall_57622_Desc = {
    Text = "<Title:Giới thiệu>\nHoa viên của Tây Đài, người bạn thơ ấu của Ôrla. \nKhi Ôrla tuyệt vọng nhất, Colette đã mang đến cho cô những khoảnh khắc hạnh phúc khó quên bằng một khu vườn. \nKhi tài năng của Ôrla bắt đầu nảy nở, Colette đã cướp đi sự giàu có, danh tiếng và cả sức sống của cô bằng một trận hỏa hoạn. \nCô hợp tác với Herbert để tạo ra thế giới trong thơ từ tập thơ của Ôrla. Có thể là để tưởng nhớ, có thể là để kiểm soát. Không ai biết. \nColette luôn tuyên bố rằng, trong những câu thơ đẹp đẽ đó, cô chỉ hiểu được dục vọng. \nĐiều này khiến cô đau khổ, nhưng đồng thời cũng là điều mà cô tự hào."
  },
  CollectionHall_57622_LockTip = {
    Text = "Hoàn thành ghi chép Đặc vụ\"Nơi trú ngụ của Hoa Hồng\"để mở khóa"
  },
  CollectionHall_57622_Title = {Text = "Corèt"},
  CollectionHall_57623_Desc = {
    Text = "<Title:Giới thiệu>\nMiriam đã gặp hai Deborah: một là linh mục tại Lemuria, một là thị nữ của gia đình Orn. Một người là bạn thân của cô, người kia cũng là bạn thân của cô.\nHai thời đại cách nhau hàng vạn năm. Hai con người khác nhau, nhưng cùng chia sẻ một cái tên, một khuôn mặt, và một tấm lòng nhân hậu. Đây là một sự trùng hợp kỳ diệu, và đối với Miriam, đây còn là một dấu hiệu linh thiêng từ trời cao.\nMiriam đã chứng kiến kết cục của cả hai Deborah: một người chìm xuống đáy biển cùng Lemuria, một người bị chính tay cô đưa lên bàn thờ, bị mổ bụng mà chết.\nTrong câu chuyện lớn lao về thần quốc, câu chuyện của Deborah chỉ là hai dòng chú thích ngắn gọn và đỏ tươi."
  },
  CollectionHall_57623_LockTip = {
    Text = "Hoàn thành Thế giới Mộng Ảo \"Phỉ Báng\"để mở khóa"
  },
  CollectionHall_57623_Title = {Text = "Đêbôra"},
  CollectionHall_57624_Desc = {
    Text = "<Title:Giới thiệu>\nNgười môi giới thông tin hàng đầu của Đại học Misaque, thành viên của Hiệp hội Suy luận Học đường.\nSở hữu khả năng thu thập và khai thác thông tin vô song, nổi tiếng trong toàn bộ Lentiennam.\nBan đầu là người của Cộng hòa Agro, cô đến Lentiennam do biến cố gia đình và đã sử dụng những bí mật về Misaque mà cô nắm giữ để nhập học thành công.\nĐừng để nụ cười sảng khoái của cô đánh lừa——hiểu biết của cô về Misaque sâu sắc hơn nhiều so với những gì người ta thường nghĩ."
  },
  CollectionHall_57624_LockTip = {
    Text = "Hoàn thành cuộc điều tra hành động chương 1 \"Bí mật khu Đông\"để mở khóa"
  },
  CollectionHall_57624_Title = {Text = "Hannah"},
  CollectionHall_57625_Desc = {
    Text = "<Title:Giới thiệu>\nCựu nhà nghiên cứu của Quỹ Green, Giám đốc Bệnh viện Điều dưỡng Laï. \nSau khi chồng và con gái qua đời, bà đã không ngừng tìm kiếm cách để hồi sinh con gái. \nTrong quá trình dài đằng đẵng, bà đã quên mất hình dáng của con gái, cũng như tình yêu và sự ấm áp từng giúp bà kiên cường tiến bước. \nBà chỉ còn nhớ rõ nỗi đau đớn."
  },
  CollectionHall_57625_LockTip = {
    Text = "Hoàn thành cuộc điều tra hành động chương 4 \"Trong im lặng\"để mở khóa"
  },
  CollectionHall_57625_Title = {Text = "Phrăng-xi"},
  CollectionHall_57626_Desc = {
    Text = "<Title:Giới thiệu>\nThuyền trưởng của tàu Sonaniel.\nQuê hương tan biến trong ký ức mọi người vì phân rã, chỉ mình anh nhớ mọi thứ. Vì vậy mọi người gọi anh là kẻ điên.\nThị trấn ven biển, gia đình, anh chị em... đó là những quá khứ điên mà anh hằng khao khát tìm lại.\nAnh đã thỏa thuận với Miryam, vận chuyển hàng hóa mà cô cần, đổi lại, cô sẽ giúp anh thức tỉnh một ký ức đã ngủ quên từ lâu.\nVậy rồi, anh thấy cô gái được vây quanh bởi gió nhẹ và những chú chim trắng.\n\n\"Tên của tôi là Celeste, miễn là bạn cần tôi, tôi sẽ tồn tại ở đây.\"\nCô ấy là dấu vết của vùng đất cố hương đã từng tồn tại, là câu chuyện cổ tích anh đã nghe từ người già lúc còn nhỏ.\n\nHóa ra, những ký ức mà anh khao khát thực sự tồn tại."
  },
  CollectionHall_57626_LockTip = {
    Text = "Hoàn thành điều tra hành động chương 6 \"sao đảo ngược\"để mở khóa"
  },
  CollectionHall_57626_Title = {Text = "Êlton"},
  CollectionHall_57627_Desc = {
    Text = "<Title:Giới thiệu>\nNhân viên của Giáo hội phước lành vĩnh cửu của Cha Londinium, chịu trách nhiệm trợ giúp giám mục và các nhân viên giáo hội khác duy trì hoạt động hàng ngày của nhà thờ.\nSau khi cha qua đời, chị gái tài giỏi của ông quán xuyến gia đình và trở thành một thương nhân có tiếng, mọi thứ dường như rất đẹp đẽ thuận lợi — cho đến khi cuộc lừa đảo đã được lên kế hoạch cẩn thận đó xảy ra.\nChỉ sau một đêm, ba người mẹ con đã mất tất cả. Nhưng điều đó không quan trọng, giám mục của Londinium đã đưa tay ra giúp đỡ; chỉ cần có gia đình bên cạnh, cô không sợ bất kỳ khó khăn nào.\nNhưng sau đó chị gái của cô đã chết.\nMẹ của cô đau buồn vô cùng rồi qua đời.\nCùng lúc đó, kẻ vô liêm sỉ ở lại nhà tổ của cô đang tổ chức một salon nghệ thuật, tìm kiếm thú vui.\nBối rối, tức giận, không hiểu... vô số cảm xúc lẫn lộn trong lồng ngực của cô, hóa thành sự thù hận có khả năng nghiền nát mình thành tro bụi. Nhưng cô không nên như vậy, giám mục đã nói rằng, những người bị giam cầm trong quá khứ không bao giờ có thể tiến về phía trước, chỉ có sự tha thứ mới có thể giải phóng.\nCô không thể làm được.\n\"Đừng ép buộc bản thân phải chịu đựng,\" người tự xưng là Bà đèn đã nói rì rầm bên tai cô, \"Tha thứ tức là dung thứ. Chỉ có người tốt mới nên được công nhận, còn người ác - người ác phải chịu sự trừng phạt tương xứng.\"\nVậy là cô đã nhận chiếc gương từ tay bà ta và bắt đầu nghi thức phán xét."
  },
  CollectionHall_57627_LockTip = {
    Text = "Hoàn thành Báo cáo Đặc vụ\"Màu máu\"để mở khóa"
  },
  CollectionHall_57627_Title = {Text = "Sôphia"},
  CollectionHall_57628_Desc = {
    Text = "<Title:Giới thiệu>\nNô lệ không rõ lai lịch, từng kế nhiệm Goliath trở thành thủ lĩnh bộ tộc.\nNăm 8 tuổi đã giết chủ nhân, trốn trong thùng gỗ, trôi dạt đến hòn đảo của người Philistine.\nTrong người chảy dòng máu hèn kém, yếu đuối, đê tiện, đầy tham vọng.\nSau khi trở thành thủ lĩnh chưa đầy một tháng đã bị chặt đầu, thời gian tại vị so với các thủ lĩnh khác, xếp hạng thứ 13.\nThủ lĩnh của người Philistine không phải là chức vị có thể thoải mái làm đến lúc nghỉ hưu."
  },
  CollectionHall_57628_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Sự ngã xuống của gã khổng lồ\"để mở khóa"
  },
  CollectionHall_57628_Title = {Text = "Glen"},
  CollectionHall_57629_Desc = {
    Text = "<Title:Giới thiệu>\n\n\nCô ấy từng là trạm trung chuyển của vương quốc vĩnh cửu, nắm giữ lối ra vào giữa vương quốc và thế giới bên ngoài, có trách nhiệm hướng dẫn những thần dân lạc đường trở về quê hương. \nKhi vương quốc chìm vào giấc ngủ, không ngừng rơi xuống đáy xoáy nước, Pháp Luân Tư đã mất liên kết với quê hương của mình. \nCô ấy không thể liên lạc với kinh đô, cũng không thể tìm thấy bất kỳ dấu vết nào trong đại dương mênh mông. \n\nLà ngọn hải đăng trên biển, nhưng lại không thể soi sáng con đường hồi hương, quả thật đầy chua cay và trớ trêu. \n\nTrong thời gian dài đằng đẵng và cô độc, dần dần đánh mất lý trí và khả năng, gây ra nhiều thảm họa trên biển cả trong lịch sử. Đến khi kiệt sức, cô bị một vị anh hùng cổ đại đánh bại. \n\nTrong các nghiên cứu sau này, thậm chí có học giả cho rằng chính sự suy sụp tinh thần của Pháp Luân Tư đã dẫn đến sự sụp đổ của châu Đại Dương. \nTất cả chỉ là phỏng đoán. Cho đến nay, quá khứ của tín đồ cuồng nhiệt này vẫn còn là một bí ẩn."
  },
  CollectionHall_57629_LockTip = {
    Text = "Được mở khóa sau khi thức tỉnh \"Pháp Luân Tư\""
  },
  CollectionHall_57629_Title = {Text = "Faros"},
  CollectionHall_57630_Desc = {
    Text = "<Title:Giới thiệu>\nLà con trai của một gia đình quý tộc nhỏ trong một công quốc, dù xuất thân cao quý nhưng cha của cậu không có thành tích gì nổi bật, tương lai của cậu rõ ràng sẽ bình lặng và tầm thường. \nCho đến một buổi tiệc Giáng sinh, cậu được cha dẫn theo để yết kiến Đại Công tước. Trong bữa tiệc, cậu đã chăm sóc và quan tâm đến công chúa cùng tuổi đang bị ốm, điều này khiến Đại Công tước chú ý đặc biệt. Trong câu nói đùa của Đại Công tước, cậu trở thành một thành viên dự bị của đội kỵ sĩ công quốc, bắt đầu tham gia huấn luyện chính thức trong đoàn kỵ sĩ. \nKhi chiến tranh bùng nổ, quân đội yếu ớt của công quốc không thể ngăn cản được cuộc tấn công của kỵ binh địch. Giữa vô số thương vong, Orci là \"kỵ sĩ\" cuối cùng còn đứng vững để bảo vệ công chúa. \nCậu nắm chặt cây giáo vẫn còn quá cao so với mình, mãi mãi chắn trước cửa phòng công chúa."
  },
  CollectionHall_57630_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"ước nguyện của hiệp sĩ\"để mở khóa"
  },
  CollectionHall_57630_Title = {Text = "Ogier"},
  CollectionHall_57631_Desc = {
    Text = "<Title:Giới thiệu>\nMột thiên tài vũ công múa trong ngọn lửa bùng cháy rực rỡ. \nSuốt hàng trăm năm, gia đình cô luôn là vũ công cung đình. Vì vậy, dù vương quốc thay đổi, trường học không còn, cô vẫn chưa bao giờ mất đi linh hồn vũ đạo tao nhã và đẹp đẽ của mình. \nKhi mười tám tuổi, cô gia nhập đoàn ballet địa phương và nhanh chóng trở thành nữ chính xứng đáng. \n\nTuy nhiên, sau khi buổi biểu diễn đầu tiên thành công, Quản lý nhóm nhảy đã đưa Liz vào phòng của một nhà giàu có dưới danh nghĩa \"giới thiệu\". \nThì ra, ballet đã không còn thuần khiết, nền tảng cao quý đã trở thành vốn liếng để các cô gái nâng cao giá trị bản thân. \nVì vậy, cô bỏ trốn, bị bắt trở lại, rồi tiếp tục bỏ trốn… Cuối cùng, sự \"cao thượng\" của cô đã làm phật lòng những người có quyền lực. \nHọ hành hạ Liz cả về thể xác lẫn tinh thần. Cô phải liên tục xoay vòng, liên tục nhảy, thậm chí khi đầu ngón chân nứt toác và máu đen chảy xuống đất cũng không được dừng lại. \n\nCuối cùng, trong một buổi biểu diễn bình thường, khi vũ đạo đạt đến đỉnh cao, ngọn lửa từ dưới chân cô bùng lên lan rộng. \nCô sẽ thiêu rụi mọi bất công và tội ác."
  },
  CollectionHall_57631_LockTip = {
    Text = "Giải khóa sau khi thức tỉnh \"Liz\""
  },
  CollectionHall_57631_Title = {Text = "Liz"},
  CollectionHall_57632_Desc = {
    Text = "<Title:Giới thiệu>\nBị nô dịch, bị nhận nuôi, bị bỏ rơi… Câu chuyện đến đây không khác gì với Hiro của một thế giới khác, nhưng dòng máu giống nhau cuối cùng đã tưới lên những cành cây tàn tạ khác biệt. \nCho đến khi rơi vào ngục tù, địa ngục thực sự mới bắt đầu. Cô kinh hoàng phát hiện ra, những người đồng tộc vốn nên cùng căm hận chủ nô lệ cũng đang căm hận cô, thậm chí sự ác ý đó còn mạnh mẽ hơn. \nMỗi ngày, cô phải chịu đựng sự tra tấn và đau khổ vô tận, món quà của số phận đã hủy diệt tinh thần của cô cả về gốc rễ lẫn lãi suất. \nSự căm hận mà cô nên dành cho chủ nô lệ đã biến thành sự căm hận đối với mọi người, và cô cũng bị mọi người căm ghét, mất đi vị trí tồn tại của mình. \nCho đến khi lợi dụng rỗng rỗng thoát khỏi nhà tù, trong lòng cô chỉ còn lại sự điên rồ, cô nắm lấy sức mạnh đột nhiên có được, không thể chờ đợi để trút bỏ sự oán hận vô tận của mình. \nĐêm đó, cả thành phố đổ mưa máu đỏ, cô đứng trong dòng sông màu đỏ, ngẩng đầu lên cười sảng khoái."
  },
  CollectionHall_57632_LockTip = {
    Text = "Sau khi thức tỉnh \"Máu Liên · Shiro\" sẽ mở khóa"
  },
  CollectionHall_57632_Title = {
    Text = "Helot: Xích Máu"
  },
  CollectionHall_57633_Desc = {
    Text = "<Title:Giới thiệu>\nNgười sáng lập và là chủ tịch Hiệp hội Điêu khắc gia.\nBị viêm tủy sống từ nhỏ, chỉ có thể tự học ở nhà và từ đó nhận thức được sự giới hạn của thân thể con người.\nLớn lên, vào học tại Misaque, nhờ sự hỗ trợ của thầy giáo đã tìm ra hướng nghiên cứu và chữa khỏi bệnh cho bản thân.\nMang trên môi nụ cười ôn hòa, nhưng thực chất lại hoàn toàn vô cảm trước cảm xúc của người khác.\nKhông chú ý đến việc quản lý hình ảnh, mái tóc và bàn làm việc đều bừa bộn.\nTrong ngăn kéo bàn làm việc có một thư mục, bên trong lưu trữ gọn gàng các bài báo mà Crowley đã công bố qua các năm —— đây là việc có tổ chức nhất mà Herbert từng làm."
  },
  CollectionHall_57633_LockTip = {
    Text = "Hoàn thành cuộc điều tra hành động chương 1 \"Bí mật khu Đông\"để mở khóa"
  },
  CollectionHall_57633_Title = {Text = "Hepat"},
  CollectionHall_57634_Desc = {
    Text = "<Title:Tổng quan>\nTrong lòng người Phi-li-tin, ông là vị lãnh đạo dũng mãnh nhất từ trước đến nay.\nVới vóc dáng cao lớn, lực lưỡng, chỉ trong vài năm nắm quyền, ông đã dẫn dắt người Phi-li-tin quét sạch các bộ lạc xung quanh, chưa từng thua trận.\nGiữa những lời ca ngợi và hoa tươi, danh tiếng của ông vang xa. Ông bất chấp sự can ngăn của đồng tộc, phạm phải sai lầm coi thường kẻ thù.\nSai lầm nhỏ khiến quân Phi-li-tin tan rã hoàn toàn. Ông tự nguyện chịu phạt, mang theo người duy nhất trung thành lưu vong trên biển khơi.\nPhẫn uất, không cam lòng... Khoảnh khắc nhục nhã này chắc chắn sẽ được ghi nhớ. Ông sẵn sàng dâng cổ yếu đuối của mình cho \"Phù thủy\", chỉ mong giành lại tất cả những gì thuộc về mình.\nÔng đã bước lên con đường báo thù đẫm máu."
  },
  CollectionHall_57634_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Sự ngã xuống của gã khổng lồ\"để mở khóa"
  },
  CollectionHall_57634_Title = {Text = "Goliath"},
  CollectionHall_57635_Desc = {
    Text = "<Title:Giới thiệu>\nBan đầu là một nô lệ thấp kém, sự thông minh và xinh đẹp từ nhỏ dường như đã định sẵn số phận bi thảm của cô ấy.\nTuy nhiên, may mắn bất ngờ đã khiến cô thay thế cho con gái đã mất của cặp vợ chồng quan chức, trở thành đứa con gái ngoan ngoãn của họ, không ai còn nhìn cô bằng ánh mắt dành cho nô lệ nữa.\nCô rời xa gia đình quá sớm, nhiều năm chung sống đã khiến cô coi người phụ nữ dịu dàng kia là mẹ thật sự, cho đến khi cô tình cờ giúp đỡ những đồng bào cũ, cặp vợ chồng quan chức cực kỳ căm ghét liên minh nô lệ lập tức ruồng bỏ cô.\nSố phận tàn nhẫn đã lộ ra bộ mặt thật không hề thay đổi, cô trở thành tù nhân trong một đêm, nuôi dưỡng lòng thù hận trong nhà tù, trải qua cả thời thanh xuân.\nKhi rỗng rỗng bùng phát trong nhà tù, cô phát hiện chất lỏng màu đen có thể ăn mòn xiềng xích, vậy là nữ thần báo thù cuối cùng đã rời khỏi nhà tù, khi tái xuất, cô dùng đầu của quan chức để đổi lấy sự giải phóng toàn diện cho người Tylor.\nQuãng đời còn lại, cô dành trọn thời gian săn lùng những chủ nô lệ cũ, cho đến khi hóa thành một ngôi mộ vô danh, khắc ghi những bài ca ngợi."
  },
  CollectionHall_57635_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"Hiro\""
  },
  CollectionHall_57635_Title = {Text = "Helot"},
  CollectionHall_57636_Title = {
    Text = "Cư dân bóng tối"
  },
  CollectionHall_57637_Desc = {
    Text = "<Title:Giới thiệu>\nKhác với những người phụ nữ thời đó thường xuất hiện trên chiến trường với vai trò y tá, cô ấy khi còn sống là một chiến binh dũng mãnh và tự hào về điều đó. \nCô ấy tin tưởng rằng đất nước của mình là thanh cao, và việc đất nước chinh phục các vùng đất khác sẽ mang lại tương lai tốt đẹp hơn cho thế giới. \nTrong một trận chiến khốc liệt, cô đã bị thương nặng khi cố gắng cứu một tân binh, sau đó mặc dù sống sót nhưng để lại di chứng không thể đi lại bình thường. Để tiếp tục phục vụ đất nước, cô không rời khỏi quân đội mà rút lui khỏi lực lượng tiền tuyến, chuyển sang làm huấn luyện viên tân binh. \n\nDần dần, những tân binh kiêu ngạo không hài lòng khi giáo viên của họ là một \"người tàn phế\", và trong quân đội bắt đầu có những lời đồn thổi về cô. \nKhi nhận ra điều này, cô đã cố gắng đưa ra ý kiến với tân binh mà cô đã cứu—— giờ đây anh ta đã trở thành thiếu tá. Tuy nhiên, người lính này cũng giống như những người khác, chế giễu chân bị thương của cô. \nBị xúc phạm như vậy khiến cô tức giận đến mức rời khỏi quân đội. \nBên ngoài quân đội và chiến trường, cô cuối cùng đã thấy toàn bộ thế giới: \"anh hùng chiến tranh\" bị đồng bào quay lưng, sự \"giải phóng\" mà cô từng tự hào chỉ mang lại thuộc địa và nỗi khổ cho cư dân địa phương. \nLòng cô bàng hoàng, từ đó cô toàn tâm toàn ý dấn thân vào cuộc giải phóng thực sự, lòng chính nghĩa mạnh mẽ và cảm giác tội lỗi dẫn dắt cô làm những việc thực sự \"đúng đắn\". \nThật đáng tiếc, vết loét ở chân vẫn không lành, và cô thậm chí đã chết trong đau đớn trước khi chuộc tội xong. \nSau khi được thức tỉnh, cô cảm kích ơn nghĩa của Thái Di Sơ, luôn cố gắng giúp bộ lạc Á Lan tiếp tục tồn tại."
  },
  CollectionHall_57637_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"Elva\""
  },
  CollectionHall_57637_Title = {Text = "Alva"},
  CollectionHall_57638_Desc = {
    Text = "<Title:Giới thiệu>\nTừng là siêu tượng La Mã cổ đại, ngôi sao đấu sĩ, và là chiến binh cuối cùng duy nhất.\nSinh ra để thực hiện ý muốn điên cuồng của hoàng đế Caligula, tiêu diệt tất cả kẻ thù chính trị của hắn: chú, anh trai, chị gái...\nHoàng đế trẻ quỳ xuống trước núi xác của người thân, giơ cao hai cánh tay, vừa khóc vừa cười.\nUvhash cảm thấy bối rối: tượng có thể khóc, có thể cười, nhưng không thể cười lớn cùng lúc rơi nước mắt.\nCuối cùng, hoàng đế bạo ngược bị xử tử. Trước khi bị hành, ông đã ôm Uvhash.\nNhưng ông không nói gì.\nVũ khí mất chủ từ đó lang thang không ngừng, cho đến khi gặp gỡ người chủ tiếp theo.\nÔng vẫn cảm thấy bối rối về con người."
  },
  CollectionHall_57638_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Máu và Cát\"để mở khóa"
  },
  CollectionHall_57638_Title = {Text = "Uvhash"},
  CollectionHall_57639_Desc = {
    Text = "<Title:Giới thiệu>\nĐược mệnh danh là \"minh châu sáng nhất của Lentiennam\", mỗi lời nói và hành động của cô đều thu hút sự chú ý của hàng triệu người.\nCô từng ký kết hợp đồng với vị thần tà ác nhất, rồi tái sinh thông qua cái \"chết\" của mình.\nVề thân phận của cô, mọi người có nhiều ý kiến khác nhau.\nDanh nhân, tình nhân, thương nhân, chính trị gia, nữ hoàng dẫn đầu thời trang...\nKhuôn mặt thật của cô đã trở nên mờ nhạt.\nHay có lẽ, sự thay đổi không ngừng này mới chính là bản chất thật của cô?"
  },
  CollectionHall_57639_LockTip = {
    Text = "Hoàn thành ghi chép nhiệm vụ đặc biệt \"Nhật Ký Hoa Hồng\" mở khóa"
  },
  CollectionHall_57639_Title = {Text = "Sorel"},
  CollectionHall_57640_Desc = {
    Text = "<Title:Giới thiệu>\nTừng là tiểu thư quý tộc La Mã cổ đại, cha cô điều hành một trường huấn luyện đấu sĩ. \nNhờ vào sự bảo vệ của những nô lệ đấu sĩ mạnh mẽ xung quanh, cô hoành hành khắp Capua, ngạo mạn và không ai có thể kiềm chế. \nTrớ trêu thay, cuối cùng cô phải van xin tên nô lệ mà mình ghét bỏ nhất giết chết mình. \nHài hước hơn nữa, sau khi trở thành thân thể được đánh thức, cô bất hạnh gặp lại \"nô lệ\"đó tại khuôn viên trường học. \nCó thể đoán được, cảnh tượng này sẽ chẳng hề ấm áp chút nào."
  },
  CollectionHall_57640_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Hậu duệ tái nhợt\"để mở khóa"
  },
  CollectionHall_57640_Title = {Text = "Agrippa"},
  CollectionHall_57641_Desc = {
    Text = "<Title:Giới thiệu>\nTrong truyền thống mê tín của các thủy thủ, vị Thánh nữ hàng hải được tạo ra thực chất chỉ là con gái bị gia đình nghèo khó bán đi, ngày qua ngày bị trói buộc trên cột buồm để cầu chúc cho chuyến đi thuận lợi. \nCuộc đời không có tự do và lựa chọn khiến cô trở nên vô cảm, hầu như không còn bản ngã, chỉ còn lại con tàu là nơi quen thuộc nhất đối với cô. \nCuộc đời yếu đuối nhưng lại mang trong mình những ước nguyện tốt đẹp, vì bị cấm nói chuyện với thủy thủ nên đã quen với việc ngẩn ngơ, chỉ có ước nguyện mãnh liệt nhất và những con chim biển bay lượn bên cột buồm mới có thể thu hút ánh nhìn của cô. \nCuối cùng, do con tàu mà cô cầu chúc bị tổn thất nặng nề bởi sự tan rã, cô đã bị người dân tức giận xử tử bằng cách chết đuối."
  },
  CollectionHall_57641_LockTip = {
    Text = "Sau khi thức tỉnh \"Hilaster\", mở khóa"
  },
  CollectionHall_57641_Title = {Text = "Celeste"},
  CollectionHall_57642_Desc = {
    Text = "<Title:Giới thiệu>\nNgười điêu khắc đến từ Tây Đài.\nXuất thân danh giá, nhưng vì theo đuổi nghệ thuật mà đoạn tuyệt với gia tộc, một mình đến Tây Đài bái sư dưới trướng nhà điêu khắc lừng danh Auguste.\nTài năng khiến người ta tuyệt vọng, nhưng chưa từng lưu lại dấu vết nào trong lịch sử nghệ thuật.\nSau khi trở thành thân thể được đánh thức, có những hiểu biết mới mẻ về điêu khắc và khắc họa, trở thành kiểu \"nghệ sĩ điên rồ\" mà ai cũng biết.\nXem Người Giữ Gìn như nguồn cảm hứng mới, ánh mắt nhìn họ luôn ẩn chứa sự dịu dàng kỳ lạ.\nỒ, đó là ánh mắt thuần khiết, như đang ngắm nghía nguyên liệu yêu thích."
  },
  CollectionHall_57642_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"như khúc ca được tạc nên\"để mở khóa"
  },
  CollectionHall_57642_Title = {Text = "Sanga"},
  CollectionHall_57643_Desc = {
    Text = "<Title:Giới thiệu>\nTừng là một nữ hầu của triều đại Achaimenid cổ xưa. \nVì không được chọn để phục vụ khách tại bữa tiệc trăm năm, cô đã làm chết đuối đồng bạn trong hồ và giả danh thay thế họ. \nCuối cùng, tại buổi tiệc, cô bị biến thành một quái vật màu xanh lá kỳ dị và xấu xí. \nCô sở hữu trí óc linh hoạt và thân hình khéo léo, có thể bưng cùng lúc mười chiếc đĩa len lỏi giữa đám đông. \nQuan niệm về ẩm thực của cô hoàn toàn khác biệt và lạc hậu so với văn hóa ăn uống đương đại. \nThỉnh thoảng, cô cũng tự hỏi liệu bản thân có bị trừng phạt vì tội giết người mà trở thành quái vật hay không. \nNhưng cô tuyệt đối không rút kinh nghiệm, nhanh chóng hành xử như thể chẳng có chuyện gì xảy ra. \nDù sao đi nữa, bài học duy nhất mà người Erivan rút ra từ lịch sử chính là: \nNgười Erivan chưa bao giờ và sẽ không bao giờ học được gì từ lịch sử."
  },
  CollectionHall_57643_LockTip = {
    Text = "Sau khi thức tỉnh \"Gia Lân\", mở khóa"
  },
  CollectionHall_57643_Title = {Text = "Karen"},
  CollectionHall_57644_Desc = {
    Text = "<Title:Giới thiệu>\nNgười quản ngục tại @2, thích hành hạ tù nhân. \nSếp của cô đã hứa sẽ điều cô về Lentiennam sau ba năm, nhưng do hiện tượng ăn mòn ngày càng nghiêm trọng và sự thay đổi địa mạch, cô bị lãng quên ở vùng đất xa xôi này. \nCô gái không nản lòng. Cô kiên trì ở lại đống đổ nát, chờ đợi ngày được gọi trở về. \nCho đến khi tù nhân cuối cùng qua đời, cô trở thành sinh vật duy nhất còn sống trên hòn đảo. \nQuản ngục không có tù nhân, khác gì một tù nhân? \nCô gái từ chối suy nghĩ về điều đó. Cô vẫn tiếp tục chờ đợi ngày được gọi trở về."
  },
  CollectionHall_57644_LockTip = {
    Text = "Sau khi thức tỉnh \"Pandia\" sẽ được mở khóa"
  },
  CollectionHall_57644_Title = {Text = "Pandia"},
  CollectionHall_57645_Title = {
    Text = "Vượt qua vạn cổ"
  },
  CollectionHall_57646_Desc = {
    Text = "<Title:Giới thiệu>\n \"Thú cưng\" mà Francis nuôi dưỡng.\nBan đầu là một cô gái hoạt bát tên \"Lisa\", sau khi được Hiệp hội Điêu khắc gia cải tạo, đã biến đổi thành hình thái méo mó kết hợp giữa người và thú, sau đó được Lily nhận nuôi và tạm thời sống trong viện tâm thần.\nMặc dù mất đi vẻ ngoài và khả năng phát âm của con người, Kume vẫn giữ lại một phần tâm trí của Lisa, có thể truyền đạt ý định của mình thông qua các cử chỉ đơn giản.\nCô ấy đã đưa ra lựa chọn của mình."
  },
  CollectionHall_57646_LockTip = {
    Text = "Hoàn thành cuộc điều tra hành động chương 4 \"Trong im lặng\"để mở khóa"
  },
  CollectionHall_57646_Title = {Text = "Kum"},
  CollectionHall_57647_Desc = {
    Text = "<Title:Giới thiệu>\nDược sĩ có nguồn gốc không rõ ràng, hiện là cố vấn khoa học của Hiệp hội Điêu khắc gia. \nNgười ta nói rằng mẹ của cô là một nông phụ ở vùng quê, và cô được chọn để mang thai đứa con của vị thần rắn vĩ đại. \nKế thừa bệnh bạch tạng và tính cách hiền lành từ mẹ, cô là người bạn duy nhất mà Herbert tin tưởng. \nĐam mê giải phẫu học, hydrocarbon thơm và mùi hương của cây belladonna cháy. \nTác phẩm đồ sộ, tác phẩm tiêu biểu là cuốn \"Dược chí\"được mệnh danh là Kinh Thánh về độc lý học. \nLâu dài ngâm mình trong các loại độc dược, thậm chí hơi thở cũng chứa chất độc mạnh. Tránh xa anh ta —— đây là lời khuyên duy nhất của người viết."
  },
  CollectionHall_57647_LockTip = {
    Text = "Hoàn thành điều tra hành động chương 2 \"Với tên gọi bình tượng nến\"để mở khóa"
  },
  CollectionHall_57647_Title = {Text = "Arubino"},
  CollectionHall_57648_Desc = {
    Text = "<Title:Giới thiệu>\nHọc trò của Walter Phillips, Người Giữ Gìn đầu tiên của Misaque.\nSống lâu năm trong khu vực bí mật dưới lòng đất, chỉ có rất ít người biết đến sự tồn tại của ông.\nSức mạnh tinh thần vượt trội, nhiều năm qua luôn duy trì sự sống bằng các bí pháp đặc biệt, đảm bảo an toàn cho Misaque.\nDự đoán vai trò then chốt của Người Giữ Gìn trong những biến động tương lai, đã cho phép người này tiếp xúc với mình bất kỳ lúc nào.\nĐây vừa là quá trình bồi dưỡng, vừa là sự quan sát."
  },
  CollectionHall_57648_LockTip = {
    Text = "Hoàn thành điều tra hành động chương 2 \"Với tên gọi bình tượng nến\"để mở khóa"
  },
  CollectionHall_57648_Title = {Text = "Alistair"},
  CollectionHall_57649_Desc = {
    Text = "<Title:Giới thiệu>\nMột con người mang dòng máu thưa thớt của người dấn thân vào biển, sinh ra từ gia tộc cổ xưa Orn. Gia tộc này từng gặp biến cố, một số người sẽ dần dần biến thành những quái vật xấu xí sau khi trưởng thành, cuối cùng chết trong đau đớn. Cha anh không chịu nổi sự biến đổi và tự tử sau khi anh sinh ra.\nTừ nhỏ đã lớn lên trong sự ghê tởm của mẹ và sự bắt nạt của bạn bè đồng lứa, tính cách trở nên u ám và cô độc.\nỞ tuổi mười sáu, sau khi đọc được những lời ám chỉ về dòng máu cao quý của gia tộc trong bản thảo mà chú để lại, anh đã có được chiến thắng về tinh thần. Anh suốt ngày mơ mộng rằng mình sẽ sở hữu lực lượng siêu nhiên vào một ngày nào đó, coi sự bắt nạt của mọi người xung quanh như thử thách mà người được chọn phải trải qua, mong chờ cảnh họ sau này sẽ cúi đầu van xin mình.\nKhi trưởng thành, anh trốn vào hang động để đối mặt với sự biến đổi, nhưng bị mắc kẹt ở dạng nửa người nửa cá, bị mẹ la hét đuổi đi và không thể trở về nhà.\nCuối cùng, anh nhảy xuống biển với hy vọng tìm thấy cộng đồng của mình, nhưng đã chết đuối vì mang chưa phát triển hoàn thiện."
  },
  CollectionHall_57649_LockTip = {
    Text = "Sau khi thức tỉnh \"Kẻ khắc sét\", sẽ mở khóa"
  },
  CollectionHall_57649_Title = {Text = "Caecus"},
  CollectionHall_57650_Desc = {
    Text = "<Title:Giới thiệu>\nXuất thân từ gia tộc Cavendish lâu đời nhất của vương quốc, từng là minh châu trong lòng cha mẹ, nhưng không may bị nhiễm rỗng rỗng.\nBị nhốt dưới lòng đất ba năm, cơn khát máu ngày càng trở nên mãnh liệt.\nAnh trai liền ra lệnh cho người tìm kiếm khắp nơi những kẻ lang thang và gái làng chơi ở khu Đông, dùng họ làm \"thức ăn\" hàng ngày cho em gái.\nMột thời gian sau, cả thành phố hoảng loạn, cảnh sát huy động toàn lực, cuối cùng đã bắt giữ hai anh em.\nTừ đó, \"sự kiện ma cà rồng\" gây chấn động thành Lentiennam cũng chính thức khép lại."
  },
  CollectionHall_57650_LockTip = {
    Text = "Sau khi thức tỉnh \"Reia\" sẽ mở khóa"
  },
  CollectionHall_57650_Title = {Text = "Leigh"},
  CollectionHall_57651_Desc = {
    Text = "<Title:Giới thiệu>\nCông nhân dệt may đến từ khu đông Lentiennam.\nBị nhiễm \"rỗng rỗng\", cô bị Hiệp hội Điêu khắc gia bắt cóc và biến thành bình tượng nến.\n「24」vừa là mã thí nghiệm, vừa là số lượng nhân cách ban đầu được chẩn đoán.\nKhi tác giả đang ghi lại nội dung này, số lượng nhân cách của cô vẫn không ngừng tăng lên.\nCho thời gian trôi qua, vương quốc của những 「24」chắc chắn sẽ trở nên phồn thịnh và hùng vĩ."
  },
  CollectionHall_57651_LockTip = {
    Text = "Mở khóa sau khi hoàn thành Đặc vụ ghi chép \"Sự bình yên bị chia cắt\""
  },
  CollectionHall_57651_Title = {Text = "24"},
  CollectionHall_57652_Desc = {
    Text = "<Title:Giới thiệu>\nTrước khi qua đời, cô và cha bị nhiễm rỗng rỗng, luôn chịu đựng chữa trị một cách ngoan ngoãn trong nỗi đau của cả gia đình.\nMẹ cô vì mất đi cả chồng và con gái nên tính tình thay đổi, trong quá trình khám phá ở Elworth đã vô tình tham gia nghi lễ của Hội Giáo đèn lồng, từ đó tình cờ thức tỉnh Lily. Do sự thức tỉnh bất thường, Lily trở thành một con rối vô cảm, chỉ hành động khi nhận lệnh.\nMẹ của cô vì rỗng rỗng mà quên đi hình dáng của Lily, coi Lily vừa được thức tỉnh là quái vật và không ngừng tiến hành thí nghiệm với hy vọng con gái thực sự sẽ hồi sinh.\nCuối cùng, cô theo Người Giữ Gìn đến Misaque, gọi Người Giữ Gìn là mẹ và rất phụ thuộc vào Người Giữ Gìn."
  },
  CollectionHall_57652_LockTip = {
    Text = "Hoàn thành ghi chép đặc vụ \"câu chuyện phép thuật\"để mở khóa"
  },
  CollectionHall_57652_Title = {Text = "Lily"},
  CollectionHall_57653_Desc = {
    Text = "<Title:Giới thiệu>\nBúp bê sáp của Rogers.\n\nGiống như những đứa trẻ ồn ào trong toa tàu, đây là một kẻ được nuông chiều hư hỏng.\nThứ nó dựa vào, chẳng qua là đôi mắt xanh xám — thứ duy nhất \"Ông Bình Tượng Nến\" để lại cho Rogers.\nTừng chạm trán với Sức mạnh không thể kháng cự trong thiên nhiên mật cảnh của \"24\", biến thành George dẹt lép, thành công khơi dậy cơn thịnh nộ của Rogers."
  },
  CollectionHall_57653_LockTip = {
    Text = "Hoàn thành điều tra hành động chương 2 \"Với tên gọi bình tượng nến\"để mở khóa"
  },
  CollectionHall_57653_Title = {Text = "Gióocgiơ"},
  CollectionHall_57654_Desc = {
    Text = "<Title:Giới thiệu>\nCô nhi của Nhà Tế Bần Lillian, cũng là người bạn thân thiết nhất của Jenkin.\nTừng bị Hiệp hội Điêu khắc gia Cải Tạo, lại tận mắt chứng kiến những đứa trẻ mồ côi khác chết thảm, mang trong lòng nỗi tội lỗi khôn nguôi vì đã sống sót và im lặng.\nCuối cùng gieo mình từ tháp chuông xuống, tìm được sự giải thoát hoàn toàn.\nLúc nào cũng ôm khư khư một con gấu bông, cô bé đặt tên cho nó là \"Poppy\".\nThích quà tặng, váy nhỏ xinh và kẹo màu vàng.\nHơi sợ bóng tối, luôn phải ôm \"Poppy\" mới dám ngủ. Nếu bạn có thể hát cho cô bé một bài hát ru, cô bé sẽ mãi mãi biết ơn và yêu quý bạn.\nCũng giống như những gì Jenkin từng làm cho cô bé."
  },
  CollectionHall_57654_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"Ai Jī Sī\""
  },
  CollectionHall_57654_Title = {Text = "Aigis"},
  CollectionHall_57716_Desc = {
    Text = "<Title:Giới thiệu>\nVốn là một nhà nghiên cứu say mê chế tạo người máy tự động, cô đã nhận được từ Daphodel một bộ phận năng lượng lấy Ngân Tâm làm lõi.\nVì người bạn nghiên cứu thèm muốn bộ phận năng lượng, hai người nhiều lần cãi vã, cuối cùng trong cơn giận dữ tranh giành đến mức quyết liệt đã dẫn đến vụ nổ phòng thí nghiệm. Không hiểu vì sao tỉnh dậy trong thân xác người máy, cô kinh hoàng nhận ra rằng: trong cơ thể người máy tự động vốn không có sự sống này, ngoài cô ra, còn có một ý thức khác.\nCô mang theo niềm tin gì để cứu người bạn ra khỏi đống đổ nát đang bốc cháy, và mang theo niềm tin gì để đi đến vùng ngoại ô, đã không còn ai biết nữa. Vị thiên tài cơ khí vô danh này từ đó biến mất khỏi thế gian, chỉ còn lại một bản tin về vụ nổ, những mảnh linh kiện vương vãi khắp nơi, và một Ngân Tâm tàn dư.\nThứ được đánh thức từ đó, rốt cuộc là sự tồn tại như thế nào?"
  },
  CollectionHall_57716_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Xoắn Lõi\" mở khóa"
  },
  CollectionHall_57716_Title = {Text = "Erica"},
  CollectionHall_57717_Desc = {
    Text = "<Title:Giới thiệu>\nSứ giả kiêm đại diện của @2, thường hóa thân thành hình người đi lại trong thế gian.\nMột ác quỷ thuần túy —— không có tương lai, không có niềm tin, không có lý tưởng.\nDùng dục vọng làm mồi, hỗn loạn làm thức ăn, thích lừa dối và quyến rũ con người.\nGiỏi chơi đùa với quy tắc, những người ký hợp đồng với hắn cuối cùng đều mất sạch tất cả.\nNhững luật sư tinh ranh nhất cũng không thể lấy được chút lợi ích nào từ hắn.\nThỉnh thoảng sẽ đóng giả làm trẻ con, nhưng điều này không khiến người ta mất cảnh giác với hắn.\nRốt cuộc, sự đáng sợ của hắn không nằm ở vẻ bề ngoài."
  },
  CollectionHall_57717_LockTip = {
    Text = "Hoàn thành ghi chép nhiệm vụ đặc biệt \"Nhật Ký Hoa Hồng\" mở khóa"
  },
  CollectionHall_57717_Title = {Text = "\"N\""},
  CollectionHall_57718_Desc = {
    Text = "<Title:Giới thiệu>\nBác sĩ tâm thần, chuyên về động kinh, huyền bệnh và các bệnh lo âu, mất ngủ. \nThành thạo việc sử dụng thôi miên để hướng dẫn bệnh nhân bộc bạch tâm tư. \nĐồn rằng, bệnh nhân của cô đều kết thúc cuộc đời bằng những cách tự tử mang tính \"nghệ thuật\" cao, nhưng cô luôn có thể thay đổi danh tính trước khi cảnh sát đến, rồi mở cửa hàng lại. \nNhiều nhân vật nổi tiếng đã từng tìm đến phòng khám của cô, được mô tả là \"người phụ nữ nắm giữ nửa bí mật của thành Lentiennam\". \nRogers từng là khách hàng lâu dài của cô ấy — có lẽ, sự đam mê nghệ thuật bất thường của anh ta cũng không thể tách rời khỏi vị bác sĩ này?"
  },
  CollectionHall_57718_LockTip = {
    Text = "Hoàn thành cuộc điều tra hành động chương 1 \"Bí mật khu Đông\"để mở khóa"
  },
  CollectionHall_57718_Title = {Text = "Clementine"},
  CollectionHall_57719_Desc = {
    Text = "<Title:Giới thiệu>\nNhà điêu khắc sáp theo đuổi sự xuất sắc, giám đốc hiện tại của Bảo tàng Sáp Rogers.\nThuở nhỏ bị xa lánh vì nói lắp, từng bị trêu chọc \"nghèo đến mức chỉ còn lại tiền\".\nNgười cha giữ vị trí cao, người mẹ rối loạn tinh thần, cùng với vụ bắt cóc gây chấn động cả nước...\nDưới tác động của hàng loạt yếu tố bi thương, Rogers đã không phụ sự kỳ vọng khi vượt qua mẹ mình, trở thành kẻ điên hàng đầu tại Scarborough.\nThành viên được các quý cô ưa chuộng nhất trong Hiệp hội Điêu khắc gia, một quý ông với tâm trạng cực kỳ ổn định — miễn là không đề cập đến nghệ thuật."
  },
  CollectionHall_57719_LockTip = {
    Text = "Hoàn thành điều tra hành động chương 2 \"Với tên gọi bình tượng nến\"để mở khóa"
  },
  CollectionHall_57719_Title = {Text = "Rogers"},
  CollectionHall_57720_Desc = {
    Text = "<Title:Giới thiệu>\nMẹ là một kỹ sư cơ khí tài ba, được mọi người yêu mến nhờ kỹ thuật cao và giá cả phải chăng.\nTám tuổi, cha ra khơi và không bao giờ trở lại. Từ đó, cô sống cùng mẹ, quản lý cửa hàng sửa chữa và dùng linh kiện tích góp để thử chế tạo một chiếc xe máy một bánh, mong rằng một ngày nào đó có thể cùng nhau phiêu lưu, hoàn thành ước mơ thời trẻ của mẹ.\nMười ba tuổi, mẹ qua đời vì bệnh tật. Để có thêm linh kiện hoàn thành chiếc xe, cô nhận nhiệm vụ trên tàu với thù lao cao.\nTrong chuyến trở về, tàu bị cuốn vào dòng xoáy lớn do cơn bão. Cô nhường bộ đồ lặn duy nhất cho bạn thân, cầm mặt dây chuyền hình ốc sên mà mẹ để lại và qua đời trong dòng nước đầy rỗng rỗng. Chỉ còn lại xác tàu và bạc tâm trôi dạt theo hải lưu."
  },
  CollectionHall_57720_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"Nốtira\""
  },
  CollectionHall_57720_Title = {Text = "Nautila"},
  CollectionHall_58148_Desc = {
    Text = "<Title:Giới thiệu>\nTiểu công chúa được Chủ Tế Đạo Hải nuôi dưỡng, cũng được gọi là \"Thánh Nữ\".\nTừ nhỏ đã được cưng chiều lớn lên, là một tiểu thư đích thực. Chiếc ô nhỏ trong tay vừa có thể bảo vệ làn da trắng nõn, vừa ngăn cách mọi thứ ô uế và bất tường ra bên ngoài.\nDù nàng thừa biết, bản thân cũng là sản phẩm của một thứ \"bất tường\" nào đó — sự ra đời của nàng không tuân theo quy luật tự nhiên, mà là để trở thành \"mẫu thân\", hạ sinh đứa con trong lời tiên tri.\nBánh ngọt ăn không hết, váy áo tân thời nhất, vô số tôi tớ xoay quanh nàng… Nàng luồn lách giữa thế giới vật chất phồn hoa, khóa chặt nỗi hoang mang bất an trong lòng.\nNỗ lực ấy cuối cùng kết thúc trong thất bại, bởi trái tim tự do không chấp nhận bất kỳ sự thỏa hiệp nào."
  },
  CollectionHall_58148_LockTip = {
    Text = "Sau khi thức tỉnh \"Muphí\", mở khóa"
  },
  CollectionHall_58148_Title = {Text = "Murphy"},
  CollectionHall_59454_Desc = {
    Text = "<Title:Giới thiệu>\nCô bé đến từ một làng chài ven biển, cha mẹ là thủy thủ viễn dương, sống nương tựa vào bà ngoại và ngây thơ tin vào câu chuyện cổ tích mà bà đã bịa ra — gia đình họ là hậu duệ của Atlantis, chỉ cần cô ngoan ngoãn lớn lên, kết bạn với nhiều người, những người bạn sẽ giúp cô trở về quê hương dưới đáy biển. \nSau khi bà mất, một chủ thủy cung đến thu mua cá và đã thuê cô bé hoạt bát làm hướng dẫn viên, mang lại cho cô một tuổi thơ đầy màu sắc. \nKhi hiện tượng rỗng rỗng khiến toàn bộ thủy cung bị ô nhiễm, thủy cung tuyên bố phá sản. Cô thất nghiệp và mang con sứa yêu thích nhất bỏ vào chai, mang về ngôi làng hẻo lánh. Nhưng chẳng bao lâu sau, hiện tượng rỗng rỗng cũng xâm chiếm cô, xâm chiếm cả ngôi làng... \nSau khi được thức tỉnh, ký ức có chút hỗn loạn, cô vẫn kiên định tin rằng mình là \"người dưới đáy biển\" và không ngừng mời bạn bè đến thăm quê hương của mình."
  },
  CollectionHall_59454_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"chư sự như thường\" mở khóa"
  },
  CollectionHall_59454_Title = {Text = "Aurita"},
  CollectionHall_59455_Desc = {
    Text = "<Title:Giới thiệu>\nNgười đàn ông được khen ngợi vì sở hữu \"vận may tuyệt đối\".\nVới năng khiếu như thế này, trở thành một con bạc là điều đương nhiên.\nNhưng đồng thời, anh ta cũng là một thám tử tương đối xuất sắc.\nKhông những thế, anh còn là một kẻ nghèo túng, vì anh luôn tiêu hết số tiền thắng được một cách nhanh nhất.\nMâu thuẫn, phức tạp. Đó là tất cả những gì chúng tôi nhận định về người đàn ông này.\nNữ thần vận mệnh yêu thích anh, người lạ mặt \"N\" yêu thích anh, thậm chí đến cả người chủ quán rượu keo kiệt nhất cũng sẵn lòng cho anh một số ưu đãi.\nMọi người đều yêu thích anh, nhưng anh chưa bao giờ dừng lại vì điều đó, thay vào đó anh lại bắt đầu một cuộc phiêu lưu mới.\nAnh chỉ yêu thích điều chưa biết."
  },
  CollectionHall_59455_LockTip = {
    Text = "Hoàn thành Đặc vụ ghi chép \"Săn bắn vui vẻ!\" mở khóa"
  },
  CollectionHall_59455_Title = {Text = "Ryker"},
  CollectionHall_59456_Desc = {
    Text = "<Title:Giới thiệu>\nSinh ra trong một gia đình quý tộc suy tàn, mặc dù mắc phải bệnh hen suyễn nặng bẩm sinh, nhưng luôn được cha mẹ yêu thương và chăm sóc đầy đủ. \nDo bị bệnh tật hành hạ, cô không thể ra khỏi nhà, thường xuyên nảy sinh ý niệm tự tử, cha mẹ đã cố gắng đưa cô đi du lịch xa để cải thiện tâm trạng, nhưng không may lại khiến cô nhiễm phải rỗng rỗng. \nSau khi trở về quê hương, cha mẹ đầy hối hận đã đưa cô vào viện dưỡng lão, một mặt ra khơi làm ăn để kiếm tiền chữa trị, một mặt đi khắp thế giới tìm cách chữa trị. \nKhi rỗng rỗng ngày càng nghiêm trọng, lòng mong muốn chết của cô cũng càng thêm mãnh liệt, nhưng vì cảm thấy mình đã gây rắc rối cho cha mẹ, cô đã nhẫn nại chịu đựng niềm khao khát được chết và giải thoát để không làm cha mẹ thêm buồn. \nSau khi nhận được tin cha mẹ mất trên đường đến thăm cô do tàu bị chìm, cô không còn gì ràng buộc với trần thế, vào ban đêm lặng lẽ rời khỏi viện dưỡng lão, từng bước từng bước đi về phía biển sâu. \nKhi nước biển ngập qua đỉnh đầu, dòng chất lỏng đen từ vết xâm thực tam giác rơi xuống bị tan rã, cơ thể bị bệnh tật hành hạ lâu ngày đã được giải thoát một cách khó tả —— Đây là lần đầu tiên, cũng là duy nhất, cô có thể thở một cách thoải mái."
  },
