  CollectionHall_62183_Title = {
    Text = "08 Bản giao hưởng cuối cùng"
  },
  CollectionHall_62184_Desc = {
    Text = "<Title:Giới thiệu>\nNhạc trưởng và nhà âm nhạc gia nổi tiếng thế giới. Dù trông còn trẻ tuổi, nhưng các buổi biểu diễn hòa nhạc mà anh chỉ huy đã đi khắp mọi nơi trên thế giới, mỗi buổi diễn đều thu hút đông đảo khán giả. \nLà thiên tài được kính trọng nhất trong giới âm nhạc cổ điển, bất kỳ thông tin cá nhân nào về Hamlin đều không ai biết, điều này đã thu hút sự chú ý của hội nghị thẩm tra. Trong quá trình điều tra lâu dài, họ phát hiện ra rằng địa điểm biểu diễn của Hamlin có sự trùng hợp cao với hành trình hoạt động của Hội Giáo đèn lồng. \nTrước khi họ tìm ra sự thật, sự thật đã tự tìm đến họ —— trong sự kiện Hội Giáo đèn lồng xâm nhập vào Misaque, Hamlin đã đóng một vai trò vô cùng quan trọng. \nChỉ đến lúc này, mọi người mới nhận ra rằng, sân khấu thực sự của vị nhạc trưởng thiên tài này chưa bao giờ nằm trong nhà hát."
  },
  CollectionHall_62184_LockTip = {
    Text = "Hoàn thành Chương 8 của Điều tra Hành động \"Bản giao hưởng cuối cùng\"để mở khóa"
