  },
  CollectionHall_65509_Desc = {
    Text = "<Title:Giới thiệu>\nMột tên côn đồ nhỏ từ khu Đông, cũng là em gái của \"24\". \nCô sở hữu ba kỹ năng độc đáo: trộm gà bắt chó, cãi vã và chuồn ngay khi thấy bất lợi. \nKhông ai có thể moi được chút lợi lộc nào từ cô. \nÀ, đúng rồi. Cô còn có một chú chuột nhỏ tên là \"brun\" luôn bên cạnh. \nBrun trưởng thành, điềm đạm, tạo nên sự bổ sung hoàn hảo cho tính cách của Jenkin. \nVì vậy, dù ở khu Đông Lentiennam thường xuyên xảy ra những vụ việc đau lòng như nấu chuột vì nạn đói rét, Jenkin chưa bao giờ nảy sinh ý nghĩ tương tự."
  },
