  CollectionHall_70839_Desc = {
    Text = "<Title:Giới thiệu>\nNịnh bợ, thực dụng, giả tạo. Viện trưởng của Trại Cứu tế Lily như một diễn viên vụng về, hóa thân thành kẻ ăn xin thấp hèn trên sân khấu danh vọng của Lentiennam.\nBà tất bật ngược xuôi, dùng những lời tâng bốc ngốc nghếch để moi từ kẽ tay giới thượng lưu vài đồng lẻ, nhằm duy trì hoạt động khó khăn của trại cứu tế. Bà nuốt trọn sự chế giễu và mắng nhiếc, dùng giọng hát nhẹ nhàng ru các em nhỏ trong trại vào giấc ngủ.\nLentiennam đã quay lưng lại với họ, nhưng Trại Cứu tế Lily thì không. Sara đã sẵn sàng, sẽ dốc hết sức mình để bảo vệ những đứa trẻ này, giúp chúng sống sót qua làn sương mù và gió lạnh của Lentiennam.\nNhưng lý tưởng khiêm nhường của bà đã thất bại, bà và những đứa trẻ đã chết trong âm mưu của Hiệp hội Điêu khắc gia. Đối với Hiệp hội Điêu khắc gia, bà và những đứa trẻ mà bà yêu quý chỉ là hạt cát nhỏ bé không đáng kể trong tòa lâu đài vĩ đại, vừa thiếu giá trị, vừa thiếu vẻ đẹp. Sự sống của họ không quan trọng, cái chết của họ chẳng đáng nhắc tới.\nBà đã thiêu cháy tất cả những gì mình có. Ngọn lửa nhanh chóng tắt lịm, chỉ còn lại gió của Lentiennam vẫn lạnh buốt xương."
  },
  CollectionHall_70839_LockTip = {
    Text = "Hoàn thành chương một để mở khóa"
  },
  CollectionHall_70839_Title = {Text = "Sarah"},
  CollectionHall_70884_Desc = {
    Text = "<Title:A. F. 185>\nCác đại diện các quốc gia đã ký hiệp định \"Mysidia\" tại Liên bang constante, quyết định hợp tác chung nhằm chống lại Clades, kiềm chế D-ranh giới.\nCùng lúc, các quốc gia đã đạt được sự đồng thuận về chính sách bảo mật liên quan đến sự tồn tại của Clades và sự che giấu D-hiện tượng.\nHiệp định này quy định, viện giữ độc lập, không thuộc về bất kỳ quốc gia nào, các quốc gia có quyền thành lập chi nhánh và quyền giao tiếp trực tiếp với lãnh đạo các quốc gia, và có quyền truy cập thông tin liên quan đến Clades và Phân rã từ các quốc gia.\nMythag chính thức trở thành một tổ chức xuyên quốc gia hoàn toàn trung lập.\n\n<Title:A. F. 186>\nCác cá nhân tham gia sửa đổi và ký kết hiệp định đã thành lập một Ủy ban thường trực tại Mysidia, Ủy ban này có đội hành động riêng để đảm bảo việc thực hiện hiệp định. Cuộc họp kín đã được thành lập, cơ cấu tổ chức cơ bản đã được xác lập.\n\n<Title:A. F. 187>\nCao đẳng Mythag chính thức đổi tên thành Đại học Mythag.\nTrong thời gian tiếp theo, D-hiện tượng xảy ra ngày càng thường xuyên và quy mô cũng ngày càng lớn. Đại học Mythag đứng ở tuyến đầu, trở thành trụ cột của nhân loại trong cuộc chiến chống lại Phân rã."
  },
  CollectionHall_70884_LockTip = {
    Text = "Hoàn thành nhiệm vụ điều tra hành động 9-13 để mở khóa"
  },
  CollectionHall_70885_Desc = {
    Text = "<Title:A.F.75>\nAlistair đã tiên đoán sự xuất hiện của các vết nứt khổng lồ trong lãnh thổ Vương quốc Leo, Waard dẫn dắt đội điều tra đến để ứng phó. Nhiều điều tra viên đã hy sinh trong vụ việc này.\n\n<Title:A.F.77>\nVết nứt không thể đóng lại, nhưng dần dần ổn định. Với sự hợp tác và hỗ trợ của chính phủ, Waard đã xây dựng trụ sở của \"Ánh mắt của sự thật\" trên vết nứt khổng lồ.\nVết nứt chính thức được đánh số L-01, còn được gọi là \"Vũng đen\".\n\n<Title:A.F.88>\n\"Vũng đen\" đã xảy ra biến dị đột ngột và lan rộng ra ngoài, lúc này \"Ánh mắt của sự thật\" đã phải chịu tổn thất nặng nề ở vùng lân cận, Waard cũng chịu thương tích trong quá trình ứng phó.\nDo \"Vũng đen\" không thể đóng lại, Tawil đã chìm vào đó để tự bảo vệ, duy trì sự ổn định tạm thời của nó.\n\n<Title:A.F.90>\nTrụ sở của \"Ánh mắt của sự thật\" được mở rộng, Cao đẳng Mythag được thành lập, Waard là hiệu trưởng đầu tiên.\nTừ đó, mọi người bắt đầu hệ thống hóa việc đào tạo các điều tra viên có đủ sức mạnh linh hồn, để chống lại một cách hiệu quả hơn cuộc khủng hoảng xói mòn ngày càng gia tăng.\n\n<Title:A.F.92>\nVết thương mà Waard phải chịu trong sự kiện \"Vũng đen\" ngày càng trầm trọng và cuối cùng đã dẫn đến cái chết của ông.\nXác của Waard được chôn trong khuôn viên của trường, bia mộ có hình dạng của một chiếc chìa khóa, mở ra truyền thống của khu mộ Đại chìa khóa.\nTiền đề của bạc được làm từ xác của Waard do Alistair tự tay chế tạo thành chìa khóa bạc, được đánh số K-0001, từ đó Alistair trở thành người giữ gìn đầu tiên, hoạt động bên ngoài.\nCùng năm, Kellarkesh đã mất tích trong quá trình điều tra để tìm kiếm phương pháp chữa trị cho Waard ở Lemwahis, từ đó không còn tung tích."
  },
  CollectionHall_70885_LockTip = {
    Text = "Hoàn thành nhiệm vụ điều tra hành động 9-13 để mở khóa"
  },
  CollectionHall_70886_Desc = {
    Text = "<Title:A.F.306>\nHerbert nhận tiền từ Quỹ Greene, với sự trợ giúp của Nhà thờ ánh sáng đền thờ, thành lập Người điêu khắc.\nCùng năm, Búp bê nhập học tại Đại học Mythag. Là một học giả thiên tài, Búp bê ngay khi gia nhập đã tham gia vào nghiên cứu của sinh viên tốt nghiệp và tiến sĩ, và trong những ngày sau đã thúc đẩy sự phát triển của công nghệ mảnh bạc của Mythag một cách đáng kể.\n\n<Title:A.F.307>\nHerbert và Nhà thờ ánh sáng đền thờ tấn công Mythag, cố gắng lấy lại \"Thánh nữ\" của Nhà thờ ánh sáng đã bị hoán đổi.\n\n<Title:A.F.309>\nNhà sống sót sau một sự kiện phân rã, William, tham gia Mythag thông qua sự giới thiệu của điều tra viên Fingol.\n\n<Title:A.F.310>\nỦy ban kiểm tra của Đại học Mythag, trước khi Người điêu khắc có thể tiếp tục lớn mạnh, đã bắt giữ hầu hết các thành viên của họ. Herbert cùng một số thành viên chủ chốt trốn thoát và chuyển sang làm việc ngầm. Sau đó, Herbert tìm đến Rogers, bắt đầu hợp tác.\nCùng năm, Salvador kế nhiệm làm giám mục của Đại thánh đường, Czort giữ chức vụ phó giám đốc.\n\n<Title:A.F.313>\nTheo lệnh của Herbert, Rogers đã quyên góp tiền cho trại mồ côi Lilian, trở thành nhà tài trợ duy nhất cho trại mồ côi.\n\n<Title:A.F.314>\nVụ nổ Akut xảy ra.\nDưới sự phái cử của Alistair, William và Ramona đã đến Akut, tìm thấy @3, người đã mất toàn bộ ký ức trong những di tích sau vụ nổ, và đưa cô trở lại Mythag để đào tạo đặc biệt."
  },
  CollectionHall_70886_LockTip = {
    Text = "Hoàn thành nhiệm vụ điều tra hành động 9-13 để mở khóa"
  },
  CollectionHall_70887_Desc = {
    Text = "<Title:A.F.263>\nFrancis ra đời.\n\n<Title:A.F.289>\nSau khi mất con gái, Francis gia nhập đội nghiên cứu, đến Elworth.\nCùng năm, toàn bộ đội thám hiểm bị diệt vong.\n\n<Title:A.F.290>\nRogers ra đời.\nCùng năm, sau khi vô tình triệu hồi Lily ở Elworth, Francis đến Lai, nhờ sự giúp đỡ của quỹ, ông đã thành lập một bệnh viện tâm thần và dựng lên một không gian tạm ngưng thời gian.\n\n<Title:A.F.292>\nBúp bê ra đời.\n\n<Title:A.F.297>\nHerbert nhập học tại Mythag với tuổi đời 17.\n\n<Title:A.F.298>\nĐèn lồng sử dụng Thánh tử song sinh để thực hiện nghi thức triệu hồi thần. Dexter đã lén lút phá hủy nghi thức bằng cách đưa Ramona, người sắp trở thành thân thể thần linh, ra ngoài, ngăn chặn nghi thức của Đèn lồng.\nNghi thức tuyên bố thất bại. Ramona trở thành con nuôi của Dexter.\n\n<Title:A.F.300>\nRogers bị \"Tượng sáp\" bắt cóc. Sau đó \"Tượng sáp\" chết, Rogers được cứu.\nCùng năm, Salvador được giám mục giáo phận lớn hồi sinh, phục vụ như một linh mục phụ tá trong giáo phận lớn.\n\n<Title:A.F.304>\nCzort nhập học tại Mythag.\n\n<Title:A.F.305>\nSinh viên Herbert của Đại học Mythag đã vi phạm quy định bằng cách chế tạo thể nghiệm, sau khi hành vi bị phơi bày, Herbert đã giết chết người hướng dẫn của mình là Crawley rồi trốn thoát, lúc đó 25 tuổi."
  },
  CollectionHall_70887_LockTip = {
    Text = "Hoàn thành nhiệm vụ điều tra hành động 9-13 để mở khóa"
  },
  CollectionHall_70888_Desc = {
    Text = "<Title:B.F.？？？>\nThảm họa hoành hành toàn cầu đã phá hủy một phần lớn đất đai. Động đất, lũ lụt, rối loạn từ trường, khí hậu bất thường... liên tiếp xảy ra, các thành phố và khu định cư chìm trong nước, những viên đá kiên cố vốn sâu dưới đáy biển giờ trở thành những đỉnh núi mới. Nền văn minh nhân loại phải chịu thiệt hại nặng nề.\n\n<Title:A.F.0>\nĐất đai cũ bị nước biển nhấn chìm, đất đai mới nổi lên mặt nước.\nTrong thế giới hoàn toàn thay đổi diện mạo này, con người đã từ bỏ lịch pháp cũ, mang theo những di tích của nền văn minh để từng bước khó khăn tái thiết, bước vào một kỷ nguyên mới: Hồng Kiến."
  },
  CollectionHall_70888_LockTip = {
    Text = "Hoàn thành nhiệm vụ điều tra hành động 9-13 để mở khóa"
  },
  CollectionHall_70888_Title = {
    Text = "B.F.???—A.F.0"
  },
  CollectionHall_70889_Desc = {
    Text = "<Title:A.F.55>\nKelarkesh chủ động tìm đến Mật hội Chìa Khóa Bạc thông qua các cuộc điều tra của mình và gia nhập thành công, hy vọng mượn sức mạnh của mật hội để giúp nhân loại tái thiết.\nCùng năm đó, Kelarkesh chú ý đến hành động của Ward và Tavi, bắt đầu theo dõi động thái của họ.\n\n<Title:A.F.58>\nKelarkesh chế tạo ra chiếc chìa khóa bạc dùng một lần, trở thành thủ lĩnh mới của mật hội: Thợ Chìa Khóa, và bắt đầu lợi dụng mật hội để âm thầm phổ biến tri thức, giúp nhân loại tái thiết.\nCùng năm đó, Kelarkesh tiếp xúc với Ward và Tavi, cam kết hỗ trợ Ward về tài chính và nhân lực.\n\n<Title:A.F.62>\nAlistair Owens sinh ra trong một gia đình bác sĩ nông thôn bình thường ở ngoại ô Londinium.\n\n<Title:A.F.64>\nSau khi hoàn thành điều tra, Kelarkesh công nhận theo đuổi của Ward. Đối mặt với Ward - người không muốn bị ràng buộc bởi quy tắc mật hội, hai bên đã đạt được mối quan hệ hợp tác bình đẳng dưới đề xuất và chứng kiến của Tavi.\nSau khi nhận được sự hỗ trợ về tài chính và nhân lực từ mật hội, nghiên cứu của Ward tiến thêm một bước, xác nhận đặc điểm của Dung Thực, mối quan hệ giữa Dung Thực và Dị Biến Thể, đồng thời sơ bộ tổng kết các đặc trưng của từng giai đoạn xâm thực Dung Thực.\n\n<Title:A.F.65>\nKelarkesh, Ward, Tavi cùng một số thành viên mật hội đã thành lập đội điều tra viên đầu tiên lấy việc truy tìm Dung Thực và ngăn chặn sự lan rộng của Dung Thực làm sứ mệnh, đặt tên là \"Chân Lý Chi Thị\".\n\n<Title:A.F.70>\nWard một lần nữa tổng kết đặc điểm và quy luật của Dung Thực cùng sự xâm thực của nó, lần đầu ghi nhận đặc trưng khu vực của Dung Thực, và viết thành cuốn \"Sơ Khảo về Dung Thực và Quy Luật Dung Thực\" để các thành viên mới gia nhập đội điều tra tham khảo sử dụng.\n\n<Title:A.F.72>\nWard cứu Alistair từ một gia đình bị hủy diệt bởi Dung Thực, nhận cậu làm học trò.\nCùng năm đó, quy mô của \"Chân Lý Chi Thị\" dưới quyền Ward dần mở rộng, thu hút sự chú ý của chính quyền."
  },
  CollectionHall_70889_LockTip = {
    Text = "Hoàn thành nhiệm vụ điều tra hành động 9-13 để mở khóa"
  },
  CollectionHall_70890_Desc = {
    Text = "<Title:A.F.30>\nWard Phillips sinh ra trong một gia đình thương nhân ở thành phố cổ Shalom, miền đông Cộng hòa Aglo.\n\n<Title:A.F.38>\nKellarkesh ra đời. Ngay sau khi sinh, cha mẹ cậu đã qua đời, cậu sống nương tựa vào chị gái và vật lộn để sinh tồn.\n\n<Title:A.F.48>\nWard từ nhỏ đã bộc lộ tài năng về hóa học và vật lý, vào tuổi 18 đã đậu vào khoa hóa học tại Đại học Mosvetuse, trở thành học trò của nhà hóa học nổi tiếng Nathaniel Milton.\n\n<Title:A.F.50>\nÔng nội của Ward, linh mục Roger Phillips già, qua đời, sau đó cha của Ward cũng mất tích. Ward đến điều tra tại nhà tổ, và theo bước chân của cha mình đến Vương quốc Leo, nơi cậu phát hiện ra một bí mật gia đình đã ẩn giấu từ lâu - một công thức bí ẩn được chiếm đoạt từ kẻ thờ phụng (hội chìa khóa bạc) trong thời kỳ săn phù thủy.\nCông thức cổ xưa được ghi chép trên một cuộn da cừu, trong đó có nhiều phần bị hư hại, Ward sau nhiều năm thí nghiệm đã khôi phục lại nó một cách tạm thời.\n\n<Title:A.F.53>\nDựa trên công thức khôi phục, Ward đã thành công tạo ra chiếc chìa khóa bạc đầu tiên. Do khiếm khuyết trong công thức, chiếc chìa khóa bạc này chỉ có thể sử dụng một lần rồi hỏng, không thể sử dụng lại.\nDù sao, nhờ chiếc chìa khóa bạc một lần, Ward đã gặp Đại diện của Thể trí tuệ, Tawil, và từ Tawil biết được rằng thế giới sắp phải đối mặt với \"thảm họa đen tối\".\nQuyết tâm ngăn chặn thảm họa, Ward đã đạt được sự thống nhất với Tawil, liên kết với Tawil, nhận được phương pháp sản xuất thể thức tỉnh và công thức chìa khóa bạc hoàn chỉnh.\nTrong thời gian tiếp theo, Ward đã đi khắp nơi, nghiên cứu phân rã và khe nứt và đặt tên cho chúng, cố gắng tìm ra cách phòng ngừa phân rã."
  },
  CollectionHall_70890_LockTip = {
    Text = "Hoàn thành nhiệm vụ điều tra hành động 9-13 để mở khóa"
  },
  CollectionHall_70891_Desc = {
    Text = "Sau một năm học và huấn luyện tiền khoa, @3 chính thức kế nhiệm Người Giữ Gìn, bắt đầu dẫn dắt thân thể được đánh thức và các lực lượng khác trong trường điều tra các sự kiện liên quan đến sự rỗng. \nCùng năm đó, Hội Giáo đèn lồng liên kết với nội quỷ trong trường Misaque tái xâm nhập Misaque, gây ra biến động hồ đen, mở cánh cửa tận cùng, thu hút ánh mắt của ý chí vô thượng. \nKhi cà đa sác sắp bị sự rỗng nuốt chửng, @3 hấp thụ quyền năng của ba chất thể, đối mặt với ánh nhìn của ý chí vô thượng bên trong cánh cửa. \nCuối cùng, ý chí vô thượng lại chìm vào giấc ngủ, cà đa sác được cứu. \n@3 hy sinh. \nVì tất cả các bản ghi liên quan sẽ bị sự rỗng xóa sổ, không thể bảo lưu, Misaque quyết định phá lệ niêm phong chìa khóa bạc mà @3 đã sử dụng khi còn sống, lưu trữ tại bảo tàng lịch sử trường, để tưởng nhớ công lao của @3. \nTên của %hisorher% không ai biết, nhưng số hiệu K-0617 sẽ tồn tại mãi mãi."
  },
