  CollectionHall_89351_Title = {
    Text = "Triệu triệu tiếng côn trùng kêu"
  },
  CollectionHall_89352_Desc = {
    Text = "Trong những khoảnh khắc quyết định của cuộc đời, dường như luôn có những hạt mưa bụi bặm đi cùng.\nChào tạm biệt những hồi ức trong cơn mưa bụi đó, hãy giữ chặt những rượu đắng đã được chưng cất kỹ càng, nắm chặt chìa khóa bạc trong tay, bắt đầu hành trình mới.\nMong rằng chìa khóa bạc dẫn dắt chúng ta."
