  CollectionHall_89353_Desc = {
    Text = "Ánh nắng ấm áp của mùa xuân, cung điện mộng mơ, váy lễ hội xoay tròn, dạ tiệc đầy tiếng cười, và nàng công chúa đẹp đẽ cùng dịu dàng.\nĐó là tất cả những gì mà hiệp sĩ muốn bảo vệ."
