  CollectionHall_89362_Desc = {
    Text = "Chú chó trung thành và dũng cảm sẽ tự lập kế hoạch huấn luyện, và chỉ cần một cái nhìn động viên từ bạn là đủ để xoa dịu mọi nỗi buồn và mệt mỏi."
