  },
  CollectionHall_89363_Title = {
    Text = "Vinh quang không hổ thẹn"
  },
  CollectionHall_89364_Desc = {
    Text = "Một chiếc thuyền ra khơi, sẽ đưa mọi người đến đâu nhỉ? \nNữ thần thuần khiết, đang ngồi trên cột buồm cao hát. \nTham lam, cuồng vọng, đấu tranh và phản bội, nàng không hề để tâm, nàng không hát về sự lật đổ của số phận, nàng chỉ hát về sự trở về của vị thuyền trưởng già"
