  CollectionHall_89367_Desc = {
    Text = "Thủy triều dâng lên, tiếng rít vang vọng, những kỷ niệm đau đớn ùa về, xé nát tinh thần cô gái. Nước mắt đen chảy từ khóe mắt, là tiếng kêu cứu im lặng của cô."
