  CollectionHall_89369_Desc = {
    Text = "Ánh trăng đổ xuống từ bầu trời đêm, những con sóng thì thầm những lời vĩnh cửu, những chiếc thuyền vĩ đại lốm đốm từ từ tiến lên.\nBạn đứng trên boong tàu mù sương, tự mình dệt nên một khúc nhạc đêm sâu sắc."
