  CollectionHall_89373_Desc = {
    Text = "Thời gian đang gào thét, thời gian đang gầm thét, thời gian đang truy đuổi những kẻ ba lần trở thành con mồi. Đừng cố gắng chạy trốn, vì kết quả đã được định sẵn."
