  CollectionHall_89374_Desc = {
    Text = "Cuộc xét xử sẽ không dừng lại, xét xử phải thực hiện.\nQuái vật sinh ra từ gương, dùng máu thịt của chính mình làm ngọn đèn, truyền ngọn lửa thanh tẩy khắp thế giới."
