  CollectionHall_89375_Desc = {
    Text = "Khi quan điểm và ý chí va chạm, con người thường chỉ tin tưởng vào quy tắc của riêng mình.\nĐối với hầu hết mọi người, điều mà họ tin tưởng chính là công lý duy nhất."
