  CollectionHall_89377_Desc = {
    Text = "Với tư cách là một quý cô, đương nhiên phải giữ gìn vẻ ngoài thanh lịch mọi lúc mọi nơi! \nĐương nhiên, ý tôi là, bất cứ việc gì quý cô làm, việc đó đều là thanh lịch!"
