  CollectionHall_89379_Desc = {
    Text = "Sau cánh cửa mà cả thời gian cũng bị giam giữ, là sự lựa chọn cuối cùng của một người mẹ để bảo vệ cô con gái yêu quý của mình. \n \"Tôi yêu bạn, Lily.\""
