  CollectionHall_89382_Desc = {
    Text = "Lúc đó, mẹ lật từng trang sách, kể cho đứa trẻ những câu chuyện cổ tích.\nNhiệt độ buổi chiều chảy qua thời gian, từ từ lan tỏa trong không gian hẹp này."
