  CollectionHall_89382_Title = {
    Text = "Câu chuyện buổi chiều"
  },
  CollectionHall_89383_Desc = {
    Text = "Làm sao để lừa dối bản thân, để tưởng tượng rằng sự sống vẫn tiếp tục trong những tàn tro đã tắt.\nCô ấy chìm trong chiếc kén đen tối và chất lỏng nhớt màu đỏ, ngắm nhìn bầu trời xa xăm trong giấc mơ.\n \"Thật lạnh lẽo, nhưng sự ấm áp trước đây của tôi đâu rồi?\""
  },
  CollectionHall_89383_LockTip = {
