  CollectionHall_89383_Title = {
    Text = "Hư cấu của tro tàn"
  },
  CollectionHall_89384_Desc = {
    Text = "Hãy hát lên, hãy hát lên!\nHãy để những cơ khí tan chảy vang lên khắp vũ trụ, ca ngợi sự kết thúc được gọi là bóng tối vĩnh cửu!"
