  CollectionHall_89384_Title = {
    Text = "Hòa ca diệt vong"
  },
  CollectionHall_89385_Desc = {
    Text = "Máu thịt bay bổng, lưỡi dao múa loạn, quái vật hát vang bằng những ngôn ngữ không thể hiểu nổi. Trong bộ não điên cuồng chỉ còn lại một suy nghĩ - nắm bắt cô ấy, bằng mọi giá, nắm bắt cô ấy."
  },
  CollectionHall_89385_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·khó khăn 3-10 mở khóa"
  },
  CollectionHall_89385_Title = {
    Text = "Ám ảnh điên cuồng"
  },
  CollectionHall_89386_Desc = {
    Text = "Nhìn kìa, ánh trăng đỏ thẫm đã lên, tất cả tội nhân sẽ bị thanh tẩy."
