    Text = "Mặt Trăng Máu"
  },
  CollectionHall_89387_Desc = {
    Text = "Lạy Cha từ bi, con sẽ thiêu đốt xương thịt của mình, thiêu rụi linh hồn của mình, làm củi để thắp sáng \"Ngọn lửa nhợt nhạt\".\nXin hãy ban mọi khổ đau lên người con, để những đứa trẻ lạc lối có thể tiếp tục bước trên con đường phía trước."
  },
  CollectionHall_89387_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Màu máu\" khó khăn"
  },
  CollectionHall_89387_Title = {
    Text = "Ân điển thần linh"
  },
  CollectionHall_89388_Desc = {
    Text = "Đèn lồng sẽ xua đuổi mọi tội ác.\nBạn cần thành tâm sám hối, đổ máu, mới có thể tẩy chay tội ác, thăng thiên."
  },
  CollectionHall_89388_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Màu máu\""
  },
  CollectionHall_89388_Title = {
    Text = "Ánh sáng đèn không bao giờ tắt"
  },
  CollectionHall_89389_Desc = {
    Text = "Bạn đã hứa với tôi, các bạn đã hứa với tôi.\nNếu tôi không thể cứu Lemuria, vậy thì cùng nhau, để đi chôn cùng nó!"
  },
  CollectionHall_89389_LockTip = {
