  CollectionHall_89403_Desc = {
    Text = "Ánh sáng xua tan bóng tối, chiếu sáng công bằng mọi đứa trẻ.\nNó nhợt nhạt, điểm yếu, nhưng vô cùng ấm áp, tràn đầy sức mạnh.\nMong rằng ánh sáng yếu ớt này có thể xóa bỏ nỗi khổ đau của bạn, xoa dịu tâm hồn bạn, con của tôi."
