  CollectionHall_89405_Desc = {
    Text = "Oản, tôi đã theo lời tiên tri chờ đợi hàng vạn năm, nhưng tương lai tại sao vẫn xa vời? \nTôi lẽ ra nên tiếp tục cầu nguyện, nhưng xin tha lỗi cho tôi, tôi không thể chờ đợi thêm nữa."
