  CollectionHall_89406_Desc = {
    Text = "Tên trộm hèn hạ đã đánh cắp sức mạnh của nhà vua, cố gắng cản trở nghi thức vĩ đại.\nĐồ giả mạo vô lễ, phải trả giá bằng cái chết!"
