  CollectionHall_89411_Desc = {
    Text = "Bạn chìm xuống vực thẳm, từ túi của bạn, cô ấy phát ra tin nhắn cuối cùng. Vì vậy, trong bóng tối vô tận, bạn thấy một tia sáng."
