  CollectionHall_89412_Desc = {
    Text = "Người từng đứng trước mặt bạn, nay đã ở sau lưng bạn.\nBạn luôn tin rằng, sau khi mình hết sức chạy, đang chờ đợi ở tận cùng của thời không, chắc chắn là đôi tay quen thuộc và ấm áp đó."
