  CollectionHall_89414_Desc = {
    Text = "Anh hùng và công chúa chạy trong bóng đêm, cát dưới chân kể lại niềm vui của sự sống. Trái tim đóng kín ngàn năm, cũng bắt đầu đập chậm rãi theo sự lướt qua của sao băng."
