  CollectionHall_89415_Desc = {
    Text = "Không cần lời nói, khi bạn đến đây, bạn sẽ nhận được sự giúp đỡ chân thành nhất.\nNgười dẫn đường mỉm cười đã đưa tay ra với bạn, cô ấy sẽ dẫn bạn vào sâu tha hồ tâm linh mà chính bạn cũng chưa từng thấy rõ."
