  CollectionHall_89416_Title = {
    Text = "Bình minh của Cambrian"
  },
  CollectionHall_89417_Desc = {
    Text = "Đường đi của thiên tài luôn có những khúc quanh co, uốn khúc và khác biệt, nhưng đó chính là điều làm cô ấy dễ thương, phải không?"
