  },
  CollectionHall_89419_Title = {
    Text = "Thủy triều ảo diệu dâng trào"
  },
  CollectionHall_89420_Desc = {
    Text = "Vương quyền tối cao, vương quyền vô biên, vua ngồi trên vinh quang, cô đơn nhìn xuống vương quốc của mình."
  },
  CollectionHall_89420_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 5-15 mở khóa"
  },
  CollectionHall_89420_Title = {
    Text = "Ngủ yên trong Vực thẳm của Vương"
  },
  CollectionHall_89706_Desc = {
    Text = "<Title:Tổng quan>\nCô nhi, nguồn gốc không rõ, từ khi có trí nhớ đã được thủy thủ nuôi dưỡng, sống trên tàu.\nVì những trải nghiệm như vậy, Képsantis từ nhỏ đã tràn đầy khao khát và tò mò về đại dương.\nKhi lớn lên, cô đã tự nhiên chọn một nghề liên quan đến đại dương và tàu bè - hoa tiêu.\nTừ đó, cô gái yêu đại dương mãi mãi trôi dạt trên biển, dưới sự đồng hành của những vì sao, dẫn đường cho các con tàu.\nCô \"giáng sinh\" trong biển cả, trên tàu.\nCô cũng không sợ \"chết\" trong biển cả, trên tàu.\nĐó chính là cuộc sống của cô."
  },
  CollectionHall_89706_LockTip = {
    Text = "Thức tỉnh \"Kep Sanga\" sau khi mở khóa"
  },
  CollectionHall_89706_Title = {Text = "Corposant"},
  CollectionHall_89968_Desc = {
    Text = "Giết chóc, hận thù, điên loạn và đau khổ, chiến trường không thiếu những điều này. Khi bạn đặt cược tính mạng lên bàn chơi bài của quái vật, bạn cũng nên nghĩ về một cơn xoáy đỏ thẫm thế nào sẽ xảy ra."
  },
  CollectionHall_89968_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Máu và Cát\""
  },
  CollectionHall_89968_Title = {
    Text = "Vòng xoáy đỏ thẫm"
  },
  CollectionHall_89969_Desc = {
    Text = "Trong truyền thuyết, nhà hàng hải sau khi chết sẽ biến thành một ánh sáng xanh trắng trên cột buồm, tiếp tục chỉ hướng cho tàu thuyền. \nVậy khi cô ấy đốt cháy sinh mạng của mình ở đỉnh cột buồm, liệu có thấy được rằng con đường hy vọng trở về?"
  },
  CollectionHall_89969_LockTip = {
    Text = "Hoàn thành cuộc phiêu lưu nhận thức \"Ngọn hải đăng cuối cùng\""
  },
  CollectionHall_89969_Title = {
    Text = "Lửa Thánh Elmo"
  },
  CollectionHall_89970_Desc = {
    Text = "Trong số phận sinh ra của cô đầy thù hận, giết chóc và cuộc chiến không ngừng.\nKhi cô từ bỏ tất cả những ảo ảnh mềm mại, ấm áp, chọn cầm dao và súng, khúc khải hoàn đã vang lên cho số phận của cô.\nCô được định sẵn trở thành một chiến binh, rửa sạch thù hận bằng máu của kẻ thù, và sống một cuộc đời có thể không vinh quang, nhưng không sợ hãi và không hối tiếc."
  },
  CollectionHall_89970_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Người trở về của Elworth\""
  },
  CollectionHall_89970_Title = {
    Text = "Làm sạch bằng máu thù"
  },
  CollectionHall_89971_Desc = {
    Text = "Dưới ánh hoàng hôn đỏ máu, là cát vàng đẫm máu.\nChiến binh mạnh mẽ nhất đứng giữa chiến trường sắp chìm vào bóng đêm, hồi tưởng về ngọn lửa và vinh quang vàng son của ngày xưa.\nVô số tiếng kêu thét của kền kền bay lên, che phủ ánh sáng cuối cùng của mặt trời. Dưới cuộc Thập tự chinh vĩ đại, là những linh hồn có mặt trong sa mạc, để cùng anh chung sống mồ chôn."
  },
  CollectionHall_89971_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Máu và Cát\" khó khăn"
  },
  CollectionHall_89971_Title = {
    Text = "Mặt trời đỏ rực tắm mình trong máu"
  },
  CollectionHall_89972_Desc = {
    Text = "Nếu thế giới này đã rơi vào bóng tối, thì tôi sẽ trở thành ngọn đuốc cuối cùng.\nNếu giữa đám đông không còn chính nghĩa, thì tôi sẽ lên tiếng vì những người yếu đuối nhất."
  },
  CollectionHall_89972_LockTip = {
    Text = "Hoàn thành cuộc phiêu lưu nhận thức \"Ngọn hải đăng cuối cùng\""
  },
  CollectionHall_89972_Title = {
    Text = "Ngọn lửa bão đêm dài"
  },
  CollectionHall_89973_Desc = {
    Text = "Đó là cuộc chiến đấu định mệnh của cô, đó là chiến trường mà cô phải tới.\nCô đã vứt bỏ tất cả sự nhút nhát, do dự, sợ hãi theo dòng thời gian.\nCô không hối tiếc, chỉ vì cô đã hiểu sự thật của cuộc chiến trong đời này.\nCô không đơn độc, thanh kiếm trong tay phản chiếu chính là gương mặt cuồng ngạo của một phiên bản khác của chính mình."
  },
  CollectionHall_89973_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Người trở về của Elworth\" khó khăn"
  },
  CollectionHall_89973_Title = {Text = "Hỏi núi"},
  CollectionHall_89974_Desc = {
    Text = "Hey yo, nặng chiếc neo, nâng cánh buồm lên, tháo dây neo cuối cùng.\nNhà hàng hải của chúng ta đã leo lên cột buồm, lá cờ rực rỡ đã được treo cao. \nKhởi hành, khởi hành, theo hướng mà cô ấy chỉ đường, chúng ta sẽ ra khơi!"
  },
  CollectionHall_89974_LockTip = {
    Text = "Hoàn thành cuộc phiêu lưu nhận thức \"Ngọn hải đăng cuối cùng\""
  },
  CollectionHall_89974_Title = {
    Text = "Nhật ký dẫn đường"
  },
  CollectionHall_89975_Desc = {
    Text = "Mỗi lần ra khơi, cô đều chuẩn bị sẵn di thư mới.\nBài hát truyền đời như bài ru trong mơ, nhẹ nhàng ôm lấy linh hồn cô.\nCờ sắc màu bay trong gió, thân thể cô có thể phân rã, thối rữa, chìm vào đại dương sâu thẳm, nhưng linh hồn cô nhất định sẽ đứng trên con thuyền, phát ra ánh sáng vĩnh cửu hướng tới vì sao và đại dương."
  },
  CollectionHall_89975_LockTip = {
    Text = "Hoàn thành cuộc phiêu lưu nhận thức \"Ngọn hải đăng cuối cùng\""
  },
  CollectionHall_89975_Title = {
    Text = "Bài ca của người dẫn đường"
  },
  CollectionHall_89976_Desc = {
    Text = "Trong sa mạc Cuxi, gió cát là một vị khách không bao giờ ngừng lại, những hạt cát bay trong không khí sẽ tràn vào miệng mũi của người sống và sẽ chôn vùi những xác chết vô danh.\nChỉ có những con thú khát máu mới sẽ tìm kiếm trong gió, mùi vị của tiệc tùng ngọt ngào đó."
  },
  CollectionHall_89976_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Máu và Cát\""
  },
  CollectionHall_89976_Title = {
    Text = "Cát vàng và thú dữ"
  },
  CollectionHall_89977_Desc = {
    Text = "Mặt trời trong sa mạc không giống như ở nơi khác, nó nhợt nhạt, chói mắt và khắc nghiệt, chưa từng có một mặt dịu dàng nào. Những con thú không thể tưởng tượng ra mùa xuân mà bạn miêu tả, vậy thì hãy để bạn thay nó đi xem, cái mà được gọi là mặt trời thực sự ấy."
  },
  CollectionHall_89977_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Máu và Cát\""
  },
  CollectionHall_89977_Title = {
    Text = "Máu và cát không còn nữa"
  },
  CollectionHall_89978_Desc = {
    Text = "Những trận tuyết rơi không ngừng, mù mịt, phủ trắng tóc của những chiến binh.\nKý ức cuộc đời của cô bắt đầu chảy ra vào lúc này, cô từng bước qua những chỗ ảm đạm của lòng người, hướng tới những ngọn núi đồ sộ.\nPhản bội, bỏ rơi và bảo vệ, tất cả nỗi đau và sự phẫn nộ, chỉ là một trận chiến rồi lại một trận chiến. Giữa con người, với núi, và với chính mình.\nCô nhìn về phía người dẫn dắt mình, nhìn về phía những đồng đội mới vừa quen vừa lạ, nở một nụ cười chưa thật sự thành thạo.\nCô có thể một ngày nào đó sẽ trở về chiến thắng, hoặc có thể sẽ mãi mãi ngã xuống trên trận địa, nhưng ngay cả khi lên thiên đường hay rơi vào địa ngục, cô cũng sẽ không buông bỏ thanh đao trong tay.\nĐể không mất đi tất cả này, lần này cô chọn nâng cao thanh kiếm mang tên bảo vệ, một mình hướng tới trận địa của mình."
  },
  CollectionHall_89978_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Người trở về của Elworth\""
  },
  CollectionHall_89978_Title = {
    Text = "Để không mất đi ngày mai"
  },
  CollectionHall_89998_LockTip = {
    Text = "Cần hoàn thành sự kiện có giới hạn thời gian \"Nhòm đến bóng tối của Vùng đất thần thánh: Biến động thủy triều\" trong bất kỳ cấp độ nào"
  },
  CollectionHall_89998_Title = {
    Text = "Nhòm ngó về bóng tối của Vùng đất thần thánh: Đợt sóng biển bất thường"
  },
  CollectionHall_89999_LockTip = {
    Text = "Cần hoàn thành một cấp độ trong sự kiện giới hạn thời gian \"Tù nhân đối xứng: Lướt qua bầu trời\""
  },
  CollectionHall_89999_Title = {
    Text = "Tù nhân đối xứng: Lướt qua bầu trời"
  },
  CollectionHall_90245_LockTip = {
    Text = "Vượt qua Thế giới mộng mơ \"Bên kia đường chân trời · Trên\" mở khóa màn đầu tiên"
  },
  CollectionHall_90245_Title = {
    Text = "Khi chim chưa rơi xuống"
  },
  CollectionHall_90415_Title = {
    Text = "Bên kia chân trời·Trên"
  },
  CollectionHall_90416_Desc = {
    Text = "<Title:Tóm tắt>\nNhà thờ ánh sáng đền thờ đã nuôi dưỡng một loạt thí nghiệm để phục vụ nghi lễ hạ thần, may mắn sinh ra như cặp song sinh nên thoát khỏi số phận bị vứt bỏ vào đống rác.\nCùng với em trai Polydeuces, từ nhỏ đã được tôn sùng là Thánh Tử, nhận quy luật nghiêm ngặt, cả ngày được rót vào nghe thần học về người mang đèn, thông tin duy nhất về thế giới bên ngoài là một cuốn bản thảo tay dày công tôn kính cung cấp bởi tín đồ.\nThuở niên thiếu, sau khi em trai bị nhà thờ thực hiện nghi lễ cải tạo tàn ác, hai anh em quyết định trốn thoát tìm kiếm tự do nhưng nhanh chóng bị bắt lại.\nAnh bị ngâm dưới nước tan chảy của \"Hồ tội lỗi\" để chữa lành vết thương bằng \"Phương pháp tội lỗi\", trải qua sự tra tấn dai dẳng.\nCuối cùng vì thế bị Juliette và những người khác lãng quên, bao gồm cả Polydeuces, quan hệ với em trai trở nên căng thẳng.\nTừ đó, anh nằm im, tỏ ra tuân thủ nhà thờ trên bề mặt, nhưng không bao giờ từ bỏ quyết tâm trốn thoát cùng em trai một lần nữa, luôn chờ đợi cơ hội giành lại tự do."
  },
  CollectionHall_90416_LockTip = {
    Text = "Mở khóa sau khi thức tỉnh \"Castor\""
  },
  CollectionHall_90416_Title = {Text = "Castor"},
  CollectionHall_94552_LockTip = {
    Text = "Cần vượt qua một cấp độ trong sự kiện giới hạn thời gian \"Đại Chinh Phục: Cuộc Săn Thần Thánh\""
  },
  CollectionHall_94552_Title = {
    Text = "Cuộc chinh phục vĩ đại: Săn bắn thiêng liêng"
  },
  CollectionHall_94553_Desc = {
    Text = "<Title:Tóm tắt>\nGiáo hội Đèn lồng đã nuôi dưỡng những sản phẩm thí nghiệm sinh đôi nhân tạo cho nghi thức triệu hồi thần linh, ngay khi bị xác định là thí nghiệm thất bại và sắp bị vứt bỏ một cách tàn nhẫn, đã chia tách từ máu thịt của người anh trai. \nSự gắn bó để sinh tồn đó không phải là may mắn, mà là biến số phận của cả hai từ bi kịch ngắn ngủi thành một bi kịch dài hơn. \nCó lẽ do bí ẩn của sự song sinh, anh ta và người anh trai có màu da, tính cách hoàn toàn trái ngược. Là người sống động hơn trong cặp sinh đôi, luôn thực hiện những hành vi nghịch ngợm trái ngược với quy tắc, giống như một cậu bé tinh nghịch trong một gia đình bình thường - cho đến khi được chọn làm vật chứa cho thần thánh, bắt đầu tham gia vào nghi thức \"Cải tạo thánh\"đau đớn và đẫm máu định kỳ. \nKhông thể chịu đựng số phận đầy đau đớn, dưới sự cầu xin và âm thầm hoạch định của anh ta, hai anh em đã lên kế hoạch bằng mật mã trong nhiều năm, cuối cùng vượt qua nhiều chướng ngại và trốn thoát thành công. \nTuy nhiên, họ không thể vui mừng lâu thì đã bị quân truy đuổi của giáo hội bắt lại, dưới lệnh của Liệt Étte, đã gỡ bỏ đôi cánh tự do của anh ta, và thực hiện việc tẩy não cực đoan, cuối cùng khiến anh ta hoàn toàn quên đi người anh trai, hưởng thụ cảm giác được tôn sùng như một Thánh Tử. \nCho đến khi trong lần trốn thoát thứ hai, do cái chết của người anh trai và tác dụng của nghi thức triệu hồi thần linh, anh đã lấy lại ký ức, bị căm thù và giận dữ thổi bùng trái tim \"Thánh\", biến việc chống lại giáo hội Đèn lồng trở thành hướng đi mới trong cuộc đời."
  },
  CollectionHall_94553_LockTip = {
    Text = "Thực hiện vượt ải thế giới mộng mơ\"Ngoài bầu trời\" mở khóa"
  },
  CollectionHall_94553_Title = {Text = "Pollux"},
  CollectionHall_95436_Desc = {
    Text = "Bay lên, bay lên, những chú chim dùng đôi cánh của mình chống lại sức nặng của trọng lực, không ngừng leo cao, leo cao, vượt qua từng dòng không khí hỗn loạn và xoáy nước, bay đến những nơi ngày càng cao hơn.\nTuy nhiên, nó không biết rằng, chân nó đã buộc chặt một sợi dây vô hình, có lẽ nó chưa bao giờ thực sự trở thành một chú chim, dù có bay lên cũng chỉ là một con diều tội nghiệp.\nBây giờ, dây diều đã chặt lại."
  },
  CollectionHall_95436_LockTip = {
    Text = "Hoàn thành \"Bên kia bầu trời\" trong thế giới mộng mơ"
  },
  CollectionHall_95436_Title = {Text = "Diều"},
  CollectionHall_95437_Desc = {
    Text = "Bạn nhìn thấy gương mặt ấy, gương mặt dịu dàng, yên bình, xinh đẹp.\nNó nhanh chóng tan biến trong ký ức của bạn, nhưng bạn vẫn sẽ nhớ rằng sau cơn mưa đêm dài, ánh sáng buổi sáng có màu sắc mềm mại như thế nào."
  },
  CollectionHall_95437_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Bóng ma trong mưa\""
  },
  CollectionHall_95437_Title = {
    Text = "Trong màn mưa"
  },
  CollectionHall_95438_Desc = {
    Text = "Hãy làm một con mèo, một con mèo không lo âu, chỉ ở bên những người yêu thương, mỗi ngày cuộn mình bên họ tận hưởng nắng ấm.\nĐây là ước mơ nhỏ bé tuyệt vời trong trái tim cô, nhưng ước mơ à, từ trước đến nay vẫn luôn là những điều mong manh dễ vỡ."
  },
  CollectionHall_95438_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Bình yên của sự chia đôi\""
  },
  CollectionHall_95438_Title = {
    Text = "Nguyện vọng của mèo"
  },
  CollectionHall_95439_Desc = {
    Text = "Dù thế giới có nát tan, dù mọi thứ bị D-chất nhầy thấm đẫm, những con sứa trong sáng vẫn có thể mãi mãi chìm đắm trong giấc mơ của riêng mình.\nỞ đó, mọi thứ vẫn như xưa. Chỉ có tiếng cười. Chỉ có niềm vui."
  },
  CollectionHall_95439_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Mọi thứ vẫn như thường\" khó khăn"
  },
  CollectionHall_95439_Title = {
    Text = "Chìm đắm trong hỗn loạn rực rỡ"
  },
  CollectionHall_95440_Desc = {
    Text = "Mùa đông ở Londinium không thường có tuyết, mỗi lần tuyết rơi đều khiến bọn trẻ phấn khích vui mừng.\nBạn tỉnh dậy từ một giấc mơ dài dịu dàng, đưa tay ra ngoài cửa sổ. Một bông tuyết rơi vào lòng bàn tay, vui vẻ tan chảy trong sự ấm áp.\nNhững bông tuyết bay lả tả, trải qua hành trình ngắn ngủi trên bầu trời, trở về với mặt đất, trở về với dòng sông tối, trở về với ngôi nhà và vòng đời của tất cả giọt nước.\nTrong cơn tuyết lớn đầu tiên của năm nay, một cô gái khác cũng đã trở về nhà của họ.\nChúc ngủ ngon, tuyết; chúc ngủ ngon,\"24\"."
  },
  CollectionHall_95440_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Bình yên của sự chia đôi\""
  },
  CollectionHall_95440_Title = {
    Text = "Chúc ngủ ngon, Tuyết"
  },
  CollectionHall_95441_Desc = {
    Text = "San hô trắng lan tỏa ra từng nhánh, mọc lên một cung điện thuần khiết. \nTrong những cột trụ dị dạng, có những con cá nhiều màu tự do bơi lội. \nThân thể đang chìm xuống, linh hồn đang bay bổng. \nBạn sẵn lòng mất đi hơi thở, chìm đắm cùng cô ấy, chìm đắm, chìm đắm trong giấc mơ trắng. \nĐó là kỳ tích của biển cả, đó là quê hương màu xanh ấm áp."
  },
  CollectionHall_95441_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Như điệu nhạc tinh xảo\""
  },
  CollectionHall_95441_Title = {
    Text = "Cung điện trắng tinh khiết"
  },
  CollectionHall_95442_Desc = {
    Text = "Tách tách——Tàu con thỏ khởi hành!\nHãy để tôi dẫn bạn bè đến vương quốc truyện cổ tích không bao giờ đau khổ."
  },
  CollectionHall_95442_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Như mọi thứ vẫn thường\""
  },
  CollectionHall_95442_Title = {
    Text = "Giấc mộng ngây thơ"
  },
  CollectionHall_95443_Desc = {
    Text = "Cô ấy có phải là kẻ sát nhân không? Cô ấy trông giống như người yêu mà bạn đã lâu không gặp.\nMưa, lá khô và một mùi hương hoa mê hoặc, bạn khẽ động mũi, cố gắng ngửi ra mùi máu từ những mùi ẩm ướt đó, để khẳng định cô ấy có tội. Nhưng bạn không ngửi thấy gì.\nCô ấy cũng không hề có ý định giải thích, trong một làn sương mờ ảo, bạn rơi vào giấc mơ xám xịt của cô ấy."
  },
  CollectionHall_95443_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Bóng ma trong mưa\""
  },
  CollectionHall_95443_Title = {
    Text = "Nghi phạm"
  },
  CollectionHall_95444_Desc = {
    Text = "Cảm giác đó cũng từng là sự khao khát mà cô đã trải qua.\nNgây ngô, hung bạo và cô độc.\nCô thật may mắn, đã kết thúc cuộc tha hương dài đằng đẵng, có được những kỷ niệm ấm áp có thể nuốt chửng cả cuộc đời.\nGiờ cô cầm tay đồng loại, đưa linh hồn lạc lối này đến miền đất êm đềm của giấc mơ."
  },
  CollectionHall_95444_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Bóng ma thị trấn mưa\"độ khó khó khăn"
  },
  CollectionHall_95444_Title = {
    Text = "Giấc mơ của thú hoang"
  },
  CollectionHall_95445_Desc = {
    Text = "Từ con dao sắc bén của tôi, đâm vào trái tim tôi.\nTrước số phận tàn nhẫn và cuộc sống đắng cay, tôi thật nhỏ bé, yếu đuối và bất lực.\nTôi có quyền gì để trở thành tôi? Tôi có làm tốt vai trò của mình không?\nTừ câu hỏi của tôi, tôi cũng không thể trả lời."
  },
  CollectionHall_95445_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Bình yên của sự chia đôi\""
  },
  CollectionHall_95445_Title = {Text = "Hỏi tôi"},
  CollectionHall_95446_Desc = {
    Text = "Hả? Hình như bạn đã khác với lúc nãy? \nLà ánh mắt sáng hơn? Hay là cử chỉ hoạt bát hơn? Hay là trong cái thân xác tầm thường này, đã có một linh hồn mới chiếm lấy?"
  },
  CollectionHall_95446_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Như điệu nhạc tinh xảo\""
  },
  CollectionHall_95446_Title = {
    Text = "Chuyển giao linh hồn"
  },
  CollectionHall_95447_Desc = {
    Text = "Cho dù có tuyết rơi, có mưa, có ngày nắng hay ngày âm u, dòng sông hôm nay vẫn lặng lẽ chảy."
  },
  CollectionHall_95447_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Bình yên của sự chia đôi\""
  },
  CollectionHall_95447_Title = {
    Text = "Dòng sông yên tĩnh"
  },
  CollectionHall_95448_Desc = {
    Text = "Thủy triều dâng cao, đầu lâu kêu gào.\nMột đôi mắt nhìn chằm chằm vào bạn, hàng miệng tức giận lớn tiếng chửi rủa bạn.\nChúng muốn đắm bạn, chúng muốn nuốt chửng bạn.\nBạn sợ hãi nhắm mắt lại, khi mở mắt ra, bạn nhận ra chúng ngay bên cạnh bạn."
  },
  CollectionHall_95448_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Bóng ma trong mưa\""
  },
  CollectionHall_95448_Title = {
    Text = "Đầu lâu biển"
  },
  CollectionHall_95449_Desc = {
    Text = "Cô ấy đã hứa với bạn, nhất định sẽ đưa bạn về nhà cùng.\n—— Với một dáng vẻ vĩnh cửu, trở lại quê hương tĩnh lặng, đầy phép màu và vẻ đẹp."
  },
  CollectionHall_95449_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Như điệu nhạc tinh xảo\""
  },
  CollectionHall_95449_Title = {
    Text = "Nghệ thuật hóa đá"
  },
  CollectionHall_95450_Desc = {
    Text = "Vị khách quý đó từng nhìn vào bóng lưng đầy hy vọng của Castor, thì thầm lời tiên tri định mệnh dưới ánh trăng: \"Anh ấy sẽ bước ra ngoài, sẽ vùng vẫy trong bão tố. Điều làm anh ấy bay cao, cũng sẽ khiến anh ấy ngã xuống.\""
  },
  CollectionHall_95450_LockTip = {
    Text = "Hoàn thành \"Bên kia bầu trời\" trong thế giới mộng mơ"
  },
  CollectionHall_95450_Title = {
    Text = "Trong cơn bão"
  },
  CollectionHall_95451_Desc = {
    Text = "Sống trong cái đẹp, chết trong cái đẹp.\nCô ấy là thiên tài, kẻ điên, quỷ dữ, cô là kẻ hành hình lạnh lùng, cũng là người thân của bạn đầy tình cảm.\nCô ấy dùng tình yêu mãnh liệt, biến bạn thành một tác phẩm hoàn hảo.\nCô ấy ôm bạn, nắm lấy bàn tay lạnh giá của bạn. Cô ấy sẽ dẫn bạn về quê hương nghệ thuật cùng với cô ấy."
  },
  CollectionHall_95451_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Điêu khắc như bài ca\" khó khăn"
  },
  CollectionHall_95451_Title = {
    Text = "Cái chết xinh đẹp"
  },
  CollectionHall_95452_Desc = {
    Text = "Biển cả đã nghe thấy tiếng gọi của tôi, vì vậy đã đưa chị đến bên tôi.\nKể từ đây, chúng ta sẽ thoải mái trò chuyện, đùa giỡn, vui chơi, định mệnh trở thành những người bạn tốt nhất thế giới.\nTrong thành phố đầy rẫy sự tiêu hủy lạnh lẽo này."
  },
  CollectionHall_95452_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Như mọi thứ vẫn thường\""
  },
  CollectionHall_95452_Title = {
    Text = "Xin hãy trở thành bạn của tôi"
  },
  CollectionHall_95453_Desc = {
    Text = "Trở về đi, tất cả những người dũng cảm, nhút nhát, thông minh, ngu ngốc, mạnh mẽ, yếu ớt của tôi. \nHãy để tất cả những trái tim vui vẻ, buồn bã, tức giận, đau khổ, mệt mỏi đều tan chảy. \nChúng ta ở bên nhau. \nHọ mãi mãi bên nhau."
  },
  CollectionHall_95453_LockTip = {
    Text = "Hoàn thành bản ghi đặc nhiệm \"Chia đôi yên bình\"ở độ khó khó"
  },
  CollectionHall_95453_Title = {
    Text = "Trở về với cô ấy"
  },
  CollectionHall_95454_Desc = {
    Text = "Đó là sự trống rỗng và vết nứt từ linh hồn chỉ có những câu chuyện cổ tích trong sáng nhất mới có thể lấp đầy.\nRồi sẽ có một ngày, cô ấy sẽ từ biệt nỗi đau, trở về với những câu chuyện cổ tích tràn đầy niềm vui ở [「Nhà」]."
  },
  CollectionHall_95454_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Như mọi thứ vẫn thường\""
  },
  CollectionHall_95454_Title = {
    Text = "Câu chuyện cổ tích đầy sự ngây thơ và kinh dị"
  },
  CollectionHall_95455_Desc = {
    Text = "Những con hẻm sâu thẳm và chật chội, ẩn chứa bóng tối, luôn chứa đựng nhiều khoảnh khắc chuyển biến vận mệnh. Tái ngộ, cãi vã, chia tay, cho đến bạo lực, bắt nạt, giết chóc.\nMay mắn thay, câu chuyện hôm nay không có những cảnh tượng tàn bạo ở nửa sau, nhưng ai có thể nói rằng những gì trước đó gây ra không phải là bi kịch thực sự nhỉ?"
  },
  CollectionHall_95455_LockTip = {
    Text = "Hoàn thành \"Bên kia bầu trời\" trong thế giới mộng mơ"
  },
  CollectionHall_95455_Title = {
    Text = "Hẻm tối"
  },
  CollectionHall_95469_LockTip = {
    Text = "Nhận phần thưởng ngày đầu tiên trong hoạt động có thời hạn \"Mùa hè vĩnh cửu dưới ánh mặt trời đen: Tiệc hè rực rỡ\""
  },
  CollectionHall_95469_Title = {
    Text = "Mùa hè vĩnh cửu dưới ánh mặt trời đen"
  },
  CollectionHall_95981_LockTip = {
    Text = "Cần hoàn thành bất kỳ nhiệm vụ nào trong sự kiện giới hạn thời gian \"Thẩm mỹ của xác sống: Tiệc tùng thèm ăn linh hồn.\""
  },
  CollectionHall_95981_Title = {
    Text = "Nghệ thuật của những hồn ma: Tiệc linh hồn"
  },
  CollectionHall_95982_LockTip = {
    Text = "Thực hiện vượt ải hành động điều tra chương 3-11 phần Bứt phá mở khóa"
  },
  CollectionHall_95982_Title = {
    Text = "Bữa tối ban đầu"
  },
  CollectionHall_96314_Title = {Text = "Tham ăn"},
  CollectionHall_96321_Title = {
    Text = "Thành phố di hài"
  },
  CollectionHall_96790_LockTip = {
    Text = "Mở khóa hành động Điều tra chương Sao 3-1"
  },
  CollectionHall_96790_Title = {
    Text = "Dạ yến tại cung điện"
  },
  CollectionHall_97150_LockTip = {
    Text = "Cần hoàn thành một cấp độ của hoạt động giới hạn thời gian \"Mặt tối của bức tranh: Cuộc tranh vẽ từ thế giới khác\""
  },
  CollectionHall_97150_Title = {
    Text = "Mặt tối của bạt vẽ: Cuộn bản đồ dị giới"
  },
  CollectionHall_97158_LockTip = {
    Text = "Cần hoàn thành hoạt động thời gian giới hạn \"Ánh sáng tuyệt vọng: Truy đuổi bụi than\" bất kỳ cấp độ nào"
  },
  CollectionHall_97158_Title = {
    Text = "Vạn triệu ánh sáng rực rỡ: Thiêu đốt kẻ truy đuổi"
  },
  CollectionHall_97208_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Họa Dị Thế\" cấp độ đầu tiên để mở khóa"
  },
  CollectionHall_97208_Title = {
    Text = "Nghệ thuật đích thực"
  },
  CollectionHall_97736_LockTip = {
    Text = "Cần vượt qua hoạt động giới hạn thời gian \"Lễ hội Giáng Sinh của thần: Tạo sinh bảy ngày\" bất kỳ cấp độ nào"
  },
  CollectionHall_97736_Title = {
    Text = "Văn bản tạm thời"
  },
  CollectionHall_97896_LockTip = {
    Text = "Cần hoàn thành hoạt động giới hạn thời gian \"Nếu mọi thứ diễn ra bình thường: Việc mới dưới ánh mặt trời\" bất kỳ cấp độ nào"
  },
  CollectionHall_97896_Title = {
    Text = "Nếu mọi thứ vẫn bình thường"
  },
  CollectionHall_98502_LockTip = {
    Text = "Hoàn thành Kẻ lang thang \"Ngày dài vĩnh cửu\" cấp độ đầu tiên để mở khóa"
  },
  CollectionHall_98502_Title = {
    Text = "Kẻ săn cháy vĩnh cửu"
  },
  CollectionHall_98636_Desc = {
    Text = "Kẻ báng bổ dấy lên cơn sóng biển xanh, vị vua yếu đuối đối diện với sóng khổng lồ cả ngàn mét. \nTóc của hắn bay trong gió, xương và máu của hắn chính là tuyên ngôn trang nghiêm của hắn, trong nụ cười khinh thường, hắn cũng dâng hiến bản thân cho cái chết và mặt trăng. \nVà như vậy toàn bộ biển cả đóng băng tại khoảnh khắc này, những tảng băng lơ lửng ngừng lại dưới ánh trăng tròn, mọi thứ trở về sự tĩnh lặng, mọi thứ sự bình yên quay trở lại vương quốc của hắn."
  },
  CollectionHall_98636_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·Khó khăn Chương 3-10 mở khóa"
  },
  CollectionHall_98636_Title = {
    Text = "Lễ hội trăng tròn"
  },
  CollectionHall_98637_Desc = {
    Text = "Nấu chín người chết, là một nghệ thuật trang trọng.  \nÔng ấy dùng dao và xẻng để hỏi những di chúc chưa hoàn tất, ông ấy dùng nước và lửa để đáp ứng những nguyện vọng cuối cùng.  \nMỗi một ký ức khó chịu, đau đớn, chua chát, đều sẽ trở thành tác phẩm sáng chói và thơm ngát, để mọi người thưởng thức và gìn giữ."
  },
  CollectionHall_98637_LockTip = {
    Text = "Hoàn thành hoạt động điều tra Chương 3-11 mở khóa"
  },
  CollectionHall_98637_Title = {
    Text = "Chủ nhân của bàn ăn"
  },
  CollectionHall_98638_Desc = {
    Text = "Trẻ khóc lóc, kêu la, rất ngang ngược.\nNgài chính là trung tâm của vũ trụ, Ngài chính là tất cả quy luật ở đây.\nNgài muốn tất cả ánh nhìn đều hướng đến, bao quanh, phục tùng và tôn kính Ngài."
  },
  CollectionHall_98638_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·độ khó 6-10 mở khóa"
  },
  CollectionHall_98638_Title = {
    Text = "Truyền thuyết thần thánh tới"
  },
  CollectionHall_98639_Desc = {
    Text = "Khi anh ta thu dọn mỗi phần cái chết, không phải chỉ đơn thuần vung lưỡi hái với sự vô tình. \nCũng từng có đôi tay ấm áp, cũng từng có tâm hồn nhạy cảm.\nKhi anh ta nếm trải nỗi buồn của linh hồn, anh sẽ cùng lúc rơi lệ.\nKhi anh ta trải nghiệm thù hận sâu sắc, anh sẽ thay thế nó bằng sự phán xét.\nTrên danh nghĩa của chúa tể của cái chết, anh hứa hẹn: tất cả những kẻ xúc phạm cái chết sẽ biến mất giữa màn sương lạnh."
  },
  CollectionHall_98639_LockTip = {
    Text = "Hoàn thành hoạt động điều tra Chương 3-11 mở khóa"
  },
  CollectionHall_98639_Title = {
    Text = "Ánh mắt của thần chết"
  },
  CollectionHall_98640_Desc = {
    Text = "Hương vị ngọt ngào của máu và thịt cùng với độ giòn của gân là ký ức quen thuộc và sâu sắc nhất của anh ta.\nAnh ta đã sớm nhận ra, thành phố mồ chôn này tồn tại cho đến hôm nay không phải nhờ vào sức mạnh của kẻ sống, mà là nhờ vào sự hy sinh của kẻ đã chết.\nMột chút đỏ thẫm lại nuốt xuống cổ họng, anh ta nhắm mắt lại, chăm chú thưởng thức từng hương vị khác nhau, ghi nhớ hương vị của từng linh hồn, vì vậy bạn bè và dân chúng của anh ta đều mãi sống trong thân thể của anh ta.\nHọ đã hứa sẽ mãi mãi đoàn tụ."
  },
  CollectionHall_98640_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·Khó khăn Chương 3-10 mở khóa"
  },
  CollectionHall_98640_Title = {
    Text = "Hợp đồng máu"
  },
  CollectionHall_98641_Desc = {
    Text = "Con dao hiến tế dưới ánh trăng lấp lánh ánh sáng quyến rũ.\nCô đã chứng minh ý chí tự do mà cô khao khát bằng một cái chết quyết liệt."
  },
  CollectionHall_98641_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 6-15 mở khóa"
  },
  CollectionHall_98641_Title = {
    Text = "Ánh trăng lạnh lẽo"
  },
  CollectionHall_98642_Desc = {
    Text = "Anh dạy cho những người trong tộc cách chiến đấu, cách giết chóc, cách sinh tồn, nhưng chưa bao giờ dạy cách chạy trốn khi đối mặt với kẻ thù mạnh gấp bội mình.\nVì vậy anh cũng sẽ không trốn.\nChỉ là một cái đầu mà thôi, mang đi! \nAnh đã nhìn thấu: những kẻ tham vọng theo đuổi sức mạnh, chết trên đường theo đuổi, chỉ là cái kết và số phận đã định sẵn."
  },
  CollectionHall_98642_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Sự sụp đổ của người khổng lồ\""
  },
  CollectionHall_98642_Title = {
    Text = "Tôi không sợ cái chết"
  },
  CollectionHall_98643_Desc = {
    Text = "Kẹt, kẹt.\nThần mở miệng, vui vẻ tiếp nhận tất cả lòng sùng kính của tín đồ và cả tín đồ chính nó."
  },
  CollectionHall_98643_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 6-15 mở khóa"
  },
  CollectionHall_98643_Title = {
    Text = "Bữa ăn đầu tiên"
  },
  CollectionHall_98644_Desc = {
    Text = "Cựu thuộc hạ đồng loạt lao vào, với ý định giết chết vị lãnh đạo đã thất bại và lưu vong của họ. Chứ không phải là lãnh đạo dũng mãnh nhất trong lịch sử Philistine, một gã khổng lồ với ý chí bất khuất, đã đáp trả bằng máu. \nTrong tiếng kêu gào vô tận, lưỡi hái khát khao uống máu, diễn giải phong cách chiến đấu của hắn—— độc tài, kiêu ngạo, man rợ, tàn bạo. \nĐối với kẻ thù, không cần sự thương xót. \nChúng chỉ là bước cầu cần thiết để hắn trở lại đỉnh cao quyền lực."
  },
  CollectionHall_98644_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Sự sụp đổ của người khổng lồ\""
  },
  CollectionHall_98644_Title = {
    Text = "Sự giết chóc cần thiết"
  },
  CollectionHall_98645_Desc = {
    Text = "Vào khoảnh khắc quay lưng rời đi, Elton như trở lại thành cậu thanh niên vừa ra khơi, bầu trời xanh hòa quyện với đại dương bao la, thế giới rộng đủ để chứa đựng mọi hoài bão và giấc mơ.\nĐiều khác biệt là, lần này anh đã rõ ràng thấy hình dáng của giấc mơ trở thành hiện thực, và có một con đường dẫn về nơi tràn ngập chim trắng, thiên đường mộng mơ."
  },
  CollectionHall_98645_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·độ khó 6-10 mở khóa"
  },
  CollectionHall_98645_Title = {
    Text = "Vùng đất của những chú chim trắng"
  },
  CollectionHall_98646_Desc = {
    Text = "Thời gian đã đến, ánh trăng bạc cao tỏa sáng.\nNâng ngón chân cứng đờ lên, tối nay chúng ta sẽ mừng tiệc.\nCô ấy đã đi đến hành trình cuối cùng, và chúng tôi sẽ tiễn đưa cô bằng dạ dày của mình.\nMột miếng cho bạn, một miếng cho tôi, từ giờ ai cũng sẽ không quên."
  },
  CollectionHall_98646_LockTip = {
    Text = "Hoàn thành hoạt động điều tra Chương 3-11 mở khóa"
  },
  CollectionHall_98646_Title = {
    Text = "Điệu nhảy an giấc"
  },
  CollectionHall_98647_Desc = {
    Text = "Nếu phép màu có hình dạng, nó sẽ như đôi tay hợp nhất của cô ấy.\nNếu thần thánh có hình dáng, nó sẽ như khuôn mặt bình yên của cô ấy."
  },
  CollectionHall_98647_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 6-15 mở khóa"
  },
  CollectionHall_98647_Title = {
    Text = "Nữ thần trắng pure"
  },
  CollectionHall_98648_Desc = {
    Text = "Hãy tổ chức một buổi lễ, bạn của tôi ♪\nXương cốt dưới ánh trăng khẽ khẽ nở rộ, một người yêu dấu được đưa lên đĩa tiệc ♪\nTất cả khách mời đã đến! Hát nào, nhảy nào ♪\nChúng tôi không bao giờ cầu nguyện cho linh hồn, chúng tôi không bao giờ thương tiếc cho xác chết ♪\nCô ấy đã giao ký ức cho tôi, cô ấy đã giao nước mắt cho tôi ♪\nHãy để chúng ta nuốt linh hồn và thịt thối của cô ấy ♪\nTrong bữa tiệc của cái chết, chúng ta sẽ đoàn tụ một lần nữa ♪"
  },
  CollectionHall_98648_LockTip = {
    Text = "Hoàn thành hoạt động điều tra Chương 3-11 mở khóa"
  },
  CollectionHall_98648_Title = {
    Text = "Bài hát của xác sống"
  },
  CollectionHall_98649_Desc = {
    Text = "Con người sợ hãi sức mạnh của hắn, tôn thờ hắn, bởi sự tàn bạo của hắn mà ghét bỏ hắn, khinh bỉ hắn, hơn nữa vì thất bại của hắn mà chế nhạo hắn, lưu đày hắn. \nNhưng tiếng ồn của kẻ yếu thật vô nghĩa, ánh mắt của người khổng lồ chỉ dừng lại với người mạnh mẽ. \nGiữa biển lưu vong hoang vắng, hắn lấy mạng sống của mình làm cược, bắt đầu cuộc hành trình tìm kiếm sức mạnh tuyệt đối."
  },
  CollectionHall_98649_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Sự sụp đổ của người khổng lồ\""
  },
  CollectionHall_98649_Title = {
    Text = "Bắt đầu hành trình mới"
  },
  CollectionHall_98650_Desc = {
    Text = "Anh nhớ cô ấy. \nCô gái trong cơn bão mà đã được anh ôm chặt trong vòng tay, cuối cùng bị chính tay anh gửi đến vực thẳm—để đổi lấy giấc mơ mà con chim trắng bay lượn ấy, cùng với lương tâm của mình. \nAnh hy vọng giấc mơ đẹp trong suốt cuộc đời đã trở thành hiện thực, và bây giờ, đến lúc phải dùng phần đời còn lại để trả giá cho tất cả tội lỗi đen tối."
  },
  CollectionHall_98650_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 6-15 mở khóa"
  },
  CollectionHall_98650_Title = {Text = "Trả nợ"},
  CollectionHall_98651_Desc = {
    Text = "Chia ly và cái chết là những điều không thể tránh khỏi trong thế gian này.\nRa khỏi vô số sự hy sinh và cái chết, hướng tới một con đường mờ mịt, một nỗi buồn nhè nhẹ bao quanh trái tim bạn. Tuy nhiên, sau khi chứng kiến những người sống trong cái chết, và thấy những vị vua đã đưa đến cái chết một kết thúc nhẹ nhàng, bạn không còn sợ hãi những kết thúc chưa biết.\nMột bông hoa lưu niệm màu tím rơi lên vai bạn, gửi lời tạm biệt từ xa.\nBạn biết rằng, dù sao đi nữa, con đường về của bạn không cô đơn."
  },
  CollectionHall_98651_LockTip = {
    Text = "Hoàn thành hoạt động điều tra·Khó khăn Chương 3-10 mở khóa"
  },
  CollectionHall_98651_Title = {
    Text = "Lễ tiễn biệt của lưu niệm"
  },
  CollectionHall_98652_Desc = {
    Text = "\"Nhân danh những người bạn của các bạn, vua, và chủ nhân của vùng đất an bình này, tôi mời các bạn - hãy tỉnh thức! Trở về quê hương mà các bạn yêu thích! Đuổi đi những kẻ đã quấy rối sự bình yên của chúng ta mãi mãi!\""
  },
  CollectionHall_98652_LockTip = {
    Text = "Hoàn thành hoạt động điều tra Chương 3-11 mở khóa"
  },
  CollectionHall_98652_Title = {
    Text = "Cơn thịnh nộ của muôn linh hồn"
  },
  CollectionHall_98653_Desc = {
    Text = "Nàng và Ngài, không thể đồng tồn, vì vậy một con dao cứa vào hai trái tim, đó là sự đền bù của nàng dành cho thần."
  },
  CollectionHall_98653_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 6-15 mở khóa"
  },
  CollectionHall_98653_Title = {
    Text = "Ngày sinh của thần thánh"
  },
  CollectionHall_98654_Desc = {
    Text = "Cậu không bao giờ nghĩ rằng cuộc trò chuyện với một vị vua lại bắt đầu bằng một điệu nhảy chung.\nSự xâm lược mạnh mẽ, sự thăm dò lẩn quẩn, tấn công và phòng thủ, đối đầu và nhượng bộ, các bạn đã giao chiến một cách bí mật trong những chiếc váy xoay tròn.\nMột thương lượng thanh lịch kết thúc trong cái chào tạm biệt cuối cùng, sợi tóc của vua bay bay, cậu thấy đôi mắt mờ ảo ấy rực rỡ với nụ cười vui vẻ.\nHả? Chẳng lẽ vừa rồi mình bị anh ta dẫn dắt?"
  },
  CollectionHall_98654_LockTip = {
    Text = "Hoàn thành hoạt động điều tra Chương 3-11 mở khóa"
  },
  CollectionHall_98654_Title = {
    Text = "Ngoại giao tango"
  },
  CollectionHall_98655_Desc = {
    Text = "Bạn đã thấy món ăn đáng sợ và phạm thượng nhất, nhưng đó là cuộc hội ngộ dịu dàng nhất trong cuộc đời của họ."
  },
  CollectionHall_98655_LockTip = {
    Text = "Hoàn thành hoạt động điều tra Chương 3-11 mở khóa"
  },
  CollectionHall_98655_Title = {
    Text = "Nơi an nghỉ của những bộ xương"
  },
  CollectionHall_98656_Desc = {
    Text = "Các vì sao chỉ đơn giản là quay vòng trong quỹ đạo của chúng, trong khi sự sống trong bụi bặm đã trải qua nhiều lần sa ngã."
  },
  CollectionHall_98656_LockTip = {
    Text = "Hoàn thành hoạt động điều tra 6-15 mở khóa"
  },
  CollectionHall_98656_Title = {
    Text = "Sao đảo ngược"
  },
  CollectionHall_98657_Desc = {
    Text = "Đối mặt với phù thủy có thể khiến người khác chết ngay lập tức, kẻ yếu sợ hãi, tôn sùng, quy phục, cầu xin sự che chở.\n Nhưng anh ta tuyệt đối không như vậy.\n Anh ta nhìn thấy sức mạnh này, khao khát sức mạnh này, và dù phải trả bất kỳ giá nào, anh ta cũng muốn có được sức mạnh này.\n Sau đó, anh ta sẽ phục sinh, một lần nữa để tên tuổi mình vang vọng trên từng tấc đất mà người Perishite đã từng đặt chân đến."
  },
  CollectionHall_98657_LockTip = {
    Text = "Hoàn thành duy thức tiềm hành \"Sự sụp đổ của người khổng lồ\"ở mức khó"
  },
  CollectionHall_98657_Title = {
    Text = "Tham vọng của người khổng lồ"
  },
  CollectionHall_99651_Desc = {
    Text = "<Bold:Cá Tuyết Bạc 24>\nMỗi lần đi qua nhà hàng cá chiên đó, tôi không thể không muốn hét lên. \nTại sao những con cá tuyết bạc bị thương luôn là nạn nhân? Chúng tôi thậm chí không phải là cá tuyết thật! \nThịt chắc, hương vị thơm ngon có phải là lỗi của chúng tôi không? \n\n<Bold:Mèo 24>\nHúp húp... Meo, meo meo (tán thành)! \n\n<Bold:Cá Tuyết Bạc 24>\nTại Vương quốc Leo, mỗi phút có một con cá tuyết bạc chết một cách thảm thương, trở thành món ăn của con người. \nĐúng vậy, trong khoảng thời gian chúng ta nói chuyện, đã có 10 con cá tuyết bạc anh dũng hy sinh. \nĐúng 10 con! Cha Thượng Đế, Ngài có nghe thấy tiếng kêu thảm thiết của chúng không? \n\n<Bold:Mèo 24>\nƯm... Meo? Meo meo meo, meo meo (ở đâu)? \n\n<Bold:Cá Tuyết Bạc 24>\nChỉ là một phép ẩn dụ thôi, ngốc ạ. Dù bạn có hơi ngốc nghếch, nhưng bạn có một trái tim vàng, có thể vượt qua bản năng thú tính và sự thiển cận của mèo. \nNghe này, tôi có một kế hoạch, cần bạn cùng tôi thực hiện... \n\n—— Trích từ《Sự cố nổ nhà hàng cá John Đại》·Tóm tắt hồ sơ: Lời khai B-03. Do bệnh viện tâm thần Bethlehem thời kỳ đó quá tải, nghi phạm đã bị từ chối tiếp nhận, và sau 23 ngày giam giữ tại tháp Lentiennam được thả ra."
  },
  CollectionHall_99651_Title = {
    Text = "Định mệnh của Bạc Khô"
  },
  CollectionHall_99653_Desc = {
    Text = "Để chờ đợi \"thời khắc đó\", cô gái chìm vào giấc ngủ dưới đáy băng hà. Nghìn thước băng giá của Elworth đóng băng cơ thể cô, nhưng không thể hoàn toàn phong bế thần thức của cô.\nDòng thần thức ấy đến từ một đứa trẻ, cũng như từ một người mẹ. Trong tử cung tối tăm của con gái Ngài, thần minh tiếp tục giấc mơ vạn cổ.\nTrong suốt hai mươi lăm năm, cô đã suy nghĩ về điều gì, lưu luyến điều gì, mong đợi điều gì?\nCho đến ngày nay, những câu hỏi này đã không còn ai có thể trả lời. Còn chính cô gái ấy... liệu cô có sẵn lòng chia sẻ tâm tư với những người xung quanh mình không? Hãy giao mọi thứ cho thời gian và tương lai."
  },
  CollectionHall_99653_Title = {
    Text = "Ngủ dưới sông băng"
  },
  CollectionHall_99654_Desc = {
    Text = "Chỉ có linh hồn chết yên tĩnh mới xứng đáng được thưởng thức tỉ mỉ. Sự vật lộn của người sống chỉ khiến hương vị trở nên hỗn độn. \n Đĩa được đặt lên khi vẫn còn nhiệt dư, một trái tim nằm yên ổn ở giữa, bề mặt hơi phồng lên, như thể vừa mới đập xong nhịp cuối cùng. Hai nhãn cầu nằm bên cạnh, điểm xuyết, trong đồng tử chứa đựng sự kinh ngạc của giây phút trước khi chết, được hầm thành màu trắng sữa ngoan ngoãn. \n Anh nâng dao lên, từ từ rạch mở tim, nhưng đột nhiên dừng lại. \n Linh hồn của nó vẫn đang gào thét khản đặc, một sợi ám ảnh vẫn còn lưu lại trong mạch máu, chưa thể hoàn toàn tan biến. Anh đặt dao xuống, chắp tay lại, lặng lẽ lắng nghe tiếng nói của người đã khuất. \n Trái tim này đến từ một nhà thơ đã chịu đựng bệnh tật trước khi chết, lâu dài thất vọng trong cái chết mà được giải thoát, nhưng vẫn có sự tiếc nuối về sự sống còn lưu lại. Anh biết rằng, để trái tim này thực sự \"thấm vị\", cần phải dành cho món ăn đủ sự tôn trọng, cách duy nhất là chờ đợi—\n chờ đợi sợi ám ảnh quấn quanh thịt hoàn toàn tan vỡ trong cái chết; chờ đợi tiếng vọng cuối cùng của người đã khuất hóa thành trầm hương, lặng lẽ thấm ra trên thành mạch máu. \n Anh đặt tay một cách thanh thoát lên đầu gối, nhắm mắt lại, hít một hơi thật sâu. \n Hương thơm từ từ lan tỏa trong không khí, đó là một mùi hương phức tạp và dịu dàng, vừa có sự run rẩy của tình nhân, lại có sự đắng cay của cuộc chia ly. Hòa quyện với mùi mực, hương thảo và một chút sự e dè như sương sớm. \n Anh ngồi yên dưới cây sống xanh tươi, chờ đợi trái chín rụng xuống đúng hẹn."
  },
  CollectionHall_99654_Title = {Text = "Món ngon"},
  CollectionHall_99655_Desc = {
    Text = "Một bó hoa đã khô héo vì để quá lâu. \nMãi mãi chẳng thể đợi được người chủ của nó."
  },
  CollectionHall_99655_Title = {
    Text = "Hoa chưa gửi"
  },
  CollectionHall_99656_Desc = {
    Text = "Từ khi ra đời, cặp song sinh không được phép tự do bay lượn bằng đôi cánh, đôi tay thứ hai mọc trên lưng họ giống như hai bộ lễ vật thể hiện uy nghi của thánh tử, bị quy định về tư thế mà họ cần giữ vào mọi lúc.\nKhi còn nhỏ, Polux là người chăm sóc đôi cánh ấy nhất trong hai người, mỗi ngày chải chuốt, bôi tinh dầu, làm cho những chiếc lông vũ sáng bóng như lụa.\nCậu ấy luôn nhân những khoảnh khắc ngắn ngủi không có người, lén lút vỗ cánh đôi cánh đang bắt đầu mướt, khiến Castor kinh ngạc mà chao đảo bay lên, để chạm vào những mái vòm được trang trí.\nSo với việc Polux có thể thực hiện đủ kiểu tư thế như một điệu nhảy với đôi cánh, Castor thường cảm thấy đôi cánh của mình nặng nề như hai tấm ván gỗ. Trong khoảnh khắc bí mật sau khi hai anh em đi ngủ hàng đêm, Castor đã như vậy thầm theo dõi Polux nhảy múa và xoay tròn trong bóng tối, bắt chước việc bay trong không gian hẹp.\n \"Đôi cánh của em trai thật đẹp, nhưng với tôi, có lẽ tôi sẽ không bao giờ học bay được.\" Castor nghĩ.\nVì vậy, vào đêm mà họ chạy trốn sau đó, Castor lần đầu tiên cảm nhận được sự mát mẻ và thoải mái của cơn gió đêm nâng đôi cánh. Polux, giàu kinh nghiệm hơn, nắm chặt lấy người anh đang bay loạng choạng, cười vang trong không trung, vẽ ra những đường uốn lượn, vòng tròn như một con chim thật sự, thuộc về bầu trời.\nCastor quay đầu, nhìn ánh trăng tỏa sáng trên đôi cánh dài và mạnh mẽ của Polux, phản chiếu ánh sáng xanh lục khiến người khác phát choáng giữa những chiếc lông vũ.\n \"Đó chắc chắn là điều đẹp nhất trên thế giới, dù phải đối mặt với điều gì, tôi nhất định phải bảo vệ Polux, bảo vệ đôi cánh đó.\"\nRất nhanh, cuộc sống khó khăn ngoài trời làm cho đôi cánh của Polux bị thương bởi thú dữ, Castor thương xót nhặt những chiếc lông rơi của Polux, giữ trong lòng, thề không để chuyện này xảy ra lần thứ hai. Nhưng cậu không biết rằng, chiếc lông đơn độc này về sau sẽ trở thành vật quý giá nhất của cậu, trở thành di vật cuối cùng còn lại về đôi cánh đó."
  },
  CollectionHall_99656_Title = {
    Text = "Lông vũ cô độc"
  },
  CollectionHall_99657_Desc = {
    Text = "Tút——tút——\nTrong tiếng còi, du thuyền an toàn cập bến dưới sự chỉ dẫn của Copper Sanga.\nCác hành khách mỉm cười bước xuống thang, cúi mũ cảm ơn cô, các thủy thủ thì ùa đến, thể hiện sự khen ngợi.\n\"Giỏi lắm, Copper Sanga, nếu không nhờ bạn cảnh báo trước, chúng tôi đã bị bão nuốt chửng.\"\n\"Đúng vậy, nhờ chỉ dẫn đúng đắn của bạn, chúng tôi đã không bị lạc giữa đại dương!\"\nCác thủy thủ cười lớn, vỗ vai cô, giơ ngón tay cái hướng về phía cô.\nThực tế, Copper Sanga luôn không quen với sự giao tiếp gần gũi như vậy, bộ não cứng nhắc và lý trí của cô không có suy nghĩ nào ngoài \"công việc\" và \"trách nhiệm\".\nVì vậy, cô chỉ có thể coi đây cũng là một phần của \"công việc\" và \"trách nhiệm\".\n\"Tôi chỉ hoàn thành công việc của mình thôi. Với tư cách là thủy thủ trưởng, trách nhiệm của tôi là dẫn dắt các bạn an toàn về nhà.\" \nCâu trả lời trang trọng nhưng tẻ nhạt, nhưng các thủy thủ quen thuộc với tính cách của cô lại bật cười, chào tạm biệt cô, hát những bài hát trên thuyền, đụng vai nhau rời khỏi bến cảng.\n\"Chiến hạm Nautilus cuối cùng cũng sắp ra khơi. Xuất phát, Nautilus.\" \nÂm thanh hát dần xa, trong khi Copper Sanga vẫn đứng lại bên bờ. Cô đang chuẩn bị cho cuộc khởi hành trong tương lai. \nBiển cả thường hay thay đổi, không có thủy thủ trưởng nào có thể đảm bảo rằng mình sẽ chiến thắng mỗi lần, cô cũng vậy. Nhưng cô sẵn sàng dành vô số thời gian để tăng một chút tỉ lệ thành công.\nKiểm tra, tuần tra, học tập, đối chiếu, trong cuộc đời cô dường như chỉ còn lại \"công việc\" này.\nNhưng cô sẵn lòng, vì tất cả điều này là để khoảnh khắc đó, khoảnh khắc thành công dẫn dắt mọi người trở về an toàn."
  },
  CollectionHall_99657_Title = {
    Text = "Hoa tiêu trên biển"
  },
  CollectionHall_99658_Desc = {
    Text = "Trong vực thẳm vô tận, ngai vàng màu xanh đứng sừng sững, \n bầu trời thấp thỏm, các vì tinh tú rung rinh, vạn vật im lặng. \n\n Những tồn tại cổ xưa và huyền bí đã lặng lẽ biến mất, \n qua bao thế hệ, chúng sinh ngâm nga trong giấc mơ. \n Những vùng nước u ám, những bí mật bị chôn vùi, \n lời thì thầm của bạn như thủy triều dâng lên, ngập lụt những khe hở trong tâm hồn. \n\n Trong giấc mơ vô biên đó, các tiên tri và kẻ điên cùng nhau du hành, \n truy tìm những linh hồn vô hình, sợ hãi và kính sợ đan xen. \n Quỹ đạo bị tảo xanh vướng víu, như một bản thảo của số phận, \n dẫn dắt trái tim của kẻ lạc lối, từ từ hướng về ngai vàng màu xanh đó. \n Ôi, sự vô lý và chân lý của vũ trụ, \n tại nơi giao thoa giữa giấc mơ và hiện thực, ánh sáng vĩnh cửu nhấp nháy."
  },
  CollectionHall_99658_Title = {
    Text = "Ngai đá xanh"
  },
  CollectionHall_99660_Desc = {
    Text = "Mọi người đều muốn chiến thắng số phận, nhưng cũng đều sợ hãi số phận. \n Những người can đảm phát ra tiếng gầm chiến đấu, những kẻ nhút nhát phát ra tiếng rên rỉ khuất phục, nhưng chỉ có anh ta phát hiện ra bí mật để chiến thắng số phận. \n Đó là không ngừng mời số phận tham gia vào ván cược, thúc giục số phận mở ra ván tiếp theo. \n Anh ta chưa bao giờ sợ hãi số phận, vì anh ta tin rằng mình sẽ không thua. \n Anh ta không bao giờ hỏi xem sẽ đặt cược cái gì, bất kể đặt lên bàn cược thứ gì, anh ta đều không do dự, bao gồm cả sinh mạng của mình. \n Với một khẩu súng lục roulette, anh ta đã dọa lui vô số kẻ thua cuộc đỏ mắt, trở thành một con bạc điên cuồng nổi tiếng của Lentiennam. \n Thật tiếc, không có đối thủ ngang sức ngang tài thật là cô đơn biết bao. \n Cho đến khi anh ta gặp người đàn ông đó. \n Anh ta đã đánh bại vô số phàm nhân, cuối cùng ngồi lên bàn cược của số phận. \n Chẳng bao lâu sau, anh ta đã mất tất cả, rồi lại thu hồi mọi thứ kèm theo cả vốn lẫn lãi. \n Cho đến khi tái sinh thành quái vật, anh ta lại thấy khẩu súng đã bắn ra viên đạn cuối cùng nằm trên mặt đất. \n Anh ta nạp lại một viên đạn, nhắm vào đầu mình và lại ấn cò. \n Trong một không gian tĩnh lặng, anh ta nở một nụ cười. \n Anh ta vẫn chưa thua, vậy thì nhất định một ngày nào đó anh ta sẽ thắng cuối cùng. \n Anh ta luôn tin tưởng như vậy, ngay cả khi phải đặt cược tất cả."
  },
  CollectionHall_99660_Title = {
    Text = "Roulette Số Phận"
  },
  CollectionHall_99663_Desc = {
    Text = "Vị phụ nữ bí ẩn đã tìm đến cô sau lễ tang. \n \"Đứa trẻ đáng thương,\" bà ấy nói, \"con không đáng phải chịu tai họa vô vọng này.\"\n \"Con không biết sao? Sau khi hắn hại chết Milly, Thompson đã tìm đến hắn. Tên rác rưởi tên Edward lẽ ra đã chết từ năm ngoái, nhưng một người đã giúp hắn.\"\n \"Con hỏi tại sao ư? Ôi, ta làm sao biết được. Có lẽ, họ vốn dĩ là đồng bọn xấu xa, hoặc có thể... kẻ tội đồ đó cũng không biết hành động của mình là tội lỗi. Hắn đã nói gì nhỉ? À đúng rồi, sự tha thứ. Tha thứ cho kẻ tội đồ, tha thứ cho những tội ác mà họ đã gây ra.\"\n \"Hắn tin rằng mọi người đều xứng đáng có cơ hội thứ hai, con nghĩ sao? Chúng ta có nên cho Edward một cơ hội nữa không, sau khi hắn hại chết Milly, hại chết chị gái con, mẹ con?\"\n \"Đúng vậy, loại người như thế sẽ không bao giờ thay đổi. Vậy nên, con biết phải làm gì rồi chứ?\"\nĐúng vậy, loại người như thế sẽ không bao giờ thay đổi, muốn chấm dứt loại người này, loại tội ác này, bi kịch này, chỉ có thể... \nphơi bày dục vọng của họ, để họ lộ rõ bộ mặt xấu xa, xem họ tàn sát lẫn nhau, đấu tranh với nhau, thanh lọc hoàn toàn họ— \nđón chào vùng đất vô tội tinh khiết."
  },
  CollectionHall_99663_Title = {
    Text = "người trong gương"
  },
  CollectionHall_99666_Desc = {
    Text = "Đàn cừu mờ mịt lang thang trên đồng cỏ bao la. \n Trên thế gian này có quá nhiều cừu, và cừu sinh ra là để cần có người chăn dắt dẫn đường. \n Cô ấy luôn là nhà tiên tri của thế giới này, nắm trong tay cây gậy tri thức. \n Cô ấy luôn là một người chăn cừu tốt, quyết tâm dẫn đàn cừu đi trên con đường đúng đắn. \n Cô ấy dùng cây gậy đó để giáo dục những con chiên, cô ấy dùng cây gậy đó để xua đuổi sói. \n Cô ấy giơ cao cây gậy của người chăn cừu, vì cô luôn có thể nhìn thấy con đường phía trước từ sớm. \n Một thời, cô dẫn đàn cừu đến nguồn nước dồi dào, đến đồng cỏ tươi tốt. \n Bây giờ cô chứng kiến sự thật của thế giới, vì vậy dẫn đàn cừu đến vòng tay cuối cùng. \n Đi về phía này, đừng nhìn lại. \n Cô ấy cười và vung cây gậy trí tuệ. \n Vì vậy, đàn cừu không nhìn thấy vực thẳm phía trước. \n Một con, hai con. \n Những con cừu rơi xuống, người chăn cừu hát lên. \n Hãy theo chân người chăn cừu vô tư, cô đã chỉ cho bạn con đường chân thực nhất. \n Đừng sợ hãi, ngay cả khi đi qua thung lũng bóng chết, cây gậy của cô vẫn ở bên bạn. \n Cho đến khi cùng nhau bước vào vực thẳm diệt vong. \n"
  },
  CollectionHall_99666_Title = {
    Text = "Cây gậy của người chăn cừu"
  },
  CollectionHall_99667_Desc = {
    Text = "Ngài bò lổm ngửa trong hỗn loạn vô tận, thỉnh thoảng mới liếc nhìn những sinh linh đang bò lê trên thế gian. \n\nNhững kẻ còn xứng đáng để nhìn, như Sorrel, Ngài đưa ra cho họ những \"điều khoản hợp đồng\" khó có thể từ chối. \nNhững kẻ thô lỗ và nhàm chán, Ngài tước bỏ xác thịt của họ, để lại một con mắt không thể rơi lệ. \nNhững con mắt này được gọi là \"Những người được sủng ái\". \n\nChúng nhấp nháy trong hang động, vừa tràn đầy hy vọng, vừa đầy tuyệt vọng, chờ đợi sự gọi của Ngài. \nTuy nhiên, một nghìn năm trôi qua, mười nghìn năm trôi qua, những người được sủng ái vẫn tiếp tục bị lãng quên trong góc tối. \n\n \"Vậy... các ngươi chắc chắn đã được giữ lại vì một lý do nào đó. Sứ mệnh của các ngươi là gì?\"\n \"Chúng tôi đang chờ đợi.\"\n \"Chờ đợi điều gì?\"\n \"Chờ đợi... chỉ đơn giản là chờ đợi mà thôi.\"\n \"Có cảm thấy đau đớn không?\"\n \"Trái lại, tình yêu dành cho người lớn ngập tràn trong chúng tôi. Vì đây là điều duy nhất chúng tôi có thể làm.\"\n \"Chỉ khi hiểu được điều này, mới có thể trở thành tín đồ chân chính.\""
  },
  CollectionHall_99667_Title = {
    Text = "Triệu ánh nhìn yêu thương"
  },
  CollectionHall_99668_Desc = {
    Text = "Tên của cô ấy chính là hiện thân của trí tuệ. \n Cô ấy biết mọi kiến thức trên thế giới, là điều mà tất cả các học giả của Misaque khao khát đạt được. \n Chỉ cần có thể lắng nghe một vài lời, bạn sẽ có được sự khai ngộ như nước chảy vào mồm. \n Nhưng cô ấy nói, mình chỉ là một người giữ cửa. \n Đó là một cánh cửa như thế nào? \n Không ai từng thấy cánh cửa đó, các học giả đã gọi nó là sự thật. \n Cô ấy là người giữ cửa của sự thật, là Athena bảo vệ Misaque. \n Tà Vy không phủ nhận những suy đoán như vậy, chỉ luôn nhìn về đây, nhìn về thế giới này. \n Im lặng và đầy lòng từ bi. \n Nếu một ngày nào đó bạn nhìn thấy cánh cửa đó, bạn sẽ thấy trên cánh cửa có một đôi mắt vô cùng quen thuộc. \n Ánh mắt đó bình tĩnh và vĩnh cửu. \n Xuyên thấu thời gian, xuyên thấu linh hồn của bạn."
  },
  CollectionHall_99668_Title = {
    Text = "Cánh cửa Sự thật"
  },
  CollectionHall_99670_Desc = {
    Text = "Cô gái tắm trong dòng máu đen và tái sinh, giữa cơn bão cát sa mạc đã tồn tại hàng nghìn năm, nâng niu hạt giống thiêng liêng của cây mẹ phong thịnh. \n\n \"Chừng nào hạt giống này còn tồn tại, dòng máu của cây sẽ không bao giờ đứt đoạn.\"\n\nTừ đó trở đi lại là một nghìn năm, hạt giống này đã chứng kiến sự thăng trầm, vinh quang và sụp đổ cùng với hậu duệ của cây, trải qua cảnh lưu lạc, mất tích, diệt vong và tái sinh, cho đến khi dòng sông cuồn cuộn hóa thành dòng máu đen dính đặc, nó cũng hoàn thành lần truyền thừa cuối cùng. \nĐó là nụ hôn nóng bỏng và dai dẳng, chứa đựng khát vọng chưa được thỏa mãn và nỗi buồn ly biệt chưa kịp nói ra, cùng với nhịp đập ấm áp của trái tim, bao bọc người kế thừa mới. \nMàu sắc như ngọc mã não, ánh sáng như ngọc trắng, sẽ cùng với nhịp đập của sức sống vượt qua cái kết thúc màu đen. \nRồi hạt giống đầu tiên của thế giới mới sẽ mọc lên từ lời chúc phúc của cô ấy, biến thành cây cổ thụ che phủ trời đất."
  },
  CollectionHall_99670_Title = {
    Text = "Nụ hôn chia ly nóng bỏng"
  },
  CollectionHall_99671_Desc = {
    Text = "Clementine sau khi hồi sinh giống như một con sâu non ngây thơ, di chuyển trong nhân gian, đi giữa một thế giới phồn hoa không thuộc về chủng tộc của cô, cảm thấy mơ hồ, cảm thấy bối rối.\nCho đến khi tiếng nói như mang lại sự khai sáng vang lên -\n\"Xin hỏi, bạn có phải là bác sĩ Charlotte không? Tôi đến tìm bác sĩ Charlotte để tư vấn tâm lý...\"\nClementine cuối cùng đã lấy lại tinh thần. Cô không quan tâm Charlotte là ai, chỉ cảm thấy tò mò về thuật ngữ mới mà người đến đề cập: \"tư vấn tâm lý\".\nNhưng cô là một thợ săn trưởng thành, cô sẽ không để lộ sự ngu ngốc của mình, vì vậy cô đã cười, như thể cô chính là Charlotte, chính là sự cứu rỗi trong lời nói của người đến.\nNước mắt, sự dằn vặt, sự bất lực, không cần phải khơi gợi, người đến đã rút ra nỗi đau sâu thẳm trong linh hồn mình.\nTrước khi rời đi, người đối diện nhìn Clementine với vẻ nhẹ nhõm, thốt lên: \"Cảm ơn bạn đã sẵn lòng lắng nghe những điều này. Tôi cảm thấy tốt hơn nhiều.\" \nSau đó, chỉ còn lại tiếng đóng cửa, và tiếng cười của Clementine vì lần đầu nếm được vị ngọt.\nTiếng cười này ban đầu nhỏ bé, như tiếng vo ve của một con sâu, sau đó ngày càng lớn, tựa như tiếng kêu của một con trưởng thành.\nVà trong tiếng cười đó, cái \"sâu tộc\" mang tên Clementine, cũng nhanh chóng trưởng thành.\nTất cả những điều tiếp theo, diễn ra tự nhiên. Cô trở thành một bác sĩ tâm lý, mang nụ cười và chiếc đ pendulum, đi sâu vào tâm hồn từng bệnh nhân.\nCô vẫn di chuyển trong nhân gian, vẫn không thuộc về thế giới phồn hoa này, nhưng không còn bối rối và hoang mang nữa.\nBởi vì toàn bộ nhân gian và thế giới, đều là chiến trường thôi miên của cô."
  },
  CollectionHall_99671_Title = {
    Text = "Con lắc thôi miên"
  },
  CollectionHall_99672_Desc = {
    Text = "Mặt trời phát ra hơn 300 trilu-ju mỗi giây, tỷ lệ phần trăm nhỏ bé trong số đó sẽ di chuyển hơn 14,7 tỷ mét từ không gian đến trái đất dưới dạng ánh sáng và nhiệt.\nNhững năng lượng này thỏa mãn nhu cầu của tất cả sinh vật trên trái đất, cho phép tất cả các loài trong ba miền phức tạp, khổng lồ và hỗn loạn có thể sinh sản và tiến hóa một cách suôn sẻ.\n\n \"Đây là chân lý của thế giới, không có trường hợp nào có thể thay đổi.\"\nÔng ta không ngừng tự nhắc nhở bản thân như vậy để giữ cho tinh thần ổn định.\n \"Nhưng tại sao... lại nóng thế, sáng thế.\"\nBởi vì vật thể từ 14,7 tỷ mét đang dần dần chiếm giữ con ngươi của ông.\nÁnh sáng và nhiệt từ đồng tử đang lan rộng ra, thiêu đốt mọi inch cơ thể quý giá của ông.\n \"Tôi hiểu rồi, tôi hiểu rồi, tôi hiểu tại sao ánh sáng lại mất 8 phút 20 giây mới đến trái đất.\"\n \"Bởi vì chúng ta không thể trả giá, đối diện với cái giá của ánh sáng.\"\nKhi ông chấp nhận mọi thứ, ông bắt đầu cười lớn.\n \"Nguyên lại ôi tôi còn gần mặt trời hơn cả Icarus.\""
  },
  CollectionHall_99672_Title = {
    Text = "Mặt trời sắp đến"
  },
  CollectionHall_99673_Desc = {
    Text = "\"Vẫn chưa đủ hoàn hảo, tối nay hãy thực hành mười lần nữa, tài năng của con bình thường, muốn vào dàn nhạc thì phải chăm chỉ hơn, hiểu không?\"\n \"Vâng, cha.\"\nThực hiện như thế nào gọi là hoàn hảo? \nHai bàn tay của anh không ngừng bay múa, không cho phép mình có một sai lầm. \nAnh trách mắng những suy nghĩ lộn xộn, khinh thường sự tầm thường của chính mình. \nVô số nốt nhạc vây quanh trước mắt, mỗi ngày, mỗi ngày, mọi thứ trong cuộc sống của anh chỉ có âm nhạc.\nMay mắn thay, mỗi ngày anh càng tiến gần hơn một chút đến màn trình diễn hoàn hảo, anh nhìn về phía ánh sáng ở cuối con đường trong giấc mơ, và dường như lại không thể chạm tới được. \nKhao khát sự hoàn hảo đã ăn sâu vào linh hồn của anh, nhưng không phải ai cũng sẵn lòng như vậy. \n \"Đem đến âm nhạc hoàn hảo nhất cho bệ hạ, cho nhân dân, chẳng phải đây chính là nhiệm vụ của dàn nhạc sao?\"\nAnh nhìn những gương mặt chứa đầy bất mãn, tựa như khinh bỉ chính mình trong quá khứ. \nCha ơi, dàn nhạc triều đình cũng chỉ có vậy thôi. \nAnh từ bỏ mục tiêu từng ngưỡng mộ, kiên định bước tiếp trên con đường tìm kiếm sự hoàn hảo. \nAnh không thể tạm dừng tay mình để nắm lấy tay họ, cũng như không thể ngừng lại cái tay từng thuộc về bản thân trong quá khứ. \nMỗi ngày, mỗi ngày, anh vẫn không ngừng biểu diễn. \nÂm nhạc là cuộc sống của anh. \nNgoài âm nhạc, anh không có gì cả."
  },
  CollectionHall_99673_Title = {
    Text = "Buổi biểu diễn không bao giờ ngừng"
  },
  CollectionHall_99674_Desc = {
    Text = "Cô ấy đứng trên đỉnh núi, giơ cao chiếc gai đen trong tay. \n Giữa bầu trời gió tuyết, cô ấy đối mặt với dãy núi điên rồ đó, đối mặt với số phận của mình bị bỏ rơi, bị phản bội, bị đạp nát. \n Cuối cùng cô ấy sẽ chiến thắng, tuyết băng sẽ tan chảy, đến lúc đó, cô sẽ tái hiện trong thế giới này với một hình dáng hoàn toàn mới. Cô đã nói như vậy. \n Elworth là vùng đất cực kỳ lạnh lẽo, với gió tuyết quanh năm không tan. Đây là điều ai cũng biết. Giống như không có chiến binh nào có thể chống lại sự tồn tại cao quý, cũng như không có người nào có thể chiến thắng số phận của mình. \n Nhưng cuối cùng dãy núi tuyết vẫn tan chảy, phải không?"
  },
  CollectionHall_99674_Title = {
    Text = "Đợi đến khi tuyết sơn tan"
  },
  CollectionHall_99676_Desc = {
    Text = "Vị vua đầu tiên đến từ Isarau. \n Ông có đôi mắt đặc trưng của người Isarau, màu vàng nhạt, lấp lánh yếu ớt trong đêm tối đen như mực. \n Nhưng ánh sáng đó đã biến mất khi Isarau sụp đổ, Vanda vớt lên từ bùn đen cuối cùng một vật chứa, cẩn thận và trân trọng cất giữ. \n Cô gặp hai vị vua tiếp theo tại cao nguyên Fran. \n Đó là một cặp anh em song sinh tham lam, Vanda từng hy vọng dựa vào sức mạnh của họ để tái xây dựng thành phố hồ đã mất. \n Cô bị lừa dối, vì vậy, gai nhọn sâu chôn vào tủy xương của họ. Trong trạng thái tê liệt, Vanda lấy ra hai đôi mắt thấp hèn và vô lễ, sau đó để lại chúng làm dấu vết của sự hiện diện của mình. \n Vị vua thứ tư, Vanda nhớ tên ông là \"John\". \n Ông là một người câm nhàm chán, nhưng phục vụ cô đủ thoải mái. Điều khiến cô vui hơn nữa là \"John\" cũng có đôi mắt màu vàng nhạt, gần như giống hệt cô. \n\n \"Hãy moi mắt vua ra.\"\n \"Xin tuân theo ý nguyện của ngài... nhưng, vua đã làm gì sai trái?\"\n Vanda lắc ly nước đục, cảm nhận chất độc lan tỏa trên đầu lưỡi. Thật là kẻ ngu ngốc, thậm chí việc đầu độc cũng làm quá thô lỗ. \n Nhìn thấy thân thể \"John\"đầy rỗng rỗng, cô nhớ lại những đôi mắt chết lặng nhìn cô rời bỏ quê hương từ xa xôi. \n Giống hệt như đôi mắt của \"John\" lúc này. \n \"... Thế nên, anh ta thiếu óc hài hước.\""
  },
  CollectionHall_99676_Title = {
    Text = "Ánh mắt của Isarau"
  },
  CollectionHall_99678_Desc = {
    Text = "Từ khi bài thơ của cô ấy trở nên nổi tiếng ở Tây Đài, người bạn thân đã chăm chỉ hơn trong việc mang hoa đến cho cô ấy. \n \"Chúng ta không cần nhiều hoa như vậy, Corlette, điều này thật là lãng phí.\"\nHoa hồng mà cô ấy mang đến hôm nay được xếp chồng lên những bông hoa từ hôm qua, hôm kia và hôm trước đó, những bông hoa cũ thậm chí đã bắt đầu mục nát vì quá chật chội. \n \"Làm sao có thể lãng phí được, chúng ta đã hứa với nhau, dùng hoa của tôi đổi lấy thơ của bạn.\"\nCorlette lắc đầu, nhìn cô ấy với vẻ hơi ngượng ngùng. \nĐúng vậy, dùng hoa đổi lấy thơ, đó là lời hứa của họ. Cô ấy cảm nhận được, có điều gì đó dường như đã thay đổi, nhưng cô ấy không muốn nghĩ thêm về nó. \nCô ấy tiếp tục viết thơ, viết thơ cả ngày lẫn đêm. Trước đây, thơ của cô ấy sẽ tự nhiên chảy ra từ đầu bút, nhưng bây giờ, bút của cô ấy dường như trở nên cứng nhắc. \nMỗi lần người bạn thân mang hoa đến, ánh mắt của cô ấy càng trở nên xa lạ, cô ấy nhìn đống hoa hồng mục nát đầy nhà, ngửi mùi hôi thối của những bông hoa đã tàn, lòng cảm thấy tiếc nuối và buồn bã. \nNhưng cô ấy chưa bao giờ ngừng viết. \n \"Tôi sẽ dựa vào những bông hoa mọc lên từ mảnh đất này để mua quần áo, mua thức ăn cho chúng ta. Một ngày nào đó, tôi sẽ mua cả căn nhà trong tòa nhà kia!\"\n \"Mỗi người đều có việc phải làm từ khi sinh ra. Tôi sinh ra để cố gắng vì khu vườn này, vì căn nhà kia... còn bạn, bạn sinh ra để viết thơ.\"\n \"Tôi tin bạn, Ôrla! Từ hôm nay, tôi sẽ giúp bạn cất giữ tất cả những bài thơ. Sau này, tôi sẽ dùng hoa của mình để đổi lấy thơ của bạn!\"\nHoa và thơ, là lời hứa mà họ dành cho nhau. \nCô ấy sẽ không bao giờ ngừng viết."
  },
  CollectionHall_99678_Title = {
    Text = "Hoa và Thơ của Quá Khứ"
  },
  CollectionHall_99679_Desc = {
    Text = "Định mệnh giữa mụ phù thủy và mũ rộng vành đôi khi giống như mối quan hệ gà và trứng, không rõ là mũ đã làm nên phù thủy hay phù thủy tạo nên mũ.\nDẫu sao thì, Hoa thủy tiên sở hữu một chiếc mũ rộng vành đủ thanh nhã.\nChiếc mũ này ban đầu thuộc về chủ tiệm trước đây, khi đó Hoa thủy tiên vẫn chưa có tên, chỉ là một linh hồn mơ màng, một dã thú đã bị chế ngự.\nNgười phụ nữ luôn mỉm cười ấy đã dẫn dắt cô, với sự kiên nhẫn như dạy cho một đứa trẻ, mà từ từ chỉ cho cô cách trở thành \"người\" và bí quyết giao tiếp với người khác.\nThành phố cảng phồn hoa với nền thương mại phát triển, là nơi hội tụ tinh hoa văn hóa nhân loại thời bấy giờ. Phố nơi cửa hàng trao đổi tọa lạc có đầy đủ các cửa hàng đa dạng, còn chủ tiệm luôn có thể trò chuyện tự nhiên như bạn cũ với tất cả các chủ tiệm.\n\"Cô ấy thật tài giỏi,\" Hoa thủy tiên suy nghĩ, \"nhưng không có gì lạ, không ai không thích cô ấy cả.\"\nChủ tiệm thích đi mua sắm, và đó là lần đầu tiên trong cả ngàn năm Hoa thủy tiên được yêu cầu đưa ra ý kiến riêng khi đã hóa thân thành những nhân vật mà người phụ nữ đã cắt đầu.\n\"Bạn thấy chiếc nào đẹp hơn? Chiếc mũ nhỏ hay chiếc mũ rộng vành này?\"\nNgười phụ nữ đứng trước gương, thử những chiếc mũ phong phú. Với Hoa thủy tiên, đó chỉ là những vật dụng để che phủ cơ thể, tạo dáng như người.\nNhưng ngày hôm đó, khi nhìn thấy chiếc mũ rộng vành trên đầu của chủ tiệm trông như một bông hoa lớn, hình ảnh người phụ nữ mang chiếc mũ ấy đi dạo cùng mình trên bãi biển bất ngờ hiện lên trong đầu cô.\n\"Chiếc này.\" Cô đột nhiên lên tiếng, \"Là chiếc này.\"\nChủ tiệm ngạc nhiên quay đầu lại, như không ngờ cô sẽ thể hiện sở thích một cách rõ ràng như vậy.\n\"Được rồi, quả là một chiếc mũ đẹp, bởi vì bạn đã chọn cho tôi, tôi sẽ thật trân trọng nó.\"\nKhông biết có phải để khuyến khích Hoa thủy tiên hay không, chiếc mũ như đã hứa trở thành vật dụng thường trực trên đầu chủ tiệm, cho đến khi từ tay đang dần buông lơi, chủ tiệm tự trao lại cho Hoa thủy tiên cùng một cái đầu mỉm cười.\n\"Thật là một chiếc mũ đẹp, tôi sẽ thật trân trọng nó.\"\nBông hoa tím, đen nở rộ cuối cùng đã nở trên đầu của chủ nhân mới."
  },
  CollectionHall_99679_Title = {
    Text = "Mũ phù thủy rộng vành"
  },
  CollectionHall_99683_Desc = {
    Text = "Trong ảo mộng của ngai vàng, nhà vua lắng nghe lời chỉ dạy của thần minh: \n Bão tố của Lemuria sẽ lắng xuống. Vực thẳm của Lemuria sẽ biến mất. \n Lấy giấc mơ làm sân, lấy các vì sao làm nến. Nhà vua sẽ bảo vệ những thần dân lương thiện của ngài, mang đến vương quốc của thần. \n\n Tín đồ của chủ nhân, hãy mở lòng ra, tiếp nhận chủ nhân. \n Ở vùng vực thẳm xa xăm, linh hồn vĩ đại cổ xưa đang say ngủ, lắng nghe lời thì thầm của các vị thần. \n Ý chí của Ngài như mạng lưới các vì sao đan xen, Ngài chờ đợi ngươi bước vào cõi mộng giữa hư vô vĩnh hằng. \n\n Bão tố yên lặng, sóng nước không gợn; \n Địa chấn lắng xuống, mặt đất bình yên. \n Thảm họa biến thành hư vô trong giấc mơ bình yên của Ngài, \n thần dân được bảo vệ dưới sự che chở của Ngài an toàn vô sự. \n Ước gì tiếng hát của chúng ta vượt qua biển sâu, xin Ngài ban cho chúng ta sấm truyền để tránh khỏi tai ương, \n dẫn chúng ta đến với sự bình an và hạnh phúc vô tận. \n Niềm tin của chúng ta cùng với Ngài, cho đến khi các vì sao tắt lửa, cho đến khi thời gian kết thúc. \n"
  },
  CollectionHall_99683_Title = {
    Text = "Gọi của Biển Sâu"
  },
  CollectionHall_99684_Desc = {
    Text = "Ngày thứ bảy bắt đầu chuyển đổi thành xác sống, anh ta rên rỉ trong cơn đau nhức ngày càng nghiêm trọng của chân tay đang thối rữa. Mỗi lần cựa quậy một chút đều kéo theo những dây thần kinh nhạy cảm, phát ra cơn đau xé nát... cùng với những tia sáng cảm hứng làm rùng mình.\nTuy nhiên, bóng tối hoang mang vẫn luôn bao trùm nghệ sĩ này— rốt cuộc cần cây bút như thế nào, mới có thể vẽ nên sự thật tột cùng nhất?\nĐôi mắt yếu đuối của Pikman tìm kiếm khắp nơi, từ những viên gạch bên cạnh biệt thự đến cành cây trên mồ, cuối cùng, ánh mắt dừng lại trên phần xương trắng trơ trọi của chân phải hắn, đang thối rữa.\nNhư thể nghe thấy một tiếng gọi thiêng liêng, Pikman moi ra xương chân, dùng đầu ngón tay chà xát hết lớp máu thịt bám dính, biến nó thành một cây bút cứng cáp.\nHắn mài nhọn đầu bút thành chiếc răng sắc nhọn, nhưng trước khi đầu bút cắm lên vải, nó lại đâm vào ngón tay gầy guộc của chủ nhân. Pikman đau đớn buông tay, cây bút thoát khỏi sự kiểm soát của hắn.\nBay múa! Nhảy lên! Xoay tròn! Nó cuồng loạn trên vải, khắc lên những đường nét điên cuồng rối loạn. Những đường nét sinh sôi nảy nở, kéo theo một mảng vết bẩn tối màu không ngừng phình to, từ từ mà kiên định cắn chặt vào cổ họng của Pikman.\nCảm giác hoan hỉ tức thì như những mũi dao xuyên thấu trái tim còn lại của hắn— cơ quan sưng tấy, hình hài hỗn loạn, khiến hắn run rẩy sợ hãi, nhưng đồng thời cũng hồi sinh giác quan sắp tàn lụi. Chúng trực tiếp, sắc bén, giáng xuống nỗi đau, sự kỳ quái cùng khát vọng, bùng nổ sức mạnh lay động không che giấu.\nTrong sự đảo lộn này, Pikman dường như càng gần hơn với thánh địa của \"vẻ đẹp\".\nKhi mọi thứ lắng xuống, Pikman đưa ra những móng vuốt đã bị ăn mòn, chà xát qua cây bút trắng nhợt. Trong cơ thể hình người còn lại này, tuôn trào ra khát vọng nóng bỏng hơn, cấp bách hơn.\nHắn sẽ cùng với cây bút này hoàn thành dấu chấm cuối cùng cho tác phẩm vĩ đại của mình."
  },
  CollectionHall_99684_Title = {
    Text = "Cây cọ khát khao"
  },
  CollectionHall_99687_Desc = {
    Text = "\"Thánh tử là người được ánh đèn chiếu rọi, sinh ra nhận được sự quan tâm của Ngài.\"\n \"Thánh tử nên truyền bá ý chỉ của Ngài, ban ánh sáng cho những người công chính đạo đức.\"\n \"Thánh tử cần giữ linh hồn mình trong sạch.\"\n \"Thánh tử nên từ bỏ dục vọng, thành tâm tu luyện, phục vụ toàn lòng cho ánh sáng.\"\n \"Thánh tử không được nói nhiều, không được nói dối.\"\n \"Thánh tử nên tránh xa tội lỗi, tránh xa những người có tội, không để linh hồn ô uế làm ô nhiễm.\"\n \"Thánh tử...\"\nTừ khi có ký ức, từng điều răn như một chuỗi xích đã trói buộc anh, đưa anh lên bệ cao quý, lại khiến anh không thể thất lễ, không thể cúi đầu, không thể buông thả cảm xúc.\nAnh được khoác lên y phục rộng rãi và lộng lẫy, lấp lánh giữa vô số người hầu, thực hiện vai trò của đại diện thánh thần, nhìn xuống các tín hữu thành kính quỳ gối, cẩn thận hôn lên tà áo của anh.\nThánh tử vốn nên như vậy, không ai quan tâm ẩn sâu sau gương mặt kiêu ngạo ấy, thực sự có cảm xúc và sở thích gì.\nGiống như anh đã quen với nụ cười kiêu ngạo đó, ngay cả khi không có ai cũng không nhận ra mình thực sự muốn thể hiện kiểu biểu cảm nào.\n \"Thánh tử Polyxenus, ngài nên đến buổi lễ ban phước rồi.\" Cô hầu gái cúi đầu tôn kính sắp xếp cuộc sống không thay đổi của anh.\nAnh quay lưng lại, ngẩng cao đầu, nở nụ cười không đổi đó, như thể tự tay đeo lên một chiếc mặt nạ thánh thiêng.\nNhững mất phương hướng, trống rỗng và cô đơn, đều được che giấu dưới lớp mặt nạ, như thể chưa từng tồn tại."
  },
  CollectionHall_99687_Title = {
    Text = "Polux SR (văn bản tạm thời)"
